function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

function loadLocalEnvFiles(filePaths = []) {
  const seen = new Set();
  filePaths.forEach((filePath) => {
    const normalizedPath = String(filePath || "").trim();
    if (!normalizedPath || seen.has(normalizedPath) || !fs.existsSync(normalizedPath)) {
      return;
    }
    seen.add(normalizedPath);
    const content = fs.readFileSync(normalizedPath, "utf8");
    parseDotEnv(content).forEach(([key, value]) => {
      if (!key || process.env[key] !== undefined) {
        return;
      }
      process.env[key] = value;
    });
  });
}

function parseDotEnv(content) {
  return String(content || "")
    .split(/\r?\n/g)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"))
    .map((line) => (line.startsWith("export ") ? line.slice(7).trim() : line))
    .map((line) => {
      const separatorIndex = line.indexOf("=");
      if (separatorIndex <= 0) {
        return null;
      }
      const key = line.slice(0, separatorIndex).trim();
      let value = line.slice(separatorIndex + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      return [key, value.replace(/\\n/g, "\n")];
    })
    .filter(Boolean);
}

