function seedDefaultProject() {
  return seedDefaultProjects()[0];
}

function seedProjectById(projectId) {
  return seedDefaultProjects().find((item) => safeText(item.id, "") === safeText(projectId, "")) || null;
}

function repairSeededProjectRecords(projectList = [], seededProjects = seedDefaultProjects()) {
  const defaultSeedDescription = safeText(seedDefaultProject().description, "");
  const seedMap = new Map((Array.isArray(seededProjects) ? seededProjects : []).map((item) => [safeText(item.id, ""), item]));

  return (Array.isArray(projectList) ? projectList : []).map((project) => {
    const record = project && typeof project === "object" ? { ...project } : {};
    const seed = seedMap.get(safeText(record.id, ""));
    if (!seed) {
      return project;
    }

    let changed = false;
    const currentDescription = safeText(record.description, "");
    if (!currentDescription || (safeText(seed.description, "") !== defaultSeedDescription && currentDescription === defaultSeedDescription)) {
      record.description = seed.description || "";
      changed = true;
    }

    if (!safeText(record.name, "")) {
      record.name = seed.name;
      changed = true;
    }
    if (!safeText(record.code, "")) {
      record.code = seed.code;
      changed = true;
    }
    if (!safeText(record.folderPolicyKey || record.defaultFolderPolicy, "")) {
      record.folderPolicyKey = seed.folderPolicyKey || "cde_standard";
      changed = true;
    }
    if (!safeText(record.memberInitMode, "")) {
      record.memberInitMode = seed.memberInitMode || "creator_only";
      changed = true;
    }
    if (!safeText(record.templateInitMode, "")) {
      record.templateInitMode = seed.templateInitMode || "default_templates";
      changed = true;
    }
    if (!safeText(record.createdBy, "")) {
      record.createdBy = seed.createdBy || "system";
      changed = true;
    }
    if (!safeText(record.createdAt, "")) {
      record.createdAt = seed.createdAt || new Date().toISOString();
      changed = true;
    }

    if (changed) {
      storeHydrationMutated = true;
    }
    return changed ? record : project;
  });
}

function refreshSeededModelHealthRulesets(rulesets = [], seededRulesets = []) {
  const seedMap = new Map((Array.isArray(seededRulesets) ? seededRulesets : []).map((item) => [safeText(item.id, ""), item]));
  return (Array.isArray(rulesets) ? rulesets : []).map((ruleset) => {
    const value = ruleset && typeof ruleset === "object" ? ruleset : {};
    const seed = seedMap.get(safeText(value.id, ""));
    if (!seed || value.builtIn === false) {
      return ruleset;
    }
    const refreshed = {
      ...seed,
      createdAt: safeText(value.createdAt, seed.createdAt),
      updatedAt: seed.updatedAt,
    };
    if (JSON.stringify(value) !== JSON.stringify(refreshed)) {
      storeHydrationMutated = true;
      return refreshed;
    }
    return ruleset;
  });
}

function pruneLegacyModelHealthRulesets(rulesets = []) {
  const legacyNames = new Set([
    "Plant 3D 工艺模型健康度模板",
    "Revit 建筑模型健康度模板",
    "Revit 结构模型健康度模板",
  ]);
  const legacyDisciplines = new Set(["architecture", "structure", "plant3d"]);
  const currentList = Array.isArray(rulesets) ? rulesets : [];
  const filtered = currentList.filter((ruleset) => {
    const value = ruleset && typeof ruleset === "object" ? ruleset : {};
    if (value.builtIn === false) {
      return true;
    }
    const name = safeText(value.name, "");
    const discipline = safeText(value.discipline, "").toLowerCase();
    return !(legacyNames.has(name) || legacyDisciplines.has(discipline));
  });
  if (filtered.length !== currentList.length) {
    storeHydrationMutated = true;
  }
  return filtered;
}

function projectFolderPolicyPreset(policyKey = "cde_standard") {
  return PROJECT_FOLDER_POLICY_PRESETS[normalizeProjectFolderPolicyKey(policyKey, "cde_standard")] || PROJECT_FOLDER_POLICY_PRESETS.cde_standard;
}

function projectFolderIds(projectId = DEFAULT_PROJECT_ID) {
  if (projectId === DEFAULT_PROJECT_ID) {
    return {
      received: "folder-received",
      receivedOwner: "folder-received-owner",
      wip: "folder-wip",
      wipMep: "folder-wip-mep",
      share: "folder-share",
      publish: "folder-publish",
      general: "folder-general",
    };
  }
  return {
    received: `${projectId}-folder-received`,
    receivedOwner: `${projectId}-folder-received-owner`,
    wip: `${projectId}-folder-wip`,
    wipMep: `${projectId}-folder-wip-mep`,
    share: `${projectId}-folder-share`,
    publish: `${projectId}-folder-publish`,
    general: `${projectId}-folder-general`,
  };
}

function folderByIdFromCollection(folderId, folderCollection = folders) {
  return (Array.isArray(folderCollection) ? folderCollection : []).find((item) => item.id === folderId) || null;
}

function folderPathLabelFromCollection(folderId, folderCollection = folders) {
  if (!folderId) {
    return "";
  }
  const parts = [];
  let cursor = folderByIdFromCollection(folderId, folderCollection);
  while (cursor) {
    parts.unshift(safeText(cursor.name, ""));
    cursor = folderByIdFromCollection(cursor.parentId, folderCollection);
  }
  return parts.filter(Boolean).join(" / ");
}

function folderPathSegmentsFromCollection(folderId, folderCollection = folders) {
  if (!folderId) {
    return [];
  }
  const parts = [];
  let cursor = folderByIdFromCollection(folderId, folderCollection);
  while (cursor) {
    parts.unshift(safeText(cursor.name, ""));
    cursor = folderByIdFromCollection(cursor.parentId, folderCollection);
  }
  return parts.filter(Boolean);
}

function projectFolderByPathSegments(projectId, pathSegments, folderCollection = folders) {
  if (!Array.isArray(pathSegments) || !pathSegments.length) {
    return null;
  }
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  let parentId = null;
  let matched = null;
  for (const segment of pathSegments) {
    const normalizedSegment = safeText(segment, "").toLowerCase();
    matched = (Array.isArray(folderCollection) ? folderCollection : []).find(
      (item) =>
        safeText(item.projectId, DEFAULT_PROJECT_ID) === normalizedProjectId &&
        (item.parentId || null) === (parentId || null) &&
        safeText(item.name, "").toLowerCase() === normalizedSegment,
    ) || null;
    if (!matched) {
      return null;
    }
    parentId = matched.id;
  }
  return matched;
}

function equivalentProjectFolderForStaleId(folderId, projectId, folderCollection = folders) {
  const sourceFolder = folderByIdFromCollection(folderId, folderCollection);
  if (!sourceFolder) {
    return null;
  }
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  if (safeText(sourceFolder.projectId, DEFAULT_PROJECT_ID) === normalizedProjectId) {
    return sourceFolder;
  }
  const pathSegments = folderPathSegmentsFromCollection(sourceFolder.id, folderCollection);
  return (
    projectFolderByPathSegments(normalizedProjectId, pathSegments, folderCollection) ||
    (safeText(sourceFolder.policyKey, "") ? projectFolderByPolicyKey(normalizedProjectId, sourceFolder.policyKey, folderCollection) : null)
  );
}

function projectFolderByPolicyKey(projectId, policyKey, folderCollection = folders) {
  return (Array.isArray(folderCollection) ? folderCollection : []).find(
    (item) =>
      safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID) &&
      safeText(item.policyKey, "") === safeText(policyKey, ""),
  ) || null;
}

function projectFolderAbsolutePath(projectId, folderId, folderCollection = folders, projectNameFallback = "") {
  const project = projectNameFallback
    ? normalizeProject({ id: projectId, name: projectNameFallback, code: "PROJECT" })
    : projectById(projectId) || normalizeProject({ id: projectId, name: "当前项目", code: "PROJECT" });
  const relativePath = folderPathLabelFromCollection(folderId, folderCollection);
  return relativePath ? `/${project.name}/${relativePath}` : `/${project.name}`;
}

function createProjectFoldersFromPolicy(projectSeed, createdAt = new Date().toISOString()) {
  const project = normalizeProject(projectSeed);
  const preset = projectFolderPolicyPreset(project.folderPolicyKey);
  const folderIdByKey = new Map();
  return preset.nodes.map((node) => {
    const folderId = `${project.id}-folder-${node.key}`;
    folderIdByKey.set(node.key, folderId);
    return normalizeFolder({
      id: folderId,
      projectId: project.id,
      policyKey: node.key,
      name: node.name,
      parentId: node.parentKey ? folderIdByKey.get(node.parentKey) || null : null,
      owner: "项目组",
      accessLevel: node.accessLevel || "edit",
      createdAt,
      updatedAt: createdAt,
    });
  });
}

function resolveProjectTemplateTargetFolders(projectId, folderCollection = folders, projectNameFallback = "") {
  const projectName = projectNameFallback || "当前项目";
  const scopedFolders = (Array.isArray(folderCollection) ? folderCollection : []).filter(
    (item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID),
  );
  const generalFolder =
    projectFolderByPolicyKey(projectId, "general", scopedFolders) ||
    scopedFolders.find((item) => /general|综合资料/i.test(safeText(item.name, ""))) ||
    null;
  const publishFolder =
    projectFolderByPolicyKey(projectId, "publish", scopedFolders) ||
    scopedFolders.find((item) => /publish|发布/i.test(safeText(item.name, ""))) ||
    null;
  return {
    generalFolderId: generalFolder?.id || "",
    generalPath: generalFolder ? projectFolderAbsolutePath(projectId, generalFolder.id, scopedFolders, projectName) : `/${projectName}`,
    publishFolderId: publishFolder?.id || "",
    publishPath: publishFolder ? projectFolderAbsolutePath(projectId, publishFolder.id, scopedFolders, projectName) : `/${projectName}`,
  };
}

