function seedDefaultProjectMembers(projectsList = seedDefaultProjects()) {
  const createdAt = "2026-04-24T00:00:00.000Z";
  const list = [];
  const pushMember = (id, projectId, userId, role, invitedBy = "user-admin") => {
    list.push({
      id,
      projectId,
      userId,
      role,
      invitedBy,
      joinedAt: createdAt,
      removedAt: "",
    });
  };

  projectsList.forEach((projectSeed) => {
    if (projectSeed.id === DEFAULT_PROJECT_ID) {
      pushMember("member-super", projectSeed.id, "user-super", "super_admin", "system");
      pushMember("member-admin", projectSeed.id, "user-admin", "project_admin", "user-super");
      pushMember("member-editor", projectSeed.id, "user-editor", "editor");
      pushMember("member-reviewer", projectSeed.id, "user-reviewer", "reviewer");
      pushMember("member-reviewer-lock", projectSeed.id, "user-reviewer-lock", "reviewer");
      pushMember("member-approver", projectSeed.id, "user-approver", "reviewer");
      pushMember("member-project-manager", projectSeed.id, "user-project-manager", "reviewer");
      pushMember("member-procurement", projectSeed.id, "user-procurement", "reviewer");
      pushMember("member-director", projectSeed.id, "user-director", "reviewer");
      pushMember("member-guest", projectSeed.id, "user-guest", "guest");
      return;
    }

    pushMember(`${projectSeed.id}-member-super`, projectSeed.id, "user-super", "super_admin", "system");
    pushMember(`${projectSeed.id}-member-admin`, projectSeed.id, "user-admin", "project_admin", "user-super");
    pushMember(`${projectSeed.id}-member-reviewer`, projectSeed.id, "user-reviewer", "reviewer");
    pushMember(`${projectSeed.id}-member-editor`, projectSeed.id, "user-editor", "editor");
    if (projectSeed.id === "project-desalination-phase1") {
      pushMember(`${projectSeed.id}-member-project-manager`, projectSeed.id, "user-project-manager", "reviewer");
      pushMember(`${projectSeed.id}-member-guest`, projectSeed.id, "user-guest", "guest");
      return;
    }
    pushMember(`${projectSeed.id}-member-procurement`, projectSeed.id, "user-procurement", "reviewer");
    pushMember(`${projectSeed.id}-member-director`, projectSeed.id, "user-director", "reviewer");
  });

  return list;
}

function seedDefaultFolderPermissions(existingFolders = [], projectsList = seedDefaultProjects()) {
  const folderIds = new Set(existingFolders.map((folder) => String(folder.id || "").trim()).filter(Boolean));
  const list = [];
  const pushPermission = (id, projectId, folderId, userId, permission, setBy = "user-admin") => {
    if (!folderIds.has(folderId)) {
      return;
    }
    list.push({
      id,
      projectId,
      folderId,
      userId,
      permission,
      setBy,
      createdAt: "2026-04-24T00:00:00.000Z",
      updatedAt: "2026-04-24T00:00:00.000Z",
    });
  };

  projectsList.forEach((projectSeed) => {
    const ids = projectFolderIds(projectSeed.id);
    if (projectSeed.id === DEFAULT_PROJECT_ID) {
      pushPermission("fp-publish-editor", projectSeed.id, ids.publish, "user-editor", "viewer");
      pushPermission("fp-publish-reviewer", projectSeed.id, ids.publish, "user-reviewer", "viewer");
      pushPermission("fp-publish-reviewer-lock", projectSeed.id, ids.publish, "user-reviewer-lock", "viewer");
      pushPermission("fp-publish-approver", projectSeed.id, ids.publish, "user-approver", "viewer");
      pushPermission("fp-publish-guest", projectSeed.id, ids.publish, "user-guest", "viewer");
      pushPermission("fp-received-guest", projectSeed.id, ids.receivedOwner, "user-guest", "none");
      pushPermission("fp-share-guest", projectSeed.id, ids.share, "user-guest", "viewer");
      return;
    }
    if (projectSeed.id === "project-desalination-phase1") {
      pushPermission(`${projectSeed.id}-fp-publish-guest`, projectSeed.id, ids.publish, "user-guest", "viewer");
      pushPermission(`${projectSeed.id}-fp-received-guest`, projectSeed.id, ids.receivedOwner, "user-guest", "none");
      pushPermission(`${projectSeed.id}-fp-share-guest`, projectSeed.id, ids.share, "user-guest", "viewer");
    }
  });
  return list;
}

