    systemEmailSettings: seedDefaultSystemEmailSettings(),
    projectEmailNotificationSettings: seedDefaultProjectEmailNotificationSettings(seededProjects),
    systemAiSettings: seedDefaultSystemAiSettings(),
    systemApsSettings: seedDefaultSystemApsSettings(),
    notificationReads: [],
    modelClashRuns: [],
    modelClashRecords: [],
    modelClashHeatmaps: [],
