function loadStore() {
  const parsed = storeRepository.read();
  const seededProjects = seedDefaultProjects();
  const nextProjectsRaw =
    Array.isArray(parsed?.projects) && parsed.projects.length
      ? parsed.projects
      : parsed?.project
        ? [parsed.project]
        : seededProjects;
  const seededUsers = seedDefaultUsers();
  const mergeSeededById = (currentItems, seededItems) => {
    const currentList = Array.isArray(currentItems) ? currentItems : [];
    const seededList = Array.isArray(seededItems) ? seededItems : [];
    const merged = [...currentList];
    const seen = new Set(currentList.map((item) => safeText(item?.id, "")).filter(Boolean));
    seededList.forEach((item) => {
      const itemId = safeText(item?.id, "");
      if (itemId && !seen.has(itemId)) {
        merged.push(item);
        seen.add(itemId);
        storeHydrationMutated = true;
      }
    });
    return merged;
  };
  const nextProjects = repairSeededProjectRecords(mergeSeededById(nextProjectsRaw, seededProjects), seededProjects);
  const normalizedProjects = nextProjects.map(normalizeProject);
  const seededFolders = seedDefaultFolders(normalizedProjects);
  const nextFolders = mergeSeededById(Array.isArray(parsed?.folders) ? parsed.folders : [], seededFolders);
  const nextDocuments = Array.isArray(parsed) ? parsed : Array.isArray(parsed.documents) ? parsed.documents : [];
  const seededTemplates = seedDefaultWorkflowTemplates(normalizedProjects);
  const seededMembers = seedDefaultProjectMembers(normalizedProjects);
  const seededFolderPermissions = seedDefaultFolderPermissions(nextFolders, normalizedProjects);
  const seededSystemEmailSettings = seedDefaultSystemEmailSettings();
  const seededProjectEmailNotificationSettings = seedDefaultProjectEmailNotificationSettings(normalizedProjects);
  const nextWorkflowTemplates = mergeSeededById(
    Array.isArray(parsed?.workflowTemplates) && parsed.workflowTemplates.length ? parsed.workflowTemplates : seededTemplates,
    seededTemplates,
  );
  const nextWorkflows = Array.isArray(parsed?.workflows) ? parsed.workflows : [];
  const nextUsers = mergeSeededById(
    Array.isArray(parsed?.users) && parsed.users.length ? parsed.users : seededUsers,
    seededUsers,
  );
  const nextProjectMembers = mergeSeededById(
    Array.isArray(parsed?.projectMembers) && parsed.projectMembers.length ? parsed.projectMembers : seededMembers,
    seededMembers,
  );
  const nextFolderPermissions =
    Array.isArray(parsed?.folderPermissions) ? parsed.folderPermissions : seededFolderPermissions;
  const nextAuditLogs = Array.isArray(parsed?.auditLogs) ? parsed.auditLogs : [];
  const nextJobs = Array.isArray(parsed?.jobs) ? parsed.jobs : [];
  const nextModelGeometryExtractionTasks = Array.isArray(parsed?.modelGeometryExtractionTasks) ? parsed.modelGeometryExtractionTasks : [];
  const nextModelHealthTasks = Array.isArray(parsed?.modelHealthTasks) ? parsed.modelHealthTasks : [];
  const nextModelHealthRuleResults = Array.isArray(parsed?.modelHealthRuleResults) ? parsed.modelHealthRuleResults : [];
  const nextModelHealthAiResults = Array.isArray(parsed?.modelHealthAiResults) ? parsed.modelHealthAiResults : [];
  const seededModelHealthRulesets = seedDefaultModelHealthRulesets(normalizedProjects);
  const nextModelHealthRulesets = refreshSeededModelHealthRulesets(mergeSeededById(
    Array.isArray(parsed?.modelHealthRulesets) ? parsed.modelHealthRulesets : [],
    seededModelHealthRulesets,
  ), seededModelHealthRulesets);
  const nextModelHealthFalsePositiveRecords = Array.isArray(parsed?.modelHealthFalsePositiveRecords) ? parsed.modelHealthFalsePositiveRecords : [];
  const nextQuantityTakeoffTasks = Array.isArray(parsed?.quantityTakeoffTasks) ? parsed.quantityTakeoffTasks : [];
  const nextQuantityPropertySnapshots = Array.isArray(parsed?.quantityPropertySnapshots) ? parsed.quantityPropertySnapshots : [];
  const nextQuantitySummaries = Array.isArray(parsed?.quantitySummaries) ? parsed.quantitySummaries : [];
  const nextQuantityTemplates = mergeSeededById(
    Array.isArray(parsed?.quantityTemplates) ? parsed.quantityTemplates : [],
    seedDefaultQuantityTemplates(normalizedProjects),
  );
  const nextNotificationReads = Array.isArray(parsed?.notificationReads) ? parsed.notificationReads : [];
  const nextModelClashRuns = Array.isArray(parsed?.modelClashRuns) ? parsed.modelClashRuns : [];
  const nextModelClashRecords = Array.isArray(parsed?.modelClashRecords) ? parsed.modelClashRecords : [];
  const nextModelClashHeatmaps = Array.isArray(parsed?.modelClashHeatmaps) ? parsed.modelClashHeatmaps : [];
  const nextModelClashHeatmapCells = Array.isArray(parsed?.modelClashHeatmapCells) ? parsed.modelClashHeatmapCells : [];
  const nextModelClashHotspots = Array.isArray(parsed?.modelClashHotspots) ? parsed.modelClashHotspots : [];
  const nextModelDiffTasks = Array.isArray(parsed?.modelDiffTasks) ? parsed.modelDiffTasks : [];
  const nextModelDiffSnapshots = Array.isArray(parsed?.modelDiffSnapshots) ? parsed.modelDiffSnapshots : [];
  const nextModelDiffRecords = Array.isArray(parsed?.modelDiffRecords) ? parsed.modelDiffRecords : [];
  const nextModelDiffPropChanges = Array.isArray(parsed?.modelDiffPropChanges) ? parsed.modelDiffPropChanges : [];
  const nextModelDiffAiSummaries = Array.isArray(parsed?.modelDiffAiSummaries) ? parsed.modelDiffAiSummaries : [];
  const nextConstructionScheduleVersions = Array.isArray(parsed?.constructionScheduleVersions) ? parsed.constructionScheduleVersions : [];
  const nextConstructionScheduleWbsNodes = Array.isArray(parsed?.constructionScheduleWbsNodes) ? parsed.constructionScheduleWbsNodes : [];
  const nextConstructionScheduleActivities = Array.isArray(parsed?.constructionScheduleActivities) ? parsed.constructionScheduleActivities : [];
  const nextConstructionSchedulePredecessors = Array.isArray(parsed?.constructionSchedulePredecessors) ? parsed.constructionSchedulePredecessors : [];
  const nextConstructionScheduleMappings = Array.isArray(parsed?.constructionScheduleMappings) ? parsed.constructionScheduleMappings : [];
  const nextConstructionProgressReports = Array.isArray(parsed?.constructionProgressReports) ? parsed.constructionProgressReports : [];
  const nextConstructionScheduleSnapshots = Array.isArray(parsed?.constructionScheduleSnapshots) ? parsed.constructionScheduleSnapshots : [];
  const nextConstructionScheduleAlerts = Array.isArray(parsed?.constructionScheduleAlerts) ? parsed.constructionScheduleAlerts : [];
  const nextDrawingPrecheckTasks = Array.isArray(parsed?.drawingPrecheckTasks) ? parsed.drawingPrecheckTasks : [];
  const nextDrawingPrecheckResults = Array.isArray(parsed?.drawingPrecheckResults) ? parsed.drawingPrecheckResults : [];
  const nextDrawingExtractionSnapshots = Array.isArray(parsed?.drawingExtractionSnapshots) ? parsed.drawingExtractionSnapshots : [];
  const nextDrawingRuleConfigs = mergeSeededById(
    Array.isArray(parsed?.drawingRuleConfigs) ? parsed.drawingRuleConfigs : [],
    seedDefaultDrawingRuleConfigs(normalizedProjects),
  );
  const nextDrawingPackages = Array.isArray(parsed?.drawingPackages) ? parsed.drawingPackages : [];
  const nextDrawingExpectedItems = Array.isArray(parsed?.drawingExpectedItems) ? parsed.drawingExpectedItems : [];
  const nextDrawingConsistencyConfirmations = Array.isArray(parsed?.drawingConsistencyConfirmations) ? parsed.drawingConsistencyConfirmations : [];
  const nextDrawingRedlineTasks = Array.isArray(parsed?.drawingRedlineTasks) ? parsed.drawingRedlineTasks : [];
  const nextDrawingRedlineRecords = Array.isArray(parsed?.drawingRedlineRecords) ? parsed.drawingRedlineRecords : [];
  const nextDrawingRedlineTitleBlockChanges = Array.isArray(parsed?.drawingRedlineTitleBlockChanges) ? parsed.drawingRedlineTitleBlockChanges : [];
  const nextDrawingRedlineAiResults = Array.isArray(parsed?.drawingRedlineAiResults) ? parsed.drawingRedlineAiResults : [];
  const nextDrawingRedlineAnnotationLinks = Array.isArray(parsed?.drawingRedlineAnnotationLinks) ? parsed.drawingRedlineAnnotationLinks : [];
  const nextDrawingOcrTasks = Array.isArray(parsed?.drawingOcrTasks) ? parsed.drawingOcrTasks : [];
  const nextDrawingOcrPages = Array.isArray(parsed?.drawingOcrPages) ? parsed.drawingOcrPages : [];
  const nextDrawingOcrBlocks = Array.isArray(parsed?.drawingOcrBlocks) ? parsed.drawingOcrBlocks : [];
  const nextSpecEntries = Array.isArray(parsed?.specEntries) ? parsed.specEntries : [];
  const nextSpecVersions = Array.isArray(parsed?.specVersions) ? parsed.specVersions : [];
  const nextSpecParameters = Array.isArray(parsed?.specParameters) ? parsed.specParameters : [];
  const nextDrawingSpecParameters = Array.isArray(parsed?.drawingSpecParameters) ? parsed.drawingSpecParameters : [];
  const nextSpecCheckTasks = Array.isArray(parsed?.specCheckTasks) ? parsed.specCheckTasks : [];
  const nextSpecCheckResults = Array.isArray(parsed?.specCheckResults) ? parsed.specCheckResults : [];
  const nextSpecDictionaries = mergeSeededById(
    Array.isArray(parsed?.specDictionaries) ? parsed.specDictionaries : [],
    seedDefaultSpecDictionaries(normalizedProjects),
  );
  const nextSpecDrawingLinks = Array.isArray(parsed?.specDrawingLinks) ? parsed.specDrawingLinks : [];
  const nextSystemEmailSettings = parsed?.systemEmailSettings
    ? normalizeSystemEmailSettings(parsed.systemEmailSettings)
    : seededSystemEmailSettings;
  const nextSystemAiSettings = parsed?.systemAiSettings
    ? normalizeSystemAiSettings(parsed.systemAiSettings)
    : seedDefaultSystemAiSettings();
  const nextSystemApsSettings = parsed?.systemApsSettings
    ? normalizeSystemApsSettings(parsed.systemApsSettings)
    : seedDefaultSystemApsSettings();
  const nextProjectEmailNotificationSettings = mergeSeededById(
    Array.isArray(parsed?.projectEmailNotificationSettings) ? parsed.projectEmailNotificationSettings : [],
    seededProjectEmailNotificationSettings,
  )
    .map(normalizeProjectEmailNotificationSettings)
    .filter((item) => normalizedProjects.some((project) => project.id === item.projectId));
  if (!parsed?.systemEmailSettings) {
    storeHydrationMutated = true;
  }
  if (!parsed?.systemAiSettings) {
    storeHydrationMutated = true;
  }
  if (!parsed?.systemApsSettings) {
    storeHydrationMutated = true;
  }
  const normalizedUsers = nextUsers.map(normalizeUser);
  const previousUsers = users;
  users = normalizedUsers;
  const normalizedWorkflowTemplates = nextWorkflowTemplates.map(normalizeWorkflowTemplate);
  const normalizedWorkflows = nextWorkflows.map(normalizeWorkflowInstance);
  users = previousUsers;

  return {
    projects: normalizedProjects,
    documents: nextDocuments.map(normalizeDocument),
    folders: nextFolders.map(normalizeFolder),
    workflowTemplates: normalizedWorkflowTemplates,
    workflows: normalizedWorkflows,
    users: normalizedUsers,
    projectMembers: nextProjectMembers.map(normalizeProjectMember),
    folderPermissions: nextFolderPermissions.map(normalizeFolderPermission).filter(Boolean),
    auditLogs: nextAuditLogs.map(normalizeAuditLog).filter(Boolean),
    jobs: nextJobs.map(normalizeJob).filter(Boolean),
    modelGeometryExtractionTasks: nextModelGeometryExtractionTasks.map(normalizeModelGeometryExtractionTask).filter(Boolean),
    modelHealthTasks: nextModelHealthTasks.map(normalizeModelHealthTask).filter(Boolean),
    modelHealthRuleResults: nextModelHealthRuleResults.map(normalizeModelHealthRuleResult).filter(Boolean),
    modelHealthAiResults: nextModelHealthAiResults.map(normalizeModelHealthAiResult).filter(Boolean),
    modelHealthRulesets: nextModelHealthRulesets.map(normalizeModelHealthRuleset).filter(Boolean),
    modelHealthFalsePositiveRecords: nextModelHealthFalsePositiveRecords.map(normalizeModelHealthFalsePositiveRecord).filter(Boolean),
    quantityTakeoffTasks: nextQuantityTakeoffTasks.map(normalizeQuantityTakeoffTask).filter(Boolean),
    quantityPropertySnapshots: nextQuantityPropertySnapshots.map(normalizeQuantityPropertySnapshot).filter(Boolean),
    quantitySummaries: nextQuantitySummaries.map(normalizeQuantitySummary).filter(Boolean),
    quantityTemplates: nextQuantityTemplates.map(normalizeQuantityTemplate).filter(Boolean),
    systemEmailSettings: nextSystemEmailSettings,
    projectEmailNotificationSettings: nextProjectEmailNotificationSettings,
    systemAiSettings: nextSystemAiSettings,
    systemApsSettings: nextSystemApsSettings,
    notificationReads: nextNotificationReads.map(normalizeNotificationRead).filter(Boolean),
    modelClashRuns: nextModelClashRuns.map(normalizeModelClashRun).filter(Boolean),
    modelClashRecords: nextModelClashRecords.map(normalizeClashRecord).filter(Boolean),
    modelClashHeatmaps: nextModelClashHeatmaps.map(normalizeHeatmapTask).filter(Boolean),
    modelClashHeatmapCells: nextModelClashHeatmapCells.map(normalizeHeatmapCell).filter(Boolean),
    modelClashHotspots: nextModelClashHotspots.map(normalizeHotspot).filter(Boolean),
    modelDiffTasks: nextModelDiffTasks.map(normalizeModelDiffTask).filter(Boolean),
    modelDiffSnapshots: nextModelDiffSnapshots.map(normalizeModelDiffSnapshot).filter(Boolean),
    modelDiffRecords: nextModelDiffRecords.map(normalizeModelDiffRecord).filter(Boolean),
    modelDiffPropChanges: nextModelDiffPropChanges.map(normalizeModelDiffPropChange).filter(Boolean),
    modelDiffAiSummaries: nextModelDiffAiSummaries.map(normalizeModelDiffAiSummary).filter(Boolean),
    constructionScheduleVersions: nextConstructionScheduleVersions.map(normalizeConstructionScheduleVersion).filter(Boolean),
    constructionScheduleWbsNodes: nextConstructionScheduleWbsNodes.map(normalizeConstructionScheduleWbsNode).filter(Boolean),
    constructionScheduleActivities: nextConstructionScheduleActivities.map(normalizeConstructionScheduleActivity).filter(Boolean),
    constructionSchedulePredecessors: nextConstructionSchedulePredecessors.map(normalizeConstructionSchedulePredecessor).filter(Boolean),
    constructionScheduleMappings: nextConstructionScheduleMappings.map(normalizeConstructionScheduleMapping).filter(Boolean),
    constructionProgressReports: nextConstructionProgressReports.map(normalizeConstructionProgressReport).filter(Boolean),
    constructionScheduleSnapshots: nextConstructionScheduleSnapshots.map(normalizeConstructionScheduleSnapshot).filter(Boolean),
    constructionScheduleAlerts: nextConstructionScheduleAlerts.map(normalizeConstructionScheduleAlert).filter(Boolean),
    drawingPrecheckTasks: nextDrawingPrecheckTasks.map(normalizeDrawingPrecheckTask).filter(Boolean),
    drawingPrecheckResults: nextDrawingPrecheckResults.map(normalizeDrawingPrecheckResult).filter(Boolean),
    drawingExtractionSnapshots: nextDrawingExtractionSnapshots.map(normalizeDrawingExtractionSnapshot).filter(Boolean),
    drawingRuleConfigs: nextDrawingRuleConfigs.map(normalizeDrawingRuleConfig).filter(Boolean),
    drawingPackages: nextDrawingPackages.map(normalizeDrawingPackage).filter(Boolean),
    drawingExpectedItems: nextDrawingExpectedItems.map(normalizeDrawingExpectedItem).filter(Boolean),
    drawingConsistencyConfirmations: nextDrawingConsistencyConfirmations.map(normalizeDrawingConsistencyConfirmation).filter(Boolean),
    drawingRedlineTasks: nextDrawingRedlineTasks.map(normalizeDrawingRedlineTask).filter(Boolean),
    drawingRedlineRecords: nextDrawingRedlineRecords.map(normalizeDrawingRedlineRecord).filter(Boolean),
    drawingRedlineTitleBlockChanges: nextDrawingRedlineTitleBlockChanges.map(normalizeDrawingRedlineTitleBlockChange).filter(Boolean),
    drawingRedlineAiResults: nextDrawingRedlineAiResults.map(normalizeDrawingRedlineAiResult).filter(Boolean),
    drawingRedlineAnnotationLinks: nextDrawingRedlineAnnotationLinks.map(normalizeDrawingRedlineAnnotationLink).filter(Boolean),
    drawingOcrTasks: nextDrawingOcrTasks.map(normalizeDrawingOcrTask).filter(Boolean),
    drawingOcrPages: nextDrawingOcrPages.map(normalizeDrawingOcrPage).filter(Boolean),
    drawingOcrBlocks: nextDrawingOcrBlocks.map(normalizeDrawingOcrBlock).filter(Boolean),
    specEntries: nextSpecEntries.map(normalizeSpecEntry).filter(Boolean),
    specVersions: nextSpecVersions.map(normalizeSpecVersion).filter(Boolean),
    specParameters: nextSpecParameters.map(normalizeSpecParameter).filter(Boolean),
    drawingSpecParameters: nextDrawingSpecParameters.map(normalizeDrawingSpecParameter).filter(Boolean),
    specCheckTasks: nextSpecCheckTasks.map(normalizeSpecCheckTask).filter(Boolean),
    specCheckResults: nextSpecCheckResults.map(normalizeSpecCheckResult).filter(Boolean),
    specDictionaries: nextSpecDictionaries.map(normalizeSpecDictionary).filter(Boolean),
    specDrawingLinks: nextSpecDrawingLinks.map(normalizeSpecDrawingLink).filter(Boolean),
  };
}

function maybeArmPersistFailureForTest(req) {
  const headerName = String(process.env.CDE_FAIL_NEXT_PERSIST_AFTER_HEADER || "").trim().toLowerCase();
  if (headerName && safeText(req.headers[headerName], "")) {
    failNextPersistForTest = true;
  }
}

