async function withStoreTransaction(task) {
  if (storeTransactionDepth > 0) {
    return task();
  }

  const snapshot = currentMutableStoreSnapshot();
  storeTransactionDepth += 1;
  storeTransactionDirty = false;
  try {
    const result = await task();
    storeTransactionDepth -= 1;
    if (storeTransactionDirty) {
      writeStoreNow();
      storeTransactionDirty = false;
    }
    return result;
  } catch (error) {
    storeTransactionDepth = 0;
    storeTransactionDirty = false;
    restoreMutableStoreSnapshot(snapshot);
    throw error;
  }
}

function writeStoreNow() {
  if (failNextPersistForTest) {
    failNextPersistForTest = false;
    throw new Error("Forced persist failure for transaction smoke test");
  }
  pendingDeferredStoreWrite = false;
  storeRepository.write({
    projects,
    documents,
    folders,
    workflowTemplates,
    workflows,
    users,
    projectMembers,
    folderPermissions,
    auditLogs,
    jobs,
    modelGeometryExtractionTasks,
    modelHealthTasks,
    modelHealthRuleResults,
    modelHealthAiResults,
    modelHealthRulesets,
    modelHealthFalsePositiveRecords,
    quantityTakeoffTasks,
    quantityPropertySnapshots,
    quantitySummaries,
    quantityTemplates,
    systemEmailSettings,
    projectEmailNotificationSettings,
    systemAiSettings,
    systemApsSettings,
    notificationReads,
    modelClashRuns,
    modelClashRecords,
    modelClashHeatmaps,
    modelClashHeatmapCells,
    modelClashHotspots,
    modelDiffTasks,
    modelDiffSnapshots,
    modelDiffRecords,
    modelDiffPropChanges,
    modelDiffAiSummaries,
    constructionScheduleVersions,
    constructionScheduleWbsNodes,
    constructionScheduleActivities,
    constructionSchedulePredecessors,
    constructionScheduleMappings,
    constructionProgressReports,
    constructionScheduleSnapshots,
    constructionScheduleAlerts,
    drawingPrecheckTasks,
    drawingPrecheckResults,
    drawingExtractionSnapshots,
    drawingRuleConfigs,
    drawingPackages,
    drawingExpectedItems,
    drawingConsistencyConfirmations,
    drawingRedlineTasks,
    drawingRedlineRecords,
    drawingRedlineTitleBlockChanges,
    drawingRedlineAiResults,
    drawingRedlineAnnotationLinks,
    specEntries,
    specVersions,
    specParameters,
    drawingSpecParameters,
    specCheckTasks,
    specCheckResults,
    specDictionaries,
    specDrawingLinks,
  });
}

function scheduleDeferredStoreWrite() {
  pendingDeferredStoreWrite = true;
  if (deferredStoreWriteScheduled) {
    return;
  }
  deferredStoreWriteScheduled = true;
  setImmediate(() => {
    deferredStoreWriteScheduled = false;
    if (!pendingDeferredStoreWrite) {
      return;
    }
    try {
      writeStoreNow();
    } catch (error) {
      console.error("Deferred store persistence failed:", error);
    }
  });
}

function flushDeferredStoreWrites() {
  if (!pendingDeferredStoreWrite) {
    return;
  }
  writeStoreNow();
}

const localeCollatorCache = new Map();
function localeCollator(locale) {
  const key = String(locale || "");
  let collator = localeCollatorCache.get(key);
  if (!collator) {
    collator = new Intl.Collator(key || undefined);
    localeCollatorCache.set(key, collator);
  }
  return collator;
}

function persistStore() {
  if (storeTransactionDepth > 0) {
    storeTransactionDirty = true;
    return;
  }
  scheduleDeferredStoreWrite();
}

process.on("exit", () => {
  try {
    flushDeferredStoreWrites();
  } catch (error) {
    console.error("Store flush on exit failed:", error);
  }
});

["SIGINT", "SIGTERM"].forEach((signal) => {
  process.once(signal, () => {
    try {
      flushDeferredStoreWrites();
    } catch (error) {
      console.error("Store flush on signal failed:", error);
    } finally {
      process.exit(0);
    }
  });
});

function publicDocuments() {
  return [...documents]
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .map((doc) => toPublicDocument(doc, SYSTEM_USER_CONTEXT));
}

function publicFolders() {
  return [...folders]
    .sort((left, right) => localeCollator("zh-CN").compare(left.name, right.name))
    .map((folder) => toPublicFolder(folder, SYSTEM_USER_CONTEXT));
}

function userById(userId) {
  return users.find((item) => item.id === userId) || null;
}

function userByEmail(email) {
  const normalizedEmail = normalizeEmail(email);
  if (!normalizedEmail) {
    return null;
  }
  return users.find((item) => normalizeEmail(item.email) === normalizedEmail) || null;
}

function userByName(name) {
  const normalizedName = safeText(name, "");
  if (!normalizedName) {
    return null;
  }
  return users.find((item) => safeText(item.name, "") === normalizedName) || null;
}

function normalizeEmail(value) {
  return safeText(value, "").trim().toLowerCase();
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(String(password || ""), String(salt || ""), PASSWORD_HASH_ITERATIONS, PASSWORD_HASH_KEYLEN, "sha512").toString("hex");
}

function issuePasswordCredentials(password, options = {}) {
  const salt = crypto.randomBytes(16).toString("hex");
  const now = new Date().toISOString();
  return {
    passwordSalt: salt,
    passwordHash: hashPassword(password, salt),
    mustChangePassword: options.mustChangePassword !== undefined ? Boolean(options.mustChangePassword) : false,
    passwordUpdatedAt: options.passwordUpdatedAt || now,
    lastLoginAt: safeText(options.lastLoginAt, ""),
  };
}

function verifyUserPassword(user, password) {
  const passwordSalt = safeText(user?.passwordSalt, "");
  const passwordHash = safeText(user?.passwordHash, "");
  if (!passwordSalt || !passwordHash) {
    return false;
  }
  const candidateHash = hashPassword(password, passwordSalt);
  const left = Buffer.from(passwordHash, "hex");
  const right = Buffer.from(candidateHash, "hex");
  if (!left.length || left.length !== right.length) {
    return false;
  }
  return crypto.timingSafeEqual(left, right);
}

function generateTempPassword() {
  const chunk = crypto.randomBytes(4).toString("hex");
  return `Cde@${chunk}`;
}

function sanitizeUserForClient(user) {
  if (!user) {
    return null;
  }
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    avatarUrl: user.avatarUrl,
    status: user.status,
    platformRole: user.platformRole,
    mustChangePassword: Boolean(user.mustChangePassword),
    passwordUpdatedAt: safeText(user.passwordUpdatedAt, ""),
    lastLoginAt: safeText(user.lastLoginAt, ""),
    createdAt: user.createdAt,
    invitedAt: safeText(user.invitedAt, ""),
    larkBinding: userLarkBindingSummary(user),
  };
}

function serializeCookie(name, value, options = {}) {
  const segments = [`${name}=${encodeURIComponent(String(value || ""))}`];
  segments.push(`Path=${options.path || "/"}`);
  if (options.maxAge !== undefined) {
    segments.push(`Max-Age=${Math.max(0, Math.floor(Number(options.maxAge) || 0))}`);
  }
  if (options.httpOnly !== false) {
    segments.push("HttpOnly");
  }
  if (options.sameSite) {
    segments.push(`SameSite=${options.sameSite}`);
  } else {
    segments.push("SameSite=Lax");
  }
  if (options.secure) {
    segments.push("Secure");
  }
  return segments.join("; ");
}

function parseCookies(req) {
  const raw = safeText(req.headers?.cookie, "");
  if (!raw) {
    return {};
  }
  return raw.split(";").reduce((cookies, chunk) => {
    const [name, ...rest] = chunk.split("=");
    const key = String(name || "").trim();
    if (!key) {
      return cookies;
    }
    cookies[key] = decodeCookieValue(rest.join("=").trim());
    return cookies;
  }, {});
}

function decodeCookieValue(value) {
  try {
    return decodeURIComponent(String(value || ""));
  } catch {
    return String(value || "");
  }
}

function parseCookieValues(req, cookieName) {
  const raw = safeText(req.headers?.cookie, "");
  const targetName = safeText(cookieName, "");
  if (!raw || !targetName) {
    return [];
  }
  return raw.split(";").reduce((values, chunk) => {
    const [name, ...rest] = chunk.split("=");
    const key = String(name || "").trim();
    if (key === targetName) {
      values.push(decodeCookieValue(rest.join("=").trim()));
    }
    return values;
  }, []);
}

function serializeSessionCookie(sessionId) {
  return serializeCookie(SESSION_COOKIE_NAME, sessionId, {
    path: "/",
    httpOnly: true,
    sameSite: "Lax",
    maxAge: Math.floor(SESSION_TTL_MS / 1000),
  });
}

function clearSessionCookie() {
  return serializeCookie(SESSION_COOKIE_NAME, "", {
    path: "/",
    httpOnly: true,
    sameSite: "Lax",
    maxAge: 0,
  });
}

function pruneExpiredSessions() {
  const now = Date.now();
  activeSessions.forEach((session, sessionId) => {
    if (!session || Number(session.expiresAt || 0) <= now) {
      activeSessions.delete(sessionId);
    }
  });
}

function projectById(projectId) {
  const normalizedProjectId = safeText(projectId, "");
  if (!normalizedProjectId) {
    return null;
  }
  return projects.find((item) => item.id === normalizedProjectId) || null;
}

function projectsForUser(user) {
  if (!user) {
    return [];
  }
  if (normalizePlatformRole(user.platformRole, "user") === "super_admin") {
    return [...projects];
  }
  const allowedProjectIds = new Set(
    projectMembers
      .filter(
        (item) =>
          item.userId === user.id &&
          !safeText(item.removedAt, "") &&
          safeText(userById(item.userId)?.status, "active") === "active",
      )
      .map((item) => item.projectId),
  );
  return projects.filter((item) => allowedProjectIds.has(item.id));
}

function ensureUserCanAccessProject(user, requestedProjectId = "") {
  const availableProjects = projectsForUser(user);
  if (!availableProjects.length) {
    if (normalizePlatformRole(user?.platformRole, "user") === "super_admin") {
      return null;
    }
    const error = new Error("当前账号尚未加入任何项目。");
    error.statusCode = 403;
    throw error;
  }
  const matchedProject =
    availableProjects.find((item) => item.id === requestedProjectId) ||
    (!requestedProjectId ? availableProjects.find((item) => item.id === DEFAULT_PROJECT_ID) : null) ||
    availableProjects[0];
  if (!matchedProject) {
    const error = new Error("未找到可访问的项目。");
    error.statusCode = 404;
    throw error;
  }
  return matchedProject;
}

function createSession(user, req, options = {}) {
  pruneExpiredSessions();
  const now = Date.now();
  const activeProject = ensureUserCanAccessProject(user, safeText(options.projectId, ""));
  const session = {
    id: crypto.randomUUID(),
    userId: safeText(user?.id, ""),
    activeProjectId: activeProject?.id || "",
    createdAt: now,
    lastSeenAt: now,
    expiresAt: now + SESSION_TTL_MS,
    ip: requestIp(req),
    userAgent: safeText(req.headers["user-agent"], ""),
  };
  activeSessions.set(session.id, session);
  return session;
}

function destroySession(sessionId) {
  if (!sessionId) {
    return;
  }
  activeSessions.delete(sessionId);
}

function touchSession(sessionId) {
  const session = activeSessions.get(sessionId);
  if (!session) {
    return null;
  }
  const now = Date.now();
  session.lastSeenAt = now;
  session.expiresAt = now + SESSION_TTL_MS;
  activeSessions.set(sessionId, session);
  return session;
}

function updateSessionProject(sessionId, projectId) {
  const session = activeSessions.get(sessionId);
  if (!session) {
    return null;
  }
  session.activeProjectId = safeText(projectId, session.activeProjectId);
  session.lastSeenAt = Date.now();
  session.expiresAt = session.lastSeenAt + SESSION_TTL_MS;
  activeSessions.set(sessionId, session);
  return session;
}

function buildUserContext(user, requestedProjectId = "") {
  const resolvedUser = user || userById(DEFAULT_CURRENT_USER_ID) || users.find((item) => item.status === "active") || SYSTEM_USER_CONTEXT.user;
  const project = ensureUserCanAccessProject(resolvedUser, requestedProjectId);
  const member = project ? activeProjectMemberByUserId(resolvedUser.id, project.id) : null;
  const platformRole = normalizePlatformRole(resolvedUser.platformRole, "user");
  const projectRole =
    platformRole === "super_admin" ? "super_admin" : member ? normalizeProjectRole(member.role, "guest") : "guest";
  return {
    project,
    projectId: project?.id || "",
    user: resolvedUser,
    member,
    projectRole,
    isSuperAdmin: platformRole === "super_admin",
  };
}

function requestAuthState(req) {
  if (req.__authState) {
    return req.__authState;
  }

  pruneExpiredSessions();
  const sessionIds = parseCookieValues(req, SESSION_COOKIE_NAME)
    .map((value) => safeText(value, ""))
    .filter(Boolean);
  if (!sessionIds.length) {
    req.__authState = {
      sessionId: "",
      session: null,
      userContext: null,
    };
    return req.__authState;
  }

  let sessionId = "";
  let session = null;
  const now = Date.now();
  for (const candidateSessionId of sessionIds) {
    const candidateSession = activeSessions.get(candidateSessionId);
    if (!candidateSession) {
      continue;
    }
    if (Number(candidateSession.expiresAt || 0) <= now) {
      destroySession(candidateSessionId);
      continue;
    }
    sessionId = candidateSessionId;
    session = candidateSession;
    break;
  }

  if (!session) {
    req.__authState = {
      sessionId: "",
      session: null,
      userContext: null,
    };
    return req.__authState;
  }

  const user = userById(session.userId);
  if (!user || user.status !== "active") {
    destroySession(sessionId);
    req.__authState = {
      sessionId: "",
      session: null,
      userContext: null,
    };
    return req.__authState;
  }

  const nextSession = touchSession(sessionId);
  req.__authState = {
    sessionId,
    session: nextSession,
    userContext: buildUserContext(user, nextSession?.activeProjectId),
  };
  return req.__authState;
}

function isUnsafeHttpMethod(method) {
  return !["GET", "HEAD", "OPTIONS"].includes(String(method || "").toUpperCase());
}

function isOriginGuardExemptApiRequest(pathname, method) {
  return /^\/api\/onlyoffice\/documents\/[^/]+\/callback$/.test(pathname) && method === "POST";
}

function requestHeaderOrigin(value) {
  try {
    return new URL(String(value || "")).origin;
  } catch {
    return "";
  }
}

function enforceApiRequestOrigin(req, pathname) {
  if (!isUnsafeHttpMethod(req.method) || isOriginGuardExemptApiRequest(pathname, req.method)) {
    return;
  }

  const expectedOrigin = requestOrigin(req);
  const origin = requestHeaderOrigin(req.headers.origin);
  if (origin && origin !== expectedOrigin) {
    const error = new Error("跨站请求已被拦截。");
    error.statusCode = 403;
    throw error;
  }

  const referer = requestHeaderOrigin(req.headers.referer);
  if (!origin && referer && referer !== expectedOrigin) {
    const error = new Error("跨站请求已被拦截。");
    error.statusCode = 403;
    throw error;
  }
}

function isPublicApiRequest(pathname, method) {
  if (pathname === "/api/session" && method === "GET") {
    return true;
  }
  if (pathname === "/api/session/login" && method === "POST") {
    return true;
  }
  if (pathname === "/api/session/lark/authorize" && method === "GET") {
    return true;
  }
  if (pathname === "/api/session/lark/callback" && method === "GET") {
    return true;
  }
  if (pathname === "/api/session/logout" && method === "POST") {
    return true;
  }
  if (pathname === "/api/session/project" && method === "POST") {
    return false;
  }
  if (/^\/api\/member-invites\/[^/]+$/.test(pathname) && method === "GET") {
    return true;
  }
  if (/^\/api\/member-invites\/[^/]+\/accept$/.test(pathname) && method === "POST") {
    return true;
  }
  return isOriginGuardExemptApiRequest(pathname, method);
}

function unauthenticatedError(message = "请先登录后再继续。") {
  const error = new Error(message);
  error.statusCode = 401;
  return error;
}

function loginWithPassword(body, req) {
  const email = normalizeEmail(body?.email);
  const password = String(body?.password || "");
  if (!email || !password) {
    const error = new Error("请输入邮箱和密码。");
    error.statusCode = 400;
    throw error;
  }

  assertLoginRateLimit(email, req);
  const user = userByEmail(email);
  if (!user || user.status !== "active" || !verifyUserPassword(user, password)) {
    recordLoginFailure(email, req);
    if (user && user.status === "invited") {
      const error = new Error("该账号尚未激活，请使用邀请链接完成密码设置。", { cause: "invited" });
      error.statusCode = 401;
      throw error;
    }
    const error = new Error("邮箱或密码错误。");
    error.statusCode = 401;
    throw error;
  }

  clearLoginFailures(email, req);
  const initialProject = ensureUserCanAccessProject(user, "");
  const session = createSession(user, req, { projectId: initialProject.id });
  user.lastLoginAt = new Date().toISOString();
  persistStore();
  return { user, session };
}

function normalizeLarkAuthMode(value) {
  return value === "bind" ? "bind" : "login";
}

function isLarkLoginConfigured() {
  return Boolean(LARK_APP_ID && LARK_APP_SECRET);
}

function larkRedirectUri(req) {
  return LARK_REDIRECT_URI || `${requestOrigin(req)}/api/session/lark/callback`;
}

function pruneLarkAuthStates(now = Date.now()) {
  larkAuthStates.forEach((record, key) => {
    if (!record || Number(record.expiresAt || 0) <= now) {
      larkAuthStates.delete(key);
    }
  });
}

function createLarkAuthState(mode, authState = null) {
  pruneLarkAuthStates();
  const now = Date.now();
  const id = crypto.randomUUID().replaceAll("-", "");
  const normalizedMode = normalizeLarkAuthMode(mode);
  const record = {
    id,
    mode: normalizedMode,
    userId: normalizedMode === "bind" ? safeText(authState?.userContext?.user?.id, "") : "",
    sessionId: normalizedMode === "bind" ? safeText(authState?.sessionId, "") : "",
    createdAt: now,
    expiresAt: now + LARK_AUTH_STATE_TTL_MS,
  };
  larkAuthStates.set(id, record);
  return record;
}

function consumeLarkAuthState(stateId) {
  pruneLarkAuthStates();
  const normalizedStateId = safeText(stateId, "");
  if (!normalizedStateId) {
    return null;
  }
  const record = larkAuthStates.get(normalizedStateId) || null;
  larkAuthStates.delete(normalizedStateId);
  if (!record || Number(record.expiresAt || 0) <= Date.now()) {
    return null;
  }
  return record;
}

function buildLarkAuthorizeUrl(req, stateId) {
  const authorizeUrl = new URL(`${LARK_OPEN_BASE_URL}/open-apis/authen/v1/index`);
  authorizeUrl.searchParams.set("app_id", LARK_APP_ID);
  authorizeUrl.searchParams.set("redirect_uri", larkRedirectUri(req));
  authorizeUrl.searchParams.set("state", safeText(stateId, ""));
  return authorizeUrl.toString();
}

function buildLarkResultRedirectUrl(req, options = {}) {
  const redirectUrl = new URL("/", requestOrigin(req));
  const mode = normalizeLarkAuthMode(options.mode);
  const status = options.status === "success" ? "success" : "error";
  const message = safeText(options.message, "");
  if (mode === "login" && status === "success" && !message) {
    return redirectUrl.toString();
  }
  if (mode === "login") {
    redirectUrl.searchParams.set("auth_tab", "lark");
  }
  if (mode === "bind") {
    redirectUrl.searchParams.set("profile", "overview");
  }
  redirectUrl.searchParams.set("lark_mode", mode);
  redirectUrl.searchParams.set("lark_status", status);
  if (message) {
    redirectUrl.searchParams.set("lark_message", message);
  }
  return redirectUrl.toString();
}

function redirectTo(res, location, extraHeaders = {}, statusCode = 302) {
  res.writeHead(statusCode, {
    Location: String(location || "/"),
    "Cache-Control": "no-store",
    ...extraHeaders,
  });
  res.end();
}

function redirectToLarkResult(res, req, mode, status, message, extraHeaders = {}) {
  redirectTo(
    res,
    buildLarkResultRedirectUrl(req, {
      mode,
      status,
      message,
    }),
    extraHeaders,
  );
}

async function fetchLarkApiJson(url, options = {}, fallbackMessage = "飞书服务请求失败。") {
  const response = await fetch(String(url || ""), {
    ...options,
    headers: {
      Accept: "application/json",
      ...(options.headers || {}),
    },
  });
  const payload = await response.json().catch(() => ({}));
  const apiCode = payload && payload.code !== undefined ? Number(payload.code) : 0;
  if (!response.ok || apiCode !== 0) {
    const error = new Error(
      safeText(
        payload?.msg || payload?.message || payload?.error_description || payload?.error || "",
        fallbackMessage,
      ),
    );
    error.statusCode = response.status || 502;
    throw error;
  }
  return payload;
}

async function fetchLarkAppAccessToken() {
  if (!isLarkLoginConfigured()) {
    throw new Error("当前环境尚未配置飞书登录。");
  }
  if (larkAppAccessTokenCache.token && larkAppAccessTokenCache.expiresAt > Date.now() + 60 * 1000) {
    return larkAppAccessTokenCache.token;
  }
  const payload = await fetchLarkApiJson(
    `${LARK_OPEN_BASE_URL}/open-apis/auth/v3/app_access_token/internal`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        app_id: LARK_APP_ID,
        app_secret: LARK_APP_SECRET,
      }),
    },
    "获取飞书应用访问令牌失败。",
  );
  const token = safeText(payload.app_access_token, "");
  if (!token) {
    throw new Error("飞书应用访问令牌为空，请检查应用配置。");
  }
  const expireInSeconds = Math.max(60, Number(payload.expire || 7200) || 7200);
  larkAppAccessTokenCache = {
    token,
    expiresAt: Date.now() + expireInSeconds * 1000,
  };
  return token;
}

function normalizeLarkProfile(data = {}) {
  const value = data && typeof data === "object" ? data : {};
  return {
    openId: safeText(value.open_id, ""),
    unionId: safeText(value.union_id, ""),
    userId: safeText(value.user_id, ""),
    name: safeText(value.name || value.en_name, ""),
    email: normalizeEmail(value.email),
    enterpriseEmail: normalizeEmail(value.enterprise_email),
    avatarUrl: safeUrl(value.avatar_url, ""),
    tenantKey: safeText(value.tenant_key, ""),
  };
}

async function fetchLarkUserProfileByCode(code) {
  const appAccessToken = await fetchLarkAppAccessToken();
  const accessTokenPayload = await fetchLarkApiJson(
    `${LARK_OPEN_BASE_URL}/open-apis/authen/v1/access_token`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${appAccessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        grant_type: "authorization_code",
        code: safeText(code, ""),
        app_id: LARK_APP_ID,
        app_secret: LARK_APP_SECRET,
      }),
    },
    "获取飞书用户访问令牌失败。",
  );
  const accessTokenData = accessTokenPayload.data && typeof accessTokenPayload.data === "object" ? accessTokenPayload.data : {};
  const userAccessToken = safeText(accessTokenData.access_token, "");
  if (!userAccessToken) {
    throw new Error("飞书未返回用户访问令牌，请稍后重试。");
  }

  const userInfoPayload = await fetchLarkApiJson(
    `${LARK_OPEN_BASE_URL}/open-apis/authen/v1/user_info`,
    {
      headers: {
        Authorization: `Bearer ${userAccessToken}`,
      },
    },
    "获取飞书用户信息失败。",
  );
  const userInfoData = userInfoPayload.data && typeof userInfoPayload.data === "object" ? userInfoPayload.data : {};
  const profile = normalizeLarkProfile({
    ...accessTokenData,
    ...userInfoData,
  });
  if (!profile.openId && !profile.unionId) {
    throw new Error("未获取到飞书账号标识，请检查应用权限配置。");
  }
  return profile;
}

function userLarkBindingSummary(user) {
  const record = user && typeof user === "object" ? user : {};
  const email = normalizeEmail(record.larkEmail);
  return {
    bound: Boolean(safeText(record.larkOpenId, "") || safeText(record.larkUnionId, "")),
    openId: safeText(record.larkOpenId, ""),
    unionId: safeText(record.larkUnionId, ""),
    userId: safeText(record.larkUserId, ""),
    name: safeText(record.larkName, ""),
    email,
    avatarUrl: safeUrl(record.larkAvatarUrl, ""),
    tenantKey: safeText(record.larkTenantKey, ""),
    boundAt: safeText(record.larkBoundAt, ""),
  };
}

function userByLarkIdentity(profile) {
  const openId = safeText(profile?.openId, "");
  const unionId = safeText(profile?.unionId, "");
  return (
    users.find((item) => (unionId && safeText(item.larkUnionId, "") === unionId) || (openId && safeText(item.larkOpenId, "") === openId)) ||
    null
  );
}

function bindLarkProfileToUser(user, profile) {
  if (!user) {
    throw unauthenticatedError();
  }
  const existingUser = userByLarkIdentity(profile);
  if (existingUser && existingUser.id !== user.id) {
    const error = new Error("该飞书账号已绑定到其他 CDE 账户，无法重复绑定。");
    error.statusCode = 409;
    throw error;
  }

  user.larkOpenId = safeText(profile.openId, "");
  user.larkUnionId = safeText(profile.unionId, "");
  user.larkUserId = safeText(profile.userId, "");
  user.larkName = safeText(profile.name, "");
  user.larkEmail = normalizeEmail(profile.email || profile.enterpriseEmail);
  user.larkAvatarUrl = safeUrl(profile.avatarUrl, "");
  user.larkTenantKey = safeText(profile.tenantKey, "");
  user.larkBoundAt = new Date().toISOString();
  if (!safeText(user.avatarUrl, "") && user.larkAvatarUrl) {
    user.avatarUrl = user.larkAvatarUrl;
  }
  persistStore();
  return user;
}

function clearLarkBinding(user) {
  if (!user) {
    throw unauthenticatedError();
  }
  const binding = userLarkBindingSummary(user);
  if (!binding.bound) {
    const error = new Error("当前账号还没有绑定飞书。");
    error.statusCode = 400;
    throw error;
  }

  user.larkOpenId = "";
  user.larkUnionId = "";
  user.larkUserId = "";
  user.larkName = "";
  user.larkEmail = "";
  user.larkAvatarUrl = "";
  user.larkTenantKey = "";
  user.larkBoundAt = "";
  persistStore();
  return user;
}

function loginWithLarkProfile(profile, req) {
  let user = userByLarkIdentity(profile);
  let autoBound = false;
  if (!user) {
    const loginEmail = normalizeEmail(profile.email || profile.enterpriseEmail);
    const emailMatchedUser = loginEmail ? userByEmail(loginEmail) : null;
    if (emailMatchedUser && emailMatchedUser.status === "active" && !userLarkBindingSummary(emailMatchedUser).bound) {
      user = bindLarkProfileToUser(emailMatchedUser, profile);
      autoBound = true;
    }
  }

  if (!user) {
    const error = new Error("当前飞书账号尚未绑定 CDE 账户，请先使用账号密码登录后在个人中心完成绑定。");
    error.statusCode = 403;
    throw error;
  }
  if (user.status !== "active") {
    const error = new Error("当前绑定的 CDE 账户不可用，请联系管理员处理。");
    error.statusCode = 403;
    throw error;
  }

  clearLoginFailures(user.email, req);
  const initialProject = ensureUserCanAccessProject(user, "");
  const session = createSession(user, req, { projectId: initialProject.id });
  user.lastLoginAt = new Date().toISOString();
  persistStore();
  return {
    user,
    session,
    autoBound,
  };
}


function loginRateLimitKey(email, req) {
  return `${normalizeEmail(email)}:${requestIp(req) || "unknown"}`;
}

function pruneLoginRateLimits(now = Date.now()) {
  loginRateLimits.forEach((record, key) => {
    const lockedUntil = Number(record.lockedUntil || 0);
    const firstFailureAt = Number(record.firstFailureAt || 0);
    if ((lockedUntil && lockedUntil <= now) || (!lockedUntil && firstFailureAt + LOGIN_RATE_LIMIT_WINDOW_MS <= now)) {
      loginRateLimits.delete(key);
    }
  });
}

function loginRateLimitError(lockedUntil) {
  const retryAfterSeconds = Math.max(1, Math.ceil((Number(lockedUntil || 0) - Date.now()) / 1000));
  const error = new Error("登录失败次数过多，请稍后再试。");
  error.statusCode = 429;
  error.headers = { "Retry-After": String(retryAfterSeconds) };
  return error;
}

function assertLoginRateLimit(email, req) {
  const now = Date.now();
  pruneLoginRateLimits(now);
  const record = loginRateLimits.get(loginRateLimitKey(email, req));
  if (record?.lockedUntil && Number(record.lockedUntil) > now) {
    throw loginRateLimitError(record.lockedUntil);
  }
}

function recordLoginFailure(email, req) {
  const now = Date.now();
  const key = loginRateLimitKey(email, req);
  const existing = loginRateLimits.get(key);
  const withinWindow = existing?.firstFailureAt && Number(existing.firstFailureAt) + LOGIN_RATE_LIMIT_WINDOW_MS > now;
  const failures = withinWindow ? Number(existing.failures || 0) + 1 : 1;
  const lockedUntil = failures >= LOGIN_RATE_LIMIT_MAX_FAILURES ? now + LOGIN_RATE_LIMIT_LOCK_MS : 0;
  loginRateLimits.set(key, {
    failures,
    firstFailureAt: withinWindow ? Number(existing.firstFailureAt) : now,
    lastFailureAt: now,
    lockedUntil,
  });
  if (lockedUntil) {
    throw loginRateLimitError(lockedUntil);
  }
}

function clearLoginFailures(email, req) {
  loginRateLimits.delete(loginRateLimitKey(email, req));
}

function requireExistingUser(userId) {
  const user = userById(userId);
  if (!user) {
    const error = new Error("User not found");
    error.statusCode = 404;
    throw error;
  }
  return user;
}

function resetUserPassword(userId, body, userContext) {
  if (!isProjectAdminRole(userContext?.projectRole) && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以重置成员密码。");
  }
  const user = requireExistingUser(userId);
  const tempPassword = String(body?.tempPassword || "").trim() || generateTempPassword();
  if (tempPassword.length < 8) {
    const error = new Error("临时密码至少需要 8 位。");
    error.statusCode = 400;
    throw error;
  }
  Object.assign(user, issuePasswordCredentials(tempPassword, { mustChangePassword: true }));
  persistStore();
  return { user, tempPassword };
}

function changeOwnPassword(body, userContext) {
  const user = requireExistingUser(safeText(userContext?.user?.id, ""));
  const currentPassword = String(body?.currentPassword || "");
  const nextPassword = String(body?.newPassword || "");
  const confirmPassword = String(body?.confirmPassword || "");
  if (!currentPassword || !nextPassword || !confirmPassword) {
    const error = new Error("请完整填写当前密码、新密码和确认密码。");
    error.statusCode = 400;
    throw error;
  }
  if (!verifyUserPassword(user, currentPassword)) {
    const error = new Error("当前密码不正确。");
    error.statusCode = 400;
    throw error;
  }
  if (nextPassword !== confirmPassword) {
    const error = new Error("两次输入的新密码不一致。");
    error.statusCode = 400;
    throw error;
  }
  if (nextPassword.length < 8) {
    const error = new Error("新密码至少需要 8 位。");
    error.statusCode = 400;
    throw error;
  }
  if (nextPassword === currentPassword) {
    const error = new Error("新密码不能与当前密码相同。");
    error.statusCode = 400;
    throw error;
  }
  Object.assign(user, issuePasswordCredentials(nextPassword, { mustChangePassword: false }));
  user.lastLoginAt = new Date().toISOString();
  persistStore();
  return user;
}

function registerProtectedExportFile(fileName, detail = {}) {
  protectedExportDownloads.set(String(fileName || ""), {
    fileName: String(fileName || ""),
    ...detail,
  });
}

function versionEntryByStoredFileName(fileName) {
  const normalizedFileName = safeText(fileName, "");
  if (!normalizedFileName) {
    return null;
  }
  for (const doc of documents) {
    const versionEntry = (doc.versionHistory || []).find((entry) => !entry.deletedAt && safeText(entry.storedFileName, "") === normalizedFileName);
    if (versionEntry) {
      return { doc, versionEntry };
    }
  }
  return null;
}

function attachmentOwnerByStorageName(fileName) {
  const normalizedFileName = safeText(fileName, "");
  if (!normalizedFileName) {
    return null;
  }
  for (const doc of documents) {
    for (const annotation of doc.annotations || []) {
      const ownAttachment = (annotation.attachments || []).find((attachment) => safeText(attachment.storageName, "") === normalizedFileName);
      if (ownAttachment) {
        return { doc, annotation, reply: null, attachment: ownAttachment };
      }
      for (const reply of annotation.replies || []) {
        const replyAttachment = (reply.attachments || []).find((attachment) => safeText(attachment.storageName, "") === normalizedFileName);
        if (replyAttachment) {
          return { doc, annotation, reply, attachment: replyAttachment };
        }
      }
    }
  }
  return null;
}

function shareRecordActive(shareRecord) {
  if (!shareRecord?.enabled || !shareRecord?.token) {
    return false;
  }
  const expiresAt = safeText(shareRecord.expiresAt, "");
  if (!expiresAt) {
    return true;
  }
  const expiresTime = new Date(`${expiresAt}T23:59:59`).getTime();
  return Number.isFinite(expiresTime) ? expiresTime >= Date.now() : true;
}

function hasValidStoredUploadShare(doc, versionEntry, requestUrl) {
  const shareToken = safeText(requestUrl?.searchParams.get("share"), "");
  const requestedVersion = safeText(requestUrl?.searchParams.get("version"), "");
  if (!shareToken) {
    return false;
  }
  if (shareRecordActive(versionEntry?.share) && versionEntry.share.token === shareToken) {
    return !requestedVersion || requestedVersion === safeText(versionEntry.id, "");
  }
  if (shareRecordActive(doc?.share) && doc.share.token === shareToken) {
    if (!requestedVersion) {
      return true;
    }
    return [safeText(doc.currentVersionId, ""), safeText(versionEntry?.id, ""), safeText(doc.version, "current"), "current"].includes(requestedVersion);
  }
  return false;
}

function assertStoredUploadAccess(fileName, requestUrl, userContext) {
  const match = versionEntryByStoredFileName(fileName);
  if (!match) {
    const error = new Error("File not found");
    error.statusCode = 404;
    throw error;
  }
  if (hasValidStoredUploadShare(match.doc, match.versionEntry, requestUrl)) {
    return match;
  }
  if (hasValidOnlyOfficeUploadSignature(fileName, requestUrl)) {
    return match;
  }
  if (!hasValidStorageSignature("uploads", fileName, requestUrl)) {
    const error = new Error("文件下载链接无效或已过期。");
    error.statusCode = 403;
    throw error;
  }
  if (!userContext) {
    throw unauthenticatedError("请先登录后再访问该文件。");
  }
  if (!documentPermissionsForUser(match.doc, userContext).preview) {
    throw permissionDeniedError("你没有查看该文件的权限。");
  }
  return match;
}

function assertAttachmentAccess(fileName, requestUrl, userContext) {
  if (!hasValidStorageSignature("attachments", fileName, requestUrl)) {
    const error = new Error("附件下载链接无效或已过期。");
    error.statusCode = 403;
    throw error;
  }
  const match = attachmentOwnerByStorageName(fileName);
  if (!match) {
    const error = new Error("Attachment not found");
    error.statusCode = 404;
    throw error;
  }
  if (!userContext) {
    throw unauthenticatedError("请先登录后再访问附件。");
  }
  if (!documentPermissionsForUser(match.doc, userContext).preview) {
    throw permissionDeniedError("你没有查看该附件的权限。");
  }
  return match;
}

function assertProtectedExportAccess(fileName, requestUrl, userContext) {
  if (!hasValidStorageSignature("exports", fileName, requestUrl)) {
    const error = new Error("导出文件下载链接无效或已过期。");
    error.statusCode = 403;
    throw error;
  }
  if (!userContext) {
    throw unauthenticatedError("请先登录后再下载导出文件。");
  }
  const registered = protectedExportDownloads.get(safeText(fileName, ""));
  if (registered?.docIds?.length) {
    registered.docIds.forEach((docId) => {
      const doc = requireDocument(docId, userContext);
      if (!documentPermissionsForUser(doc, userContext).download) {
        throw permissionDeniedError("你没有下载该导出文件的权限。");
      }
    });
    return registered;
  }
  const ownerDoc = documents.find((doc) => safeText(doc.lastExportFileName, "") === safeText(fileName, ""));
  if (ownerDoc) {
    if (!documentPermissionsForUser(ownerDoc, userContext).download) {
      throw permissionDeniedError("你没有下载该导出文件的权限。");
    }
    return ownerDoc;
  }
  for (const workflow of workflows) {
    const linkedDocIds = (workflow.autoExport?.files || [])
      .filter((item) => path.basename(safeText(item.url, "")) === safeText(fileName, ""))
      .map(() => (workflow.fileRefs || []).map((fileRef) => fileRef.docId))
      .flat();
    if (!linkedDocIds.length) {
      continue;
    }
    linkedDocIds.forEach((docId) => {
      const doc = requireDocument(docId, userContext);
      if (!documentPermissionsForUser(doc, userContext).download) {
        throw permissionDeniedError("你没有下载该导出文件的权限。");
      }
    });
    return workflow;
  }
  const error = new Error("Export file not found");
  error.statusCode = 404;
  throw error;
}

function workflowTemplateById(templateId, projectId = "") {
  return workflowTemplates.find(
    (item) =>
      item.id === templateId &&
      (!projectId || safeText(item.projectId, DEFAULT_PROJECT_ID) === projectId),
  ) || null;
}

function workflowById(workflowId, projectId = "") {
  return workflows.find(
    (item) =>
      item.id === workflowId &&
      (!projectId || safeText(item.projectId, DEFAULT_PROJECT_ID) === projectId),
  ) || null;
}

function workflowCurrentStep(workflow) {
  if (!workflow || workflow.status !== "running" || !Array.isArray(workflow.steps) || !workflow.steps.length) {
    return null;
  }
  return workflow.steps[Math.max(0, Math.min(workflow.currentStepIndex, workflow.steps.length - 1))] || null;
}

function workflowIsFinalStep(workflow) {
  return Boolean(workflow && Array.isArray(workflow.steps) && workflow.steps.length && workflow.currentStepIndex >= workflow.steps.length - 1);
}

function workflowReviewerMatches(reviewer, userContext) {
  const actorName = actorDisplayName(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  return (
    safeText(reviewer?.name, "") === actorName ||
    (actorUserId && safeText(reviewer?.userId, "") === actorUserId)
  );
}

function workflowStepPendingReviewerNames(step) {
  return Array.isArray(step?.reviewers)
    ? step.reviewers
        .filter((reviewer) => reviewer.status === "pending")
        .map((reviewer) => safeText(reviewer.name, ""))
        .filter(Boolean)
    : [];
}

function resolveWorkflowTemplateStepReviewers(step, projectId = DEFAULT_PROJECT_ID) {
  const selectors = Array.isArray(step?.reviewers)
    ? step.reviewers.map((item, index) => normalizeWorkflowTemplateReviewerSelector(item, index)).filter(Boolean)
    : [];
  const resolved = [];
  const seen = new Set();

  const pushReviewer = (reviewer) => {
    const key = safeText(reviewer.userId, "") || `label:${safeText(reviewer.name, "")}`;
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    resolved.push(reviewer);
  };

  selectors.forEach((selector) => {
    if (selector.type === "role") {
      if (!isWorkflowApproverRole(selector.role)) {
        return;
      }
      activeProjectMembers(projectId)
        .filter((member) => member.role === selector.role)
        .map((member) => userById(member.userId))
        .filter((user) => user && user.status === "active")
        .forEach((user) => {
          pushReviewer({
            userId: user.id,
            name: user.name,
            selectorType: "role",
            selectorRole: selector.role,
          });
        });
      return;
    }

    const matchedUser =
      userById(safeText(selector.userId, "")) ||
      userByName(safeText(selector.label, "")) ||
      userByEmail(safeText(selector.label, ""));

    if (matchedUser && matchedUser.status === "active") {
      const matchedProjectMember = activeProjectMemberByUserId(matchedUser.id, projectId);
      if (!matchedProjectMember || !isWorkflowApproverRole(matchedProjectMember.role)) {
        return;
      }
      pushReviewer({
        userId: matchedUser.id,
        name: matchedUser.name,
        selectorType: "user",
        selectorRole: "",
      });
    }
  });

  return resolved;
}

function validateWorkflowTemplateRoleInputs(template) {
  const allowedRoles = Array.isArray(template?.allowedRoles) ? template.allowedRoles : [];
  allowedRoles.forEach((item) => {
    const role = workflowTemplateRoleValueFromInput(item);
    if (!role || !isWorkflowStarterRole(role)) {
      const error = new Error("流程模板发起角色只能选择超级管理员、项目管理员或审阅者。");
      error.statusCode = 400;
      throw error;
    }
  });

  const steps = Array.isArray(template?.steps) ? template.steps : [];
  steps.forEach((step, stepIndex) => {
    const reviewers = Array.isArray(step?.reviewers) ? step.reviewers : [];
    reviewers.forEach((reviewer) => {
      const value = reviewer && typeof reviewer === "object" ? reviewer : {};
      const explicitType = safeText(value.type, "");
      const rawValue = typeof reviewer === "string"
        ? safeText(reviewer, "")
        : safeText(value.role || value.label || value.name || value.userId, "");
      const inferredRole = workflowTemplateRoleFromValue(value.role || rawValue);
      const isRoleSelector = explicitType === "role" || (!explicitType && inferredRole);
      if (!isRoleSelector) {
        return;
      }
      const role = workflowTemplateRoleValueFromInput(value.role || rawValue);
      if (!role || !isWorkflowApproverRole(role)) {
        const error = new Error(`步骤 ${stepIndex + 1} 的审批角色只能选择超级管理员、项目管理员或审阅者。`);
        error.statusCode = 400;
        throw error;
      }
    });
  });
}

function validateWorkflowTemplateDefinition(template, options = {}) {
  const requireResolvableReviewers = options.requireResolvableReviewers !== false;
  if (!safeText(template?.name, "")) {
    const error = new Error("流程模板名称不能为空。");
    error.statusCode = 400;
    throw error;
  }
  if (!Array.isArray(template?.steps) || !template.steps.length) {
    const error = new Error("至少需要配置一个流程步骤。");
    error.statusCode = 400;
    throw error;
  }
  const invalidStarterRole = (Array.isArray(template?.allowedRoles) ? template.allowedRoles : []).find((role) => !isWorkflowStarterRole(role));
  if (invalidStarterRole) {
    const error = new Error("流程模板发起角色只能选择超级管理员、项目管理员或审阅者。");
    error.statusCode = 400;
    throw error;
  }

  template.steps.forEach((step, index) => {
    if (!Array.isArray(step.reviewers) || !step.reviewers.length) {
      const error = new Error(`步骤 ${index + 1} 还没有配置审批人。`);
      error.statusCode = 400;
      throw error;
    }
    const invalidReviewerRole = step.reviewers.find((reviewer) => reviewer.type === "role" && !isWorkflowApproverRole(reviewer.role));
    if (invalidReviewerRole) {
      const error = new Error(`步骤 ${index + 1} 的审批角色只能选择超级管理员、项目管理员或审阅者。`);
      error.statusCode = 400;
      throw error;
    }
    const resolvedReviewers = resolveWorkflowTemplateStepReviewers(step, safeText(template?.projectId, DEFAULT_PROJECT_ID));
    if (requireResolvableReviewers && !resolvedReviewers.length) {
      const error = new Error(`步骤 ${index + 1} 没有匹配到有效审批人，请检查角色或成员配置。`);
      error.statusCode = 400;
      throw error;
    }
    if (step.mode === "single" && resolvedReviewers.length !== 1) {
      const error = new Error(`步骤 ${index + 1} 是串联单签，必须且只能解析出 1 名审批人。`);
      error.statusCode = 400;
      throw error;
    }
  });

  if (template.autoExport?.enabled) {
    if (!safeText(template.autoExport.targetFolderId, "") && !safeText(template.autoExport.targetPath, "")) {
      const error = new Error("启用自动导出时，必须配置目标文件夹或目标路径。");
      error.statusCode = 400;
      throw error;
    }
    if (!safeText(template.autoExport.namingRule, "")) {
      const error = new Error("启用自动导出时，必须配置命名规则。");
      error.statusCode = 400;
      throw error;
    }
    if (!template.autoExport.exportReviewedFile && !template.autoExport.exportApprovalReport) {
      const error = new Error("自动导出至少需要选择一种导出内容。");
      error.statusCode = 400;
      throw error;
    }
  }

  return template;
}

function workflowSummaryCounts(workflow) {
  return (workflow.steps || []).reduce(
    (summary, step) => {
      step.reviewers.forEach((reviewer) => {
        if (reviewer.status === "approved") {
          summary.approved += 1;
        } else if (reviewer.status === "rejected") {
          summary.rejected += 1;
        } else if (reviewer.status === "pending") {
          summary.pending += 1;
        }
      });
      return summary;
    },
    { approved: 0, rejected: 0, pending: 0 },
  );
}

function workflowVisibleForUser(workflow, userContext) {
  if (!workflow) {
    return false;
  }
  if (safeText(workflow.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    return false;
  }
  if (isProjectAdminRole(safeText(userContext?.projectRole, "guest")) || isSuperAdmin(userContext)) {
    return true;
  }
  const actorName = actorDisplayName(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  if (
    safeText(workflow.initiator, "") === actorName ||
    (actorUserId && safeText(workflow.initiatorUserId, "") === actorUserId)
  ) {
    return true;
  }
  if (
    (workflow.steps || []).some((step) => step.reviewers.some((reviewer) => workflowReviewerMatches(reviewer, userContext)))
  ) {
    return true;
  }
  return (workflow.fileRefs || []).some((fileRef) => {
    const doc = documents.find((item) => item.id === fileRef.docId);
    return doc
      ? permissionRank(folderFilePermissionLevel(doc.parentId, userContext)) >= permissionRank("viewer")
      : false;
  });
}

function workflowPermissionsForInstance(workflow, userContext) {
  const visible = workflowVisibleForUser(workflow, userContext);
  const isAdmin = isProjectAdminRole(safeText(userContext?.projectRole, "guest")) || isSuperAdmin(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  const actorName = actorDisplayName(userContext);
  const currentStep = workflowCurrentStep(workflow);
  const currentStepReviewer = Boolean(
    currentStep &&
      currentStep.reviewers.some(
        (reviewer) => reviewer.status === "pending" && workflowReviewerMatches(reviewer, userContext),
      ),
  );
  const isInitiator =
    safeText(workflow.initiator, "") === actorName ||
    (actorUserId && safeText(workflow.initiatorUserId, "") === actorUserId);

  return {
    visible,
    run: visible && workflow.status === "running" && (isAdmin || currentStepReviewer),
    withdraw: visible && workflow.status === "running" && (isAdmin || isInitiator),
    currentStepReviewer,
    isFinalStep: workflowIsFinalStep(workflow),
    manageTemplates: isAdmin,
  };
}

function workflowFileRefFromDocument(doc, versionId = "") {
  const resolvedVersionId = safeText(versionId, doc.currentVersionId);
  return normalizeWorkflowFileRef({
    docId: doc.id,
    versionId: resolvedVersionId,
    name: doc.name,
    version: doc.version,
    parentId: doc.parentId,
    folderPath: folderPathLabel(doc.parentId),
    mimeType: doc.mimeType,
    size: doc.size,
    status: doc.status,
    exportUrl: doc.lastExportFileName ? signedExportUrl(doc.lastExportFileName) : "",
  });
}

function resolveWorkflowTemplateForLaunch(body, fallbackDoc = null, userContext = SYSTEM_USER_CONTEXT) {
  const project = userContext?.project || projectById(userContext?.projectId) || seedDefaultProject();
  const templateId = safeText(body.templateId, "");
  if (templateId) {
    const template = workflowTemplateById(templateId, project.id);
    if (!template) {
      const error = new Error("未找到所选流程模板。");
      error.statusCode = 404;
      throw error;
    }
    return template;
  }

  return normalizeWorkflowTemplate({
    id: "",
    category: "临时流程",
    projectId: project.id,
    projectName: project.name,
    name: safeText(body.templateName || body.workflowName, fallbackDoc?.workflowName || "临时流程"),
    description: "由兼容旧入口自动生成的串联流程。",
    enabled: true,
    allowedRoles: ["super_admin", "project_admin", "reviewer"],
    autoExport: {
      enabled: false,
      targetFolderId: "",
      targetPath: "",
      namingRule: "",
    },
    steps: [
      {
        name: "1st review",
        mode: "single",
        reviewers: [safeText(body.reviewer, fallbackDoc?.reviewer || "初审人")],
        dueDays: 2,
      },
      {
        name: "final review",
        mode: "single",
        reviewers: [safeText(body.approver, fallbackDoc?.approver || "总工")],
        dueDays: 2,
      },
    ],
  });
}

function workflowDueDateFromTemplate(template) {
  const totalDays = (template.steps || []).reduce((sum, step) => sum + Math.max(1, Number(step.dueDays || 1) || 1), 0);
  const nextDate = new Date();
  nextDate.setDate(nextDate.getDate() + Math.max(1, totalDays));
  return nextDate.toISOString().slice(0, 10);
}

function syncDocumentFromWorkflowInstance(doc, workflow) {
  if (!doc || !workflow) {
    return doc;
  }

  const firstStep = workflow.steps?.[0] || null;
  const lastStep = workflow.steps?.[workflow.steps.length - 1] || null;
  doc.workflowName = safeText(workflow.workflowName, doc.workflowName);
  doc.initiator = safeText(workflow.initiator, doc.initiator);
  doc.reviewer = firstStep?.reviewers.map((reviewer) => reviewer.name).filter(Boolean).join(" / ") || doc.reviewer;
  doc.approver = lastStep?.reviewers.map((reviewer) => reviewer.name).filter(Boolean).join(" / ") || doc.approver;
  doc.dueDate = safeText(workflow.dueDate, doc.dueDate || defaultDueDate());
  doc.activeWorkflowId = workflow.status === "running" ? workflow.id : "";
  doc.workflowIds = Array.from(new Set([...(Array.isArray(doc.workflowIds) ? doc.workflowIds : []), workflow.id].filter(Boolean)));

  if (workflow.status === "withdrawn") {
    doc.status = "uploaded";
    return doc;
  }
  if (workflow.status === "rejected") {
    doc.status = "rejected";
    return doc;
  }
  if (workflow.status === "approved") {
    doc.status = "approved";
    return doc;
  }

  doc.status = workflowIsFinalStep(workflow) ? "final_review" : "in_review";
  return doc;
}

function syncDocumentsFromWorkflowInstance(workflow) {
  (workflow.fileRefs || []).forEach((fileRef) => {
    const doc = documents.find((item) => item.id === fileRef.docId);
    if (doc) {
      syncDocumentFromWorkflowInstance(doc, workflow);
    }
  });
}

function sanitizeWorkflowExportSegment(value, fallback = "export") {
  const cleaned = safeText(value, "")
    .replace(/[\\/:*?"<>|]+/g, "_")
    .replace(/[+＋]/g, "_")
    .replace(/\s+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return cleaned || fallback;
}

function buildWorkflowAutoExportBaseName(workflow, namingRule = "") {
  const createdDate = safeText(workflow?.createdAt, "").slice(0, 10).replace(/-/g, "") || new Date().toISOString().slice(0, 10).replace(/-/g, "");
  const replacements = [
    ["流程发起时间", createdDate],
    ["审核流程名称", safeText(workflow?.workflowName, "审批流程")],
    ["流程名称", safeText(workflow?.workflowName, "审批流程")],
    ["发起人", safeText(workflow?.initiator, "系统")],
  ];
  let rendered = safeText(namingRule, "") || "流程发起时间 + 审核流程名称 + 发起人";
  replacements.forEach(([token, replacement]) => {
    rendered = rendered.replaceAll(token, replacement);
  });
  return sanitizeWorkflowExportSegment(rendered, `workflow_${safeText(workflow?.id, crypto.randomUUID())}`);
}

function workflowAutoExportTargetPath(targetFolderId, targetPath = "", projectId = DEFAULT_PROJECT_ID) {
  const project = projectById(projectId) || seedDefaultProject();
  if (targetFolderId) {
    const folderPath = folderPathLabel(targetFolderId);
    return folderPath ? `/${project.name}/${folderPath}` : `/${project.name}`;
  }
  return safeText(targetPath, "");
}

function ensureFolderPathByLabel(pathLabel, projectId = DEFAULT_PROJECT_ID) {
  const project = projectById(projectId) || seedDefaultProject();
  const rawPath = safeText(pathLabel, "");
  if (!rawPath) {
    return null;
  }
  const segments = rawPath
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean);
  if (segments[0] === project.name) {
    segments.shift();
  }
  let parentId = null;
  segments.forEach((segment) => {
    let folder = folders.find(
      (item) =>
        safeText(item.projectId, DEFAULT_PROJECT_ID) === project.id &&
        item.parentId === parentId &&
        item.name.toLowerCase() === segment.toLowerCase(),
    );
    if (!folder) {
      folder = normalizeFolder({
        id: crypto.randomUUID(),
        projectId: project.id,
        name: segment,
        parentId,
        owner: "系统",
        accessLevel: "view",
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
      folders.push(folder);
      touchFolder(parentId);
      storeHydrationMutated = true;
    }
    parentId = folder.id;
  });
  return parentId;
}

function ensureWorkflowAutoExportTargetFolder(config) {
  const explicitFolderId = safeText(config?.targetFolderId, "");
  if (explicitFolderId) {
    const existing = folders.find((item) => item.id === explicitFolderId);
    if (existing) {
      return explicitFolderId;
    }
  }
  return ensureFolderPathByLabel(config?.targetPath, safeText(config?.projectId, DEFAULT_PROJECT_ID));
}

function resolveWorkflowExportDestination(workflow, fallbackSegments = []) {
  const projectId = safeText(workflow?.projectId, DEFAULT_PROJECT_ID);
  const project = projectById(projectId) || seedDefaultProject();
  let targetFolderId = ensureWorkflowAutoExportTargetFolder({
    ...workflow?.autoExport,
    projectId,
  });

  if (!targetFolderId) {
    const primaryDocId = safeText(workflow?.fileRefs?.[0]?.docId, "");
    const primaryDoc = primaryDocId ? documents.find((item) => item.id === primaryDocId) : null;
    if (primaryDoc?.parentId) {
      targetFolderId = primaryDoc.parentId;
    }
  }

  if (!targetFolderId) {
    const fallbackPath = `/${[project.name, ...fallbackSegments].filter(Boolean).join("/")}`;
    targetFolderId = ensureFolderPathByLabel(fallbackPath, projectId);
  }

  return {
    targetFolderId: targetFolderId || "",
    targetPath: workflowAutoExportTargetPath(targetFolderId, workflow?.autoExport?.targetPath, projectId),
  };
}

async function createWorkflowAutoExportDocument(outputPath, options = {}) {
  const buffer = fs.readFileSync(outputPath);
  const workflow = options.workflow;
  const sourceDoc = options.sourceDoc || null;
  const created = await createDocument({
    projectId: safeText(options.projectId, safeText(workflow?.projectId, DEFAULT_PROJECT_ID)),
    name: options.name,
    dataBase64: buffer.toString("base64"),
    size: buffer.length,
    mimeType: "application/pdf",
    parentId: options.parentId || null,
    actor: "系统",
    owner: safeText(workflow?.initiator, "系统"),
    accessLevel: "view",
    downloadScope: "team",
    watermarkEnabled: false,
    conflictMode: "rename",
    note: safeText(options.note, "自动导出"),
  }, SYSTEM_USER_CONTEXT);

  created.status = "approved";
  created.workflowName = safeText(workflow?.workflowName, created.workflowName);
  created.initiator = safeText(workflow?.initiator, created.initiator);
  created.reviewer = workflow?.steps?.[0]?.reviewers?.map((reviewer) => reviewer.name).filter(Boolean).join(" / ") || created.reviewer;
  created.approver = workflow?.steps?.[workflow.steps.length - 1]?.reviewers?.map((reviewer) => reviewer.name).filter(Boolean).join(" / ") || created.approver;
  created.dueDate = safeText(workflow?.dueDate, created.dueDate || "");
  created.activeWorkflowId = "";
  created.workflowIds = Array.from(new Set([...(Array.isArray(created.workflowIds) ? created.workflowIds : []), safeText(workflow?.id, "")].filter(Boolean)));
  if (options.kind === "approval_record") {
    created.remarks = `流程 ${safeText(workflow?.workflowName, "审批流程")} 审批记录单`;
  }
  touchDocument(created);
  addActivity(
    created,
    "系统",
    "自动导出",
    options.kind === "approval_record"
      ? `流程 ${safeText(workflow?.workflowName, "审批流程")} 已生成审批记录单`
      : `流程 ${safeText(workflow?.workflowName, "审批流程")} 已生成审阅归档文件${sourceDoc ? ` · ${sourceDoc.name}` : ""}`,
  );
  persistStore();
  return created;
}

function prependWorkflowExportFile(workflow, file) {
  const normalized = file && typeof file === "object" ? file : null;
  if (!normalized?.url) {
    return;
  }
  const existing = Array.isArray(workflow?.autoExport?.files) ? workflow.autoExport.files : [];
  workflow.autoExport.files = [
    normalized,
    ...existing.filter((item) => safeText(item?.id, "") !== safeText(normalized.id, "")),
  ];
}

async function runWorkflowAutoExportJob(workflow, job = null) {
  if (!workflow?.autoExport?.enabled) {
    return workflow;
  }

  const exportedFiles = [];
  const failedFiles = [];
  const targetFolderId = ensureWorkflowAutoExportTargetFolder({
    ...workflow.autoExport,
    projectId: safeText(workflow?.projectId, DEFAULT_PROJECT_ID),
  });
  const targetPath = workflowAutoExportTargetPath(
    targetFolderId,
    workflow.autoExport.targetPath,
    safeText(workflow?.projectId, DEFAULT_PROJECT_ID),
  );
  const exportBaseName = buildWorkflowAutoExportBaseName(workflow, workflow.autoExport.namingRule);
  workflow.autoExport.status = "idle";
  workflow.autoExport.error = "";
  workflow.autoExport.targetFolderId = targetFolderId || "";
  workflow.autoExport.targetPath = targetPath;

  if (!targetFolderId && !targetPath) {
    workflow.autoExport.status = "failed";
    workflow.autoExport.error = "未找到自动导出的目标路径。";
    return workflow;
  }

  if (workflow.autoExport.exportReviewedFile) {
    for (const fileRef of workflow.fileRefs || []) {
      const doc = documents.find((item) => item.id === fileRef.docId);
      if (!doc) {
        continue;
      }
      if (!doc.isPdf) {
        failedFiles.push(`${doc.name}: 仅 PDF 文件支持自动导出审阅版。`);
        continue;
      }
      try {
        const tempOutputPath = path.join(EXPORTS_DIR, `${doc.id}-${Date.now()}-${crypto.randomUUID().slice(0, 6)}.pdf`);
        await runExportScript(doc, tempOutputPath);
        const createdDoc = await createWorkflowAutoExportDocument(tempOutputPath, {
          workflow,
          projectId: workflow.projectId,
          sourceDoc: doc,
          parentId: targetFolderId,
          kind: "reviewed_pdf",
          name: `${exportBaseName}_${sanitizeWorkflowExportSegment(path.parse(doc.name).name || doc.name, "reviewed")}_审阅版.pdf`,
          note: `流程 ${workflow.workflowName} 自动导出审阅版`,
        });
        touchDocument(doc);
        addActivity(doc, "系统", "自动导出", `流程 ${workflow.workflowName} 审批完成后自动导出了审阅版本 ${doc.name}`);
        exportedFiles.push({
          id: crypto.randomUUID(),
          name: createdDoc.name,
          url: signedUploadUrl(createdDoc.storedFileName),
          type: "pdf",
          kind: "reviewed_pdf",
          documentId: createdDoc.id,
          targetFolderId: targetFolderId || "",
          targetPath,
          sourceDocId: doc.id,
        });
      } catch (error) {
        failedFiles.push(`${doc.name}: ${error.message}`);
      }
    }
  }

  if (workflow.autoExport.exportApprovalReport) {
    try {
      const reportOutputPath = path.join(EXPORTS_DIR, `workflow-report-${workflow.id}-${Date.now()}-${crypto.randomUUID().slice(0, 6)}.pdf`);
      await runWorkflowReportExportScript(workflow, reportOutputPath);
      const createdReport = await createWorkflowAutoExportDocument(reportOutputPath, {
        workflow,
        projectId: workflow.projectId,
        parentId: targetFolderId,
        kind: "approval_record",
        name: `${exportBaseName}_审批记录单.pdf`,
        note: `流程 ${workflow.workflowName} 自动导出审批记录单`,
      });
      exportedFiles.push({
        id: crypto.randomUUID(),
        name: createdReport.name,
        url: signedUploadUrl(createdReport.storedFileName),
        type: "pdf",
        kind: "approval_record",
        documentId: createdReport.id,
        targetFolderId: targetFolderId || "",
        targetPath,
        sourceDocId: "",
      });
    } catch (error) {
      failedFiles.push(`审批记录单: ${error.message}`);
    }
  }

  workflow.autoExport.files = exportedFiles;
  workflow.autoExport.lastRunAt = new Date().toISOString();
  if (failedFiles.length) {
    workflow.autoExport.status = "failed";
    workflow.autoExport.error = failedFiles.join("；");
  } else {
    workflow.autoExport.status = "success";
    workflow.autoExport.error = "";
  }
  return workflow;
}

function waitMs(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function scheduleAsyncJob(job) {
  if (!job) {
    return;
  }
  if (["canceled", "succeeded"].includes(safeText(job.status, ""))) {
    return;
  }
  const nextRunAt = Date.parse(safeText(job.nextRunAt, ""));
  const dueDelayMs = Number.isFinite(nextRunAt) ? Math.max(0, nextRunAt - Date.now()) : 0;
  const delayMs = Math.max(dueDelayMs, job.type === "quantity.takeoff" ? CDE_QUANTITY_TAKEOFF_JOB_START_DELAY_MS : 0);
  setTimeout(() => {
    if (["canceled", "succeeded"].includes(safeText(job.status, ""))) {
      return;
    }
    void processJob(job).catch((error) => {
      console.error("[job]", error);
    });
  }, delayMs);
}

function resumeRecoverableBackgroundJobs() {
  let mutated = false;
  jobs
    .filter((job) => ["quantity.takeoff", "model.health", "model.diff", "drawing.redline", "drawing.ocr"].includes(job.type) && ["queued", "running"].includes(job.status))
    .forEach((job) => {
      job.status = "queued";
      job.nextRunAt = "";
      job.updatedAt = new Date().toISOString();
      if (job.type === "quantity.takeoff") {
        const task = quantityTaskById(job.payload?.taskId);
        if (task && ["queued", "running"].includes(task.status)) {
          task.status = "queued";
          task.updatedAt = job.updatedAt;
        }
      }
      if (job.type === "model.health") {
        const task = modelHealthTaskById(job.payload?.taskId);
        if (task && ["queued", "checking", "ai_analyzing"].includes(task.status)) {
          task.status = "queued";
          task.updatedAt = job.updatedAt;
        }
      }
      if (job.type === "model.diff") {
        const task = modelDiffTaskById(job.payload?.taskId);
        if (task && ["queued", "extracting", "comparing", "ai_analyzing"].includes(task.status)) {
          task.status = "queued";
          task.updatedAt = job.updatedAt;
        }
      }
      if (job.type === "drawing.redline") {
        const task = drawingRedlineTaskById(job.payload?.taskId);
        if (task && ["queued", "rendering", "detecting", "ai_analyzing"].includes(task.status)) {
          task.status = "queued";
          task.progress = 5;
          task.updatedAt = job.updatedAt;
        }
      }
      if (job.type === "drawing.ocr") {
        const task = drawingOcrTaskById(job.payload?.taskId);
        if (task && ["queued", "processing", "indexing"].includes(task.status)) {
          task.status = "queued";
          task.progress = 5;
          task.updatedAt = job.updatedAt;
        }
      }
      mutated = true;
      scheduleAsyncJob(job);
    });
  if (mutated) {
    persistStore();
  }
}

function quantityTaskById(taskId) {
  const id = safeText(taskId, "");
  return quantityTakeoffTasks.find((task) => task.id === id) || null;
}

function quantityTemplateById(templateId, projectId = DEFAULT_PROJECT_ID) {
  const id = safeText(templateId, "");
  return quantityTemplates.find(
    (template) =>
      template.id === id &&
      safeText(template.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID),
  ) || null;
}

function quantityTasksForDocument(doc) {
  return quantityTakeoffTasks
    .filter((task) => task.documentId === doc.id)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")));
}

function activeQuantityTakeoffTaskForDocument(doc) {
  return quantityTasksForDocument(doc).find((task) => ["queued", "running"].includes(task.status)) || null;
}

function quantityTakeoffJobForTask(taskId) {
  const id = safeText(taskId, "");
  return jobs.find((job) => job.type === "quantity.takeoff" && job.payload?.taskId === id && ["queued", "running", "canceled"].includes(job.status)) || null;
}

function quantitySnapshotsForTask(taskId) {
  const id = safeText(taskId, "");
  return quantityPropertySnapshots.filter((snapshot) => snapshot.taskId === id);
}

function quantitySummariesForTask(taskId) {
  const id = safeText(taskId, "");
  return quantitySummaries.filter((summary) => summary.taskId === id);
}

function latestQuantityTaskForDocument(doc) {
  return quantityTasksForDocument(doc).find((task) => task.status === "succeeded") || quantityTasksForDocument(doc)[0] || null;
}

function quantityTakeoffDocumentCandidate(doc) {
  return Boolean(doc && isApsModelDocument(doc.name) && apsDocumentWorkspaceKind(doc.name) === "model");
}

function quantityTakeoffDocumentsForUser(userContext) {
  return publicDocumentsForUser(userContext)
    .filter(quantityTakeoffDocumentCandidate)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      version: doc.version,
      currentVersionId: doc.currentVersionId,
      updatedAt: doc.updatedAt,
      aps: doc.aps,
    }));
}

function resolveQuantityTaskForDocument(doc, taskId = "") {
  if (taskId) {
    const task = quantityTaskById(taskId);
    return task && task.documentId === doc.id ? task : null;
  }
  return latestQuantityTaskForDocument(doc);
}

function resolveQuantityTakeoffConfig(doc, options = {}) {
  const template = quantityTemplateById(options.templateId, doc.projectId) || null;
  return normalizeTakeoffTemplate({
    ...(template?.config || {}),
    ...(options.config && typeof options.config === "object" ? options.config : {}),
    fields: options.fields !== undefined ? options.fields : options.config?.fields ?? template?.config?.fields,
    filters: {
      ...(template?.config?.filters || {}),
      ...(options.config?.filters || {}),
      ...(options.filters || {}),
    },
    groupBy: options.groupBy || options.config?.groupBy || template?.config?.groupBy,
    name: safeText(options.name, template?.name || options.config?.name || "工程量统计"),
  });
}

function assertQuantityTakeoffCapability(doc, userContext, options = {}) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该模型工程量的权限。");
  }
  if (!isApsModelDocument(doc.name) || apsDocumentWorkspaceKind(doc.name) !== "model") {
    const error = new Error("当前文件类型不支持 APS 工程量统计。");
    error.statusCode = 400;
    throw error;
  }
  if (!apsSettingsReady() && !options.skipApsSettings) {
    const error = new Error("APS 服务尚未配置完整，请先到系统设置 / APS 配置填写 Client ID 和 Client Secret。");
    error.statusCode = 400;
    throw error;
  }
  const translationStatus = normalizeApsTranslationStatus(doc.aps?.translationStatus, doc.aps?.urn ? "success" : "idle");
  if (!doc.aps?.urn || translationStatus !== "success") {
    const error = new Error("所选模型尚未完成 APS 转换，不能发起工程量提取。");
    error.statusCode = 400;
    throw error;
  }
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("你没有发起工程量提取任务的权限。");
  }
}

function quantityFixturePayloadAllowed() {
  return String(process.env.CDE_ALLOW_QUANTITY_FIXTURE_PAYLOAD || "").trim() === "1";
}

function assertQuantityPayloadBoundary(options = {}) {
  if (!options.propertiesPayload) {
    return;
  }
  if (quantityFixturePayloadAllowed()) {
    return;
  }
  const error = new Error("测试属性载荷仅允许在 CDE_ALLOW_QUANTITY_FIXTURE_PAYLOAD=1 的测试环境使用。");
  error.statusCode = 400;
  throw error;
}

function createQuantityTemplate(body, userContext) {
  const now = new Date().toISOString();
  const template = normalizeQuantityTemplate({
    id: crypto.randomUUID(),
    projectId: safeText(userContext?.projectId, DEFAULT_PROJECT_ID),
    name: safeText(body.name, "工程量模板"),
    description: safeText(body.description, ""),
    config: body.config || body,
    createdBy: actorDisplayName(userContext),
    createdAt: now,
    updatedAt: now,
  });
  quantityTemplates.unshift(template);
  persistStore();
  return template;
}

function updateQuantityTemplate(templateId, body, userContext) {
  const template = quantityTemplateById(templateId, userContext.projectId);
  if (!template) {
    const error = new Error("Quantity template not found");
    error.statusCode = 404;
    throw error;
  }
  const next = normalizeQuantityTemplate({
    ...template,
    ...body,
    projectId: template.projectId,
    config: {
      ...(template.config || {}),
      ...(body.config || {}),
      fields: body.fields !== undefined ? body.fields : body.config?.fields ?? template.config?.fields,
      filters: {
        ...(template.config?.filters || {}),
        ...(body.config?.filters || {}),
        ...(body.filters || {}),
      },
      groupBy: body.groupBy || body.config?.groupBy || template.config?.groupBy,
    },
    updatedAt: new Date().toISOString(),
  });
  Object.assign(template, next);
  persistStore();
  return template;
}

function enqueueQuantityTakeoffJob(doc, options = {}) {
  if (!doc?.aps?.urn && !options.modelUrn) {
    return null;
  }
  const existing = activeQuantityTakeoffTaskForDocument(doc);
  if (existing && !options.force) {
    return quantityTakeoffJobForTask(existing.id);
  }

  const now = new Date().toISOString();
  const config = resolveQuantityTakeoffConfig(doc, options);
  const task = normalizeQuantityTakeoffTask({
    id: crypto.randomUUID(),
    documentId: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    modelUrn: safeText(options.modelUrn, doc.aps?.urn || ""),
    versionId: safeText(options.versionId, doc.currentVersionId),
    version: safeText(options.version, doc.version),
    status: "queued",
    config,
    createdBy: safeText(options.actor, "系统"),
    createdAt: now,
    updatedAt: now,
  });
  quantityTakeoffTasks.unshift(task);
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    quantityTakeoff: {
      latestTaskId: task.id,
      status: task.status,
      updatedAt: now,
    },
  });

  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "quantity.takeoff",
    status: "queued",
    resourceType: "document",
    resourceId: doc.id,
    payload: {
      taskId: task.id,
      documentId: doc.id,
      actor: safeText(options.actor, "系统"),
      actorUserId: safeText(options.actorUserId, ""),
      propertiesPayload: options.propertiesPayload || null,
    },
    attempts: 0,
    maxAttempts: Math.max(1, Number(options.maxAttempts || CDE_BACKGROUND_JOB_MAX_ATTEMPTS) || CDE_BACKGROUND_JOB_MAX_ATTEMPTS),
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  touchDocument(doc);
  addActivity(doc, safeText(options.actor, "系统"), "工程量提取排队", `${doc.name} ${task.version} 已加入工程量统计队列`);
  persistStore();
  return job;
}

function cancelQuantityTakeoffTask(doc, taskId, options = {}) {
  const task = quantityTaskById(taskId);
  if (!task || task.documentId !== doc.id) {
    const error = new Error("工程量任务不存在。");
    error.statusCode = 404;
    throw error;
  }
  if (!["queued", "running"].includes(task.status)) {
    const error = new Error("只有排队中或运行中的工程量任务可以取消。");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  task.status = "canceled";
  task.error = safeText(options.reason, "用户取消工程量提取");
  task.updatedAt = now;
  const job = quantityTakeoffJobForTask(task.id);
  if (job) {
    job.status = "canceled";
    job.error = task.error;
    job.updatedAt = now;
  }
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    quantityTakeoff: {
      latestTaskId: task.id,
      status: task.status,
      error: task.error,
      updatedAt: now,
    },
  });
  addActivity(doc, safeText(options.actor, "系统"), "取消工程量统计", task.error);
  persistStore();
  return task;
}

function retryQuantityTakeoffTask(doc, taskId, options = {}) {
  const task = quantityTaskById(taskId);
  if (!task || task.documentId !== doc.id) {
    const error = new Error("工程量任务不存在。");
    error.statusCode = 404;
    throw error;
  }
  return enqueueQuantityTakeoffJob(doc, {
    ...options,
    config: {
      ...(task.config || {}),
      ...(options.config && typeof options.config === "object" ? options.config : {}),
    },
    modelUrn: safeText(options.modelUrn, task.modelUrn || doc.aps?.urn || ""),
    versionId: safeText(options.versionId, task.versionId || doc.currentVersionId),
    version: safeText(options.version, task.version || doc.version),
    force: true,
  });
}

function replaceQuantityResults(task, snapshots, summaries) {
  quantityPropertySnapshots = quantityPropertySnapshots.filter((snapshot) => snapshot.taskId !== task.id);
  quantitySummaries = quantitySummaries.filter((summary) => summary.taskId !== task.id);
  quantityPropertySnapshots.unshift(
    ...snapshots.map((snapshot) =>
      normalizeQuantityPropertySnapshot({
        ...snapshot,
        id: crypto.randomUUID(),
        taskId: task.id,
      }),
    ).filter(Boolean),
  );
  quantitySummaries.unshift(
    ...summaries.map((summary) =>
      normalizeQuantitySummary({
        ...summary,
        id: crypto.randomUUID(),
        taskId: task.id,
      }),
    ),
  );
}

async function runQuantityTakeoffJob(doc, task, job) {
  const now = new Date().toISOString();
  task.status = "running";
  task.error = "";
  task.updatedAt = now;
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    quantityTakeoff: {
      latestTaskId: task.id,
      status: task.status,
      updatedAt: now,
    },
  });
  persistStore();

  if (task.status === "canceled" || job.status === "canceled") {
    return task;
  }
  const propertiesPayload =
    job.payload?.propertiesPayload ||
    await fetchApsModelPropertiesForQuantityTask(task);
  if (task.status === "canceled" || job.status === "canceled") {
    return task;
  }
  const snapshots = snapshotsFromDerivativeProperties(propertiesPayload, task.config, { taskId: task.id });
  const summaries = aggregateQuantitySummaries(snapshots, task.config, { taskId: task.id });
  replaceQuantityResults(task, snapshots, summaries);

  const completedAt = new Date().toISOString();
  task.status = "succeeded";
  task.snapshotCount = snapshots.length;
  task.summaryCount = summaries.length;
  task.completedAt = completedAt;
  task.updatedAt = completedAt;
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    quantityTakeoff: {
      latestTaskId: task.id,
      status: task.status,
      snapshotCount: snapshots.length,
      summaryCount: summaries.length,
      updatedAt: completedAt,
    },
  });
  touchDocument(doc);
  addActivity(doc, safeText(job.payload?.actor, "系统"), "工程量统计完成", `提取 ${snapshots.length} 个对象，生成 ${summaries.length} 条汇总`);
  persistStore();
  return task;
}

function markQuantityTakeoffFailed(job, error) {
  const task = quantityTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task) {
    return;
  }
  const updatedAt = new Date().toISOString();
  task.status = "failed";
  task.error = safeText(error?.message, "工程量提取失败");
  task.updatedAt = updatedAt;
  if (doc) {
    doc.aps = normalizeApsConfig({
      ...(doc.aps || {}),
      quantityTakeoff: {
        latestTaskId: task.id,
        status: "failed",
        error: task.error,
        updatedAt,
      },
    });
    addActivity(doc, safeText(job?.payload?.actor, "系统"), "工程量统计失败", task.error);
  }
}

function markQuantityTakeoffRetryQueued(job, error) {
  const task = quantityTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task) {
    return;
  }
  const updatedAt = new Date().toISOString();
  task.status = "queued";
  task.error = safeText(error?.message, "工程量提取失败，等待自动重试");
  task.updatedAt = updatedAt;
  if (doc) {
    doc.aps = normalizeApsConfig({
      ...(doc.aps || {}),
      quantityTakeoff: {
        latestTaskId: task.id,
        status: "queued",
        error: `等待重试：${task.error}`,
        updatedAt,
      },
    });
  }
}

function toPublicQuantityTakeoffTask(task) {
  return task ? normalizeQuantityTakeoffTask(task) : null;
}

function toPublicQuantityTemplate(template) {
  return template ? normalizeQuantityTemplate(template) : null;
}

function buildQuantityTakeoffPayload(doc, userContext = SYSTEM_USER_CONTEXT) {
  const tasks = quantityTasksForDocument(doc).map(toPublicQuantityTakeoffTask);
  const latestTask = latestQuantityTaskForDocument(doc);
  const latestTaskId = safeText(latestTask?.id, "");
  return {
    document: toPublicDocument(doc, userContext),
    templates: quantityTemplates
      .filter((template) => template.projectId === safeText(doc.projectId, DEFAULT_PROJECT_ID))
      .map(toPublicQuantityTemplate),
    tasks,
    latestTask: toPublicQuantityTakeoffTask(latestTask),
    summaries: latestTaskId ? quantitySummariesForTask(latestTaskId).map(normalizeQuantitySummary) : [],
    snapshots: latestTaskId ? quantitySnapshotsForTask(latestTaskId).map(normalizeQuantityPropertySnapshot) : [],
  };
}

function buildQuantityTakeoffHomePayload(userContext = SYSTEM_USER_CONTEXT) {
  const docs = quantityTakeoffDocumentsForUser(userContext);
  const visibleIds = new Set(docs.map((doc) => doc.id));
  return {
    documents: docs,
    tasks: quantityTakeoffTasks
      .filter((task) => safeText(task.projectId, DEFAULT_PROJECT_ID) === safeText(userContext.projectId, DEFAULT_PROJECT_ID) && visibleIds.has(task.documentId))
      .map(toPublicQuantityTakeoffTask),
    templates: quantityTemplates
      .filter((template) => safeText(template.projectId, DEFAULT_PROJECT_ID) === safeText(userContext.projectId, DEFAULT_PROJECT_ID))
      .map(toPublicQuantityTemplate),
  };
}

function constructionScheduleDocumentCandidate(doc) {
  return Boolean(doc && isApsModelDocument(doc.name) && apsDocumentWorkspaceKind(doc.name) === "model");
}

function constructionScheduleDocumentsForUser(userContext) {
  return publicDocumentsForUser(userContext)
    .filter(constructionScheduleDocumentCandidate)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      version: doc.version,
      currentVersionId: doc.currentVersionId,
      updatedAt: doc.updatedAt,
      aps: doc.aps,
      latestSchedule: latestConstructionScheduleForDocument(doc)?.id || "",
      scheduleCount: constructionSchedulesForDocument(doc).length,
    }));
}

function constructionScheduleById(scheduleId) {
  const id = safeText(scheduleId, "");
  return constructionScheduleVersions.find((schedule) => schedule.id === id) || null;
}

function constructionSchedulesForDocument(doc) {
  return constructionScheduleVersions
    .filter((schedule) => schedule.documentId === doc?.id)
    .sort((left, right) => safeText(right.importedAt, "").localeCompare(safeText(left.importedAt, "")));
}

function latestConstructionScheduleForDocument(doc) {
  return constructionSchedulesForDocument(doc).find((schedule) => schedule.isCurrent) || constructionSchedulesForDocument(doc)[0] || null;
}

function constructionActivitiesForSchedule(scheduleId) {
  const id = safeText(scheduleId, "");
  return constructionScheduleActivities
    .filter((activity) => activity.scheduleId === id && !activity.deletedAt)
    .sort((left, right) => localeCollator("zh-CN").compare(safeText(left.activityId, ""), safeText(right.activityId, "")));
}

function constructionWbsForSchedule(scheduleId) {
  const id = safeText(scheduleId, "");
  return constructionScheduleWbsNodes
    .filter((node) => node.scheduleId === id)
    .sort((left, right) => Number(left.sequence || 0) - Number(right.sequence || 0));
}

function constructionMappingsForSchedule(scheduleId) {
  const id = safeText(scheduleId, "");
  return constructionScheduleMappings.filter((mapping) => mapping.scheduleId === id && mapping.status !== "deleted");
}

function constructionReportsForSchedule(scheduleId) {
  const ids = new Set(constructionActivitiesForSchedule(scheduleId).map((activity) => activity.activityId));
  return constructionProgressReports
    .filter((report) => ids.has(report.activityId))
    .sort((left, right) => safeText(left.reportedAt, "").localeCompare(safeText(right.reportedAt, "")));
}

function toScheduleServiceActivity(activity) {
  return {
    id: activity.activityId,
    internalId: activity.internalId,
    name: activity.name,
    wbsId: activity.wbsId,
    type: activity.type,
    plannedStart: activity.plannedStart,
    plannedFinish: activity.plannedFinish,
    actualStart: activity.actualStart,
    actualFinish: activity.actualFinish,
    status: activity.status,
    percentComplete: activity.percentComplete,
    totalFloatHours: activity.totalFloatHours,
    calendarId: activity.calendarId,
  };
}

function toScheduleServiceActivities(scheduleId) {
  return constructionActivitiesForSchedule(scheduleId).map(toScheduleServiceActivity);
}

function toScheduleServiceMappings(scheduleId) {
  return constructionMappingsForSchedule(scheduleId).map((mapping) => ({
    activityId: mapping.activityId,
    dbId: mapping.dbId,
    uniqueId: mapping.uniqueId,
    modelUrn: mapping.modelUrn,
    matchMethod: mapping.matchMethod,
    confidence: mapping.confidence,
  }));
}

function toScheduleServiceElements(scheduleId, providedElements = []) {
  const provided = (Array.isArray(providedElements) ? providedElements : []).map(normalizeScheduleModelElement);
  if (provided.length) return provided;
  const schedule = constructionScheduleById(scheduleId);
  if (schedule) {
    const quantityTask = quantityTakeoffTasks
      .filter((task) => task.documentId === schedule.documentId && task.status === "succeeded")
      .sort((left, right) => safeText(right.completedAt || right.updatedAt, "").localeCompare(safeText(left.completedAt || left.updatedAt, "")))[0] || null;
    const quantityElements = quantityTask ? quantitySnapshotsForTask(quantityTask.id).map((snapshot) => ({
      dbId: snapshot.dbId,
      uniqueId: safeText(snapshot.properties?.UniqueId || snapshot.properties?.GlobalId || snapshot.properties?.Handle || snapshot.properties?.["Element UniqueId"], ""),
      name: snapshot.name,
      elementType: snapshot.elementType,
      floor: snapshot.floor || snapshot.systemArea,
      discipline: snapshot.discipline,
      properties: snapshot.properties,
    })).map(normalizeScheduleModelElement) : [];
    if (quantityElements.length) {
      return quantityElements;
    }
    const diffSnapshot = modelDiffSnapshots
      .filter((snapshot) => snapshot.documentId === schedule.documentId && Array.isArray(snapshot.elements) && snapshot.elements.length)
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
    const diffElements = diffSnapshot ? diffSnapshot.elements.map((element) => ({
      dbId: element.dbId,
      uniqueId: element.uniqueId || element.elementId || element.stableKey,
      name: element.name,
      elementType: element.elementType,
      floor: element.floor,
      discipline: element.discipline,
      properties: element.properties,
    })).map(normalizeScheduleModelElement) : [];
    if (diffElements.length) {
      return diffElements;
    }
  }
  const elementsByKey = new Map();
  constructionMappingsForSchedule(scheduleId).forEach((mapping) => {
    const key = mapping.uniqueId || `db:${mapping.dbId}`;
    if (!key || elementsByKey.has(key)) return;
    elementsByKey.set(key, {
      dbId: mapping.dbId,
      uniqueId: mapping.uniqueId,
      name: mapping.elementName || mapping.uniqueId || `dbId ${mapping.dbId}`,
      elementType: mapping.elementType,
      floor: mapping.floor,
      discipline: mapping.discipline,
      properties: {},
    });
  });
  return Array.from(elementsByKey.values());
}

function buildConstructionMappingCompleteness(scheduleId) {
  const activities = constructionActivitiesForSchedule(scheduleId);
  const mappings = constructionMappingsForSchedule(scheduleId);
  const mappedActivityIds = new Set(mappings.map((mapping) => mapping.activityId));
  const byConfidence = { High: 0, Medium: 0, Low: 0, Manual: 0 };
  mappings.forEach((mapping) => {
    byConfidence[mapping.confidence] = Number(byConfidence[mapping.confidence] || 0) + 1;
  });
  const mappedElements = new Set(mappings.map((mapping) => mapping.uniqueId || `db:${mapping.dbId}`).filter(Boolean));
  return {
    totalActivities: activities.length,
    mappedActivities: mappedActivityIds.size,
    unmappedActivities: Math.max(0, activities.length - mappedActivityIds.size),
    mappedActivityRatio: activities.length ? Math.round((mappedActivityIds.size / activities.length) * 1000) / 10 : 0,
    mappedElements: mappedElements.size,
    byConfidence,
  };
}

function assertConstructionScheduleCapability(doc, userContext, action = "查看") {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError(`你没有${action}该模型施工进度的权限。`);
  }
  if (!constructionScheduleDocumentCandidate(doc)) {
    const error = new Error("当前文件类型不支持施工进度可视化，请先选择三维模型。");
    error.statusCode = 400;
    throw error;
  }
  return permissions;
}

function buildConstructionScheduleHomePayload(userContext = SYSTEM_USER_CONTEXT) {
  const docs = constructionScheduleDocumentsForUser(userContext);
  const visibleIds = new Set(docs.map((doc) => doc.id));
  return {
    documents: docs,
    schedules: constructionScheduleVersions
      .filter((schedule) => safeText(schedule.projectId, DEFAULT_PROJECT_ID) === safeText(userContext.projectId, DEFAULT_PROJECT_ID) && visibleIds.has(schedule.documentId))
      .sort((left, right) => safeText(right.importedAt, "").localeCompare(safeText(left.importedAt, ""))),
    alerts: constructionScheduleAlerts
      .filter((alert) => safeText(alert.projectId, DEFAULT_PROJECT_ID) === safeText(userContext.projectId, DEFAULT_PROJECT_ID) && alert.status === "open")
      .slice(0, 20),
  };
}

function parseScheduleXerBody(body = {}) {
  const xerText = safeText(body.xerText || body.xer || body.content, "");
  if (!xerText) {
    const error = new Error("请上传或粘贴 P6 XER 文件内容后再解析。");
    error.statusCode = 400;
    throw error;
  }
  const parsed = parseXerSchedule(xerText);
  const preview = buildXerImportPreview(parsed);
  return { xerText, parsed, preview };
}

function buildConstructionScheduleImportSummary(previousSchedule, parsed) {
  if (!previousSchedule) {
    return {
      baseScheduleId: "",
      added: parsed.activities.length,
      deleted: 0,
      dateChanged: 0,
      statusChanged: 0,
      progressChanged: 0,
      unchanged: 0,
      warnings: [],
      changedActivities: [],
    };
  }
  const previousActivities = new Map(
    constructionActivitiesForSchedule(previousSchedule.id).map((activity) => [activity.activityId, activity]),
  );
  const nextActivities = new Map((Array.isArray(parsed.activities) ? parsed.activities : []).map((activity) => [activity.id, activity]));
  const summary = {
    baseScheduleId: previousSchedule.id,
    baseScheduleName: previousSchedule.name,
    added: 0,
    deleted: 0,
    dateChanged: 0,
    statusChanged: 0,
    progressChanged: 0,
    unchanged: 0,
    warnings: [],
    changedActivities: [],
  };
  nextActivities.forEach((next, activityId) => {
    const previous = previousActivities.get(activityId);
    if (!previous) {
      summary.added += 1;
      summary.changedActivities.push({ activityId, name: next.name, type: "added" });
      return;
    }
    const changes = [];
    if (previous.plannedStart !== next.plannedStart || previous.plannedFinish !== next.plannedFinish) {
      summary.dateChanged += 1;
      changes.push({
        field: "planned_dates",
        valueBefore: `${previous.plannedStart || "—"} → ${previous.plannedFinish || "—"}`,
        valueAfter: `${next.plannedStart || "—"} → ${next.plannedFinish || "—"}`,
      });
    }
    if (previous.status !== next.status) {
      summary.statusChanged += 1;
      changes.push({ field: "status", valueBefore: previous.status, valueAfter: next.status });
    }
    if (Number(previous.percentComplete || 0) !== Number(next.percentComplete || 0)) {
      summary.progressChanged += 1;
      changes.push({ field: "percent_complete", valueBefore: previous.percentComplete, valueAfter: next.percentComplete });
    }
    if (changes.length) {
      summary.changedActivities.push({ activityId, name: next.name, type: "changed", changes });
    } else {
      summary.unchanged += 1;
    }
  });
  previousActivities.forEach((previous, activityId) => {
    if (nextActivities.has(activityId)) return;
    summary.deleted += 1;
    summary.changedActivities.push({ activityId, name: previous.name, type: "deleted" });
  });
  if (summary.dateChanged + summary.statusChanged + summary.progressChanged > 0) {
    summary.warnings.push("本次导入与上一计划存在日期、状态或进度差异，请在版本列表中核对变更摘要。");
  }
  return summary;
}

function createConstructionScheduleFromXer(doc, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const { parsed, preview } = parseScheduleXerBody(body);
  const permissions = assertConstructionScheduleCapability(doc, userContext, "导入");
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("你没有导入施工进度计划的权限。");
  }
  const now = new Date().toISOString();
  const previousSchedule = latestConstructionScheduleForDocument(doc);
  const importSummary = buildConstructionScheduleImportSummary(previousSchedule, parsed);
  const schedule = normalizeConstructionScheduleVersion({
    id: crypto.randomUUID(),
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    documentId: doc.id,
    fileId: doc.id,
    name: safeText(body.versionName || body.name, `${parsed.project.dataDate || "未注明数据日期"} 施工计划`),
    projectCode: parsed.project.id,
    projectName: parsed.project.name,
    dataDate: parsed.project.dataDate,
    plannedStart: parsed.project.plannedStart,
    plannedFinish: parsed.project.plannedFinish,
    isBaseline: Boolean(body.isBaseline),
    isCurrent: !body.isBaseline,
    status: "imported",
    modelUrn: safeText(body.modelUrn, doc.aps?.urn || ""),
    versionId: safeText(body.versionId, doc.currentVersionId),
    activityCount: parsed.activities.length,
    stats: preview.stats,
    preview,
    importSummary,
    importedBy: actorDisplayName(userContext),
    importedByUserId: safeText(userContext?.user?.id, ""),
    importedAt: now,
    createdAt: now,
    updatedAt: now,
  });
  if (schedule.isBaseline) {
    constructionScheduleVersions.forEach((item) => {
      if (item.documentId === doc.id) item.isBaseline = false;
    });
  }
  if (schedule.isCurrent) {
    constructionScheduleVersions.forEach((item) => {
      if (item.documentId === doc.id) item.isCurrent = false;
    });
  }
  constructionScheduleVersions.unshift(schedule);
  const wbsNodes = parsed.wbs.map((node) => normalizeConstructionScheduleWbsNode({
    ...node,
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    wbsId: node.id,
  })).filter(Boolean);
  const activities = parsed.activities.map((activity) => normalizeConstructionScheduleActivity({
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    internalId: activity.internalId,
    activityId: activity.id,
    name: activity.name,
    wbsId: activity.wbsId,
    type: activity.type,
    plannedStart: activity.plannedStart,
    plannedFinish: activity.plannedFinish,
    actualStart: activity.actualStart,
    actualFinish: activity.actualFinish,
    percentComplete: activity.percentComplete,
    status: activity.status,
    totalFloatHours: activity.totalFloatHours,
    calendarId: activity.calendarId,
    createdAt: now,
    updatedAt: now,
  })).filter(Boolean);
  const predecessors = parsed.predecessors.map((pred) => normalizeConstructionSchedulePredecessor({
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    successorId: pred.successorId,
    predecessorId: pred.predecessorId,
    type: pred.type,
    lag: pred.lag,
  })).filter(Boolean);
  constructionScheduleWbsNodes.unshift(...wbsNodes);
  constructionScheduleActivities.unshift(...activities);
  constructionSchedulePredecessors.unshift(...predecessors);
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    constructionSchedule: {
      latestScheduleId: schedule.id,
      status: schedule.status,
      dataDate: schedule.dataDate,
      importedAt: schedule.importedAt,
    },
  });
  touchDocument(doc);
  addActivity(doc, actorDisplayName(userContext), "导入施工进度计划", `${schedule.name} 已导入，Activity ${activities.length} 项`);
  persistStore();
  return { schedule, preview, wbsNodes, activities, predecessors };
}

function buildConstructionScheduleDocumentPayload(doc, userContext = SYSTEM_USER_CONTEXT) {
  assertConstructionScheduleCapability(doc, userContext);
  const schedules = constructionSchedulesForDocument(doc);
  const latest = latestConstructionScheduleForDocument(doc);
  return {
    document: toPublicDocument(doc, userContext),
    schedules,
    latestSchedule: latest,
    activities: latest ? constructionActivitiesForSchedule(latest.id) : [],
    wbsNodes: latest ? constructionWbsForSchedule(latest.id) : [],
    mappings: latest ? constructionMappingsForSchedule(latest.id) : [],
    reports: latest ? constructionReportsForSchedule(latest.id) : [],
    completeness: latest ? buildConstructionMappingCompleteness(latest.id) : null,
    alerts: latest ? constructionScheduleAlerts.filter((alert) => alert.scheduleId === latest.id) : [],
  };
}

function runConstructionAutoMapping(scheduleId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const schedule = constructionScheduleById(scheduleId);
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!schedule || !doc) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  assertConstructionScheduleCapability(doc, userContext, "映射");
  const elements = toScheduleServiceElements(schedule.id, body.modelElements || body.elements || []);
  if (!elements.length) {
    const error = new Error("当前模型还没有可用于映射的构件属性快照，请先导入构件索引或在 Viewer 中手动选择构件。");
    error.statusCode = 400;
    throw error;
  }
  const activities = toScheduleServiceActivities(schedule.id);
  const wbs = constructionWbsForSchedule(schedule.id).map((node) => ({
    id: node.wbsId,
    code: node.code,
    name: node.name,
    parentId: node.parentId,
    level: node.level,
  }));
  const autoMappings = autoMapScheduleActivities(activities, elements, { wbs });
  constructionScheduleMappings = constructionScheduleMappings.filter((mapping) => !(mapping.scheduleId === schedule.id && mapping.matchMethod !== "manual"));
  const elementByKey = new Map();
  elements.forEach((element) => {
    if (element.uniqueId) elementByKey.set(`u:${element.uniqueId}`, element);
    if (element.dbId !== null && element.dbId !== undefined) elementByKey.set(`d:${element.dbId}`, element);
  });
  const now = new Date().toISOString();
  const mappings = autoMappings.map((mapping) => {
    const element = (mapping.uniqueId && elementByKey.get(`u:${mapping.uniqueId}`)) || elementByKey.get(`d:${mapping.dbId}`) || {};
    return normalizeConstructionScheduleMapping({
      ...mapping,
      scheduleId: schedule.id,
      projectId: schedule.projectId,
      documentId: schedule.documentId,
      modelUrn: schedule.modelUrn,
      elementName: element.name,
      elementType: element.elementType,
      floor: element.floor,
      discipline: element.discipline,
      createdBy: actorDisplayName(userContext),
      createdAt: now,
      updatedAt: now,
    });
  }).filter(Boolean);
  constructionScheduleMappings.unshift(...mappings);
  const completeness = buildConstructionMappingCompleteness(schedule.id);
  schedule.mappedActivityCount = completeness.mappedActivities;
  schedule.updatedAt = now;
  addActivity(doc, actorDisplayName(userContext), "施工进度自动映射", `${schedule.name} 已自动映射 ${completeness.mappedActivities}/${completeness.totalActivities} 个 Activity`);
  persistStore();
  return { schedule, mappings: constructionMappingsForSchedule(schedule.id), completeness };
}

function runConstructionManualMapping(scheduleId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const schedule = constructionScheduleById(scheduleId);
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!schedule || !doc) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  assertConstructionScheduleCapability(doc, userContext, "手动映射");
  const activityRowId = safeText(body.activityRowId || body.activity_row_id, "");
  const activityIdInput = safeText(body.activityId || body.activity_id, "");
  const activity = constructionActivitiesForSchedule(schedule.id).find((item) =>
    (activityRowId && item.id === activityRowId) ||
    (activityIdInput && item.activityId === activityIdInput),
  );
  if (!activity) {
    const error = new Error("请选择需要绑定的 Activity。");
    error.statusCode = 400;
    throw error;
  }

  const rawElements = Array.isArray(body.elements) ? body.elements : [];
  const dbIds = Array.isArray(body.dbIds) ? body.dbIds.map((item) => Number(item)).filter(Number.isFinite) : [];
  const uniqueIds = Array.isArray(body.uniqueIds) ? body.uniqueIds.map((item) => safeText(item, "")) : [];
  const manualElements = rawElements.length
    ? rawElements.map((element) => ({
        dbId: Number(element.dbId ?? element.dbid),
        uniqueId: safeText(element.uniqueId || element.unique_id, ""),
        elementName: safeText(element.name || element.elementName, ""),
        elementType: safeText(element.elementType || element.type, ""),
        floor: safeText(element.floor || element.zone, ""),
        discipline: safeText(element.discipline, ""),
      }))
    : dbIds.map((dbId, index) => ({
        dbId,
        uniqueId: uniqueIds[index] || "",
        elementName: "",
        elementType: "",
        floor: "",
        discipline: "",
      }));
  const normalizedElements = manualElements
    .filter((element) => Number.isFinite(Number(element.dbId)) || element.uniqueId)
    .map((element) => ({
      ...element,
      dbId: Number.isFinite(Number(element.dbId)) ? Number(element.dbId) : null,
    }));
  if (!normalizedElements.length) {
    const error = new Error("请先在 Viewer 中选择构件，或提供 dbId / UniqueId。");
    error.statusCode = 400;
    throw error;
  }

  const now = new Date().toISOString();
  const incomingKeys = new Set(normalizedElements.map((element) => element.uniqueId || `db:${element.dbId}`));
  constructionScheduleMappings = constructionScheduleMappings.filter((mapping) => {
    if (mapping.scheduleId !== schedule.id || mapping.activityId !== activity.activityId) return true;
    return !incomingKeys.has(mapping.uniqueId || `db:${mapping.dbId}`);
  });
  const createdMappings = normalizedElements.map((element) => normalizeConstructionScheduleMapping({
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    documentId: schedule.documentId,
    activityId: activity.activityId,
    activityRowId: activity.id,
    modelUrn: schedule.modelUrn,
    dbId: element.dbId,
    uniqueId: element.uniqueId,
    elementName: element.elementName,
    elementType: element.elementType,
    floor: element.floor,
    discipline: element.discipline,
    matchMethod: "manual",
    confidence: "Manual",
    reason: safeText(body.reason, "Viewer 手动选择构件绑定 Activity"),
    createdBy: actorDisplayName(userContext),
    createdAt: now,
    updatedAt: now,
  })).filter(Boolean);
  constructionScheduleMappings.unshift(...createdMappings);
  const completeness = buildConstructionMappingCompleteness(schedule.id);
  schedule.mappedActivityCount = completeness.mappedActivities;
  schedule.updatedAt = now;
  addActivity(doc, actorDisplayName(userContext), "施工进度手动映射", `${activity.activityId} ${activity.name} 已手动绑定 ${createdMappings.length} 个构件`);
  persistStore();
  return { schedule, createdMappings, mappings: constructionMappingsForSchedule(schedule.id), completeness };
}

function scheduleMappingTextMatches(value, expected) {
  const left = safeText(value, "").toLowerCase();
  const right = safeText(expected, "").toLowerCase();
  return !right || (left && (left === right || left.includes(right) || right.includes(left)));
}

function modelElementSystemText(element) {
  const properties = element?.properties || {};
  return [
    element?.floor,
    properties.Zone,
    properties.zone,
    properties.System,
    properties.system,
    properties["Process Unit"],
    properties["Plant Area"],
    properties["Area Code"],
    properties["工艺单元"],
    properties["区域"],
    properties["系统"],
  ].map((item) => safeText(item, "")).filter(Boolean).join(" ");
}

function resolveConstructionScheduleActivity(schedule, body = {}) {
  const activityRowId = safeText(body.activityRowId || body.activity_row_id, "");
  const activityIdInput = safeText(body.activityId || body.activity_id, "");
  return constructionActivitiesForSchedule(schedule.id).find((item) =>
    (activityRowId && item.id === activityRowId) ||
    (activityIdInput && item.activityId === activityIdInput),
  ) || null;
}

function createConstructionMappings(schedule, activity, elements, options = {}, userContext = SYSTEM_USER_CONTEXT) {
  const now = new Date().toISOString();
  const normalizedElements = (Array.isArray(elements) ? elements : [])
    .map((element) => ({
      dbId: Number.isFinite(Number(element.dbId ?? element.dbid)) ? Number(element.dbId ?? element.dbid) : null,
      uniqueId: safeText(element.uniqueId || element.unique_id, ""),
      elementName: safeText(element.elementName || element.name, ""),
      elementType: safeText(element.elementType || element.type, ""),
      floor: safeText(element.floor || element.zone, ""),
      discipline: safeText(element.discipline, ""),
    }))
    .filter((element) => element.uniqueId || element.dbId !== null);
  const incomingKeys = new Set(normalizedElements.map((element) => element.uniqueId || `db:${element.dbId}`));
  constructionScheduleMappings = constructionScheduleMappings.filter((mapping) => {
    if (mapping.scheduleId !== schedule.id || mapping.activityId !== activity.activityId) return true;
    return !incomingKeys.has(mapping.uniqueId || `db:${mapping.dbId}`);
  });
  const createdMappings = normalizedElements.map((element) => normalizeConstructionScheduleMapping({
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    documentId: schedule.documentId,
    activityId: activity.activityId,
    activityRowId: activity.id,
    modelUrn: schedule.modelUrn,
    dbId: element.dbId,
    uniqueId: element.uniqueId,
    elementName: element.elementName,
    elementType: element.elementType,
    floor: element.floor,
    discipline: element.discipline,
    matchMethod: options.matchMethod || "manual",
    confidence: options.confidence || "Manual",
    reason: safeText(options.reason, "施工进度批量映射"),
    createdBy: actorDisplayName(userContext),
    createdAt: now,
    updatedAt: now,
  })).filter(Boolean);
  constructionScheduleMappings.unshift(...createdMappings);
  return createdMappings;
}

function runConstructionBulkMapping(scheduleId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const schedule = constructionScheduleById(scheduleId);
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!schedule || !doc) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  assertConstructionScheduleCapability(doc, userContext, "批量映射");
  const activity = resolveConstructionScheduleActivity(schedule, body);
  if (!activity) {
    const error = new Error("请选择需要批量绑定的 Activity。");
    error.statusCode = 400;
    throw error;
  }
  const mode = ["floor_type", "system"].includes(safeText(body.mode, "floor_type")) ? safeText(body.mode, "floor_type") : "floor_type";
  const floor = safeText(body.floor || body.zone || body.system, "");
  const elementType = safeText(body.elementType || body.element_type || body.type, "");
  const discipline = safeText(body.discipline, "");
  if (!floor && !elementType && !discipline) {
    const error = new Error("请至少填写系统/区域、对象类型或专业中的一个批量映射条件。");
    error.statusCode = 400;
    throw error;
  }
  const elements = toScheduleServiceElements(schedule.id, body.modelElements || body.elements || []);
  if (!elements.length) {
    const error = new Error("当前模型还没有可用于批量映射的构件属性快照。");
    error.statusCode = 400;
    throw error;
  }
  const matchedElements = elements.filter((element) => {
    const systemText = modelElementSystemText(element);
    const floorOk = mode === "system" ? scheduleMappingTextMatches(systemText, floor) : scheduleMappingTextMatches(element.floor, floor);
    const typeOk = scheduleMappingTextMatches(element.elementType, elementType);
    const disciplineOk = scheduleMappingTextMatches(element.discipline, discipline);
    return floorOk && typeOk && disciplineOk;
  });
  if (!matchedElements.length) {
    const error = new Error("没有构件符合当前批量映射条件，请调整系统/区域、对象类型或专业。");
    error.statusCode = 400;
    throw error;
  }
  const createdMappings = createConstructionMappings(schedule, activity, matchedElements, {
    matchMethod: mode === "system" ? "bulk_system" : "bulk_floor_type",
    confidence: "Manual",
    reason: mode === "system" ? "按系统/区域批量映射" : "按楼层/对象类型批量映射",
  }, userContext);
  const completeness = buildConstructionMappingCompleteness(schedule.id);
  schedule.mappedActivityCount = completeness.mappedActivities;
  schedule.updatedAt = new Date().toISOString();
  addActivity(doc, actorDisplayName(userContext), "施工进度批量映射", `${activity.activityId} ${activity.name} 批量绑定 ${createdMappings.length} 个构件`);
  persistStore();
  return { schedule, mode, createdMappings, mappings: constructionMappingsForSchedule(schedule.id), completeness };
}

function parseScheduleMappingCsv(csvText = "") {
  const lines = safeText(csvText, "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  if (!lines.length) return [];
  const splitLine = (line) => line.split(/,|\t/).map((cell) => cell.trim().replace(/^"|"$/g, ""));
  const first = splitLine(lines[0]).map((cell) => cell.toLowerCase().replace(/[^a-z0-9_]+/g, ""));
  const hasHeader = first.some((cell) => ["activityid", "activity_id", "dbid", "uniqueid", "unique_id"].includes(cell));
  const header = hasHeader ? first : ["activityid", "uniqueid", "dbid", "elementname", "elementtype", "floor", "discipline"];
  const rows = hasHeader ? lines.slice(1) : lines;
  return rows.map((line, index) => {
    const cells = splitLine(line);
    const value = (names, fallbackIndex) => {
      for (const name of names) {
        const found = header.indexOf(name);
        if (found >= 0) return safeText(cells[found], "");
      }
      return safeText(cells[fallbackIndex], "");
    };
    return {
      row: index + (hasHeader ? 2 : 1),
      activityId: value(["activityid", "activity_id", "activitycode"], 0),
      uniqueId: value(["uniqueid", "unique_id", "stableid", "handle", "globalid"], 1),
      dbId: Number(value(["dbid", "db_id"], 2)),
      elementName: value(["elementname", "element_name", "name"], 3),
      elementType: value(["elementtype", "element_type", "type"], 4),
      floor: value(["floor", "zone", "system"], 5),
      discipline: value(["discipline", "trade"], 6),
    };
  });
}

function importConstructionScheduleMappings(scheduleId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const schedule = constructionScheduleById(scheduleId);
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!schedule || !doc) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  assertConstructionScheduleCapability(doc, userContext, "导入映射");
  const rows = parseScheduleMappingCsv(body.csvText || body.csv || body.content);
  if (!rows.length) {
    const error = new Error("请提供 Activity ID → 构件 UniqueId/dbId 的 CSV 映射内容。");
    error.statusCode = 400;
    throw error;
  }
  const activities = constructionActivitiesForSchedule(schedule.id);
  const byActivityId = new Map(activities.map((activity) => [activity.activityId, activity]));
  const grouped = new Map();
  const skippedRows = [];
  rows.forEach((row) => {
    const activity = byActivityId.get(row.activityId);
    if (!activity) {
      skippedRows.push({ row: row.row, reason: "Activity 不存在", activityId: row.activityId });
      return;
    }
    if (!row.uniqueId && !Number.isFinite(row.dbId)) {
      skippedRows.push({ row: row.row, reason: "缺少 UniqueId/dbId", activityId: row.activityId });
      return;
    }
    const list = grouped.get(activity.activityId) || [];
    list.push(row);
    grouped.set(activity.activityId, list);
  });
  const createdMappings = [];
  grouped.forEach((elements, activityId) => {
    const activity = byActivityId.get(activityId);
    createdMappings.push(...createConstructionMappings(schedule, activity, elements, {
      matchMethod: "csv_import",
      confidence: "Manual",
      reason: "CSV 导入 Activity 与构件映射",
    }, userContext));
  });
  const completeness = buildConstructionMappingCompleteness(schedule.id);
  schedule.mappedActivityCount = completeness.mappedActivities;
  schedule.updatedAt = new Date().toISOString();
  addActivity(doc, actorDisplayName(userContext), "施工进度 CSV 映射", `CSV 导入 ${createdMappings.length} 条构件映射，跳过 ${skippedRows.length} 行`);
  persistStore();
  return { schedule, createdMappings, skippedRows, mappings: constructionMappingsForSchedule(schedule.id), completeness };
}

function updateConstructionActivityFromReport(activity, report) {
  if (report.actualStart) activity.actualStart = report.actualStart;
  if (report.actualFinish) activity.actualFinish = report.actualFinish;
  activity.percentComplete = Math.max(0, Math.min(100, Number(report.percentComplete || 0) || 0));
  if (activity.actualFinish || activity.percentComplete >= 100) {
    activity.status = "Completed";
  } else if (activity.actualStart || activity.percentComplete > 0) {
    activity.status = "In Progress";
  } else {
    activity.status = "Not Started";
  }
  activity.updatedAt = new Date().toISOString();
}

function submitConstructionProgressReport(activityRowId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const activity = constructionScheduleActivities.find((item) => item.id === safeText(activityRowId, ""));
  const schedule = activity ? constructionScheduleById(activity.scheduleId) : null;
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!activity || !schedule || !doc) {
    const error = new Error("Activity 不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = assertConstructionScheduleCapability(doc, userContext, "上报");
  if (!permissions.annotations.create && !permissions.rename) {
    throw permissionDeniedError("你没有上报施工进度的权限。");
  }
  const report = normalizeConstructionProgressReport({
    id: crypto.randomUUID(),
    scheduleId: schedule.id,
    projectId: schedule.projectId,
    activityId: activity.activityId,
    activityRowId: activity.id,
    reportedBy: actorDisplayName(userContext),
    reportedByUserId: safeText(userContext?.user?.id, ""),
    reportedAt: new Date().toISOString(),
    actualStart: body.actualStart,
    actualFinish: body.actualFinish,
    percentComplete: body.percentComplete,
    note: body.note,
    attachments: body.attachments,
  });
  constructionProgressReports.unshift(report);
  updateConstructionActivityFromReport(activity, report);
  addActivity(doc, actorDisplayName(userContext), "上报施工进度", `${activity.activityId} ${activity.name} 完成率 ${activity.percentComplete}%`);
  persistStore();
  return { report, activity };
}

function buildConstructionTimelinePayload(scheduleId, date, options = {}) {
  const schedule = constructionScheduleById(scheduleId);
  if (!schedule) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  const activities = toScheduleServiceActivities(schedule.id);
  const mappings = toScheduleServiceMappings(schedule.id);
  const elements = toScheduleServiceElements(schedule.id, options.modelElements || []);
  const timeline = buildScheduleTimeline(activities, mappings, elements, date || schedule.dataDate || new Date().toISOString().slice(0, 10), options);
  return { schedule, timeline, completeness: buildConstructionMappingCompleteness(schedule.id) };
}

function upsertConstructionScheduleAlerts(scheduleId, date) {
  const schedule = constructionScheduleById(scheduleId);
  if (!schedule) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  const generated = generateScheduleAlerts(toScheduleServiceActivities(schedule.id), toScheduleServiceMappings(schedule.id), {
    asOfDate: date || schedule.dataDate || new Date().toISOString().slice(0, 10),
    reports: constructionReportsForSchedule(schedule.id),
  }).map((alert) => normalizeConstructionScheduleAlert({
    ...alert,
    id: `csalert_${sha1Hash([schedule.id, alert.activityId, alert.type].join("|")).slice(0, 18)}`,
    scheduleId: schedule.id,
    projectId: schedule.projectId,
  })).filter(Boolean);
  generated.forEach((alert) => {
    const existingIndex = constructionScheduleAlerts.findIndex((item) => item.id === alert.id);
    if (existingIndex >= 0) {
      const existing = constructionScheduleAlerts[existingIndex];
      constructionScheduleAlerts.splice(existingIndex, 1, {
        ...existing,
        ...alert,
        issueId: existing.issueId || alert.issueId,
        status: existing.status === "resolved" ? existing.status : alert.status,
        updatedAt: new Date().toISOString(),
      });
    } else {
      constructionScheduleAlerts.unshift(alert);
    }
  });
  persistStore();
  return constructionScheduleAlerts
    .filter((alert) => alert.scheduleId === schedule.id)
    .sort((left, right) => {
      const rank = { critical: 0, high: 1, medium: 2, low: 3 };
      return (rank[left.severity] ?? 4) - (rank[right.severity] ?? 4) || safeText(left.activityCode, "").localeCompare(safeText(right.activityCode, ""));
    });
}

async function createIssueFromConstructionScheduleAlert(alertId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const alert = constructionScheduleAlerts.find((item) => item.id === safeText(alertId, ""));
  const schedule = alert ? constructionScheduleById(alert.scheduleId) : null;
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!alert || !schedule || !doc) {
    const error = new Error("施工进度预警不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.annotations.create) {
    throw permissionDeniedError("你没有从施工进度预警创建 Issue 的权限。");
  }
  const noteParts = [
    `预警类型：${alert.type}`,
    `严重程度：${alert.severity}`,
    `Activity：${alert.activityCode} ${alert.activityName}`,
    alert.plannedFinish ? `计划完成：${alert.plannedFinish}` : "",
    `当前完成率：${alert.percentComplete}%`,
    alert.delayDays ? `已滞后：${alert.delayDays} 天` : "",
    body.responsible ? `责任专业：${safeText(body.responsible, "")}` : "",
    body.dueDate ? `截止日期：${safeText(body.dueDate, "")}` : "",
    alert.message,
  ].filter(Boolean);
  const annotation = await createAnnotation({
    type: "note",
    variant: "construction-schedule",
    page: 1,
    x: 0.5,
    y: 0.5,
    width: 0.16,
    height: 0.08,
    title: safeText(body.title, `${alert.activityCode} ${alert.activityName} 进度预警`),
    note: noteParts.join("\n"),
    actor: actorDisplayName(userContext),
    status: "open",
    dbIds: alert.dbIds,
    modelUrn: schedule.modelUrn || doc.aps?.urn || "",
    boundModelVersion: schedule.name,
    migrationStatus: "synced",
    source: "construction_schedule",
  }, doc.currentVersionId, {
    modelUrn: schedule.modelUrn || doc.aps?.urn || "",
    boundModelVersion: schedule.name,
  });
  doc.annotations.unshift(annotation);
  alert.issueId = annotation.id;
  alert.status = "issue_created";
  alert.updatedAt = new Date().toISOString();
  addActivity(doc, actorDisplayName(userContext), "进度预警转 Issue", `${alert.activityCode} ${alert.activityName} 已创建 Issue`);
  persistStore();
  await bestEffortProjectEmailNotification("annotationCreated", {
    document: doc,
    annotation,
    userContext,
    occurredAt: annotation.createdAt,
  });
  return { alert, issue: normalizeAnnotation(annotation, doc.currentVersionId), document: doc };
}

function buildConstructionWeeklyPayload(scheduleId, query = {}) {
  const schedule = constructionScheduleById(scheduleId);
  if (!schedule) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  const weekStart = normalizeScheduleDate(query.weekStart) || schedule.dataDate || new Date().toISOString().slice(0, 10);
  const weekEnd = normalizeScheduleDate(query.weekEnd) || new Date(new Date(`${weekStart}T00:00:00.000Z`).getTime() + 6 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const activities = toScheduleServiceActivities(schedule.id);
  const report = buildWeeklyProgressReport(activities, { weekStart, weekEnd, dataDate: schedule.dataDate });
  const sCurve = buildSCurve(activities, { start: schedule.plannedStart || weekStart, end: schedule.plannedFinish || weekEnd, intervalDays: 30 });
  const disciplineMatrix = buildDisciplineProgressMatrix(
    activities,
    toScheduleServiceMappings(schedule.id),
    toScheduleServiceElements(schedule.id),
    weekEnd,
  );
  return { schedule, report, sCurve, disciplineMatrix };
}

function normalizeConstructionScheduleExportKind(value) {
  const kind = safeText(value, "workbook").toLowerCase();
  if (["workbook", "weekly_pdf", "gantt_pdf"].includes(kind)) return kind;
  return "workbook";
}

function constructionScheduleExportFileName(schedule, kind) {
  const stamp = Date.now();
  const suffix = crypto.randomUUID().slice(0, 8);
  if (kind === "weekly_pdf") return `${schedule.id}-schedule-weekly-${stamp}-${suffix}.pdf`;
  if (kind === "gantt_pdf") return `${schedule.id}-schedule-gantt-${stamp}-${suffix}.pdf`;
  return `${schedule.id}-schedule-data-${stamp}-${suffix}.xlsx`;
}

function runConstructionScheduleExportScript(schedule, kind, outputPath, options = {}) {
  persistStore();
  return new Promise((resolve, reject) => {
    const child = spawn(PYTHON_BIN, [
      CONSTRUCTION_SCHEDULE_EXPORT_SCRIPT,
      STORE_PATH,
      safeText(schedule?.id, ""),
      kind,
      outputPath,
      safeText(options.weekStart, ""),
      safeText(options.weekEnd, ""),
    ], exportSpawnOptions(options.language));
    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
    });
    child.on("close", (code) => {
      if (code === 0) {
        resolve();
        return;
      }
      const error = new Error(stderr.trim() || "Failed to export construction schedule");
      error.statusCode = 500;
      reject(error);
    });
    child.on("error", reject);
  });
}

async function exportConstructionSchedule(scheduleId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const schedule = constructionScheduleById(scheduleId);
  const doc = schedule ? documents.find((item) => item.id === schedule.documentId) : null;
  if (!schedule || !doc) {
    const error = new Error("施工进度计划不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = assertConstructionScheduleCapability(doc, userContext, "导出");
  if (!permissions.preview && !permissions.annotations?.export) {
    throw permissionDeniedError("你没有导出该施工进度报表的权限。");
  }
  const kind = normalizeConstructionScheduleExportKind(body.kind);
  const fileName = constructionScheduleExportFileName(schedule, kind);
  const outputPath = path.join(EXPORTS_DIR, fileName);
  await runConstructionScheduleExportScript(schedule, kind, outputPath, {
    weekStart: body.weekStart,
    weekEnd: body.weekEnd,
    language: body.language,
  });
  registerProtectedExportFile(fileName, {
    kind: `construction_schedule_${kind}`,
    docIds: [doc.id],
    scheduleId: schedule.id,
    createdBy: safeText(userContext?.user?.id, ""),
    createdAt: new Date().toISOString(),
  });
  addActivity(doc, actorDisplayName(userContext), "导出施工进度报表", `${schedule.name} 已导出 ${kind}`);
  persistStore();
  return { kind, fileName, downloadUrl: signedExportUrl(fileName), schedule };
}

function modelDiffFixturePayloadAllowed() {
  return String(process.env.CDE_ALLOW_MODEL_DIFF_FIXTURE_PAYLOAD || "").trim() === "1";
}

function assertModelDiffPayloadBoundary(body = {}) {
  const payloads = body?.propertiesPayloads || body?.propertiesPayloadA || body?.propertiesPayloadB;
  if (!payloads) {
    return;
  }
  if (modelDiffFixturePayloadAllowed()) {
    return;
  }
  const error = new Error("测试属性载荷仅允许在 CDE_ALLOW_MODEL_DIFF_FIXTURE_PAYLOAD=1 的测试环境使用。");
  error.statusCode = 400;
  throw error;
}

function modelDiffDocumentCandidate(doc) {
  return Boolean(doc && isApsModelDocument(doc.name) && apsDocumentWorkspaceKind(doc.name) === "model");
}

function latestQuantityTakeoffTaskForVersion(doc, versionId) {
  const normalizedVersionId = safeText(versionId, "");
  return quantityTakeoffTasks
    .filter((task) =>
      task.documentId === doc.id &&
      task.versionId === normalizedVersionId &&
      task.status === "succeeded",
    )
    .sort((left, right) => safeText(right.completedAt || right.updatedAt, "").localeCompare(safeText(left.completedAt || left.updatedAt, "")))[0] || null;
}

function modelDiffVersionReadiness(doc, entry) {
  const versionId = safeText(entry?.id, "");
  const versionAps = normalizeApsConfig(entry?.aps || {});
  const docAps = normalizeApsConfig(doc?.aps || {});
  const isActiveApsVersion = versionId && [safeText(docAps.sourceVersionId, ""), safeText(doc?.currentVersionId, "")].includes(versionId);
  const activeAps = isActiveApsVersion ? docAps : versionAps;
  const translationStatus = normalizeApsTranslationStatus(activeAps.translationStatus, activeAps.urn ? "success" : "idle");
  const modelUrn = safeText(activeAps.urn, "");
  const diffSnapshot = modelDiffSnapshotsForVersion(doc, versionId, modelUrn)[0] || modelDiffSnapshotsForVersion(doc, versionId, "")[0] || null;
  const quantityTask = latestQuantityTakeoffTaskForVersion(doc, versionId);
  const quantitySnapshotCount = quantityTask ? quantitySnapshotsForTask(quantityTask.id).length : 0;
  const canExtractNow = Boolean(modelUrn && translationStatus === "success");
  const snapshotAvailable = Boolean(diffSnapshot || quantitySnapshotCount);
  const ready = canExtractNow || snapshotAvailable;
  const source = diffSnapshot
    ? diffSnapshot.extractionSource || "model-diff-cache"
    : quantitySnapshotCount
      ? "quantity-cache"
      : canExtractNow
        ? "aps-properties"
        : "";
  return {
    modelUrn,
    translationStatus,
    canExtractNow,
    snapshotAvailable,
    snapshotSource: source,
    objectCount: Number(diffSnapshot?.objectCount || quantitySnapshotCount || 0),
    ready,
    reason: ready
      ? source
      : translationStatus === "failed"
        ? "APS 转换失败"
        : "该版本缺少 APS URN 或已缓存属性快照",
  };
}

function modelDiffDocumentsForUser(userContext) {
  return publicDocumentsForUser(userContext)
    .filter(modelDiffDocumentCandidate)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      version: doc.version,
      currentVersionId: doc.currentVersionId,
      updatedAt: doc.updatedAt,
      aps: doc.aps,
      versionHistory: Array.isArray(doc.versionHistory)
        ? doc.versionHistory.filter((entry) => !entry.deletedAt).map((entry) => ({
            id: entry.id,
            version: entry.version,
            name: entry.name,
            note: entry.note,
            uploadedAt: entry.uploadedAt,
            uploadedBy: entry.uploadedBy,
            parseStatus: entry.parseStatus,
            isCurrent: Boolean(entry.isCurrent),
            modelDiff: modelDiffVersionReadiness(doc, entry),
          }))
        : [],
    }));
}

function modelDiffTaskById(taskId) {
  const id = safeText(taskId, "");
  return modelDiffTasks.find((task) => task.id === id) || null;
}

function modelDiffRecordsForTask(taskId) {
  const id = safeText(taskId, "");
  return modelDiffRecords.filter((record) => record.taskId === id);
}

function modelDiffPropChangesForTask(taskId) {
  const id = safeText(taskId, "");
  return modelDiffPropChanges.filter((change) => change.taskId === id);
}

function modelDiffAiSummaryForTask(taskId) {
  const id = safeText(taskId, "");
  return modelDiffAiSummaries.find((summary) => summary.taskId === id) || null;
}

function modelDiffSnapshotById(snapshotId) {
  const id = safeText(snapshotId, "");
  return modelDiffSnapshots.find((snapshot) => snapshot.id === id) || null;
}

function modelDiffSnapshotStillFresh(snapshot) {
  const expiresAt = Date.parse(safeText(snapshot?.expiresAt, ""));
  return Boolean(snapshot && (!Number.isFinite(expiresAt) || expiresAt > Date.now()));
}

function modelDiffSnapshotsForVersion(doc, versionId, modelUrn = "") {
  const normalizedUrn = safeText(modelUrn, "");
  return modelDiffSnapshots
    .filter((snapshot) => snapshot.documentId === doc.id && snapshot.versionId === versionId)
    .filter((snapshot) => !normalizedUrn || snapshot.modelUrn === normalizedUrn)
    .filter(modelDiffSnapshotStillFresh)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")));
}

function latestModelDiffTaskForPair(doc, versionAId, versionBId) {
  return modelDiffTasks
    .filter((task) =>
      task.documentId === doc.id &&
      task.versionAId === versionAId &&
      task.versionBId === versionBId &&
      !["failed", "canceled"].includes(task.status),
    )
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
}

function modelDiffJobForTask(taskId) {
  const id = safeText(taskId, "");
  return jobs.find((job) => job.type === "model.diff" && job.payload?.taskId === id && ["queued", "running"].includes(job.status)) || null;
}

function activeModelDiffTaskForDocument(doc) {
  return modelDiffTasks
    .filter((task) => task.documentId === doc?.id && ["queued", "extracting", "comparing", "ai_analyzing"].includes(task.status))
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
}

function toPublicModelDiffTask(task) {
  return task ? normalizeModelDiffTask(task) : null;
}

function toPublicModelDiffRecord(record) {
  return record ? normalizeModelDiffRecord(record) : null;
}

function toPublicModelDiffRecordForDocument(record, doc) {
  const normalized = toPublicModelDiffRecord(record);
  if (!normalized || !normalized.issueId || !doc) {
    return normalized;
  }
  const issue = (Array.isArray(doc.annotations) ? doc.annotations : []).find((annotation) => annotation.id === normalized.issueId);
  if (issue) {
    normalized.issueStatus = safeText(issue.status, issue.resolved ? "resolved" : "open");
  }
  return normalized;
}

function toPublicModelDiffAiSummary(summary) {
  return summary ? normalizeModelDiffAiSummary(summary) : null;
}

function buildModelDiffHomePayload(userContext = SYSTEM_USER_CONTEXT) {
  const docs = modelDiffDocumentsForUser(userContext);
  const visibleIds = new Set(docs.map((doc) => doc.id));
  return {
    documents: docs,
    tasks: modelDiffTasks
      .filter((task) => safeText(task.projectId, DEFAULT_PROJECT_ID) === safeText(userContext.projectId, DEFAULT_PROJECT_ID) && visibleIds.has(task.documentId))
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
      .map(toPublicModelDiffTask),
  };
}

function buildModelDiffTaskPayload(task, userContext = SYSTEM_USER_CONTEXT) {
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task || !doc) {
    const error = new Error("模型差异任务不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该模型差异报告的权限。");
  }
  const projectId = safeText(userContext.projectId, DEFAULT_PROJECT_ID);
  const history = modelDiffTasks
    .filter((item) => item.documentId === doc.id && safeText(item.projectId, DEFAULT_PROJECT_ID) === projectId)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
    .map(toPublicModelDiffTask);
  const records = modelDiffRecordsForTask(task.id).map((record) => toPublicModelDiffRecordForDocument(record, doc));
  return {
    document: toPublicDocument(doc, userContext),
    task: toPublicModelDiffTask(task),
    records,
    propChanges: modelDiffPropChangesForTask(task.id).map(normalizeModelDiffPropChange).filter(Boolean),
    aiSummary: toPublicModelDiffAiSummary(modelDiffAiSummaryForTask(task.id)),
    snapshots: [modelDiffSnapshotById(task.snapshotAId), modelDiffSnapshotById(task.snapshotBId)].filter(Boolean).map(normalizeModelDiffSnapshot),
    history,
    trends: buildModelDiffTrendRows(doc, userContext),
  };
}

function assertModelDiffCapability(doc, userContext, options = {}) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该模型差异报告的权限。");
  }
  if (!modelDiffDocumentCandidate(doc)) {
    const error = new Error("当前文件不是可比对的三维模型。");
    error.statusCode = 400;
    throw error;
  }
  if (!options.skipApsSettings && !apsSettingsReady()) {
    const error = new Error("APS 服务尚未配置完整，请先到系统设置 / APS 配置填写 Client ID 和 Client Secret。");
    error.statusCode = 400;
    throw error;
  }
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("你没有发起模型差异对比任务的权限。");
  }
}

function modelDiffPayloadForVersion(body, versionId, side) {
  const payloads = body?.propertiesPayloads && typeof body.propertiesPayloads === "object" ? body.propertiesPayloads : {};
  return payloads[versionId] || (side === "A" ? body.propertiesPayloadA : body.propertiesPayloadB) || null;
}

function modelDiffModelUrnForVersion(doc, versionEntry, body = {}, side = "A") {
  const versionId = safeText(versionEntry?.id, "");
  const urns = body?.modelUrns && typeof body.modelUrns === "object" ? body.modelUrns : {};
  const fromBody = safeText(urns[versionId] || (side === "A" ? body.modelUrnA : body.modelUrnB), "");
  if (fromBody) {
    return fromBody;
  }
  const fromVersionEntry = safeText(versionEntry?.aps?.urn, "");
  if (fromVersionEntry) {
    return fromVersionEntry;
  }
  if ([safeText(doc.aps?.sourceVersionId, ""), safeText(doc.currentVersionId, "")].includes(versionId) && doc.aps?.urn) {
    return safeText(doc.aps.urn, "");
  }
  const quantityTask = quantityTakeoffTasks
    .filter((task) => task.documentId === doc.id && task.versionId === versionId && task.modelUrn)
    .sort((left, right) => safeText(right.completedAt || right.updatedAt, "").localeCompare(safeText(left.completedAt || left.updatedAt, "")))[0];
  if (quantityTask?.modelUrn) {
    return safeText(quantityTask.modelUrn, "");
  }
  const snapshot = modelDiffSnapshots
    .filter((item) => item.documentId === doc.id && item.versionId === versionId && item.modelUrn)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0];
  return safeText(snapshot?.modelUrn, "");
}

function hashModelDiffPayload(payload) {
  try {
    return sha256Hash(JSON.stringify(canonicalizeJson(payload)));
  } catch {
    return sha256Hash(JSON.stringify(payload || {}));
  }
}

function upsertModelDiffSnapshot(snapshotInput) {
  const snapshot = normalizeModelDiffSnapshot(snapshotInput);
  const index = modelDiffSnapshots.findIndex((item) =>
    item.documentId === snapshot.documentId &&
    item.versionId === snapshot.versionId &&
    item.payloadHash &&
    item.payloadHash === snapshot.payloadHash,
  );
  if (index >= 0) {
    modelDiffSnapshots.splice(index, 1, {
      ...modelDiffSnapshots[index],
      ...snapshot,
      id: modelDiffSnapshots[index].id,
      updatedAt: new Date().toISOString(),
    });
    return modelDiffSnapshots[index];
  }
  modelDiffSnapshots.unshift(snapshot);
  return snapshot;
}

function modelDiffSnapshotFromPayload(doc, versionEntry, modelUrn, payload, options = {}) {
  const elements = elementsFromDerivativeProperties(payload, {
    defaultDiscipline: doc.aps?.discipline || inferModelDisciplineFromDocument(doc),
    geometryIndex: doc.aps?.geometryIndex || [],
  });
  const now = new Date().toISOString();
  return upsertModelDiffSnapshot({
    id: crypto.randomUUID(),
    documentId: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    versionId: versionEntry.id,
    versionLabel: safeText(versionEntry.version, doc.version),
    modelUrn,
    payloadHash: hashModelDiffPayload(payload),
    extractionSource: safeText(options.source, "aps-properties"),
    objectCount: elements.length,
    elements,
    expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
    createdAt: now,
    updatedAt: now,
  });
}

function modelDiffSnapshotFromQuantityCache(doc, versionEntry, modelUrn) {
  const task = quantityTakeoffTasks
    .filter((item) => item.documentId === doc.id && item.versionId === versionEntry.id && item.status === "succeeded")
    .sort((left, right) => safeText(right.completedAt || right.updatedAt, "").localeCompare(safeText(left.completedAt || left.updatedAt, "")))[0];
  if (!task) {
    return null;
  }
  const snapshots = quantitySnapshotsForTask(task.id);
  if (!snapshots.length) {
    return null;
  }
  const payload = {
    data: {
      collection: snapshots.map((snapshot) => ({
        objectid: snapshot.dbId,
        name: snapshot.name,
        properties: Object.entries(snapshot.properties || {}).map(([displayName, displayValue]) => ({ displayName, displayValue })),
      })),
    },
  };
  const elements = elementsFromDerivativeProperties(payload, {
    defaultDiscipline: doc.aps?.discipline || inferModelDisciplineFromDocument(doc),
  });
  if (!elements.length || !elements.some((element) => element.stableKey)) {
    return null;
  }
  const now = new Date().toISOString();
  return upsertModelDiffSnapshot({
    id: crypto.randomUUID(),
    documentId: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    versionId: versionEntry.id,
    versionLabel: safeText(versionEntry.version, doc.version),
    modelUrn: modelUrn || task.modelUrn,
    payloadHash: `quantity:${task.id}:${snapshots.length}`,
    extractionSource: "quantity-cache",
    objectCount: elements.length,
    elements,
    expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
    createdAt: now,
    updatedAt: now,
  });
}

async function resolveModelDiffSnapshot(doc, versionEntry, options = {}) {
  const modelUrn = safeText(options.modelUrn, "");
  const providedPayload = options.propertiesPayload || null;
  if (providedPayload) {
    return modelDiffSnapshotFromPayload(doc, versionEntry, modelUrn, providedPayload, { source: "fixture" });
  }
  const cached = modelDiffSnapshotsForVersion(doc, versionEntry.id, modelUrn)[0];
  if (cached) {
    return cached;
  }
  const quantityCached = modelDiffSnapshotFromQuantityCache(doc, versionEntry, modelUrn);
  if (quantityCached) {
    return quantityCached;
  }
  if (!modelUrn) {
    const error = new Error(`版本 ${versionEntry.version || versionEntry.id} 缺少可用于属性提取的 APS URN，请先完成该版本转换或已有属性快照。`);
    error.statusCode = 400;
    throw error;
  }
  const payload = await fetchApsModelPropertiesForDocument(doc, modelUrn);
  return modelDiffSnapshotFromPayload(doc, versionEntry, modelUrn, payload, { source: "aps-properties" });
}

function enqueueModelDiffJob(doc, body, userContext, req = null) {
  const versionA = requireVersionEntry(doc, safeText(body.versionAId || body.versionA, ""));
  const versionB = requireVersionEntry(doc, safeText(body.versionBId || body.versionB, ""));
  if (versionA.id === versionB.id) {
    const error = new Error("请选择两个不同版本进行模型差异对比。");
    error.statusCode = 400;
    throw error;
  }
  const extA = path.extname(versionA.name || doc.name).toLowerCase();
  const extB = path.extname(versionB.name || doc.name).toLowerCase();
  if (extA && extB && extA !== extB) {
    const error = new Error("同一文件的不同格式版本不支持互相对比。");
    error.statusCode = 400;
    throw error;
  }
  const payloadA = modelDiffPayloadForVersion(body, versionA.id, "A");
  const payloadB = modelDiffPayloadForVersion(body, versionB.id, "B");
  const readinessA = modelDiffVersionReadiness(doc, versionA);
  const readinessB = modelDiffVersionReadiness(doc, versionB);
  const blockedVersions = [
    !payloadA && !readinessA.ready ? `${versionA.version || "版本 A"}：${readinessA.reason}` : "",
    !payloadB && !readinessB.ready ? `${versionB.version || "版本 B"}：${readinessB.reason}` : "",
  ].filter(Boolean);
  if (blockedVersions.length) {
    const error = new Error(`版本属性快照未就绪，不能发起模型差异对比。${blockedVersions.join("；")}。请先完成对应版本 APS 转换，或通过工程量/健康度功能生成属性快照。`);
    error.statusCode = 400;
    throw error;
  }
  const existing = latestModelDiffTaskForPair(doc, versionA.id, versionB.id);
  if (existing && body.force !== true) {
    return {
      task: existing,
      job: modelDiffJobForTask(existing.id),
      reused: true,
    };
  }
  const now = new Date().toISOString();
  const modelUrnA = modelDiffModelUrnForVersion(doc, versionA, body, "A");
  const modelUrnB = modelDiffModelUrnForVersion(doc, versionB, body, "B");
  const task = normalizeModelDiffTask({
    id: crypto.randomUUID(),
    documentId: doc.id,
    fileId: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    fileName: doc.name,
    versionAId: versionA.id,
    versionALabel: versionA.version,
    versionBId: versionB.id,
    versionBLabel: versionB.version,
    modelUrnA,
    modelUrnB,
    status: "queued",
    toleranceMm: body.toleranceMm,
    coordinateUnit: body.coordinateUnit || doc.aps?.coordinateSystem || "m",
    createdBy: actorDisplayName(userContext),
    createdByUserId: safeText(userContext?.user?.id, ""),
    createdAt: now,
    updatedAt: now,
  });
  modelDiffTasks = modelDiffTasks.filter((item) => !(item.documentId === doc.id && item.versionAId === versionA.id && item.versionBId === versionB.id));
  modelDiffTasks.unshift(task);
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "model.diff",
    status: "queued",
    resourceType: "document",
    resourceId: doc.id,
    payload: {
      taskId: task.id,
      documentId: doc.id,
      actor: actorDisplayName(userContext),
      actorUserId: safeText(userContext?.user?.id, ""),
      propertiesPayloadA: payloadA,
      propertiesPayloadB: payloadB,
    },
    attempts: 0,
    maxAttempts: Math.max(1, Number(body.maxAttempts || CDE_BACKGROUND_JOB_MAX_ATTEMPTS) || CDE_BACKGROUND_JOB_MAX_ATTEMPTS),
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  touchDocument(doc);
  addActivity(doc, actorDisplayName(userContext), "模型差异对比排队", `${doc.name} ${versionA.version} → ${versionB.version} 已加入差异对比队列`);
  appendAuditLog(userContext, "model_diff.enqueue", "model_diff_task", task.id, {
    documentId: doc.id,
    versionAId: versionA.id,
    versionBId: versionB.id,
  }, req);
  persistStore();
  return { task, job, reused: false };
}

function replaceModelDiffResults(task, diff) {
  const now = new Date().toISOString();
  const records = (Array.isArray(diff.records) ? diff.records : []).map((record) =>
    normalizeModelDiffRecord({
      ...record,
      id: crypto.randomUUID(),
      taskId: task.id,
      projectId: task.projectId,
      documentId: task.documentId,
      createdAt: now,
      updatedAt: now,
    }),
  );
  modelDiffRecords = modelDiffRecords.filter((record) => record.taskId !== task.id);
  modelDiffPropChanges = modelDiffPropChanges.filter((change) => change.taskId !== task.id);
  modelDiffRecords.unshift(...records);
  const propChanges = records.flatMap((record) =>
    (record.changedProps || []).map((change) => normalizeModelDiffPropChange({
      id: crypto.randomUUID(),
      diffId: record.id,
      taskId: task.id,
      propName: change.propName,
      valueA: change.valueA,
      valueB: change.valueB,
    })).filter(Boolean),
  );
  modelDiffPropChanges.unshift(...propChanges);
  return records;
}

async function requestExternalModelDiffNarrative(diff, context = {}) {
  const aiSettings = effectiveWorkflowCrsAiSettings();
  if (!systemAiSettingsReady(aiSettings)) {
    return null;
  }
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), aiSettings.timeoutMs);
  try {
    const response = await fetch(aiSettings.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(aiSettings.apiKey ? { Authorization: `Bearer ${aiSettings.apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: aiSettings.model || "",
        input: {
          task: context,
          stats: diff.stats,
          records: diff.records
            .filter((record) => record.diffType !== "unchanged")
            .slice(0, Math.max(10, Math.min(120, Number(aiSettings.batchSize || 100) || 100)))
            .map((record) => ({
              diffType: record.diffType,
              diffTypes: record.diffTypes,
              elementType: record.elementType,
              floor: record.floor,
              discipline: record.discipline,
              name: record.name,
              changedProps: record.changedProps,
              bboxDelta: record.bboxDelta,
            })),
          outputLanguage: "zh-CN",
          domain: "海水淡化工程模型差异审阅",
        },
      }),
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`Model diff AI request failed: ${response.status}`);
    }
    const body = await response.json();
    const source = body?.data || body?.result || body;
    if (safeText(source?.summary, "")) {
      return {
        summary: safeText(source.summary, ""),
        detailByDiscipline: Array.isArray(source.detailByDiscipline || source.detail_by_discipline)
          ? source.detailByDiscipline || source.detail_by_discipline
          : [],
      };
    }
  } finally {
    clearTimeout(timeout);
  }
  return null;
}

async function runModelDiffJob(doc, task, job) {
  const versionA = requireVersionEntry(doc, task.versionAId);
  const versionB = requireVersionEntry(doc, task.versionBId);
  task.status = "extracting";
  task.error = "";
  task.updatedAt = new Date().toISOString();
  persistStore();
  const snapshotA = await resolveModelDiffSnapshot(doc, versionA, {
    modelUrn: task.modelUrnA,
    propertiesPayload: job.payload?.propertiesPayloadA || null,
  });
  const snapshotB = await resolveModelDiffSnapshot(doc, versionB, {
    modelUrn: task.modelUrnB,
    propertiesPayload: job.payload?.propertiesPayloadB || null,
  });
  task.snapshotAId = snapshotA.id;
  task.snapshotBId = snapshotB.id;
  task.status = "comparing";
  task.updatedAt = new Date().toISOString();
  persistStore();
  const diff = compareModelSnapshots(snapshotA.elements, snapshotB.elements, {
    toleranceMm: task.toleranceMm,
    coordinateUnit: task.coordinateUnit,
    versionA: { id: versionA.id, label: versionA.version },
    versionB: { id: versionB.id, label: versionB.version },
  });
  const records = replaceModelDiffResults(task, diff);
  task.status = "ai_analyzing";
  task.summary = summarizeDiffRecords(records, {
    totalA: snapshotA.objectCount,
    totalB: snapshotB.objectCount,
  });
  task.recordCount = records.length;
  task.updatedAt = new Date().toISOString();
  persistStore();
  let narrative = null;
  try {
    narrative = await requestExternalModelDiffNarrative({ records, stats: task.summary }, {
      fileName: doc.name,
      versionA: { id: versionA.id, label: versionA.version },
      versionB: { id: versionB.id, label: versionB.version },
    });
  } catch (error) {
    console.warn("[model-diff-ai]", error.message || error);
  }
  narrative = narrative || generateModelDiffNarrative({ records, stats: task.summary }, {
    fileName: doc.name,
    versionA: { id: versionA.id, label: versionA.version },
    versionB: { id: versionB.id, label: versionB.version },
  });
  modelDiffAiSummaries = modelDiffAiSummaries.filter((summary) => summary.taskId !== task.id);
  modelDiffAiSummaries.unshift(normalizeModelDiffAiSummary({
    id: crypto.randomUUID(),
    taskId: task.id,
    ...narrative,
    generatedAt: new Date().toISOString(),
  }));
  const completedAt = new Date().toISOString();
  task.status = "completed";
  task.completedAt = completedAt;
  task.updatedAt = completedAt;
  touchDocument(doc);
  addActivity(doc, safeText(job.payload?.actor, "系统"), "模型差异对比完成", `${versionA.version} → ${versionB.version}：${task.summary.totalDiffs || 0} 项差异`);
  persistStore();
  const notification = await notifyModelDiffCompleted(doc, task, job).catch((error) => ({ status: "failed", error: safeText(error?.message, "") }));
  task.notification = notification || {};
  persistStore();
  return task;
}

function markModelDiffFailed(job, error) {
  const task = modelDiffTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task) {
    return;
  }
  task.status = "failed";
  task.error = safeText(error?.message, "模型差异对比失败");
  task.updatedAt = new Date().toISOString();
  if (doc) {
    addActivity(doc, safeText(job?.payload?.actor, "系统"), "模型差异对比失败", task.error);
  }
}

function markModelDiffRetryQueued(job, error) {
  const task = modelDiffTaskById(job?.payload?.taskId);
  if (!task) {
    return;
  }
  task.status = "queued";
  task.error = safeText(error?.message, "模型差异对比失败，等待自动重试");
  task.updatedAt = new Date().toISOString();
}

async function notifyModelDiffCompleted(doc, task, job) {
  const context = {
    document: doc,
    task,
    userContext: buildUserContext(userById(safeText(job.payload?.actorUserId, "")) || SYSTEM_USER_CONTEXT.user, doc.projectId),
    occurredAt: task.completedAt || new Date().toISOString(),
    note: `${task.versionALabel} → ${task.versionBLabel}：新增 ${task.summary.added || 0}，删除 ${task.summary.deleted || 0}，属性变更 ${task.summary.modified || 0}，位置移动 ${task.summary.moved || 0}`,
  };
  const email = await bestEffortProjectEmailNotification("modelDiffCompleted", context);
  const lark = await bestEffortLarkNotification("modelDiffCompleted", context);
  return { email, lark };
}

async function bestEffortLarkNotification(eventKey, context = {}) {
  if (!isLarkLoginConfigured()) {
    return { status: "skipped", reason: "channel_unavailable" };
  }
  const doc = notificationDocuments(context)[0] || context.document || null;
  const project = notificationProject(context);
  const recipients = projectAdminNotificationUsers(project.id)
    .concat(documentUploaderNotificationUsers(doc ? [doc] : []))
    .filter((user) => safeText(user?.larkOpenId, ""));
  const seen = new Set();
  const uniqueRecipients = recipients.filter((user) => {
    const openId = safeText(user.larkOpenId, "");
    if (!openId || seen.has(openId)) return false;
    seen.add(openId);
    return true;
  });
  if (!uniqueRecipients.length) {
    return { status: "skipped", reason: "no_lark_recipients" };
  }
  const token = await fetchLarkAppAccessToken();
  const textMessage = buildNotificationSummary(eventKey, context, project, notificationWorkflow(context), doc, null);
  const results = [];
  for (const user of uniqueRecipients.slice(0, 20)) {
    try {
      const response = await fetchLarkApiJson(
        `${LARK_OPEN_BASE_URL.replace(/\/+$/g, "")}/open-apis/im/v1/messages?receive_id_type=open_id`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            receive_id: user.larkOpenId,
            msg_type: "text",
            content: JSON.stringify({ text: textMessage }),
          }),
        },
        "发送飞书模型差异通知失败。",
      );
      results.push({ userId: user.id, status: "sent", messageId: safeText(response?.data?.message_id, "") });
    } catch (error) {
      results.push({ userId: user.id, status: "failed", error: safeText(error?.message, "") });
    }
  }
  appendAuditLog(context.userContext || SYSTEM_USER_CONTEXT, "notification.lark.model_diff", "model_diff_task", context.task?.id || "", {
    eventKey,
    recipientCount: uniqueRecipients.length,
    results,
  });
  persistStore();
  return { status: results.some((item) => item.status === "sent") ? "sent" : "failed", results };
}

function buildModelDiffTrendRows(doc, userContext = SYSTEM_USER_CONTEXT) {
  const projectId = safeText(userContext.projectId, DEFAULT_PROJECT_ID);
  return modelDiffTasks
    .filter((task) => task.documentId === doc.id && task.projectId === projectId && task.status === "completed")
    .sort((left, right) => safeText(left.completedAt || left.updatedAt, "").localeCompare(safeText(right.completedAt || right.updatedAt, "")))
    .map((task) => ({
      taskId: task.id,
      versionPair: `${task.versionALabel || task.versionAId} → ${task.versionBLabel || task.versionBId}`,
      versionAId: task.versionAId,
      versionBId: task.versionBId,
      added: Number(task.summary?.added || 0),
      deleted: Number(task.summary?.deleted || 0),
      modified: Number(task.summary?.modified || 0),
      moved: Number(task.summary?.moved || 0),
      total: Number(task.summary?.totalDiffs || 0),
      completedAt: task.completedAt,
      attention: Number(task.summary?.totalDiffs || 0) >= 40 ? "high_change_volume" : "",
    }));
}

async function createIssueFromModelDiffRecord(recordId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const record = modelDiffRecords.find((item) => item.id === recordId);
  if (!record) {
    const error = new Error("差异记录不存在。");
    error.statusCode = 404;
    throw error;
  }
  const task = modelDiffTaskById(record.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task || !doc) {
    const error = new Error("差异任务不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.annotations.create) {
    throw permissionDeniedError("你没有从模型差异创建 Issue 的权限。");
  }
  const dbIds = record.dbIdAfter !== null && record.dbIdAfter !== undefined
    ? [record.dbIdAfter]
    : record.dbIdBefore !== null && record.dbIdBefore !== undefined
      ? [record.dbIdBefore]
      : [];
  const changedText = (record.changedProps || [])
    .map((change) => `${change.propName}: ${change.valueA || "空"} → ${change.valueB || "空"}`)
    .join("；");
  const noteParts = [
    `差异类型：${record.diffType}`,
    `构件：${record.name}`,
    changedText ? `属性变化：${changedText}` : "",
    record.bboxDelta?.distanceMm ? `位置移动：${Number(record.bboxDelta.distanceMm).toFixed(0)}mm` : "",
    body.responsible ? `责任专业：${safeText(body.responsible, "")}` : "",
    body.dueDate ? `截止日期：${safeText(body.dueDate, "")}` : "",
  ].filter(Boolean);
  const customNote = safeText(body.note, "");
  const annotation = await createAnnotation({
    type: "note",
    variant: "model-diff",
    page: 1,
    x: 0.5,
    y: 0.5,
    width: 0.16,
    height: 0.08,
    title: safeText(body.title, `${record.elementType} ${record.diffType} 复核`),
    note: customNote ? `${noteParts.join("\n")}\n补充说明：${customNote}` : noteParts.join("\n"),
    actor: actorDisplayName(userContext),
    status: "open",
    dbIds,
    modelUrn: task.modelUrnB || task.modelUrnA || doc.aps?.urn || "",
    elementUniqueId: record.uniqueId,
    elementId: record.elementId,
    boundModelVersion: task.versionBLabel || doc.version,
    migrationStatus: record.diffType === "deleted" ? "deleted" : "synced",
    source: "model_diff",
  }, task.versionBId || doc.currentVersionId, {
    modelUrn: task.modelUrnB || doc.aps?.urn || "",
    boundModelVersion: task.versionBLabel || doc.version,
  });
  doc.annotations.unshift(annotation);
  record.issueId = annotation.id;
  record.issueStatus = "open";
  record.updatedAt = new Date().toISOString();
  addActivity(doc, actorDisplayName(userContext), "差异转 Issue", `${record.name} 的 ${record.diffType} 差异已创建 Issue`);
  persistStore();
  await bestEffortProjectEmailNotification("annotationCreated", {
    document: doc,
    annotation,
    userContext,
    occurredAt: annotation.createdAt,
  });
  return { record, issue: normalizeAnnotation(annotation, task.versionBId || doc.currentVersionId), document: doc };
}

function modelHealthFixturePayloadAllowed() {
  return String(process.env.CDE_ALLOW_MODEL_HEALTH_FIXTURE_PAYLOAD || "").trim() === "1";
}

function assertModelHealthPayloadBoundary(body = {}) {
  const payloads = body?.propertiesPayloads || body?.propertiesPayload;
  if (!payloads) {
    return;
  }
  if (modelHealthFixturePayloadAllowed()) {
    return;
  }
  const error = new Error("测试模型健康度属性载荷仅允许在 CDE_ALLOW_MODEL_HEALTH_FIXTURE_PAYLOAD=1 的测试环境使用。");
  error.statusCode = 400;
  throw error;
}

function modelHealthDocumentCandidate(doc) {
  return Boolean(doc && isApsModelDocument(doc.name) && apsDocumentWorkspaceKind(doc.name) === "model");
}

function modelHealthDocuments(userContext) {
  return publicDocumentsForUser(userContext)
    .filter(modelHealthDocumentCandidate)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      version: doc.version,
      currentVersionId: doc.currentVersionId,
      updatedAt: doc.updatedAt,
      aps: doc.aps,
      healthGate: modelHealthGateSummaryForDocument(doc),
    }));
}

function modelHealthRulesetsForProject(projectId) {
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  return modelHealthRulesets
    .filter((ruleset) => safeText(ruleset.projectId, DEFAULT_PROJECT_ID) === normalizedProjectId)
    .sort((left, right) => localeCollator("zh-CN").compare(safeText(left.name, ""), safeText(right.name, "")));
}

function ensureModelHealthRulesets(projectId) {
  const current = modelHealthRulesetsForProject(projectId);
  if (current.length) {
    return current;
  }
  const seeded = seedDefaultModelHealthRulesets([{ id: projectId }]);
  modelHealthRulesets.push(...seeded);
  persistStore();
  return modelHealthRulesetsForProject(projectId);
}

function modelHealthRulesetById(rulesetId, projectId = DEFAULT_PROJECT_ID) {
  const id = safeText(rulesetId, "");
  return modelHealthRulesets.find((ruleset) => ruleset.id === id && safeText(ruleset.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID)) || null;
}

function defaultModelHealthRulesetForDocument(doc) {
  const projectRulesets = ensureModelHealthRulesets(safeText(doc?.projectId, DEFAULT_PROJECT_ID));
  const discipline = safeText(doc?.aps?.discipline || inferModelDisciplineFromDocument(doc), "general").toLowerCase();
  return projectRulesets.find((ruleset) => safeText(ruleset.discipline, "").toLowerCase() === discipline) ||
    projectRulesets.find((ruleset) => safeText(ruleset.discipline, "").toLowerCase() === "desalination") ||
    projectRulesets.find((ruleset) => ["structure", "architecture", "plant3d"].includes(safeText(ruleset.discipline, "").toLowerCase())) ||
    projectRulesets[0] ||
    buildDefaultModelHealthRuleset({ projectId: safeText(doc?.projectId, DEFAULT_PROJECT_ID), discipline });
}

function latestModelHealthTaskForDocument(doc) {
  return modelHealthTasks
    .filter((task) => task.fileId === doc?.id && task.projectId === doc?.projectId)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
}

function activeModelHealthTaskForDocument(doc) {
  return modelHealthTasks
    .filter((task) => task.fileId === doc?.id && ["queued", "checking", "ai_analyzing"].includes(task.status))
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
}

function modelHealthTaskById(taskId) {
  const id = safeText(taskId, "");
  return modelHealthTasks.find((task) => task.id === id) || null;
}

function modelHealthRuleResultsForTask(task) {
  return task ? modelHealthRuleResults.filter((result) => result.taskId === task.id) : [];
}

function modelHealthAiResultsForTask(task) {
  return task ? modelHealthAiResults.filter((result) => result.taskId === task.id) : [];
}

function modelHealthPreviousReportForDocument(doc, excludingTaskId = "") {
  const previous = modelHealthTasks
    .filter((task) => task.fileId === doc?.id && task.status === "completed" && task.id !== excludingTaskId && task.report)
    .sort((left, right) => safeText(right.completedAt || right.updatedAt, "").localeCompare(safeText(left.completedAt || left.updatedAt, "")))[0];
  return previous?.report || null;
}

function modelHealthGateSummaryForTask(task, ruleResults = modelHealthRuleResultsForTask(task), aiResults = modelHealthAiResultsForTask(task), doc = null) {
  const normalizedTask = task ? normalizeModelHealthTask(task) : null;
  if (!normalizedTask) {
    return { status: "not_run", canStartWorkflow: false, message: "尚未完成模型健康度检查。", blockingCount: 0, openCount: 0, taskId: "" };
  }
  if (["queued", "checking", "ai_analyzing"].includes(normalizedTask.status)) {
    return { status: "running", canStartWorkflow: false, message: "模型健康度检查正在运行，请等待完成后再发起审批。", blockingCount: 0, openCount: 0, taskId: normalizedTask.id };
  }
  if (normalizedTask.status === "failed") {
    return { status: "failed", canStartWorkflow: false, message: "最近一次模型健康度检查失败，请重新运行检查。", blockingCount: 0, openCount: 0, taskId: normalizedTask.id };
  }
  if (doc && normalizedTask.versionId && normalizedTask.versionId !== doc.currentVersionId) {
    return { status: "stale", canStartWorkflow: false, message: "当前模型版本晚于最近一次健康度检查，请重新检查。", blockingCount: 0, openCount: 0, taskId: normalizedTask.id, versionId: normalizedTask.versionId, currentVersionId: doc.currentVersionId };
  }
  const ruleset = modelHealthRulesetById(normalizedTask.rulesetId, normalizedTask.projectId) || defaultModelHealthRulesetForDocument(doc);
  const gate = normalizeGateConfig(ruleset.gateConfig || {});
  const openRules = ruleResults.filter((item) => item.status === "open");
  const openAi = aiResults.filter((item) => item.feedbackStatus === "open" && item.actionRequired !== false);
  let blockers = [];
  if (gate.mode === "strict") {
    blockers = [...openRules.filter((item) => ["error", "warning"].includes(item.level)), ...openAi];
  } else if (gate.mode === "standard") {
    blockers = openRules.filter((item) => item.level === "error");
    if (gate.requireWarningDisposition) {
      blockers.push(...openRules.filter((item) => item.level === "warning"));
    }
    if (gate.requireAiDisposition) {
      blockers.push(...openAi);
    }
  }
  const errorCount = openRules.filter((item) => item.level === "error").length;
  if (gate.mode !== "loose" && errorCount > gate.errorThreshold) {
    blockers = [...new Map([...blockers, ...openRules.filter((item) => item.level === "error")].map((item) => [item.id, item])).values()];
  }
  const minScoreToSubmit = Math.max(0, Math.min(100, Number(gate.minScoreToSubmit || 0) || 0));
  if (gate.mode !== "loose" && minScoreToSubmit && normalizedTask.score < minScoreToSubmit) {
    blockers.push({
      id: `${normalizedTask.id}:score-gate`,
      level: "error",
      category: "score",
      description: `模型健康度评分 ${normalizedTask.score} 低于提交阈值 ${minScoreToSubmit}。`,
      dbIds: [],
    });
  }
  const openCount = openRules.length + openAi.length;
  return {
    status: blockers.length ? "blocked" : "ready",
    canStartWorkflow: blockers.length === 0 || gate.mode === "loose",
    message: blockers.length ? `仍有 ${blockers.length} 条模型健康度问题需要处理。` : "模型健康度门控已通过，可发起审批。",
    blockingCount: blockers.length,
    openCount,
    taskId: normalizedTask.id,
    versionId: normalizedTask.versionId,
    score: normalizedTask.score,
    summary: normalizedTask.summary,
    blockers: blockers.slice(0, 12).map((item) => ({
      id: item.id,
      level: item.level || "ai",
      category: item.category,
      description: item.description,
      dbIds: item.dbIds || [],
    })),
  };
}

function modelHealthGateSummaryForDocument(doc) {
  if (!modelHealthDocumentCandidate(doc)) {
    return { status: "optional", canStartWorkflow: true, message: "该文件不是三维模型，健康度检查为可选项。", blockingCount: 0, openCount: 0, taskId: "" };
  }
  const latestTask = latestModelHealthTaskForDocument(doc);
  if (!latestTask) {
    return { status: "not_run", canStartWorkflow: false, message: "模型发起审批前需先完成健康度检查。", blockingCount: 0, openCount: 0, taskId: "" };
  }
  return modelHealthGateSummaryForTask(latestTask, modelHealthRuleResultsForTask(latestTask), modelHealthAiResultsForTask(latestTask), doc);
}

function assertModelHealthGateAllowsWorkflow(doc, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  if (!modelHealthDocumentCandidate(doc)) {
    return null;
  }
  const gate = modelHealthGateSummaryForDocument(doc);
  if (gate.canStartWorkflow) {
    return null;
  }
  const override = body?.healthGateOverride && typeof body.healthGateOverride === "object" ? body.healthGateOverride : null;
  if (override?.reason && (isProjectAdminRole(userContext.projectRole) || isSuperAdmin(userContext))) {
    return {
      id: crypto.randomUUID(),
      fileId: doc.id,
      taskId: gate.taskId,
      reason: safeText(override.reason, ""),
      exemptResultIds: Array.isArray(override.exemptResultIds) ? override.exemptResultIds.map((item) => safeText(item, "")).filter(Boolean) : [],
      gate,
      approvedBy: actorDisplayName(userContext),
      createdAt: new Date().toISOString(),
    };
  }
  if (gate.status === "not_run") {
    const active = activeModelHealthTaskForDocument(doc) || enqueueModelHealthJob(doc, { actor: actorDisplayName(userContext), actorUserId: safeText(userContext?.user?.id, ""), reason: "workflow_gate_auto_check" });
    if (active?.id && !jobs.some((job) => job.type === "model.health" && job.payload?.taskId === active.id)) {
      scheduleAsyncJob(active);
    }
  }
  const error = new Error(`文件 ${doc.name} 未通过模型健康度审批前置门控。${gate.message || ""}`);
  error.statusCode = 409;
  error.detail = gate;
  throw error;
}

function buildModelHealthPayload(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  ensureModelHealthRulesets(projectId);
  const visibleIds = new Set(publicDocumentsForUser(userContext).map((doc) => doc.id));
  return {
    documents: modelHealthDocuments(userContext),
    rulesets: modelHealthRulesetsForProject(projectId).map(toPublicModelHealthRuleset),
    tasks: modelHealthTasks.filter((task) => task.projectId === projectId && visibleIds.has(task.fileId)).map(toPublicModelHealthTask),
    ruleResults: modelHealthRuleResults.filter((result) => result.projectId === projectId && visibleIds.has(result.fileId)).map(toPublicModelHealthRuleResult),
    aiResults: modelHealthAiResults.filter((result) => result.projectId === projectId && visibleIds.has(result.fileId)).map(toPublicModelHealthAiResult),
  };
}

function toPublicModelHealthRuleset(ruleset) {
  return normalizeModelHealthRuleset(ruleset);
}

function buildModelHealthDocumentPayload(doc, userContext) {
  const tasks = modelHealthTasks
    .filter((task) => task.fileId === doc.id)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
    .map(toPublicModelHealthTask);
  const latestTask = tasks[0] || null;
  const task = latestTask ? modelHealthTaskById(latestTask.id) : null;
  const ruleResults = task ? modelHealthRuleResultsForTask(task).map(toPublicModelHealthRuleResult) : [];
  const aiResults = task ? modelHealthAiResultsForTask(task).map(toPublicModelHealthAiResult) : [];
  return {
    document: toPublicDocument(doc, userContext),
    rulesets: modelHealthRulesetsForProject(doc.projectId).map(toPublicModelHealthRuleset),
    tasks,
    latestTask,
    ruleResults,
    aiResults,
    report: task?.report || null,
    gate: modelHealthGateSummaryForTask(task, ruleResults, aiResults, doc),
  };
}

function createModelHealthRuleset(body, userContext) {
  if (!isProjectAdminRole(userContext.projectRole) && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以配置模型健康度规则集。");
  }
  const now = new Date().toISOString();
  const ruleset = normalizeModelHealthRuleset({
    ...body,
    id: crypto.randomUUID(),
    projectId: safeText(userContext?.projectId, DEFAULT_PROJECT_ID),
    builtIn: false,
    version: safeText(body.version, `1.0.${Date.now()}`),
    createdAt: now,
    updatedAt: now,
  });
  modelHealthRulesets.unshift(ruleset);
  persistStore();
  return ruleset;
}

function updateModelHealthRuleset(rulesetId, body, userContext) {
  if (!isProjectAdminRole(userContext.projectRole) && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以配置模型健康度规则集。");
  }
  const ruleset = modelHealthRulesetById(rulesetId, userContext.projectId);
  if (!ruleset) {
    const error = new Error("Model health ruleset not found");
    error.statusCode = 404;
    throw error;
  }
  Object.assign(ruleset, normalizeModelHealthRuleset({
    ...ruleset,
    ...body,
    id: ruleset.id,
    projectId: ruleset.projectId,
    builtIn: false,
    updatedAt: new Date().toISOString(),
  }));
  persistStore();
  return ruleset;
}

function assertModelHealthRunCapability(doc, userContext, options = {}) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该模型健康度报告的权限。");
  }
  if (!modelHealthDocumentCandidate(doc)) {
    const error = new Error(`文件 ${doc.name} 不是可检查的三维模型。`);
    error.statusCode = 400;
    throw error;
  }
  if (!apsSettingsReady() && !options.skipApsSettings) {
    const error = new Error("APS 服务尚未配置完整，请先到系统设置 / APS 配置填写 Client ID 和 Client Secret。");
    error.statusCode = 400;
    throw error;
  }
  if (!doc.aps?.urn || normalizeApsTranslationStatus(doc.aps?.translationStatus, doc.aps?.urn ? "success" : "idle") !== "success") {
    const error = new Error("所选模型尚未完成 APS 转换，不能发起健康度检查。");
    error.statusCode = 400;
    throw error;
  }
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("你没有发起模型健康度检查的权限。");
  }
}

function enqueueModelHealthJob(doc, options = {}) {
  const existing = activeModelHealthTaskForDocument(doc);
  if (existing && !options.force) {
    return modelHealthJobForTask(existing.id) || existing;
  }
  const now = new Date().toISOString();
  const ruleset = modelHealthRulesetById(options.rulesetId, doc.projectId) || defaultModelHealthRulesetForDocument(doc);
  const task = normalizeModelHealthTask({
    id: crypto.randomUUID(),
    fileId: doc.id,
    projectId: doc.projectId,
    fileName: doc.name,
    versionId: doc.currentVersionId,
    version: doc.version,
    rulesetId: ruleset.id,
    status: "queued",
    triggeredBy: safeText(options.actorUserId, ""),
    triggeredByName: safeText(options.actor, "系统"),
    createdAt: now,
    updatedAt: now,
  });
  modelHealthTasks.unshift(task);
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "model.health",
    status: "queued",
    resourceType: "document",
    resourceId: doc.id,
    payload: {
      taskId: task.id,
      documentId: doc.id,
      actor: safeText(options.actor, "系统"),
      actorUserId: safeText(options.actorUserId, ""),
      propertiesPayload: options.propertiesPayload || null,
    },
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  touchDocument(doc);
  addActivity(doc, safeText(options.actor, "系统"), "模型健康度检查排队", `${doc.name} ${doc.version} 已加入检查队列`);
  persistStore();
  return job;
}

function modelHealthJobForTask(taskId) {
  const id = safeText(taskId, "");
  return jobs.find((job) => job.type === "model.health" && job.payload?.taskId === id && ["queued", "running"].includes(job.status)) || null;
}

async function requestExternalModelHealthAi(payload) {
  const aiSettings = effectiveWorkflowCrsAiSettings();
  if (!systemAiSettingsReady(aiSettings)) {
    return null;
  }
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), aiSettings.timeoutMs);
  try {
    const response = await fetch(aiSettings.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(aiSettings.apiKey ? { Authorization: `Bearer ${aiSettings.apiKey}` } : {}),
      },
      body: JSON.stringify({ model: aiSettings.model || "", input: payload }),
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`Model health AI request failed: ${response.status}`);
    }
    const body = await response.json();
    return body?.results ? body : body?.data || body;
  } finally {
    clearTimeout(timeout);
  }
}

async function runModelHealthJob(doc, task, job) {
  task.status = "checking";
  task.error = "";
  task.updatedAt = new Date().toISOString();
  persistStore();
  const propertiesPayload = job.payload?.propertiesPayload || await fetchApsModelPropertiesForDocument(doc, doc.aps?.urn);
  const ruleset = modelHealthRulesetById(task.rulesetId, task.projectId) || defaultModelHealthRulesetForDocument(doc);
  const elements = modelElementsFromDerivativeProperties(propertiesPayload, {
    geometryIndex: doc.aps?.geometryIndex || [],
    defaultDiscipline: doc.aps?.discipline || inferModelDisciplineFromDocument(doc),
  });
  const now = new Date().toISOString();
  const ruleResults = runModelHealthRuleChecks(elements, ruleset).map((result) => normalizeModelHealthRuleResult({
    ...result,
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    fileId: doc.id,
    createdAt: now,
    updatedAt: now,
  }));
  modelHealthRuleResults = modelHealthRuleResults.filter((result) => result.taskId !== task.id);
  modelHealthRuleResults.unshift(...ruleResults);
  task.status = "ai_analyzing";
  task.updatedAt = new Date().toISOString();
  persistStore();
  const aiResults = await runModelHealthAiChecks(elements, ruleResults, ruleset, {
    maxCalls: 5,
    externalAiInvoker: requestExternalModelHealthAi,
  });
  const normalizedAiResults = aiResults.map((result) => normalizeModelHealthAiResult({
    ...result,
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    fileId: doc.id,
    createdAt: now,
    updatedAt: now,
  }));
  modelHealthAiResults = modelHealthAiResults.filter((result) => result.taskId !== task.id);
  modelHealthAiResults.unshift(...normalizedAiResults);
  const previousReport = modelHealthPreviousReportForDocument(doc, task.id);
  const report = buildModelHealthReport({
    task,
    ruleset,
    ruleResults,
    aiResults: normalizedAiResults,
    previousReport,
  });
  const completedAt = new Date().toISOString();
  const summary = summarizeModelHealthResults(ruleResults, normalizedAiResults);
  task.status = "completed";
  task.score = report.score;
  task.summary = summary;
  task.report = report;
  task.completedAt = completedAt;
  task.updatedAt = completedAt;
  task.gate = modelHealthGateSummaryForTask(task, ruleResults, normalizedAiResults, doc);
  touchDocument(doc);
  addActivity(doc, safeText(job.payload?.actor, "系统"), "模型健康度检查完成", `评分 ${task.score}，Error ${summary.errorCount}，Warning ${summary.warningCount}，AI ${summary.aiCount}`);
  persistStore();
  return task;
}

function markModelHealthFailed(job, error) {
  const task = modelHealthTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.fileId) : null;
  if (!task) return;
  task.status = "failed";
  task.error = safeText(error?.message, "模型健康度检查失败");
  task.updatedAt = new Date().toISOString();
  task.gate = modelHealthGateSummaryForTask(task, [], [], doc);
  if (doc) {
    addActivity(doc, safeText(job?.payload?.actor, "系统"), "模型健康度检查失败", task.error);
  }
}

function updateModelHealthRuleResult(resultId, body, userContext) {
  const result = modelHealthRuleResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("模型健康度规则结果不存在。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(result.fileId, userContext);
  assertDocumentCapability(doc, "annotations.updateOwn", userContext, "你没有处理模型健康度问题的权限。");
  result.status = ["open", "resolved", "accepted"].includes(safeText(body?.status, "")) ? safeText(body.status, "") : result.status;
  result.updatedAt = new Date().toISOString();
  const task = modelHealthTaskById(result.taskId);
  if (task) {
    task.gate = modelHealthGateSummaryForTask(task, modelHealthRuleResultsForTask(task), modelHealthAiResultsForTask(task), doc);
    task.updatedAt = result.updatedAt;
  }
  persistStore();
  return result;
}

function updateModelHealthAiFeedback(resultId, body, userContext) {
  const result = modelHealthAiResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("模型健康度 AI 结果不存在。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(result.fileId, userContext);
  assertDocumentCapability(doc, "annotations.updateOwn", userContext, "你没有处理模型健康度 AI 结果的权限。");
  const nextStatus = ["open", "confirmed", "accepted", "false_positive"].includes(safeText(body?.feedbackStatus, "")) ? safeText(body.feedbackStatus, "") : result.feedbackStatus;
  result.feedbackStatus = nextStatus;
  result.status = nextStatus === "open" ? "open" : "resolved";
  result.updatedAt = new Date().toISOString();
  let falsePositiveRecord = null;
  if (nextStatus === "false_positive") {
    falsePositiveRecord = normalizeModelHealthFalsePositiveRecord({
      id: crypto.randomUUID(),
      aiResultId: result.id,
      taskId: result.taskId,
      projectId: result.projectId,
      markedBy: safeText(body?.actor, actorDisplayName(userContext)),
      reason: safeText(body?.reason, "经人工确认该 AI 结果为误报。"),
      createdAt: result.updatedAt,
    });
    modelHealthFalsePositiveRecords.unshift(falsePositiveRecord);
  }
  const task = modelHealthTaskById(result.taskId);
  if (task) {
    task.gate = modelHealthGateSummaryForTask(task, modelHealthRuleResultsForTask(task), modelHealthAiResultsForTask(task), doc);
    task.updatedAt = result.updatedAt;
  }
  persistStore();
  return { aiResult: result, falsePositiveRecord };
}

function workflowCrsSourceDocuments(workflow) {
  return (workflow?.fileRefs || [])
    .map((fileRef) => documents.find((item) => item.id === fileRef.docId))
    .filter(Boolean);
}

function workflowDocumentVersionLabel(doc, versionId = "") {
  const history = Array.isArray(doc?.versionHistory) ? doc.versionHistory : [];
  const matched = history.find((item) => safeText(item?.id, "") === safeText(versionId, ""));
  return safeText(matched?.version, safeText(doc?.version, "V1"));
}

function uniqueTextValues(values) {
  return Array.from(
    new Set(
      (values || [])
        .map((item) => safeText(item, ""))
        .filter(Boolean),
    ),
  );
}

function workflowAnnotationReplyContents(annotation) {
  return uniqueTextValues((annotation?.replies || []).map((reply) => safeText(reply?.content, "")));
}

function workflowCrsApprovalCommentStatus(reviewerStatus = "") {
  if (reviewerStatus === "approved") {
    return "closed";
  }
  if (reviewerStatus === "rejected") {
    return "open";
  }
  return "needs_review";
}

function workflowCrsAnnotationStatus(status = "") {
  if (status === "resolved") {
    return "closed";
  }
  if (status === "in_progress") {
    return "replied";
  }
  return "open";
}

function workflowCrsRecordContent(record) {
  return safeText(record?.content, "");
}

function normalizeWorkflowCrsSimilarityText(value) {
  return safeText(value, "")
    .toLowerCase()
    .replace(/[\s\p{P}\p{S}]+/gu, "")
    .trim();
}

function workflowCrsBigrams(value) {
  const normalized = normalizeWorkflowCrsSimilarityText(value);
  if (!normalized) {
    return new Set();
  }
  const chars = Array.from(normalized);
  if (chars.length < 2) {
    return new Set([normalized]);
  }
  const output = new Set();
  for (let index = 0; index < chars.length - 1; index += 1) {
    output.add(`${chars[index]}${chars[index + 1]}`);
  }
  return output;
}

function workflowCrsSimilarity(leftText, rightText) {
  const left = workflowCrsBigrams(leftText);
  const right = workflowCrsBigrams(rightText);
  if (!left.size || !right.size) {
    return 0;
  }
  let overlap = 0;
  left.forEach((item) => {
    if (right.has(item)) {
      overlap += 1;
    }
  });
  return (2 * overlap) / (left.size + right.size);
}

function workflowCrsInferDiscipline(textValue = "", context = "") {
  const haystack = `${safeText(textValue, "")} ${safeText(context, "")}`;
  const rules = [
    ["结构", ["结构", "梁", "柱", "板", "基础", "配筋", "剪力墙", "钢筋", "钢结构", "荷载"]],
    ["工艺", ["工艺", "流程", "设备布置", "工序", "反应釜", "泵组", "阀门", "管线流程"]],
    ["电气", ["电气", "配电", "电缆", "桥架", "照明", "接地", "开关柜", "动力"]],
    ["暖通", ["暖通", "风管", "空调", "送风", "回风", "排烟", "风口"]],
    ["给排水", ["给排水", "排水", "给水", "消防", "喷淋", "立管", "阀井"]],
    ["建筑", ["建筑", "门窗", "平面", "立面", "剖面", "净高", "装修"]],
  ];
  const matched = rules.find(([, keywords]) => keywords.some((keyword) => haystack.includes(keyword)));
  return matched ? matched[0] : "综合";
}

function workflowCrsInferIssueType(textValue = "", replyValue = "") {
  const haystack = `${safeText(textValue, "")} ${safeText(replyValue, "")}`;
  const rules = [
    ["规范不符", ["规范", "标准", "不符合", "不满足", "条文", "规范要求"]],
    ["需澄清", ["确认", "澄清", "请说明", "待确认", "不明确", "建议说明"]],
    ["设计错误", ["错误", "有误", "冲突", "碰撞", "遗漏", "缺失", "调整"]],
    ["资料缺失", ["缺少", "补充", "附件", "资料", "缺失", "未提供"]],
    ["施工可实施性", ["施工", "安装", "检修", "操作空间", "可达性", "吊装"]],
  ];
  const matched = rules.find(([, keywords]) => keywords.some((keyword) => haystack.includes(keyword)));
  return matched ? matched[0] : "其他";
}

function workflowCrsMergeStatus(records, replyContent = "") {
  const statuses = new Set((records || []).map((item) => safeText(item?.status, "open")).filter(Boolean));
  const hasClosed = statuses.has("closed");
  const hasOpen = statuses.has("open");
  const hasReplied = statuses.has("replied");
  const mixed = statuses.size > 1 && ((hasClosed && (hasOpen || hasReplied)) || (hasOpen && hasReplied));
  if (mixed) {
    return "needs_review";
  }
  if (hasClosed) {
    return "closed";
  }
  if (replyContent || hasReplied) {
    return "replied";
  }
  return "open";
}

function workflowCrsConclusionForStatus(status, replyContent = "", needsHumanReview = false) {
  if (needsHumanReview || status === "needs_review") {
    return "意见存在状态或语义冲突，需人工重点核查后确认闭环。";
  }
  if (status === "closed") {
    return replyContent ? "已形成回复并闭环，可纳入归档。": "该意见已闭环，可纳入归档。";
  }
  if (status === "replied") {
    return "已有回复，建议审批人确认后关闭。";
  }
  return "尚未形成明确回复，需继续处理。";
}

function workflowCrsStatusForLabel(status) {
  return {
    open: "待处理",
    replied: "已回复",
    closed: "已关闭",
    needs_review: "需确认",
  }[safeText(status, "open")] || "待处理";
}

function workflowCrsApprovalCycle(workflow) {
  const start = safeText(workflow?.createdAt, "").slice(0, 10);
  const end = safeText(workflow?.updatedAt, workflow?.createdAt || "").slice(0, 10);
  if (start && end && start !== end) {
    return `${start} ~ ${end}`;
  }
  return start || end || "—";
}

function workflowCrsSourceStats(workflow) {
  const docs = workflowCrsSourceDocuments(workflow);
  const versionIds = new Set();
  let annotationCount = 0;
  let replyCount = 0;
  docs.forEach((doc) => {
    (doc.annotations || []).forEach((annotation) => {
      annotationCount += 1;
      replyCount += Array.isArray(annotation.replies) ? annotation.replies.length : 0;
      if (annotation.versionId) {
        versionIds.add(annotation.versionId);
      }
    });
  });
  const approvalCommentCount = (workflow?.steps || []).reduce(
    (count, step) => count + (step.reviewers || []).filter((reviewer) => safeText(reviewer?.comment, "")).length,
    0,
  );
  return {
    totalRecords: annotationCount + approvalCommentCount,
    documentCount: docs.length,
    versionCount: versionIds.size || docs.length,
    annotationCount,
    replyCount,
    approvalCommentCount,
  };
}

function collectWorkflowCrsSourceRecords(workflow) {
  const docs = workflowCrsSourceDocuments(workflow);
  const records = [];
  docs.forEach((doc) => {
    (doc.annotations || []).forEach((annotation) => {
      const content = uniqueTextValues([annotation.title, annotation.note]).join(" · ");
      const replyContents = workflowAnnotationReplyContents(annotation);
      records.push({
        kind: "annotation",
        id: safeText(annotation.id, crypto.randomUUID()),
        workflowId: workflow.id,
        docId: doc.id,
        docName: doc.name,
        versionId: safeText(annotation.versionId, safeText(doc.currentVersionId, "")),
        versionLabel: workflowDocumentVersionLabel(doc, annotation.versionId),
        page: Number(annotation.page || 0) || 0,
        actor: safeText(annotation.actor, "系统"),
        content,
        replyContents,
        status: workflowCrsAnnotationStatus(annotation.status),
        createdAt: safeText(annotation.createdAt, doc.updatedAt),
        context: `${doc.name} ${annotation.type || ""} ${annotation.note || ""}`,
      });
    });
  });
  (workflow.steps || []).forEach((step) => {
    (step.reviewers || []).forEach((reviewer) => {
      const comment = safeText(reviewer?.comment, "");
      if (!comment) {
        return;
      }
      records.push({
        kind: "approval",
        id: safeText(reviewer?.id, crypto.randomUUID()),
        workflowId: workflow.id,
        docId: "",
        docName: "",
        versionId: "",
        versionLabel: "",
        page: 0,
        actor: safeText(reviewer?.name, "审批人"),
        content: comment,
        replyContents: [],
        status: workflowCrsApprovalCommentStatus(reviewer?.status),
        createdAt: safeText(reviewer?.actedAt, workflow.updatedAt),
        context: `${safeText(step?.name, "")} ${comment}`,
      });
    });
  });
  return records
    .map((record) => ({
      ...record,
      similarityText: normalizeWorkflowCrsSimilarityText(record.content),
    }))
    .filter((record) => record.similarityText || record.replyContents.length)
    .sort((left, right) => String(left.createdAt || "").localeCompare(String(right.createdAt || "")));
}

function groupWorkflowCrsRecords(records) {
  const groups = [];
  records.forEach((record) => {
    let bestGroup = null;
    let bestScore = 0;
    groups.forEach((group) => {
      const score = Math.max(
        workflowCrsSimilarity(group.canonicalText, record.content),
        ...group.sourceTexts.map((textValue) => workflowCrsSimilarity(textValue, record.content)),
      );
      if (score > bestScore) {
        bestScore = score;
        bestGroup = group;
      }
    });
    if (bestGroup && (bestScore >= 0.72 || bestGroup.sourceTexts.includes(record.content))) {
      bestGroup.records.push(record);
      bestGroup.sourceTexts.push(record.content);
      if (record.content.length >= bestGroup.canonicalText.length) {
        bestGroup.canonicalText = record.content;
      }
      bestGroup.similarityTotal += bestScore;
      bestGroup.similaritySamples += 1;
      return;
    }
    groups.push({
      id: crypto.randomUUID(),
      canonicalText: record.content,
      sourceTexts: [record.content],
      records: [record],
      similarityTotal: 1,
      similaritySamples: 1,
    });
  });
  return groups;
}

function workflowCrsManualReason(group, status, replyContent, avgSimilarity) {
  if (status === "needs_review") {
    return "存在已关闭与未关闭意见混合，需人工确认最终状态。";
  }
  if (group.records.length > 1 && avgSimilarity < 0.82) {
    return "多条意见已自动归并，但语义相似度较低，建议人工复核。";
  }
  if (!replyContent && group.records.some((record) => record.kind === "approval")) {
    return "包含审批意见但缺少明确回复，建议人工补充结论。";
  }
  return "";
}

function buildWorkflowCrsDraftReportFromRecords(workflow, records) {
  const sourceStats = workflowCrsSourceStats(workflow);
  const grouped = groupWorkflowCrsRecords(records);
  const items = grouped
    .map((group, index) => {
      const reviewerNames = uniqueTextValues(group.records.map((record) => record.actor));
      const replyContent = uniqueTextValues(group.records.flatMap((record) => record.replyContents || [])).join("；");
      const discipline = workflowCrsInferDiscipline(group.canonicalText, group.records.map((record) => record.context).join(" "));
      const issueType = workflowCrsInferIssueType(group.canonicalText, replyContent);
      const status = workflowCrsMergeStatus(group.records, replyContent);
      const avgSimilarity = group.similaritySamples ? group.similarityTotal / group.similaritySamples : 1;
      const manualReason = workflowCrsManualReason(group, status, replyContent, avgSimilarity);
      const needsHumanReview = Boolean(manualReason);
      const versionLabel = uniqueTextValues(group.records.map((record) => record.versionLabel)).join(" / ");
      const pageLabel = uniqueTextValues(group.records.map((record) => (record.page ? `P${record.page}` : ""))).join(" / ");
      const source = reviewerNames.length ? reviewerNames.join(" / ") : "系统";
      return normalizeWorkflowCrsDraftItem(
        {
          id: group.id,
          index: index + 1,
          source: group.records.length > 1 ? `${source} · ${group.records.length} 条原始意见` : source,
          discipline,
          issueType,
          issueContent: group.canonicalText,
          replyContent: replyContent || "—",
          conclusion: workflowCrsConclusionForStatus(status, replyContent, needsHumanReview),
          status,
          needsHumanReview,
          confidence: Number(avgSimilarity.toFixed(2)),
          versionLabel,
          reviewerNames,
          sourceCount: group.records.length,
          docName: uniqueTextValues(group.records.map((record) => record.docName)).join(" / "),
          pageLabel,
        },
        index,
      );
    })
    .sort((left, right) => {
      const leftPriority = left.status === "closed" ? 1 : left.status === "replied" ? 2 : left.status === "needs_review" ? 0 : 3;
      const rightPriority = right.status === "closed" ? 1 : right.status === "replied" ? 2 : right.status === "needs_review" ? 0 : 3;
      if (leftPriority !== rightPriority) {
        return leftPriority - rightPriority;
      }
      return left.index - right.index;
    })
    .map((item, index) => ({ ...item, index: index + 1 }));

  const unresolvedItems = items.filter((item) => item.status !== "closed");
  const manualCheckItems = items
    .filter((item) => item.needsHumanReview)
    .map((item) => `${item.index}. ${item.issueContent}`);
  const versionLabel = uniqueTextValues(records.map((record) => record.versionLabel)).join(" / ");
  const executiveSummary = [
    `本轮审批覆盖 ${sourceStats.documentCount || 0} 个文件、${sourceStats.versionCount || 0} 个版本，`,
    `系统共收集 ${sourceStats.totalRecords || 0} 条批注与审批意见，自动归并为 ${items.length} 条 CRS 草稿。`,
    `其中已关闭 ${items.filter((item) => item.status === "closed").length} 条，`,
    `待处理 ${items.filter((item) => item.status === "open").length} 条，`,
    `已回复待确认 ${items.filter((item) => item.status === "replied").length} 条，`,
    `需人工重点核查 ${manualCheckItems.length} 条。`,
  ].join("");
  const unresolvedSummary = unresolvedItems.length
    ? unresolvedItems
        .slice(0, 10)
        .map((item) => `${item.index}. ${item.issueContent}（${workflowCrsStatusForLabel(item.status)}）`)
        .join("\n")
    : "当前无未解决意见。";
  const aiSettings = effectiveWorkflowCrsAiSettings();
  return normalizeWorkflowCrsDraft({
    status: "succeeded",
    progress: 100,
    error: "",
    message: "CRS 草稿已生成，可继续编辑与确认。",
    provider: "heuristic",
    model: "",
    batchCount: Math.max(1, Math.ceil(records.length / aiSettings.batchSize)),
    generatedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    sourceStats: {
      ...sourceStats,
      itemCount: items.length,
      unresolvedCount: unresolvedItems.length,
      manualCheckCount: manualCheckItems.length,
    },
    report: {
      fileName:
        workflow.fileRefs?.length === 1
          ? safeText(workflowCrsSourceDocuments(workflow)[0]?.name, safeText(workflow.workflowName, "未命名流程"))
          : `${safeText(workflow.workflowName, "未命名流程")}（${sourceStats.documentCount} 个文件）`,
      versionLabel: versionLabel || "当前流程版本",
      approvalCycle: workflowCrsApprovalCycle(workflow),
      executiveSummary,
      unresolvedSummary,
      manualCheckItems,
      items,
    },
  });
}

function workflowCrsPromptPayload(workflow, records) {
  return {
    task: "workflow_crs_draft",
    workflow: {
      id: workflow.id,
      workflowName: workflow.workflowName,
      templateName: workflow.templateName,
      createdAt: workflow.createdAt,
      updatedAt: workflow.updatedAt,
      dueDate: workflow.dueDate,
    },
    records: records.map((record) => ({
      kind: record.kind,
      docName: record.docName,
      versionLabel: record.versionLabel,
      page: record.page,
      actor: record.actor,
      status: record.status,
      content: record.content,
      replies: record.replyContents,
      createdAt: record.createdAt,
    })),
    instructions: [
      "将同一文件多轮批注和审批意见自动归并为 CRS 草稿。",
      "需要输出执行摘要、未解决意见汇总、需人工确认项，以及结构化 items 数组。",
      "items 每项包含 source, discipline, issueType, issueContent, replyContent, conclusion, status, needsHumanReview。",
      "status 仅允许 open / replied / closed / needs_review。",
    ],
  };
}

async function requestExternalWorkflowCrsDraft(workflow, records) {
  const aiSettings = effectiveWorkflowCrsAiSettings();
  if (!systemAiSettingsReady(aiSettings)) {
    return null;
  }
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), aiSettings.timeoutMs);
  try {
    const response = await fetch(aiSettings.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(aiSettings.apiKey ? { Authorization: `Bearer ${aiSettings.apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: aiSettings.model || "",
        input: workflowCrsPromptPayload(workflow, records),
      }),
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`CRS AI request failed: ${response.status}`);
    }
    const payload = await response.json();
    return normalizeWorkflowCrsDraft({
      ...(payload?.report ? payload : payload?.data || {}),
      provider: "external_ai",
      model: aiSettings.model || safeText(payload?.model, ""),
    });
  } finally {
    clearTimeout(timeout);
  }
}

async function generateWorkflowCrsDraftReport(workflow, records) {
  if (systemAiSettingsReady(effectiveWorkflowCrsAiSettings())) {
    try {
      const external = await requestExternalWorkflowCrsDraft(workflow, records);
      if (external?.report?.items?.length || external?.report?.executiveSummary) {
        return normalizeWorkflowCrsDraft({
          ...external,
          sourceStats: {
            ...workflowCrsSourceStats(workflow),
            ...(external.sourceStats || {}),
          },
        });
      }
    } catch (error) {
      console.warn("[crs-ai]", error.message || error);
    }
  }
  return buildWorkflowCrsDraftReportFromRecords(workflow, records);
}

async function runWorkflowCrsDraftJob(workflow, job = null) {
  if (!workflow) {
    return null;
  }
  const now = new Date().toISOString();
  const currentDraft = normalizeWorkflowCrsDraft(workflow.crsDraft);
  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...currentDraft,
    status: "running",
    progress: 18,
    error: "",
    message: "正在收集流程批注、回复与审批意见",
    updatedAt: now,
    jobId: job?.id || currentDraft.jobId,
  });
  persistStore();
  await waitMs(CDE_CRS_JOB_STAGE_DELAY_MS);

  const records = collectWorkflowCrsSourceRecords(workflow);
  if (!records.length) {
    workflow.crsDraft = normalizeWorkflowCrsDraft({
      ...workflow.crsDraft,
      status: "failed",
      progress: 100,
      error: "当前流程还没有可用于生成 CRS 草稿的批注或审批意见。",
      message: "未找到可汇总的数据源",
      updatedAt: new Date().toISOString(),
    });
    persistStore();
    return workflow;
  }

  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...workflow.crsDraft,
    status: "running",
    progress: 42,
    batchCount: Math.max(1, Math.ceil(records.length / effectiveWorkflowCrsAiSettings().batchSize)),
    sourceStats: workflowCrsSourceStats(workflow),
    message: "正在归并相似意见并生成摘要",
    updatedAt: new Date().toISOString(),
  });
  persistStore();
  await waitMs(CDE_CRS_JOB_STAGE_DELAY_MS);

  const report = await generateWorkflowCrsDraftReport(workflow, records);
  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...workflow.crsDraft,
    ...report,
    status: "running",
    progress: 82,
    message: "正在整理未解决意见与人工确认项",
    updatedAt: new Date().toISOString(),
    confirmedAt: "",
    confirmedBy: "",
    confirmedByUserId: "",
  });
  persistStore();
  await waitMs(CDE_CRS_JOB_STAGE_DELAY_MS);

  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...workflow.crsDraft,
    ...report,
    status: "succeeded",
    progress: 100,
    message: "CRS 草稿已生成，可继续编辑与确认。",
    updatedAt: new Date().toISOString(),
    generatedAt: new Date().toISOString(),
    sourceStats: {
      ...workflowCrsSourceStats(workflow),
      ...report.sourceStats,
    },
  });
  workflow.updatedAt = new Date().toISOString();
  workflow.activity.unshift(
    normalizeWorkflowActivityItem({
      actor: safeText(workflow.crsDraft.requestedBy, "系统"),
      label: "生成 CRS 草稿",
      note: `已汇总 ${workflow.crsDraft.sourceStats.versionCount || 0} 个版本、${workflow.crsDraft.sourceStats.totalRecords || 0} 条原始意见，生成 ${workflow.crsDraft.sourceStats.itemCount || 0} 条 CRS 草稿。`,
      timestamp: workflow.updatedAt,
    }),
  );
  persistStore();
  return workflow;
}

function enqueueWorkflowAutoExportJob(workflow, options = {}) {
  if (!workflow?.autoExport?.enabled) {
    return null;
  }
  const existing = jobs.find(
    (job) =>
      job.type === "workflow.auto_export" &&
      job.resourceType === "workflow" &&
      job.resourceId === workflow.id &&
      ["queued", "running", "failed"].includes(job.status),
  );
  if (existing && !options.force) {
    return existing;
  }

  const now = new Date().toISOString();
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "workflow.auto_export",
    status: "queued",
    resourceType: "workflow",
    resourceId: workflow.id,
    payload: { workflowId: workflow.id },
    attempts: 0,
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  workflow.autoExport.status = "queued";
  workflow.autoExport.error = "";
  workflow.autoExport.jobId = job.id;
  persistStore();
  return job;
}

function enqueueWorkflowCrsDraftJob(workflow, options = {}) {
  if (!workflow) {
    return null;
  }
  const existing = jobs.find(
    (job) =>
      job.type === "workflow.crs_draft" &&
      job.resourceType === "workflow" &&
      job.resourceId === workflow.id &&
      ["queued", "running"].includes(job.status),
  );
  if (existing && !options.force) {
    return existing;
  }
  const now = new Date().toISOString();
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "workflow.crs_draft",
    status: "queued",
    resourceType: "workflow",
    resourceId: workflow.id,
    payload: {
      workflowId: workflow.id,
      actor: safeText(options.actor, "系统"),
      actorUserId: safeText(options.actorUserId, ""),
    },
    attempts: 0,
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...workflow.crsDraft,
    status: "queued",
    progress: 5,
    error: "",
    message: "已加入智能汇总队列",
    jobId: job.id,
    requestedBy: safeText(options.actor, "系统"),
    requestedByUserId: safeText(options.actorUserId, ""),
    updatedAt: now,
    sourceStats: {
      ...(workflow.crsDraft?.sourceStats || {}),
      ...(options.sourceStats || {}),
    },
  });
  persistStore();
  return job;
}

function shouldRetryBackgroundJob(job, error) {
  if (!["quantity.takeoff", "model.health", "model.diff", "drawing.redline", "drawing.ocr"].includes(job?.type)) {
    return false;
  }
  if (safeText(job.status, "") === "canceled") {
    return false;
  }
  const maxAttempts = Math.max(1, Number(job.maxAttempts || CDE_BACKGROUND_JOB_MAX_ATTEMPTS) || CDE_BACKGROUND_JOB_MAX_ATTEMPTS);
  if (Number(job.attempts || 0) >= maxAttempts) {
    return false;
  }
  const statusCode = Number(error?.statusCode || error?.status || 0);
  return !statusCode || [408, 429, 500, 502, 503, 504].includes(statusCode);
}

function retryDelayForJob(job, error) {
  const retryAfterMs = Number(error?.retryAfterMs || 0);
  if (Number.isFinite(retryAfterMs) && retryAfterMs > 0) {
    return Math.min(retryAfterMs, 60000);
  }
  const attempt = Math.max(1, Number(job?.attempts || 1) || 1);
  return Math.min(CDE_BACKGROUND_JOB_RETRY_BASE_MS * (2 ** (attempt - 1)), 60000);
}

async function processJob(job) {
  if (!job) {
    return null;
  }
  if (safeText(job.status, "") === "canceled") {
    return job;
  }

  const normalizedJob = normalizeJob(job);
  if (normalizedJob.status === "canceled") {
    Object.assign(job, normalizedJob);
    return job;
  }
  Object.assign(job, normalizedJob, { status: "running", attempts: Number(normalizedJob.attempts || 0) + 1, updatedAt: new Date().toISOString() });
  persistStore();

  try {
    if (job.type === "workflow.auto_export") {
      const workflow = workflowById(job.resourceId);
      if (!workflow) {
        const error = new Error("Workflow not found for auto-export job");
        error.statusCode = 404;
        throw error;
      }
      await runWorkflowAutoExportJob(workflow, job);
      if (workflow.autoExport?.status === "failed") {
        throw new Error(workflow.autoExport.error || "Workflow auto-export failed");
      }
      await bestEffortProjectEmailNotification("exportCompleted", {
        workflow,
        userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, workflow.projectId),
        occurredAt: workflow.autoExport?.lastRunAt || new Date().toISOString(),
        note: `已导出 ${Array.isArray(workflow.autoExport?.files) ? workflow.autoExport.files.length : 0} 个文件`,
      });
    }
    if (job.type === "workflow.crs_draft") {
      const workflow = workflowById(job.resourceId);
      if (!workflow) {
        const error = new Error("Workflow not found for CRS draft job");
        error.statusCode = 404;
        throw error;
      }
      await runWorkflowCrsDraftJob(workflow, job);
      if (workflow.crsDraft?.status === "failed") {
        throw new Error(workflow.crsDraft.error || "Workflow CRS draft generation failed");
      }
    }
    if (job.type === "quantity.takeoff") {
      const task = quantityTaskById(job.payload?.taskId);
      const doc = task ? documents.find((item) => item.id === task.documentId) : null;
      if (!task || !doc) {
        const error = new Error("Quantity takeoff task not found");
        error.statusCode = 404;
        throw error;
      }
      await runQuantityTakeoffJob(doc, task, job);
    }
    if (job.type === "model.health") {
      const task = modelHealthTaskById(job.payload?.taskId);
      const doc = task ? documents.find((item) => item.id === task.fileId) : null;
      if (!task || !doc) {
        const error = new Error("Model health task not found");
        error.statusCode = 404;
        throw error;
      }
      await runModelHealthJob(doc, task, job);
    }
    if (job.type === "model.diff") {
      const task = modelDiffTaskById(job.payload?.taskId);
      const doc = task ? documents.find((item) => item.id === task.documentId) : null;
      if (!task || !doc) {
        const error = new Error("Model diff task not found");
        error.statusCode = 404;
        throw error;
      }
      await runModelDiffJob(doc, task, job);
    }
    if (job.type === "drawing.redline") {
      const task = drawingRedlineTaskById(job.payload?.taskId);
      const doc = task ? documents.find((item) => item.id === task.documentId) : null;
      if (!task || !doc) {
        const error = new Error("Drawing redline task not found");
        error.statusCode = 404;
        throw error;
      }
      await runDrawingRedlineJob(doc, task, job);
    }
    if (job.type === "drawing.ocr") {
      const task = drawingOcrTaskById(job.payload?.taskId);
      const doc = task ? documents.find((item) => item.id === task.documentId) : null;
      if (!task || !doc) {
        const error = new Error("Drawing OCR task not found");
        error.statusCode = 404;
        throw error;
      }
      await runDrawingOcrJob(doc, task, job);
    }
    if (job.status === "canceled") {
      job.updatedAt = new Date().toISOString();
      persistStore();
      return job;
    }
    job.status = "succeeded";
    job.error = "";
    job.nextRunAt = "";
    job.updatedAt = new Date().toISOString();
    persistStore();
    return job;
  } catch (error) {
    if (shouldRetryBackgroundJob(job, error)) {
      const retryDelayMs = retryDelayForJob(job, error);
      job.status = "queued";
      job.error = error.message || "Job failed";
      job.nextRunAt = new Date(Date.now() + retryDelayMs).toISOString();
      job.updatedAt = new Date().toISOString();
      if (job.type === "quantity.takeoff") {
        markQuantityTakeoffRetryQueued(job, error);
      }
      if (job.type === "model.diff") {
        markModelDiffRetryQueued(job, error);
      }
      if (job.type === "drawing.redline") {
        markDrawingRedlineRetryQueued(job, error);
      }
      if (job.type === "drawing.ocr") {
        markDrawingOcrRetryQueued(job, error);
      }
      persistStore();
      scheduleAsyncJob(job);
      return job;
    }
    job.status = "failed";
    job.error = error.message || "Job failed";
    job.nextRunAt = "";
    job.updatedAt = new Date().toISOString();
    if (job.type === "workflow.auto_export") {
      const workflow = workflowById(job.resourceId);
      if (workflow) {
        await bestEffortProjectEmailNotification("exportFailed", {
          workflow,
          userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, workflow.projectId),
          occurredAt: new Date().toISOString(),
          errorMessage: safeText(error?.message, "Workflow auto-export failed"),
        });
      }
    }
    if (job.type === "workflow.crs_draft") {
      const workflow = workflowById(job.resourceId);
      if (workflow) {
        workflow.crsDraft = normalizeWorkflowCrsDraft({
          ...workflow.crsDraft,
          status: "failed",
          progress: 100,
          error: safeText(error?.message, "CRS 草稿生成失败"),
          message: safeText(error?.message, "CRS 草稿生成失败"),
          updatedAt: new Date().toISOString(),
        });
        workflow.updatedAt = new Date().toISOString();
        workflow.activity.unshift(
          normalizeWorkflowActivityItem({
            actor: safeText(workflow.crsDraft.requestedBy, "系统"),
            label: "生成 CRS 草稿失败",
            note: safeText(error?.message, "CRS 草稿生成失败"),
            timestamp: workflow.updatedAt,
          }),
        );
      }
    }
    if (job.type === "quantity.takeoff") {
      markQuantityTakeoffFailed(job, error);
    }
    if (job.type === "model.health") {
      markModelHealthFailed(job, error);
    }
    if (job.type === "model.diff") {
      markModelDiffFailed(job, error);
    }
    if (job.type === "drawing.redline") {
      markDrawingRedlineFailed(job, error);
    }
    if (job.type === "drawing.ocr") {
      markDrawingOcrFailed(job, error);
    }
    persistStore();
    return job;
  }
}

async function maybeRunWorkflowAutoExport(workflow) {
  const job = enqueueWorkflowAutoExportJob(workflow);
  if (!job) {
    return workflow;
  }
  await processJob(job);
  return workflow;
}

function toPublicJob(job) {
  if (!job) {
    return null;
  }
  const normalized = normalizeJob(job);
  return {
    id: normalized.id,
    type: normalized.type,
    status: normalized.status,
    resourceType: normalized.resourceType,
    resourceId: normalized.resourceId,
    error: normalized.error,
    attempts: normalized.attempts,
    maxAttempts: normalized.maxAttempts,
    nextRunAt: normalized.nextRunAt,
    createdAt: normalized.createdAt,
    updatedAt: normalized.updatedAt,
  };
}

function toPublicWorkflow(workflow, userContext = SYSTEM_USER_CONTEXT) {
  const currentStep = workflowCurrentStep(workflow);
  const counts = workflowSummaryCounts(workflow);
  return {
    ...workflow,
    currentStep: currentStep ? JSON.parse(JSON.stringify(currentStep)) : null,
    permissions: workflowPermissionsForInstance(workflow, userContext),
    fileCount: Array.isArray(workflow.fileRefs) ? workflow.fileRefs.length : 0,
    approvedCount: counts.approved,
    rejectedCount: counts.rejected,
    pendingCount: counts.pending,
    fileRefs: (workflow.fileRefs || []).map((fileRef) => {
      const doc = documents.find((item) => item.id === fileRef.docId);
      if (!doc) {
        return fileRef;
      }
      return normalizeWorkflowFileRef({
        ...fileRef,
        name: doc.name,
        versionId: doc.currentVersionId,
        version: doc.version,
        parentId: doc.parentId,
        folderPath: folderPathLabel(doc.parentId),
        mimeType: doc.mimeType,
        size: doc.size,
        status: doc.status,
        exportUrl: doc.lastExportFileName ? signedExportUrl(doc.lastExportFileName) : fileRef.exportUrl,
      });
    }),
  };
}

function publicWorkflowTemplatesForUser(userContext) {
  const role = safeText(userContext?.projectRole, "guest");
  const canManage = isProjectAdminRole(role) || isSuperAdmin(userContext);
  return [...workflowTemplates]
    .filter((template) => safeText(template.projectId, DEFAULT_PROJECT_ID) === safeText(userContext?.projectId, DEFAULT_PROJECT_ID))
    .filter((template) => template.enabled || canManage)
    .filter((template) => canManage || template.allowedRoles.includes(role))
    .sort((left, right) => {
      const categoryDiff = localeCollator("zh-CN").compare(left.category, right.category);
      if (categoryDiff !== 0) {
        return categoryDiff;
      }
      const projectDiff = localeCollator("zh-CN").compare(left.projectName, right.projectName);
      if (projectDiff !== 0) {
        return projectDiff;
      }
      return localeCollator("zh-CN").compare(left.name, right.name);
    })
    .map((template) => ({
      ...template,
      permissions: {
        launch: canManage || template.allowedRoles.includes(role),
        manage: canManage,
      },
    }));
}

function publicWorkflowsForUser(userContext) {
  return [...workflows]
    .filter((workflow) => workflowVisibleForUser(workflow, userContext))
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .map((workflow) => toPublicWorkflow(workflow, userContext));
}

function buildWorkspacePayload(userContext, options = {}) {
  const visibleDocuments = publicDocumentsForUser(userContext);
  const visibleFolders = publicFoldersForUser(userContext);
  const visibleWorkflowTemplates = publicWorkflowTemplatesForUser(userContext);
  const visibleWorkflows = publicWorkflowsForUser(userContext);
  return {
    documents: visibleDocuments,
    folders: visibleFolders,
    workflowTemplates: visibleWorkflowTemplates,
    workflows: visibleWorkflows,
    access: accessPayload(userContext, options),
    notificationCenter: buildNotificationCenterPayload(userContext, {
      documents: visibleDocuments,
      workflows: visibleWorkflows,
    }),
  };
}

function drawingSmartReviewDocumentCandidate(doc) {
  const extension = path.extname(String(doc?.name || "")).toLowerCase();
  return doc?.mimeType === "application/pdf" || extension === ".pdf" || APS_DRAWING_DOCUMENT_EXTENSIONS.has(extension);
}

function drawingRuleConfigForProject(projectId) {
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  let config = drawingRuleConfigs.find((item) => item.projectId === normalizedProjectId);
  if (!config) {
    config = normalizeDrawingRuleConfig({
      id: `${normalizedProjectId}-drawing-rule-config`,
      projectId: normalizedProjectId,
      rules: defaultDrawingRuleConfigRules(),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    drawingRuleConfigs.push(config);
    persistStore();
  }
  return config;
}

function publicDrawingPrecheckTasks(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const visibleIds = new Set(publicDocumentsForUser(userContext).map((doc) => doc.id));
  return drawingPrecheckTasks
    .filter((task) => task.projectId === projectId && visibleIds.has(task.fileId))
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
    .map((task) => {
      const doc = documents.find((item) => item.id === task.fileId);
      const taskResults = drawingPrecheckResults.filter((item) => item.taskId === task.id);
      return {
        ...task,
        gateStatus: drawingPrecheckGateSummaryForTask(task, taskResults, doc),
        report: {
          ...(task.report || {}),
          issueSummary: drawingPrecheckIssueSummary(taskResults),
        },
      };
    });
}

function publicDrawingPrecheckResults(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const visibleIds = new Set(publicDocumentsForUser(userContext).map((doc) => doc.id));
  return drawingPrecheckResults
    .filter((result) => result.projectId === projectId && visibleIds.has(result.fileId))
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
    .map((result) => publicDrawingPrecheckResult(result));
}

function drawingPrecheckAnnotationForResult(result) {
  if (!result?.annotationId) {
    return null;
  }
  const doc = documents.find((item) => item.id === result.fileId);
  return doc?.annotations?.find((annotation) => annotation.id === result.annotationId) || null;
}

function drawingPrecheckIssueLinkForResult(result) {
  const annotation = drawingPrecheckAnnotationForResult(result);
  if (annotation) {
    const doc = documents.find((item) => item.id === result.fileId) || null;
    const extension = path.extname(String(doc?.name || result.fileName || "")).toLowerCase();
    const linkType = extension === ".pdf" || doc?.mimeType === "application/pdf"
      ? "pdf_annotation"
      : APS_DRAWING_DOCUMENT_EXTENSIONS.has(extension)
        ? "aps_drawing_annotation"
        : "review_annotation";
    return {
      type: linkType,
      target: "workflow_issue_board",
      annotationId: annotation.id,
      status: safeText(annotation.status, "open"),
      page: Number(annotation.page || result.page || 1) || 1,
      source: "drawing_precheck",
    };
  }
  return {
    type: "precheck_report_item",
    target: "precheck_report",
    annotationId: "",
    status: safeText(result?.status, "open"),
    page: Number(result?.page || 1) || 1,
    source: "drawing_precheck",
  };
}

function publicDrawingPrecheckResult(result) {
  const normalized = normalizeDrawingPrecheckResult(result);
  return {
    ...normalized,
    issueLink: drawingPrecheckIssueLinkForResult(normalized),
  };
}

function drawingSmartReviewPayload(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const documentsForReview = publicDocumentsForUser(userContext)
    .filter(drawingSmartReviewDocumentCandidate)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      version: doc.version,
      currentVersionId: doc.currentVersionId,
      mimeType: doc.mimeType,
      drawingMetadata: doc.drawingMetadata || {},
      parseStatus: doc.parseStatus,
      updatedAt: doc.updatedAt,
      annotationsCount: Array.isArray(doc.annotations) ? doc.annotations.length : 0,
      precheckGate: drawingPrecheckGateSummaryForDocument(doc),
    }));
  return {
    documents: documentsForReview,
    tasks: publicDrawingPrecheckTasks(userContext),
    results: publicDrawingPrecheckResults(userContext),
    ruleConfig: drawingRuleConfigForProject(projectId),
  };
}

function supportedSpecDocumentTypes() {
  return [
    "Equipment Datasheet",
    "Valve Datasheet",
    "Instrument Datasheet",
    "Line List",
    "Equipment List",
    "Pipe Class Specification",
    "Material Requisition",
  ];
}

function seedDefaultSpecDictionaries(projectsList = seedDefaultProjects()) {
  return projectsList.flatMap((project) => {
    const projectId = safeText(project?.id, DEFAULT_PROJECT_ID);
    const createdAt = "2026-04-25T00:00:00.000Z";
    return [
      {
        id: `${projectId}-spec-dictionary-material`,
        projectId,
        category: "material",
        name: "Material Synonyms",
        synonyms: [
          ["316L SS", "UNS S31603", "1.4404", "X2CrNiMo17-12-2"],
          ["Duplex SS 2205", "UNS S31803", "1.4462"],
          ["Duplex SS 2507", "UNS S32750", "Super Duplex"],
          ["CS", "Carbon Steel", "A105", "ASTM A105"],
          ["GRP", "FRP", "Glass Reinforced Plastic", "Fibreglass"],
          ["HDPE", "High Density Polyethylene", "PE100"],
        ],
        conversions: [],
        createdAt,
        updatedAt: createdAt,
      },
      {
        id: `${projectId}-spec-dictionary-fluid`,
        projectId,
        category: "fluid",
        name: "Fluid Synonyms",
        synonyms: [
          ["Seawater", "SW", "Raw Seawater", "海水"],
          ["RO Permeate", "Product Water", "Desalinated Water", "Permeate"],
          ["NaOCl", "Sodium Hypochlorite", "Chlorine Solution", "次氯酸钠"],
          ["RO Concentrate", "Brine", "RO Brine", "Concentrate"],
        ],
        conversions: [],
        createdAt,
        updatedAt: createdAt,
      },
      {
        id: `${projectId}-spec-dictionary-unit`,
        projectId,
        category: "unit",
        name: "Engineering Unit Conversions",
        synonyms: [],
        conversions: [
          { from: "barg", to: "MPag", factor: 0.1 },
          { from: "bara", to: "MPaa", factor: 0.1 },
          { from: "psi", to: "barg", factor: 0.0689476 },
          { from: "°F", to: "°C", formula: "(x - 32) * 5 / 9" },
          { from: "gpm", to: "m3/h", factor: 0.2271 },
          { from: "lbs", to: "kg", factor: 0.4536 },
          { from: "lb", to: "kg", factor: 0.4536 },
          { from: "t", to: "kg", factor: 1000 },
        ],
        createdAt,
        updatedAt: createdAt,
      },
    ];
  });
}

function normalizeSpecConfidence(value, fallback = "medium") {
  const textValue = safeText(value, "").toLowerCase();
  return ["high", "medium", "low"].includes(textValue) ? textValue : fallback;
}

function normalizeSpecCheckLevel(value, fallback = "info") {
  const textValue = safeText(value, "").toLowerCase();
  return ["error", "warning", "info", "pending"].includes(textValue) ? textValue : fallback;
}

function normalizeSpecCheckStatus(value, fallback = "open") {
  const textValue = safeText(value, "").toLowerCase();
  return ["queued", "extracting", "comparing", "completed", "failed", "open", "passed", "resolved", "accepted", "verified_closed"].includes(textValue)
    ? textValue
    : fallback;
}

function normalizeSpecVersionStatus(value, fallback = "current") {
  const textValue = safeText(value, "").toLowerCase();
  return ["draft", "current", "superseded", "vendor_returned", "void"].includes(textValue) ? textValue : fallback;
}

function normalizeSpecPosition(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  return {
    x: clampNumber(source.x),
    y: clampNumber(source.y),
    width: clampNumber(source.width || 0.14),
    height: clampNumber(source.height || 0.05),
  };
}

function normalizeSpecParamName(value) {
  return safeText(value, "")
    .toLowerCase()
    .replace(/[\s_\-./()]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeSpecEntry(entry) {
  const value = entry && typeof entry === "object" ? entry : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const documentType = safeText(value.documentType || value.docType, "Equipment Datasheet");
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    tagNumber: safeText(value.tagNumber || value.tag_number, ""),
    equipmentType: safeText(value.equipmentType || value.equipment_type, ""),
    discipline: safeText(value.discipline, "Process"),
    documentType: supportedSpecDocumentTypes().includes(documentType) ? documentType : "Equipment Datasheet",
    currentVersionId: safeText(value.currentVersionId || value.current_version_id, ""),
    status: safeText(value.status, "active"),
    createdBy: safeText(value.createdBy || value.created_by, "System"),
    createdByUserId: safeText(value.createdByUserId || value.created_by_user_id, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecVersion(version) {
  const value = version && typeof version === "object" ? version : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    entryId: safeText(value.entryId || value.entry_id, ""),
    fileId: safeText(value.fileId || value.file_id, ""),
    fileName: safeText(value.fileName || value.file_name, ""),
    version: normalizeDrawingRevisionLabel(value.version || value.revision || "Rev.A", "Rev.A"),
    status: normalizeSpecVersionStatus(value.status, "current"),
    isCurrent: value.isCurrent !== undefined ? Boolean(value.isCurrent) : Boolean(value.is_current),
    extractionStatus: safeText(value.extractionStatus || value.extraction_status, "not_extracted"),
    parameterCount: Math.max(0, Number(value.parameterCount || value.parameter_count || 0) || 0),
    extractedAt: safeText(value.extractedAt || value.extracted_at, ""),
    createdBy: safeText(value.createdBy || value.created_by, "System"),
    createdByUserId: safeText(value.createdByUserId || value.created_by_user_id, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecParameter(parameter) {
  const value = parameter && typeof parameter === "object" ? parameter : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const paramName = safeText(value.paramName || value.name || value.param_name, "");
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    entryId: safeText(value.entryId || value.entry_id, ""),
    versionId: safeText(value.versionId || value.version_id, ""),
    tagNumber: safeText(value.tagNumber || value.tag_number, ""),
    paramName,
    normalizedName: normalizeSpecParamName(value.normalizedName || value.normalized_name || paramName),
    paramValue: safeText(value.paramValue ?? value.value ?? value.param_value, ""),
    paramUnit: normalizeSpecUnit(value.paramUnit || value.unit || value.param_unit || ""),
    page: Math.max(1, Number(value.page || 1) || 1),
    position: normalizeSpecPosition(value.position),
    confidence: normalizeSpecConfidence(value.confidence, "medium"),
    source: safeText(value.source, "text_layer"),
    sourceText: safeText(value.sourceText || value.source_text, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeDrawingSpecParameter(parameter) {
  const value = parameter && typeof parameter === "object" ? parameter : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const paramName = safeText(value.paramName || value.name || value.param_name, "");
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    drawingId: safeText(value.drawingId || value.fileId || value.drawing_id || value.file_id, ""),
    drawingName: safeText(value.drawingName || value.fileName || value.drawing_name || value.file_name, ""),
    drawingNumber: safeText(value.drawingNumber || value.drawing_number, ""),
    drawingVersionId: safeText(value.drawingVersionId || value.versionId || value.drawing_version_id || value.version_id, ""),
    drawingVersion: safeText(value.drawingVersion || value.version || value.drawing_version, "V1"),
    tagNumber: safeText(value.tagNumber || value.tag_number, ""),
    paramName,
    normalizedName: normalizeSpecParamName(value.normalizedName || value.normalized_name || paramName),
    paramValue: safeText(value.paramValue ?? value.value ?? value.param_value, ""),
    paramUnit: normalizeSpecUnit(value.paramUnit || value.unit || value.param_unit || ""),
    page: Math.max(1, Number(value.page || 1) || 1),
    position: normalizeSpecPosition(value.position),
    confidence: normalizeSpecConfidence(value.confidence, "medium"),
    source: safeText(value.source, "drawing_text_layer"),
    sourceText: safeText(value.sourceText || value.source_text, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecCheckTask(task) {
  const value = task && typeof task === "object" ? task : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    tagNumber: safeText(value.tagNumber || value.tag_number, ""),
    specVersionId: safeText(value.specVersionId || value.spec_version_id, ""),
    drawingVersionIds: Array.isArray(value.drawingVersionIds || value.drawing_version_ids)
      ? (value.drawingVersionIds || value.drawing_version_ids).map((item) => safeText(item, "")).filter(Boolean)
      : [],
    status: normalizeSpecCheckStatus(value.status, "completed"),
    summary: value.summary && typeof value.summary === "object" ? value.summary : {},
    report: value.report && typeof value.report === "object" ? value.report : {},
    error: safeText(value.error, ""),
    createdBy: safeText(value.createdBy || value.created_by, "System"),
    createdByUserId: safeText(value.createdByUserId || value.created_by_user_id, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
    completedAt: safeText(value.completedAt || value.completed_at, ""),
  };
}

function normalizeSpecCheckResult(result) {
  const value = result && typeof result === "object" ? result : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const paramName = safeText(value.paramName || value.param_name || value.name, "");
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    taskId: safeText(value.taskId || value.task_id, ""),
    tagNumber: safeText(value.tagNumber || value.tag_number, ""),
    paramName,
    normalizedName: normalizeSpecParamName(value.normalizedName || value.normalized_name || paramName),
    specVersionId: safeText(value.specVersionId || value.spec_version_id, ""),
    specValue: safeText(value.specValue ?? value.spec_value, ""),
    specUnit: normalizeSpecUnit(value.specUnit || value.spec_unit || ""),
    specSource: value.specSource && typeof value.specSource === "object" ? value.specSource : {},
    drawingValue: safeText(value.drawingValue ?? value.drawing_value, ""),
    drawingUnit: normalizeSpecUnit(value.drawingUnit || value.drawing_unit || ""),
    drawingSource: value.drawingSource && typeof value.drawingSource === "object" ? value.drawingSource : {},
    diffPct: value.diffPct === null || value.diffPct === undefined || value.diffPct === "" ? null : Number(value.diffPct),
    difference: safeText(value.difference, ""),
    level: normalizeSpecCheckLevel(value.level, "info"),
    status: normalizeSpecCheckStatus(value.status, "open"),
    confidence: normalizeSpecConfidence(value.confidence, "medium"),
    reason: safeText(value.reason, ""),
    annotationId: safeText(value.annotationId || value.annotation_id, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecDictionary(dictionary) {
  const value = dictionary && typeof dictionary === "object" ? dictionary : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const category = ["material", "fluid", "unit"].includes(safeText(value.category, "")) ? safeText(value.category, "") : "material";
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    category,
    name: safeText(value.name, `${category} dictionary`),
    synonyms: Array.isArray(value.synonyms)
      ? value.synonyms
          .map((group) => Array.isArray(group) ? group.map((item) => safeText(item, "")).filter(Boolean) : [])
          .filter((group) => group.length >= 2)
      : [],
    conversions: Array.isArray(value.conversions)
      ? value.conversions
          .map((item) => ({
            from: normalizeSpecUnit(item?.from),
            to: normalizeSpecUnit(item?.to),
            factor: item?.factor === undefined ? null : Number(item.factor),
            formula: safeText(item?.formula, ""),
          }))
          .filter((item) => item.from && item.to && (Number.isFinite(item.factor) || item.formula))
      : [],
    createdBy: safeText(value.createdBy || value.created_by, "System"),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecDrawingLink(link) {
  const value = link && typeof link === "object" ? link : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    specEntryId: safeText(value.specEntryId || value.spec_entry_id, ""),
    drawingId: safeText(value.drawingId || value.drawingEntryId || value.drawing_id || value.drawing_entry_id, ""),
    drawingNumber: safeText(value.drawingNumber || value.drawing_number, ""),
    createdBy: safeText(value.createdBy || value.created_by, "System"),
    createdByUserId: safeText(value.createdByUserId || value.created_by_user_id, ""),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

function normalizeSpecUnit(value) {
  const raw = safeText(value, "");
  if (!raw) return "";
  const compact = raw.replace(/\s+/g, "");
  const aliases = {
    m3hr: "m3/h",
    "m3/hr": "m3/h",
    "m³/h": "m3/h",
    degc: "°C",
    c: "°C",
    "℃": "°C",
    degf: "°F",
    f: "°F",
    "℉": "°F",
    kg: "kg",
    lbs: "lbs",
    lb: "lb",
    barg: "barg",
    bara: "bara",
    mpag: "MPag",
    mpaa: "MPaa",
    psi: "psi",
    mm: "mm",
    m: "m",
    dn: "DN",
  };
  return aliases[compact.toLowerCase()] || compact;
}

function publicSpecDictionary(dictionary) {
  const normalized = normalizeSpecDictionary(dictionary);
  return {
    id: normalized.id,
    projectId: normalized.projectId,
    category: normalized.category,
    name: normalized.name,
    synonyms: normalized.synonyms,
    conversions: normalized.conversions,
    updatedAt: normalized.updatedAt,
  };
}

function specDictionariesForProject(projectId = DEFAULT_PROJECT_ID) {
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  const current = specDictionaries.filter((item) => item.projectId === normalizedProjectId);
  if (current.length >= 3) {
    return current;
  }
  const seeded = seedDefaultSpecDictionaries([{ id: normalizedProjectId }]);
  seeded.forEach((dictionary) => {
    if (!specDictionaries.some((item) => item.id === dictionary.id)) {
      specDictionaries.push(normalizeSpecDictionary(dictionary));
    }
  });
  persistStore();
  return specDictionaries.filter((item) => item.projectId === normalizedProjectId);
}

function specDictionaryBundle(projectId = DEFAULT_PROJECT_ID) {
  const dictionaries = specDictionariesForProject(projectId);
  return {
    materialSynonyms: dictionaries.find((item) => item.category === "material")?.synonyms || [],
    fluidSynonyms: dictionaries.find((item) => item.category === "fluid")?.synonyms || [],
    unitConversions: dictionaries.find((item) => item.category === "unit")?.conversions || [],
    records: dictionaries.map(publicSpecDictionary),
  };
}

function updateSpecDictionary(dictionaryId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  if (!isProjectAdminRole(userContext.projectRole) && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("Only project administrators can maintain spec-check dictionaries.");
  }
  const dictionary = specDictionaries.find((item) => item.id === dictionaryId && item.projectId === safeText(userContext.projectId, DEFAULT_PROJECT_ID));
  if (!dictionary) {
    const error = new Error("Spec-check dictionary not found.");
    error.statusCode = 404;
    throw error;
  }
  Object.assign(dictionary, normalizeSpecDictionary({
    ...dictionary,
    ...body,
    id: dictionary.id,
    projectId: dictionary.projectId,
    category: dictionary.category,
    updatedAt: new Date().toISOString(),
    createdBy: dictionary.createdBy,
  }));
  persistStore();
  return dictionary;
}

function specVersionParameters(versionId) {
  const id = safeText(versionId, "");
  return specParameters.filter((parameter) => parameter.versionId === id);
}

function drawingParametersForVersions(versionIds = [], tagNumber = "") {
  const versionIdSet = new Set((versionIds || []).map((item) => safeText(item, "")).filter(Boolean));
  const normalizedTag = safeText(tagNumber, "");
  return drawingSpecParameters.filter((parameter) => {
    const matchesVersion = versionIdSet.size ? versionIdSet.has(parameter.drawingVersionId) : true;
    const matchesTag = normalizedTag ? parameter.tagNumber === normalizedTag : true;
    return matchesVersion && matchesTag;
  });
}

function publicSpecEntry(entry) {
  const normalized = normalizeSpecEntry(entry);
  const versions = specVersions
    .filter((version) => version.entryId === normalized.id)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")));
  const currentVersion =
    versions.find((version) => version.id === normalized.currentVersionId) ||
    versions.find((version) => version.isCurrent) ||
    versions[0] ||
    null;
  const linkedDrawingIds = specDrawingLinks
    .filter((link) => link.specEntryId === normalized.id)
    .map((link) => link.drawingId)
    .filter(Boolean);
  const latestTask = specCheckTasks
    .filter((task) => task.tagNumber === normalized.tagNumber && task.projectId === normalized.projectId)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
  const latestResults = latestTask ? specCheckResults.filter((result) => result.taskId === latestTask.id) : [];
  const resultSummary = summarizeSpecCheckResults(latestResults);
  const checkStatus =
    !latestTask ? "not_checked" :
    resultSummary.errorCount ? "failed" :
    resultSummary.warningCount || resultSummary.pendingCount ? "needs_confirmation" :
    "passed";
  return {
    ...normalized,
    versions: versions.map(publicSpecVersion),
    currentVersion: currentVersion ? publicSpecVersion(currentVersion) : null,
    linkedDrawingIds,
    linkedDrawingCount: linkedDrawingIds.length,
    parameterExtractionStatus: currentVersion?.extractionStatus || "not_extracted",
    checkStatus,
    latestTaskId: latestTask?.id || "",
    resultSummary,
  };
}

function publicSpecVersion(version) {
  const normalized = normalizeSpecVersion(version);
  return {
    ...normalized,
    parameterCount: specVersionParameters(normalized.id).length || normalized.parameterCount,
  };
}

function publicSpecParameter(parameter) {
  return normalizeSpecParameter(parameter);
}

function publicDrawingSpecParameter(parameter) {
  return normalizeDrawingSpecParameter(parameter);
}

function specCheckAnnotationForResult(result) {
  if (!result?.annotationId) {
    return null;
  }
  const doc = documents.find((item) => item.id === result.drawingSource?.fileId || item.id === result.drawingSource?.drawingId);
  return doc?.annotations?.find((annotation) => annotation.id === result.annotationId) || null;
}

function specCheckIssueLinkForResult(result) {
  const annotation = specCheckAnnotationForResult(result);
  if (annotation) {
    const doc = documents.find((item) => item.id === result.drawingSource?.fileId || item.id === result.drawingSource?.drawingId) || null;
    const extension = path.extname(String(doc?.name || "")).toLowerCase();
    return {
      type: extension === ".pdf" || doc?.mimeType === "application/pdf" ? "pdf_annotation" : "review_annotation",
      target: "workflow_issue_board",
      annotationId: annotation.id,
      status: safeText(annotation.status, "open"),
      page: Number(annotation.page || result.drawingSource?.page || 1) || 1,
      source: "drawing_spec_check",
    };
  }
  return {
    type: "spec_check_report_item",
    target: "spec_check_report",
    annotationId: "",
    status: safeText(result?.status, "open"),
    page: Number(result?.drawingSource?.page || 1) || 1,
    source: "drawing_spec_check",
  };
}

function publicSpecCheckResult(result) {
  const normalized = normalizeSpecCheckResult(result);
  return {
    ...normalized,
    issueLink: specCheckIssueLinkForResult(normalized),
  };
}

function publicSpecCheckTask(task) {
  const normalized = normalizeSpecCheckTask(task);
  const results = specCheckResults.filter((result) => result.taskId === normalized.id);
  return {
    ...normalized,
    summary: summarizeSpecCheckResults(results),
    resultCount: results.length,
  };
}

function buildSpecTraceabilityRows(projectId, visibleDocIds) {
  return specEntries
    .filter((entry) => entry.projectId === projectId)
    .map((entry) => {
      const links = specDrawingLinks.filter((link) => link.specEntryId === entry.id && (!visibleDocIds || visibleDocIds.has(link.drawingId)));
      const versions = specVersions.filter((version) => version.entryId === entry.id);
      const currentVersion = versions.find((version) => version.id === entry.currentVersionId) || versions.find((version) => version.isCurrent) || versions[0] || null;
      const relatedResults = specCheckResults.filter((result) => result.projectId === projectId && result.tagNumber === entry.tagNumber);
      const openResults = relatedResults.filter((result) => ["open"].includes(result.status) && result.level !== "info");
      return {
        tagNumber: entry.tagNumber,
        equipmentType: entry.equipmentType,
        discipline: entry.discipline,
        specCount: versions.length,
        currentVersion: currentVersion?.version || "",
        drawingCount: links.length,
        issueCount: openResults.length,
        status: summarizeSpecCheckResults(relatedResults),
      };
    })
    .sort((left, right) => left.tagNumber.localeCompare(right.tagNumber));
}

function buildDrawingSpecCheckPayload(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const visibleDocs = publicDocumentsForUser(userContext);
  const visibleDocIds = new Set(visibleDocs.map((doc) => doc.id));
  const projectSpecEntries = specEntries
    .filter((entry) => entry.projectId === projectId)
    .map(publicSpecEntry)
    .sort((left, right) => left.tagNumber.localeCompare(right.tagNumber));
  const projectVersions = specVersions
    .filter((version) => version.projectId === projectId && (!version.fileId || visibleDocIds.has(version.fileId)))
    .map(publicSpecVersion);
  const projectSpecVersionIds = new Set(projectVersions.map((version) => version.id));
  const projectDrawingVersionIds = new Set(
    visibleDocs.flatMap((doc) => (Array.isArray(doc.versionHistory) ? doc.versionHistory.map((entry) => entry.id) : [doc.currentVersionId])).filter(Boolean),
  );
  const projectResults = specCheckResults
    .filter((result) => result.projectId === projectId)
    .filter((result) => !result.drawingSource?.fileId || visibleDocIds.has(result.drawingSource.fileId))
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
    .map(publicSpecCheckResult);
  return {
    supportedDocumentTypes: supportedSpecDocumentTypes(),
    documents: visibleDocs
      .filter((doc) => doc.mimeType === "application/pdf" || path.extname(String(doc.name || "")).toLowerCase() === ".pdf")
      .map((doc) => ({
        id: doc.id,
        name: doc.name,
        version: doc.version,
        currentVersionId: doc.currentVersionId,
        mimeType: doc.mimeType,
        drawingMetadata: doc.drawingMetadata || {},
        specMetadata: doc.specMetadata || {},
        updatedAt: doc.updatedAt,
      })),
    specEntries: projectSpecEntries,
    specVersions: projectVersions,
    specParameters: specParameters.filter((parameter) => projectSpecVersionIds.has(parameter.versionId)).map(publicSpecParameter),
    drawingParameters: drawingSpecParameters
      .filter((parameter) => parameter.projectId === projectId && visibleDocIds.has(parameter.drawingId) && projectDrawingVersionIds.has(parameter.drawingVersionId))
      .map(publicDrawingSpecParameter),
    tasks: specCheckTasks
      .filter((task) => task.projectId === projectId)
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
      .map(publicSpecCheckTask),
    results: projectResults,
    links: specDrawingLinks.filter((link) => link.projectId === projectId && visibleDocIds.has(link.drawingId)).map(normalizeSpecDrawingLink),
    dictionaries: specDictionaryBundle(projectId),
    traceability: buildSpecTraceabilityRows(projectId, visibleDocIds),
    summary: {
      totalSpecs: projectSpecEntries.length,
      currentVersions: projectVersions.filter((version) => version.isCurrent).length,
      drawingParameterCount: drawingSpecParameters.filter((parameter) => parameter.projectId === projectId && visibleDocIds.has(parameter.drawingId)).length,
      openIssueCount: projectResults.filter((result) => result.status === "open" && result.annotationId).length,
      openFindingCount: projectResults.filter((result) => result.status === "open" && result.level !== "info").length,
      errorCount: projectResults.filter((result) => result.status === "open" && result.level === "error").length,
      warningCount: projectResults.filter((result) => result.status === "open" && result.level === "warning").length,
      pendingCount: projectResults.filter((result) => result.status === "open" && result.level === "pending").length,
    },
  };
}

function validateSpecRegistrationBody(body = {}) {
  const missing = [];
  if (!safeText(body.fileId, "")) missing.push("fileId");
  if (!safeText(body.documentType, "")) missing.push("documentType");
  if (!safeText(body.discipline, "")) missing.push("discipline");
  if (!safeText(body.version, "")) missing.push("version");
  if (missing.length) {
    const error = new Error(`Missing required spec metadata: ${missing.join(", ")}`);
    error.statusCode = 400;
    throw error;
  }
  if (!supportedSpecDocumentTypes().includes(safeText(body.documentType, ""))) {
    const error = new Error("Unsupported specification document type.");
    error.statusCode = 400;
    throw error;
  }
}

function inferSpecRegistrationTagNumber(body = {}, doc = null, rawParameters = []) {
  const explicit = safeText(body.tagNumber || body.tag_number, "");
  if (explicit) return explicit;
  const parameterTag = (Array.isArray(rawParameters) ? rawParameters : [])
    .map((parameter) => {
      const value = parameter && typeof parameter === "object" ? parameter : {};
      const name = safeText(value.name || value.paramName || value.param_name, "");
      if (normalizeSpecParamName(name) === "tag number") {
        return safeText(value.value || value.paramValue || value.param_value, "");
      }
      return safeText(value.tagNumber || value.tag_number, "");
    })
    .find(Boolean);
  if (parameterTag) return parameterTag;
  const inferred = inferTagNumberFromText([
    body.text,
    body.textContent,
    body.fileName,
    doc?.name,
  ].filter(Boolean).join("\n"));
  if (inferred) return inferred;
  const fallback = safeText(doc?.id || crypto.randomUUID(), "").replace(/[^a-zA-Z0-9]/g, "").slice(0, 8).toUpperCase();
  return `PENDING-${fallback || "TAG"}`;
}

function humanizeSpecFilenameToken(value = "") {
  return safeText(value, "")
    .replace(/\.[^.]+$/, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function inferSpecRegistrationEquipmentType(body = {}, doc = null, tagNumber = "") {
  const explicit = safeText(body.equipmentType || body.equipment_type, "");
  if (explicit) return explicit;
  const typeByDocumentType = {
    "Valve Datasheet": "Valve",
    "Instrument Datasheet": "Instrument",
    "Line List": "Line List",
    "Equipment List": "Equipment List",
    "Pipe Class Specification": "Pipe Class Specification",
    "Material Requisition": "Material Requisition",
  };
  const rawFileLabel = safeText(doc?.name || body.fileName || "").replace(/\.[^.]+$/, "");
  if (tagNumber && rawFileLabel) {
    const escapedTag = tagNumber.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    let candidate = rawFileLabel.replace(new RegExp(`(^|[^A-Z0-9])${escapedTag}(?=[^A-Z0-9]|$)`, "i"), " ");
    candidate = humanizeSpecFilenameToken(candidate);
    candidate = candidate.replace(/\b(rev\.?\s*[a-z0-9]+|revision\s*[a-z0-9]+)\b/gi, " ");
    candidate = candidate.replace(/\b(datasheet|data sheet|specification|spec|equipment|vendor|document|pdf|docx?|xlsx?|csv|txt)\b/gi, " ");
    candidate = humanizeSpecFilenameToken(candidate);
    if (candidate) {
      return candidate.split(" ").map((part) => part ? part[0].toUpperCase() + part.slice(1).toLowerCase() : "").join(" ");
    }
  }
  const documentType = safeText(body.documentType || body.docType, "");
  return typeByDocumentType[documentType] || "Unspecified Equipment";
}

function extractedSpecParametersFromBody(body = {}) {
  if (Array.isArray(body.parameters) && body.parameters.length) {
    return body.parameters;
  }
  return parseSpecParametersFromText(body.text || body.textContent || "");
}

function parseSpecParametersFromText(textValue = "") {
  const lines = safeText(textValue, "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const fields = [
    "Tag Number",
    "Design Pressure",
    "Design Temperature",
    "Operating Pressure",
    "Operating Temperature",
    "Shell Material",
    "Internal Material",
    "Fluid Service",
    "Design Standard",
    "Flow Rate",
    "Nozzle N1 Size",
    "Dry Weight",
    "Operating Weight",
  ];
  const parameters = [];
  lines.forEach((line, index) => {
    const separatorIndex = line.search(/[:=]/);
    if (separatorIndex < 0) return;
    const key = line.slice(0, separatorIndex).trim();
    const matched = fields.find((field) => normalizeSpecParamName(field) === normalizeSpecParamName(key));
    if (!matched || matched === "Tag Number") return;
    const rawValue = line.slice(separatorIndex + 1).trim();
    const parsed = parseSpecNumericValue(rawValue, "");
    parameters.push({
      name: matched,
      value: parsed.hasNumber ? parsed.value : rawValue,
      unit: parsed.hasNumber ? parsed.unit : "",
      page: 1,
      position: { x: 0.12, y: 0.12 + index * 0.04, width: 0.18, height: 0.035 },
      confidence: "medium",
      source: "text_layer",
    });
  });
  return parameters;
}

function registerSpecCheckSpec(body = {}, userContext = SYSTEM_USER_CONTEXT) {
  validateSpecRegistrationBody(body);
  const doc = requireDocument(body.fileId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("You do not have access to this specification document.");
  }
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("You do not have permission to register specification metadata.");
  }
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const rawParameters = extractedSpecParametersFromBody(body);
  const tagNumber = inferSpecRegistrationTagNumber(body, doc, rawParameters);
  const equipmentType = inferSpecRegistrationEquipmentType(body, doc, tagNumber);
  const now = new Date().toISOString();
  let entry = specEntries.find((item) => item.projectId === projectId && item.tagNumber === tagNumber && item.documentType === safeText(body.documentType, ""));
  if (!entry) {
    entry = normalizeSpecEntry({
      id: crypto.randomUUID(),
      projectId,
      tagNumber,
      equipmentType,
      discipline: body.discipline,
      documentType: body.documentType,
      status: "active",
      createdBy: actorDisplayName(userContext),
      createdByUserId: safeText(userContext?.user?.id, ""),
      createdAt: now,
      updatedAt: now,
    });
    specEntries.unshift(entry);
  } else {
    entry.equipmentType = safeText(equipmentType, entry.equipmentType);
    entry.discipline = safeText(body.discipline, entry.discipline);
    entry.status = "active";
    entry.updatedAt = now;
  }

  const isCurrent = body.isCurrent !== undefined ? Boolean(body.isCurrent) : normalizeSpecVersionStatus(body.status, "current") === "current";
  if (isCurrent) {
    specVersions.forEach((version) => {
      if (version.entryId === entry.id) {
        version.isCurrent = false;
        if (version.status === "current") version.status = "superseded";
        version.updatedAt = now;
      }
    });
  }
  const version = normalizeSpecVersion({
    id: crypto.randomUUID(),
    projectId,
    entryId: entry.id,
    fileId: doc.id,
    fileName: doc.name,
    version: body.version,
    status: isCurrent ? "current" : normalizeSpecVersionStatus(body.status, "draft"),
    isCurrent,
    extractionStatus: "extracted",
    extractedAt: now,
    createdBy: actorDisplayName(userContext),
    createdByUserId: safeText(userContext?.user?.id, ""),
    createdAt: now,
    updatedAt: now,
  });
  const parameters = rawParameters.map((parameter) => normalizeSpecParameter({
    ...parameter,
    id: crypto.randomUUID(),
    projectId,
    entryId: entry.id,
    versionId: version.id,
    tagNumber,
    createdAt: now,
    updatedAt: now,
  }));
  version.parameterCount = parameters.length;
  if (parameters.length) {
    version.extractionStatus = parameters.some((parameter) => parameter.confidence === "low") ? "needs_confirmation" : "extracted";
  } else {
    version.extractionStatus = "manual_required";
  }
  specVersions.unshift(version);
  specParameters = specParameters.filter((parameter) => parameter.versionId !== version.id);
  specParameters.unshift(...parameters);
  if (isCurrent || !entry.currentVersionId) {
    entry.currentVersionId = version.id;
  }

  doc.specMetadata = normalizeDocumentSpecMetadata({
    markedAsSpec: true,
    documentType: body.documentType,
    tagNumber,
    equipmentType,
    discipline: body.discipline,
    revision: version.version,
    specEntryId: entry.id,
    specVersionId: version.id,
  });
  addActivity(doc, actorDisplayName(userContext), "Register specification", `${tagNumber} ${version.version} registered for Drawing-Spec Check.`);

  const linkedDrawingIds = Array.isArray(body.linkedDrawingIds) ? body.linkedDrawingIds.map((item) => safeText(item, "")).filter(Boolean) : [];
  const links = [];
  linkedDrawingIds.forEach((drawingId) => {
    const drawing = requireDocument(drawingId, userContext);
    const drawingMetadata = normalizeDocumentDrawingMetadata(drawing.drawingMetadata);
    const existing = specDrawingLinks.find((link) => link.specEntryId === entry.id && link.drawingId === drawing.id);
    if (existing) {
      existing.drawingNumber = drawingMetadata.drawingNumber || existing.drawingNumber;
      existing.updatedAt = now;
      links.push(existing);
      return;
    }
    const link = normalizeSpecDrawingLink({
      id: crypto.randomUUID(),
      projectId,
      specEntryId: entry.id,
      drawingId: drawing.id,
      drawingNumber: drawingMetadata.drawingNumber,
      createdBy: actorDisplayName(userContext),
      createdByUserId: safeText(userContext?.user?.id, ""),
      createdAt: now,
      updatedAt: now,
    });
    specDrawingLinks.unshift(link);
    links.push(link);
  });
  touchDocument(doc);
  persistStore();
  return {
    specEntry: publicSpecEntry(entry),
    specVersion: publicSpecVersion(version),
    parameters: parameters.map(publicSpecParameter),
    links: links.map(normalizeSpecDrawingLink),
    ...buildDrawingSpecCheckPayload(userContext),
  };
}

function extractDrawingParametersFromBody(body = {}, drawingDoc = null) {
  if (Array.isArray(body.parameters) && body.parameters.length) {
    return body.parameters;
  }
  const parsed = parseSpecParametersFromText(body.text || body.textContent || "");
  const tagNumber = safeText(body.tagNumber, "");
  return parsed.map((parameter) => ({
    ...parameter,
    tagNumber: tagNumber || inferTagNumberFromText(body.text || body.textContent || "") || safeText(drawingDoc?.drawingMetadata?.relatedDrawingNumber, ""),
  }));
}

function inferTagNumberFromText(textValue = "") {
  const match = safeText(textValue, "").toUpperCase().match(/(?:^|[^A-Z0-9])([A-Z]{1,4}-\d{2,4}[A-Z]?)(?=[^A-Z0-9]|$)/);
  return match ? match[1] : "";
}

function extractDrawingSpecParameters(drawingId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const doc = requireDocument(drawingId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("You do not have access to this drawing.");
  }
  if (!drawingSmartReviewDocumentCandidate(doc)) {
    const error = new Error("Only PDF/DWG drawing documents can be used for Drawing-Spec Check extraction.");
    error.statusCode = 400;
    throw error;
  }
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const drawingVersionId = safeText(body.drawingVersionId || body.versionId, doc.currentVersionId);
  const versionEntry = requireVersionEntry(doc, drawingVersionId, { includeDeleted: false });
  const drawingMetadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata);
  const now = new Date().toISOString();
  const rawParameters = extractDrawingParametersFromBody(body, doc);
  const parameters = rawParameters.map((parameter) => normalizeDrawingSpecParameter({
    ...parameter,
    id: crypto.randomUUID(),
    projectId,
    drawingId: doc.id,
    drawingName: doc.name,
    drawingNumber: drawingMetadata.drawingNumber,
    drawingVersionId: versionEntry.id,
    drawingVersion: versionEntry.version || doc.version,
    tagNumber: safeText(parameter.tagNumber || body.tagNumber, ""),
    createdAt: now,
    updatedAt: now,
  })).filter((parameter) => parameter.tagNumber && parameter.paramName);
  drawingSpecParameters = drawingSpecParameters.filter((parameter) => parameter.drawingVersionId !== versionEntry.id);
  drawingSpecParameters.unshift(...parameters);
  addActivity(doc, actorDisplayName(userContext), "Extract drawing parameters", `${parameters.length} Drawing-Spec Check parameters extracted.`);
  touchDocument(doc);
  persistStore();
  return {
    document: toPublicDocument(doc, userContext),
    parameters: parameters.map(publicDrawingSpecParameter),
    tagNumbers: Array.from(new Set(parameters.map((parameter) => parameter.tagNumber))).sort(),
    ...buildDrawingSpecCheckPayload(userContext),
  };
}

function parseSpecNumericValue(value, unit = "") {
  const rawValue = safeText(value, "");
  const rawUnit = normalizeSpecUnit(unit);
  const match = rawValue.match(/(?:\bDN\s*)?(-?\d+(?:\.\d+)?)\s*([A-Za-z°℃℉/³0-9]+)?/i);
  if (!match) {
    return { hasNumber: false, value: rawValue, unit: rawUnit };
  }
  return {
    hasNumber: true,
    value: Number(match[1]),
    unit: rawUnit || (/^\s*DN/i.test(rawValue) ? "DN" : normalizeSpecUnit(match[2] || "")),
  };
}

function specParamDisplayValue(parameter) {
  if (!parameter) return "—";
  return [safeText(parameter.paramValue, ""), normalizeSpecUnit(parameter.paramUnit || "")].filter(Boolean).join(" ");
}

function normalizedSynonymText(value) {
  return safeText(value, "")
    .toLowerCase()
    .replace(/[\s_\-./()]+/g, "")
    .replace(/[°℃℉]/g, "")
    .trim();
}

function synonymMatch(leftValue, rightValue, synonymGroups = []) {
  const left = normalizedSynonymText(leftValue);
  const right = normalizedSynonymText(rightValue);
  if (!left || !right) return false;
  if (left === right) return true;
  return synonymGroups.some((group) => {
    const normalized = group.map(normalizedSynonymText);
    return normalized.includes(left) && normalized.includes(right);
  });
}

function specParameterKind(name = "") {
  const normalized = normalizeSpecParamName(name);
  if (/pressure|mawp|hydrotest/.test(normalized)) return "pressure";
  if (/temperature/.test(normalized)) return "temperature";
  if (/flow|capacity/.test(normalized)) return "flow";
  if (/weight|mass/.test(normalized)) return "weight";
  if (/size|diameter|nozzle|interface|connection|nominal/.test(normalized)) return "dimension";
  if (/material|moc|metallurgy/.test(normalized)) return "material";
  if (/fluid|medium|service|media/.test(normalized)) return "fluid";
  if (/standard|code|specification/.test(normalized)) return "standard";
  if (/tag number|tag/.test(normalized)) return "tag";
  return "text";
}

function specNumericTolerance(kind) {
  if (kind === "pressure") return { type: "pct", value: 5 };
  if (kind === "temperature") return { type: "abs", value: 5 };
  if (kind === "dimension") return { type: "exact", value: 0 };
  if (kind === "weight") return { type: "pct", value: 10 };
  if (kind === "flow") return { type: "pct", value: 5 };
  return { type: "exact", value: 0 };
}

function specParameterMismatchLevel(name, kind, reason = "") {
  const normalized = normalizeSpecParamName(name);
  if (reason === "low_confidence") return "pending";
  if (kind === "tag") return "error";
  if (kind === "material") return "error";
  if (kind === "pressure" && /design|mawp|hydrotest/.test(normalized)) return "error";
  if (kind === "temperature" && /design/.test(normalized)) return "error";
  if (kind === "dimension" && /nozzle|interface|connection/.test(normalized)) return "error";
  if (kind === "standard") return "warning";
  if (kind === "text") return "info";
  return "warning";
}

function confidenceScore(value) {
  return { high: 3, medium: 2, low: 1 }[normalizeSpecConfidence(value, "medium")] || 2;
}

function chooseBestParameter(parameters = []) {
  return [...parameters]
    .filter(Boolean)
    .sort((left, right) => {
      const confidenceDiff = confidenceScore(right.confidence) - confidenceScore(left.confidence);
      if (confidenceDiff) return confidenceDiff;
      return safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, ""));
    })[0] || null;
}

function convertSpecUnit(value, fromUnit, toUnit, conversions = []) {
  const numericValue = Number(value);
  const from = normalizeSpecUnit(fromUnit);
  const to = normalizeSpecUnit(toUnit);
  if (!Number.isFinite(numericValue) || !from || !to || from === to) {
    return { value: numericValue, converted: from === to, unit: to || from };
  }
  const direct = conversions.find((item) => normalizeSpecUnit(item.from) === from && normalizeSpecUnit(item.to) === to);
  if (direct) {
    if (Number.isFinite(Number(direct.factor))) {
      return { value: numericValue * Number(direct.factor), converted: true, unit: to };
    }
    if (direct.formula === "(x - 32) * 5 / 9") {
      return { value: (numericValue - 32) * 5 / 9, converted: true, unit: to };
    }
  }
  const inverse = conversions.find((item) => normalizeSpecUnit(item.from) === to && normalizeSpecUnit(item.to) === from && Number.isFinite(Number(item.factor)) && Number(item.factor) !== 0);
  if (inverse) {
    return { value: numericValue / Number(inverse.factor), converted: true, unit: to };
  }
  if (from === "°C" && to === "°F") {
    return { value: (numericValue * 9 / 5) + 32, converted: true, unit: to };
  }
  return { value: numericValue, converted: false, unit: from };
}

function compareSpecNumeric(specParam, drawingParam, kind, dictionaries) {
  const specNumeric = parseSpecNumericValue(specParam?.paramValue, specParam?.paramUnit);
  const drawingNumeric = parseSpecNumericValue(drawingParam?.paramValue, drawingParam?.paramUnit);
  if (!specNumeric.hasNumber || !drawingNumeric.hasNumber) {
    return { comparable: false, passed: false, diffPct: null, difference: "Unable to parse numeric value" };
  }
  const convertedDrawing = convertSpecUnit(drawingNumeric.value, drawingNumeric.unit, specNumeric.unit || drawingNumeric.unit, dictionaries.unitConversions);
  if (drawingNumeric.unit && specNumeric.unit && !convertedDrawing.converted && drawingNumeric.unit !== specNumeric.unit) {
    return { comparable: false, passed: false, diffPct: null, difference: `Unit conversion required: ${drawingNumeric.unit} to ${specNumeric.unit}` };
  }
  const tolerance = specNumericTolerance(kind);
  const specValue = Number(specNumeric.value);
  const drawingValue = Number(convertedDrawing.value);
  if (!Number.isFinite(specValue) || !Number.isFinite(drawingValue)) {
    return { comparable: false, passed: false, diffPct: null, difference: "Invalid numeric value" };
  }
  const rawDiffPct = specValue === 0 ? (drawingValue === 0 ? 0 : 100) : ((drawingValue - specValue) / specValue) * 100;
  if (tolerance.type === "pct") {
    const passed = Math.abs(rawDiffPct) <= tolerance.value + 1e-9;
    return {
      comparable: true,
      passed,
      diffPct: Number((passed ? Math.abs(rawDiffPct) : rawDiffPct).toFixed(3)),
      difference: passed ? "Within tolerance" : `${Number(rawDiffPct.toFixed(3))}% exceeds ±${tolerance.value}% tolerance`,
    };
  }
  if (tolerance.type === "abs") {
    const delta = drawingValue - specValue;
    const passed = Math.abs(delta) <= tolerance.value + 1e-9;
    return {
      comparable: true,
      passed,
      diffPct: specValue === 0 ? null : Number(rawDiffPct.toFixed(3)),
      difference: passed ? "Within tolerance" : `${Number(delta.toFixed(3))} ${specNumeric.unit || ""} exceeds ±${tolerance.value}${specNumeric.unit || ""} tolerance`,
    };
  }
  const passed = String(specParam?.paramValue || "").trim().toLowerCase() === String(drawingParam?.paramValue || "").trim().toLowerCase() ||
    (specValue === drawingValue && normalizeSpecUnit(specNumeric.unit) === normalizeSpecUnit(convertedDrawing.unit || specNumeric.unit));
  return {
    comparable: true,
    passed,
    diffPct: specValue === 0 ? null : Number(rawDiffPct.toFixed(3)),
    difference: passed ? "Exact match" : "Exact dimensional match required",
  };
}

function stripStandardVersion(value) {
  return safeText(value, "")
    .toLowerCase()
    .replace(/\b(19|20)\d{2}\b/g, "")
    .replace(/[-_:.\s]+/g, "")
    .trim();
}

function compareSpecText(specParam, drawingParam, kind, dictionaries) {
  const left = safeText(specParam?.paramValue, "");
  const right = safeText(drawingParam?.paramValue, "");
  if (kind === "material") {
    const passed = synonymMatch(left, right, dictionaries.materialSynonyms);
    return { passed, level: passed ? "info" : "error", difference: passed ? "Material synonym match" : "Material mismatch" };
  }
  if (kind === "fluid") {
    const passed = synonymMatch(left, right, dictionaries.fluidSynonyms);
    return { passed, level: passed ? "info" : "warning", difference: passed ? "Fluid synonym match" : "Fluid service differs" };
  }
  if (kind === "standard") {
    if (normalizedSynonymText(left) === normalizedSynonymText(right)) {
      return { passed: true, level: "info", difference: "Exact match" };
    }
    if (stripStandardVersion(left) && stripStandardVersion(left) === stripStandardVersion(right)) {
      return { passed: false, level: "warning", difference: "Standard version differs" };
    }
    return { passed: false, level: "info", difference: "Standard reference differs" };
  }
  const passed = normalizedSynonymText(left) === normalizedSynonymText(right);
  return { passed, level: passed ? "info" : specParameterMismatchLevel(specParam?.paramName || drawingParam?.paramName, kind), difference: passed ? "Exact match" : "Text differs" };
}

function buildSpecResultSource(parameter, kind = "spec") {
  if (!parameter) return {};
  if (kind === "drawing") {
    return {
      parameterId: parameter.id,
      fileId: parameter.drawingId,
      fileName: parameter.drawingName,
      drawingNumber: parameter.drawingNumber,
      versionId: parameter.drawingVersionId,
      version: parameter.drawingVersion,
      page: parameter.page,
      position: parameter.position,
      confidence: parameter.confidence,
      source: parameter.source,
    };
  }
  const version = specVersions.find((item) => item.id === parameter.versionId);
  return {
    parameterId: parameter.id,
    fileId: version?.fileId || "",
    fileName: version?.fileName || "",
    versionId: parameter.versionId,
    version: version?.version || "",
    page: parameter.page,
    position: parameter.position,
    confidence: parameter.confidence,
    source: parameter.source,
  };
}

function buildSpecCheckResultForParam({ task, name, specParam, drawingParam, dictionaries }) {
  const kind = specParameterKind(name);
  const hasLowConfidence = [specParam?.confidence, drawingParam?.confidence].some((confidence) => normalizeSpecConfidence(confidence, "medium") === "low");
  const specValue = specParam ? specParamDisplayValue(specParam) : "";
  const drawingValue = drawingParam ? specParamDisplayValue(drawingParam) : "";
  const confidence = hasLowConfidence ? "low" : confidenceScore(specParam?.confidence) >= 3 && confidenceScore(drawingParam?.confidence) >= 3 ? "high" : "medium";
  if (hasLowConfidence) {
    return normalizeSpecCheckResult({
      id: crypto.randomUUID(),
      projectId: task.projectId,
      taskId: task.id,
      tagNumber: task.tagNumber,
      paramName: name,
      specVersionId: task.specVersionId,
      specValue,
      specUnit: specParam?.paramUnit || "",
      specSource: buildSpecResultSource(specParam, "spec"),
      drawingValue,
      drawingUnit: drawingParam?.paramUnit || "",
      drawingSource: buildSpecResultSource(drawingParam, "drawing"),
      level: "pending",
      status: "open",
      confidence,
      reason: "Low extraction confidence requires human confirmation.",
      difference: "Pending human confirmation",
    });
  }
  if (!specParam || !drawingParam) {
    const missingSide = specParam ? "drawing" : "specification";
    const level = specParameterMismatchLevel(name, kind, "missing");
    return normalizeSpecCheckResult({
      id: crypto.randomUUID(),
      projectId: task.projectId,
      taskId: task.id,
      tagNumber: task.tagNumber,
      paramName: name,
      specVersionId: task.specVersionId,
      specValue,
      specUnit: specParam?.paramUnit || "",
      specSource: buildSpecResultSource(specParam, "spec"),
      drawingValue,
      drawingUnit: drawingParam?.paramUnit || "",
      drawingSource: buildSpecResultSource(drawingParam, "drawing"),
      level: level === "error" ? "warning" : level,
      status: "open",
      confidence,
      reason: `${missingSide} parameter is missing.`,
      difference: `${missingSide} missing`,
    });
  }
  if (["pressure", "temperature", "flow", "weight", "dimension"].includes(kind)) {
    const compared = compareSpecNumeric(specParam, drawingParam, kind, dictionaries);
    const level = compared.passed ? "info" : specParameterMismatchLevel(name, kind, compared.comparable ? "mismatch" : "unit");
    return normalizeSpecCheckResult({
      id: crypto.randomUUID(),
      projectId: task.projectId,
      taskId: task.id,
      tagNumber: task.tagNumber,
      paramName: name,
      specVersionId: task.specVersionId,
      specValue,
      specUnit: specParam.paramUnit,
      specSource: buildSpecResultSource(specParam, "spec"),
      drawingValue,
      drawingUnit: drawingParam.paramUnit,
      drawingSource: buildSpecResultSource(drawingParam, "drawing"),
      diffPct: compared.diffPct,
      level,
      status: compared.passed ? "passed" : "open",
      confidence,
      reason: compared.difference,
      difference: compared.difference,
    });
  }
  const compared = compareSpecText(specParam, drawingParam, kind, dictionaries);
  const level = compared.passed ? "info" : compared.level || specParameterMismatchLevel(name, kind);
  return normalizeSpecCheckResult({
    id: crypto.randomUUID(),
    projectId: task.projectId,
    taskId: task.id,
    tagNumber: task.tagNumber,
    paramName: name,
    specVersionId: task.specVersionId,
    specValue,
    specUnit: specParam.paramUnit,
    specSource: buildSpecResultSource(specParam, "spec"),
    drawingValue,
    drawingUnit: drawingParam.paramUnit,
    drawingSource: buildSpecResultSource(drawingParam, "drawing"),
    level,
    status: compared.passed ? "passed" : "open",
    confidence,
    reason: compared.difference,
    difference: compared.difference,
  });
}

function summarizeSpecCheckResults(results = []) {
  const normalized = results.map(normalizeSpecCheckResult);
  return {
    total: normalized.length,
    passCount: normalized.filter((result) => result.status === "passed").length,
    errorCount: normalized.filter((result) => result.status === "open" && result.level === "error").length,
    warningCount: normalized.filter((result) => result.status === "open" && result.level === "warning").length,
    infoCount: normalized.filter((result) => result.status === "open" && result.level === "info").length,
    pendingCount: normalized.filter((result) => result.status === "open" && result.level === "pending").length,
    openCount: normalized.filter((result) => result.status === "open").length,
    resolvedCount: normalized.filter((result) => ["resolved", "accepted", "verified_closed"].includes(result.status)).length,
  };
}

function buildSpecCheckReport(task, results) {
  const summary = summarizeSpecCheckResults(results);
  const specVersion = specVersions.find((version) => version.id === task.specVersionId) || null;
  const drawings = Array.from(new Set(results.map((result) => result.drawingSource?.fileId).filter(Boolean)))
    .map((docId) => documents.find((doc) => doc.id === docId))
    .filter(Boolean)
    .map((doc) => ({
      id: doc.id,
      name: doc.name,
      drawingNumber: doc.drawingMetadata?.drawingNumber || "",
      version: doc.version,
    }));
  return {
    title: "Drawing-Spec Consistency Check Report",
    generatedAt: task.completedAt || new Date().toISOString(),
    basic: {
      tagNumber: task.tagNumber,
      specVersion: specVersion?.version || "",
      specFileName: specVersion?.fileName || "",
      drawings,
      checkedAt: task.completedAt || task.updatedAt,
    },
    conclusion: summary.errorCount ? "Failed" : summary.warningCount || summary.pendingCount ? "Needs confirmation" : "Passed",
    summary,
    details: results.map((result) => ({
      id: result.id,
      paramName: result.paramName,
      specValue: result.specValue,
      drawingValue: result.drawingValue,
      difference: result.difference,
      level: result.level,
      status: result.status,
      specSource: result.specSource,
      drawingSource: result.drawingSource,
    })),
  };
}

function resolveSpecComparisonTargets(body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const requestedVersionIds = Array.isArray(body.specVersionIds || body.spec_version_ids)
    ? (body.specVersionIds || body.spec_version_ids).map((item) => safeText(item, "")).filter(Boolean)
    : [];
  const legacyVersionId = safeText(body.specVersionId || body.spec_version_id, "");
  const versionIds = Array.from(new Set(requestedVersionIds.length ? requestedVersionIds : legacyVersionId ? [legacyVersionId] : []));
  if (versionIds.length) {
    return versionIds.map((versionId) => {
      const specVersion = specVersions.find((version) => version.projectId === projectId && version.id === versionId);
      if (!specVersion) {
        const error = new Error("Specification version not found.");
        error.statusCode = 404;
        throw error;
      }
      const entry = specEntries.find((item) => item.projectId === projectId && item.id === specVersion.entryId);
      if (!entry) {
        const error = new Error("Specification entry not found for selected version.");
        error.statusCode = 404;
        throw error;
      }
      return { projectId, entry, specVersion, tagNumber: entry.tagNumber };
    });
  }
  const tagNumber = safeText(body.tagNumber, "");
  if (!tagNumber) {
    const error = new Error("tagNumber or specVersionIds is required.");
    error.statusCode = 400;
    throw error;
  }
  const entry = specEntries.find((item) => item.projectId === projectId && item.tagNumber === tagNumber);
  if (!entry) {
    const error = new Error("No registered specification entry was found for this tag number.");
    error.statusCode = 404;
    throw error;
  }
  const specVersionId = safeText(body.specVersionId || body.spec_version_id, entry.currentVersionId);
  const specVersion = specVersions.find((version) => version.id === specVersionId && version.entryId === entry.id);
  if (!specVersion) {
    const error = new Error("Specification version not found.");
    error.statusCode = 404;
    throw error;
  }
  return [{ projectId, entry, specVersion, tagNumber }];
}

function buildDrawingSpecComparison({ projectId, entry, specVersion, tagNumber, drawingVersionIds, userContext }) {
  const linkedDrawingIds = specDrawingLinks.filter((link) => link.specEntryId === entry.id).map((link) => link.drawingId);
  const resolvedDrawingVersionIds = Array.isArray(drawingVersionIds) && drawingVersionIds.length
    ? drawingVersionIds.map((item) => safeText(item, "")).filter(Boolean)
    : drawingSpecParameters
        .filter((parameter) => linkedDrawingIds.includes(parameter.drawingId) && parameter.tagNumber === tagNumber)
        .map((parameter) => parameter.drawingVersionId);
  const specParams = specVersionParameters(specVersion.id).filter((parameter) => parameter.tagNumber === tagNumber);
  const drawingParams = drawingParametersForVersions(resolvedDrawingVersionIds, tagNumber);
  const visibleDocs = new Set(publicDocumentsForUser(userContext).map((doc) => doc.id));
  drawingParams.forEach((parameter) => {
    if (parameter.drawingId && !visibleDocs.has(parameter.drawingId)) {
      throw permissionDeniedError("You do not have access to all linked drawings.");
    }
  });
  const now = new Date().toISOString();
  const task = normalizeSpecCheckTask({
    id: crypto.randomUUID(),
    projectId,
    tagNumber,
    specVersionId: specVersion.id,
    drawingVersionIds: Array.from(new Set(resolvedDrawingVersionIds)),
    status: "comparing",
    createdBy: actorDisplayName(userContext),
    createdByUserId: safeText(userContext?.user?.id, ""),
    createdAt: now,
    updatedAt: now,
  });
  const dictionaries = specDictionaryBundle(projectId);
  const names = Array.from(new Set([...specParams, ...drawingParams].map((parameter) => parameter.normalizedName))).filter(Boolean);
  const results = names.map((normalizedName) => {
    const specParam = chooseBestParameter(specParams.filter((parameter) => parameter.normalizedName === normalizedName));
    const drawingParam = chooseBestParameter(drawingParams.filter((parameter) => parameter.normalizedName === normalizedName));
    const paramName = specParam?.paramName || drawingParam?.paramName || normalizedName;
    return buildSpecCheckResultForParam({ task, name: paramName, specParam, drawingParam, dictionaries });
  });
  task.status = "completed";
  task.completedAt = new Date().toISOString();
  task.updatedAt = task.completedAt;
  task.summary = summarizeSpecCheckResults(results);
  task.report = buildSpecCheckReport(task, results);
  return { task, results };
}

function buildDrawingSpecBatchReport(tasks = [], results = []) {
  if (tasks.length === 1) {
    return tasks[0].report || buildSpecCheckReport(tasks[0], results);
  }
  const summary = summarizeSpecCheckResults(results);
  const specs = tasks.map((task) => {
    const version = specVersions.find((item) => item.id === task.specVersionId) || null;
    return {
      tagNumber: task.tagNumber,
      specVersionId: task.specVersionId,
      version: version?.version || "",
      fileName: version?.fileName || "",
    };
  });
  return {
    title: "Drawing-Spec Consistency Check Batch Report",
    generatedAt: new Date().toISOString(),
    basic: {
      tagNumbers: Array.from(new Set(tasks.map((task) => task.tagNumber).filter(Boolean))),
      specs,
      drawingVersionIds: Array.from(new Set(tasks.flatMap((task) => task.drawingVersionIds || []))),
      checkedAt: new Date().toISOString(),
    },
    conclusion: summary.errorCount ? "Failed" : summary.warningCount || summary.pendingCount ? "Needs confirmation" : "Passed",
    summary,
    details: results.map((result) => ({
      id: result.id,
      tagNumber: result.tagNumber,
      specVersionId: result.specVersionId,
      paramName: result.paramName,
      specValue: result.specValue,
      drawingValue: result.drawingValue,
      difference: result.difference,
      level: result.level,
      status: result.status,
      specSource: result.specSource,
      drawingSource: result.drawingSource,
    })),
  };
}

function runDrawingSpecComparison(body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const targets = resolveSpecComparisonTargets(body, userContext);
  const drawingVersionIds = Array.isArray(body.drawingVersionIds || body.drawing_version_ids)
    ? (body.drawingVersionIds || body.drawing_version_ids).map((item) => safeText(item, "")).filter(Boolean)
    : [];
  const comparisons = targets.map((target) => buildDrawingSpecComparison({
    ...target,
    drawingVersionIds,
    userContext,
  }));
  const tasks = comparisons.map((comparison) => comparison.task);
  const results = comparisons.flatMap((comparison) => comparison.results);
  specCheckTasks.unshift(...tasks);
  specCheckResults.unshift(...results);
  persistStore();
  const report = buildDrawingSpecBatchReport(tasks, results);
  return {
    ...buildDrawingSpecCheckPayload(userContext),
    task: publicSpecCheckTask(tasks[0]),
    batch: {
      taskCount: tasks.length,
      taskIds: tasks.map((task) => task.id),
      specVersionIds: tasks.map((task) => task.specVersionId),
    },
    results: results.map(publicSpecCheckResult),
    report,
  };
}

function drawingSpecAnnotationColor(level) {
  if (level === "error") return "#d34a4a";
  if (level === "warning") return "#f2b84b";
  if (level === "pending") return "#8a6df1";
  return "#237df0";
}

async function createDrawingSpecCheckIssue(resultId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const result = specCheckResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("Drawing-Spec Check result not found.");
    error.statusCode = 404;
    throw error;
  }
  if (result.status === "passed") {
    const error = new Error("Passed comparison items do not require Issue creation.");
    error.statusCode = 400;
    throw error;
  }
  const drawingDoc = requireDocument(result.drawingSource?.fileId || result.drawingSource?.drawingId, userContext);
  const permissions = documentPermissionsForUser(drawingDoc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("You do not have access to this drawing.");
  }
  if (!permissions.annotations.create) {
    throw permissionDeniedError("You do not have permission to create Drawing-Spec Check Issues.");
  }
  const created = !result.annotationId;
  if (created) {
    const position = normalizeSpecPosition(result.drawingSource?.position);
    const annotation = await createAnnotation({
      type: "mark",
      variant: "spec-check",
      page: result.drawingSource?.page || 1,
      x: position.x,
      y: position.y,
      width: position.width,
      height: position.height,
      title: safeText(body.title, `[${result.tagNumber}] ${result.paramName} Datasheet and drawing mismatch`),
      note: [
        `Spec value: ${result.specValue || "Not found"}`,
        `Drawing value: ${result.drawingValue || "Not found"}`,
        `Difference: ${result.difference || "Mismatch"}`,
        `Spec source: ${result.specSource?.fileName || ""} ${result.specSource?.version || ""} P.${result.specSource?.page || "-"}`,
        `Drawing source: ${result.drawingSource?.fileName || drawingDoc.name} ${result.drawingSource?.version || drawingDoc.version} P.${result.drawingSource?.page || "-"}`,
      ].filter(Boolean).join("\n"),
      actor: safeText(body.actor, actorDisplayName(userContext)),
      color: drawingSpecAnnotationColor(result.level),
      status: "open",
      source: "drawing_spec_check",
    }, result.drawingSource?.versionId || drawingDoc.currentVersionId, {
      modelUrn: drawingDoc.aps?.urn,
      boundModelVersion: result.drawingSource?.version || drawingDoc.version,
    });
    annotation.specCheckResultId = result.id;
    annotation.specCheckTaskId = result.taskId;
    annotation.specCheckLevel = result.level;
    annotation.source = "drawing_spec_check";
    drawingDoc.annotations.push(normalizeAnnotation(annotation, result.drawingSource?.versionId || drawingDoc.currentVersionId));
    result.annotationId = annotation.id;
    result.updatedAt = new Date().toISOString();
    addActivity(drawingDoc, actorDisplayName(userContext), "Create Drawing-Spec Check Issue", `${result.tagNumber} ${result.paramName} mismatch was linked to a drawing annotation.`);
    touchDocument(drawingDoc);
  }
  const task = specCheckTasks.find((item) => item.id === result.taskId);
  if (task) {
    const results = specCheckResults.filter((item) => item.taskId === task.id);
    task.summary = summarizeSpecCheckResults(results);
    task.report = buildSpecCheckReport(task, results);
    task.updatedAt = new Date().toISOString();
  }
  persistStore();
  return {
    created,
    result: publicSpecCheckResult(result),
    document: toPublicDocument(drawingDoc, userContext),
    ...buildDrawingSpecCheckPayload(userContext),
  };
}

function updateDrawingSpecCheckResult(resultId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const result = specCheckResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("Drawing-Spec Check result not found.");
    error.statusCode = 404;
    throw error;
  }
  const drawingDoc = result.drawingSource?.fileId ? requireDocument(result.drawingSource.fileId, userContext) : null;
  if (drawingDoc) {
    assertDocumentCapability(drawingDoc, "annotations.updateOwn", userContext, "You do not have permission to disposition this Drawing-Spec Check result.");
  }
  const nextStatus = normalizeSpecCheckStatus(body.status, result.status);
  if (!["open", "resolved", "accepted", "verified_closed"].includes(nextStatus)) {
    const error = new Error("Unsupported result status.");
    error.statusCode = 400;
    throw error;
  }
  result.status = nextStatus;
  result.reason = safeText(body.reason || body.disposition, result.reason);
  result.updatedAt = new Date().toISOString();
  const annotation = specCheckAnnotationForResult(result);
  if (annotation && nextStatus !== "open") {
    annotation.status = "resolved";
    annotation.resolved = true;
    annotation.resolvedAt = result.updatedAt;
  }
  const task = specCheckTasks.find((item) => item.id === result.taskId);
  if (task) {
    const results = specCheckResults.filter((item) => item.taskId === task.id);
    task.summary = summarizeSpecCheckResults(results);
    task.report = buildSpecCheckReport(task, results);
    task.updatedAt = result.updatedAt;
  }
  if (drawingDoc) {
    touchDocument(drawingDoc);
  }
  persistStore();
  return result;
}

function drawingRegisterDocumentCandidate(doc) {
  const metadata = drawingRegisterMetadataForDocument(doc);
  return Boolean(metadata.markedAsDrawing && metadata.drawingNumber && drawingRegisterFormatForDocument(doc));
}

function drawingRegisterFormatForDocument(doc) {
  const extension = path.extname(String(doc?.name || "")).toLowerCase();
  const mimeType = String(doc?.mimeType || "").toLowerCase();
  if (extension === ".pdf" || mimeType === "application/pdf") {
    return "pdf";
  }
  if (APS_DRAWING_DOCUMENT_EXTENSIONS.has(extension)) {
    return "dwg";
  }
  return "";
}

function inferDrawingDisciplineFromName(name) {
  const value = safeText(name, "");
  if (/总图|总平面|平面布置|总布置/.test(value)) return "总图";
  if (/工艺|流程|PID|P&ID|管道仪表/i.test(value)) return "工艺";
  if (/管道|配管/.test(value)) return "管道";
  if (/设备|机械|机泵|泵|阀门|阀|风机|起重/.test(value)) return "设备";
  if (/土建|场站|基坑|地基/.test(value)) return "土建";
  if (/结构|结施|钢筋|基础|钢结构/.test(value)) return "结构";
  if (/建筑|建施|装修/.test(value)) return "建筑";
  if (/电气|电力|照明|动力|变配电|接地/.test(value)) return "电气";
  if (/仪表|自控|控制|DCS|PLC|SCADA/i.test(value)) return "仪表自控";
  if (/给排水|给水|排水|水施/.test(value)) return "给排水";
  if (/暖通|空调|通风|HVAC/i.test(value)) return "暖通";
  if (/消防|喷淋/.test(value)) return "消防";
  if (/海水|取水|排海|取排水| intake |outfall/i.test(value)) return "海水取排水";
  if (/预处理|絮凝|沉淀|过滤|超滤|UF/i.test(value)) return "预处理";
  if (/反渗透|RO|膜|高压泵|能量回收/i.test(value)) return "反渗透";
  if (/化学|加药|药剂|CIP/i.test(value)) return "化学加药";
  if (/排放|污泥|排泥|浓盐水|brine/i.test(value)) return "排放/污泥";
  if (/通信|通讯|网络/.test(value)) return "通信";
  if (/弱电|安防|监控|门禁/.test(value)) return "弱电";
  if (/道路|场坪/.test(value)) return "道路";
  return "其他";
}

function inferDrawingMetadataFromFileName(name) {
  const fileName = path.basename(safeText(name, ""));
  const baseName = path.basename(fileName, path.extname(fileName)).trim();
  if (!baseName) {
    return normalizeDocumentDrawingMetadata({});
  }
  const drawingNumber = inferDrawingNumber(baseName);
  const revision = normalizeDrawingRevisionLabel(inferDrawingRevision(baseName), "");
  if (!drawingNumber || !revision) {
    return normalizeDocumentDrawingMetadata({});
  }
  const parts = baseName.split("_").map((part) => part.trim()).filter(Boolean);
  const nameParts = parts
    .filter((part, index) => index !== 0 || part.replace(/_/g, "-").toUpperCase() !== drawingNumber.toUpperCase())
    .filter((part) => !inferDrawingRevision(part))
    .filter((part) => !/^\d{10,}$/.test(part));
  const drawingName = safeText(nameParts.join("_"), baseName
    .replace(drawingNumber, "")
    .replace(inferDrawingRevision(baseName), "")
    .replace(/[_\-\s]+$/g, "")
    .replace(/^[_\-\s]+/g, ""));
  return {
    markedAsDrawing: true,
    drawingNumber,
    drawingName: drawingName || drawingNumber,
    discipline: inferDrawingDisciplineFromName(drawingName || baseName),
    revision,
    relatedDrawingNumber: "",
    relatedDrawingId: "",
  };
}

function inferLooseDrawingMetadataFromFileName(name, revisionFallback = "V1") {
  const fileName = path.basename(safeText(name, ""));
  const baseName = path.basename(fileName, path.extname(fileName)).trim();
  if (!baseName) {
    return normalizeDocumentDrawingMetadata({});
  }
  return {
    markedAsDrawing: true,
    drawingNumber: baseName,
    drawingName: baseName,
    discipline: inferDrawingDisciplineFromName(baseName),
    revision: normalizeDrawingRevisionLabel(revisionFallback, "V1") || "V1",
    relatedDrawingNumber: "",
    relatedDrawingId: "",
  };
}

function drawingRegisterMetadataForDocument(doc) {
  const declared = normalizeDocumentDrawingMetadata(doc?.drawingMetadata || {});
  if (declared.markedAsDrawing && declared.drawingNumber) {
    return {
      ...declared,
      metadataSource: "declared",
      metadataConfidence: "user",
      requiresMetadataConfirmation: false,
    };
  }
  const format = drawingRegisterFormatForDocument(doc);
  if (!format) {
    return {
      ...declared,
      metadataSource: "",
      metadataConfidence: "",
      requiresMetadataConfirmation: false,
    };
  }
  const inferred = inferDrawingMetadataFromFileName(doc?.name || "");
  if (inferred.markedAsDrawing && inferred.drawingNumber && inferred.revision) {
    return {
      ...inferred,
      metadataSource: "auto",
      metadataConfidence: "filename",
      requiresMetadataConfirmation: true,
    };
  }
  if (format === "dwg") {
    return {
      ...inferLooseDrawingMetadataFromFileName(doc?.name || "", doc?.version || "V1"),
      metadataSource: "auto",
      metadataConfidence: "filename_loose",
      requiresMetadataConfirmation: true,
    };
  }
  return {
    ...declared,
    metadataSource: "",
    metadataConfidence: "",
    requiresMetadataConfirmation: false,
  };
}

function drawingRegisterVersionId(projectId, drawingNo, revision) {
  return `drv_${sha1Hash([projectId, drawingNo, revision || "current"].join("|")).slice(0, 18)}`;
}

function drawingRegisterEntryId(projectId, drawingNo) {
  return `dr_${sha1Hash([projectId, drawingNo].join("|")).slice(0, 18)}`;
}

function drawingRevisionSortValue(revision) {
  const value = safeText(revision, "").toUpperCase();
  const revMatch = value.match(/^REV\.?([A-Z0-9.-]+)$/);
  const raw = revMatch ? revMatch[1] : value.replace(/^V/, "");
  const numeric = Number(raw.replace(/[^0-9.]/g, ""));
  if (Number.isFinite(numeric) && /\d/.test(raw)) {
    return numeric;
  }
  if (/^[A-Z]+$/.test(raw)) {
    return raw.split("").reduce((sum, char) => sum * 26 + (char.charCodeAt(0) - 64), 0);
  }
  return 0;
}

function normalizeDrawingRegisterFormat(format) {
  return ["all", "pdf", "dwg"].includes(String(format || "").trim()) ? String(format || "").trim() : "all";
}

function normalizeDrawingPackageType(value, fallback = "complete") {
  return ["pdf", "dwg", "complete"].includes(String(value || "").trim()) ? String(value || "").trim() : fallback;
}

function normalizeDrawingPackageStatus(value, fallback = "draft") {
  return ["draft", "published", "archived"].includes(String(value || "").trim()) ? String(value || "").trim() : fallback;
}

function normalizeDrawingPackageRecipient(recipient) {
  const value = recipient && typeof recipient === "object" ? recipient : {};
  const name = safeText(value.name || value.recipient || value.company, "");
  if (!name) {
    return null;
  }
  return {
    id: safeText(value.id, crypto.randomUUID()),
    name,
    email: normalizeEmail(value.email || ""),
    format: normalizeDrawingPackageType(value.format, "pdf"),
    ackRequired: value.ackRequired !== undefined ? Boolean(value.ackRequired) : true,
    ackAt: safeText(value.ackAt, ""),
    ackBy: safeText(value.ackBy, ""),
    linkExpiresAt: safeText(value.linkExpiresAt, ""),
    accessToken: safeText(value.accessToken || value.token, ""),
    accessUrl: safeText(value.accessUrl || value.downloadUrl, ""),
    status: safeText(value.status, value.ackAt ? "acknowledged" : "pending"),
  };
}

function normalizeDrawingPackageItem(item) {
  const value = item && typeof item === "object" ? item : {};
  const versionId = safeText(value.versionId || value.id, "");
  if (!versionId) {
    return null;
  }
  return {
    id: safeText(value.id, crypto.randomUUID()),
    versionId,
    drawingNo: safeText(value.drawingNo, ""),
    drawingName: safeText(value.drawingName || value.name, ""),
    discipline: safeText(value.discipline, ""),
    version: safeText(value.version, ""),
    sortOrder: Number.isFinite(Number(value.sortOrder)) ? Number(value.sortOrder) : 0,
    preCheckWarnings: Array.isArray(value.preCheckWarnings)
      ? value.preCheckWarnings.map((warning) => safeText(warning, "")).filter(Boolean)
      : [],
  };
}

function drawingPackageTypeLabel(type) {
  return {
    pdf: "PDF包",
    dwg: "DWG包",
    complete: "完整包",
  }[type] || "完整包";
}

function drawingPackageStatusLabel(status) {
  return {
    draft: "草稿",
    published: "已发布",
    archived: "已归档",
  }[status] || "草稿";
}

function drawingApprovalStatusFromDocuments(formatDocs) {
  const docs = formatDocs.filter(Boolean);
  if (!docs.length) {
    return { key: "not_approved", label: "未审批" };
  }
  const statuses = docs.map((doc) => safeText(doc.status, "uploaded"));
  const approvedCount = statuses.filter((status) => status === "approved").length;
  if (approvedCount === docs.length) {
    return { key: "approved", label: "已批准" };
  }
  if (statuses.some((status) => ["in_review", "final_review"].includes(status)) || docs.some((doc) => safeText(doc.activeWorkflowId, ""))) {
    return { key: "in_review", label: "审批中" };
  }
  if (statuses.some((status) => status === "rejected")) {
    return { key: "rejected", label: "已退回" };
  }
  if (approvedCount > 0) {
    return { key: "partial", label: "部分审批" };
  }
  return { key: "not_approved", label: "未审批" };
}

function drawingPublishStatusForVersion(versionId) {
  const refs = drawingPackages.filter((pkg) => (pkg.items || []).some((item) => item.versionId === versionId));
  if (refs.some((pkg) => pkg.status === "published")) {
    return { key: "published", label: "已发布" };
  }
  if (refs.some((pkg) => pkg.status === "archived")) {
    return { key: "archived", label: "已归档" };
  }
  return { key: "unpublished", label: "未发布" };
}

function drawingFormatRecord(doc, format, metadata) {
  return {
    format,
    fileId: doc.id,
    fileName: doc.name,
    versionId: doc.currentVersionId,
    documentVersion: doc.version,
    mimeType: doc.mimeType,
    size: Number(doc.size || 0),
    uploadedAt: doc.uploadedAt,
    updatedAt: doc.updatedAt,
    uploader: doc.uploader,
    parseStatus: doc.parseStatus,
    previewUrl: doc.fileUrl,
    downloadUrl: doc.fileUrl,
    aps: doc.aps || {},
    metadataSource: safeText(metadata.metadataSource, "declared"),
    metadataConfidence: safeText(metadata.metadataConfidence, "user"),
    requiresMetadataConfirmation: Boolean(metadata.requiresMetadataConfirmation),
    extractedMeta: {
      drawingNo: metadata.drawingNumber,
      drawingName: metadata.drawingName,
      discipline: metadata.discipline,
      revision: metadata.revision,
    },
  };
}

function drawingConsistencyConfirmationForVersion(projectId, versionId) {
  return drawingConsistencyConfirmations.find(
    (item) => item.projectId === projectId && item.versionId === versionId,
  ) || null;
}

function drawingConsistencyForVersion(version, projectId = DEFAULT_PROJECT_ID) {
  const pdf = version.formats.pdf;
  const dwg = version.formats.dwg;
  if (!pdf || !dwg) {
    return {
      status: "single",
      label: "—",
      details: [],
    };
  }
  const fields = [
    { key: "drawingNo", label: "图纸编号" },
    { key: "drawingName", label: "图纸名称" },
    { key: "revision", label: "版本号" },
  ];
  const details = fields
    .map((field) => ({
      field: field.label,
      key: field.key,
      pdfValue: safeText(pdf.extractedMeta?.[field.key], ""),
      dwgValue: safeText(dwg.extractedMeta?.[field.key], ""),
      status: safeText(pdf.extractedMeta?.[field.key], "") === safeText(dwg.extractedMeta?.[field.key], "") ? "pass" : "warning",
    }))
    .filter((item) => item.status === "warning");
  if (details.length) {
    const confirmation = drawingConsistencyConfirmationForVersion(projectId, version.id);
    if (confirmation) {
      return {
        status: "confirmed",
        label: "已确认",
        details,
        confirmation,
      };
    }
    return {
      status: "warning",
      label: "⚠",
      details,
    };
  }
  const dwgUploadedAt = new Date(dwg.uploadedAt || dwg.updatedAt || 0).getTime();
  const pdfUploadedAt = new Date(pdf.uploadedAt || pdf.updatedAt || 0).getTime();
  if (dwgUploadedAt && pdfUploadedAt && dwgUploadedAt - pdfUploadedAt > 60 * 1000) {
    const confirmation = drawingConsistencyConfirmationForVersion(projectId, version.id);
    if (confirmation) {
      return {
        status: "confirmed",
        label: "已确认",
        details: [
          {
            field: "更新时间",
            key: "uploadedAt",
            pdfValue: safeText(pdf.uploadedAt || pdf.updatedAt, ""),
            dwgValue: safeText(dwg.uploadedAt || dwg.updatedAt, ""),
            status: "warning",
            message: "DWG 已更新，PDF 可能需要重新导出。",
          },
        ],
        confirmation,
      };
    }
    return {
      status: "warning",
      label: "⚠",
      details: [
        {
          field: "更新时间",
          key: "uploadedAt",
          pdfValue: safeText(pdf.uploadedAt || pdf.updatedAt, ""),
          dwgValue: safeText(dwg.uploadedAt || dwg.updatedAt, ""),
          status: "warning",
          message: "DWG 已更新，PDF 可能需要重新导出。",
        },
      ],
    };
  }
  return {
    status: "pass",
    label: "✓",
    details: [],
  };
}

function enrichDrawingRegisterVersion(version, projectId) {
  const formatDocs = [version.sourceDocuments.pdf, version.sourceDocuments.dwg].filter(Boolean);
  const consistency = drawingConsistencyForVersion(version, projectId);
  const approval = drawingApprovalStatusFromDocuments(formatDocs);
  const publish = drawingPublishStatusForVersion(version.id);
  const formatRecords = [version.formats.pdf, version.formats.dwg].filter(Boolean);
  const hasAutoMetadata = formatRecords.some((item) => item.metadataSource === "auto");
  const metadataSource = hasAutoMetadata ? "auto" : formatRecords.some((item) => item.metadataSource === "declared") ? "declared" : "";
  const metadataConfidence = hasAutoMetadata
    ? formatRecords.some((item) => item.metadataConfidence === "filename_loose") ? "filename_loose" : "filename"
    : formatRecords.some((item) => item.metadataConfidence === "user") ? "user" : "";
  const packageRefs = drawingPackages
    .filter((pkg) => pkg.projectId === projectId && (pkg.items || []).some((item) => item.versionId === version.id))
    .map((pkg) => ({
      id: pkg.id,
      packageNo: pkg.packageNo,
      name: pkg.name,
      status: pkg.status,
      statusLabel: drawingPackageStatusLabel(pkg.status),
    }));
  const locked = packageRefs.some((item) => item.status === "published");
  const latestUpdatedAt = formatDocs
    .map((doc) => safeText(doc.updatedAt || doc.uploadedAt, ""))
    .sort()
    .pop() || "";
  return {
    id: version.id,
    drawingNo: version.drawingNo,
    drawingName: version.drawingName,
    discipline: version.discipline,
    version: version.version,
    versionDate: latestUpdatedAt,
    formats: version.formats,
    metadataSource,
    metadataConfidence,
    requiresMetadataConfirmation: formatRecords.some((item) => item.requiresMetadataConfirmation),
    consistencyStatus: consistency.status,
    consistencyLabel: consistency.label,
    consistencyDetails: consistency.details,
    consistencyConfirmation: consistency.confirmation || null,
    approvalStatus: approval.label,
    approvalStatusKey: approval.key,
    publishStatus: publish.label,
    publishStatusKey: publish.key,
    locked,
    packageRefs,
    sortValue: drawingRevisionSortValue(version.version),
  };
}

function buildDrawingRegisterPayload(userContext, options = {}) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const visibleDocs = publicDocumentsForUser(userContext).filter(
    (doc) => safeText(doc.projectId, DEFAULT_PROJECT_ID) === projectId && drawingRegisterDocumentCandidate(doc),
  );
  const entryMap = new Map();

  visibleDocs.forEach((doc) => {
    const metadata = drawingRegisterMetadataForDocument(doc);
    const format = drawingRegisterFormatForDocument(doc);
    if (!format) {
      return;
    }
    const drawingNo = metadata.drawingNumber;
    const revision = metadata.revision || normalizeDrawingRevisionLabel(doc.version, doc.version || "V1");
    const entryKey = `${projectId}:${drawingNo}`;
    const versionId = drawingRegisterVersionId(projectId, drawingNo, revision);
    if (!entryMap.has(entryKey)) {
      entryMap.set(entryKey, {
        id: drawingRegisterEntryId(projectId, drawingNo),
        projectId,
        drawingNo,
        name: metadata.drawingName,
        discipline: metadata.discipline,
        versions: new Map(),
      });
    }
    const entry = entryMap.get(entryKey);
    if (!entry.versions.has(versionId)) {
      entry.versions.set(versionId, {
        id: versionId,
        drawingNo,
        drawingName: metadata.drawingName,
        discipline: metadata.discipline,
        version: revision,
        formats: {},
        sourceDocuments: {},
      });
    }
    const version = entry.versions.get(versionId);
    const existing = version.sourceDocuments[format];
    const existingTime = new Date(existing?.updatedAt || existing?.uploadedAt || 0).getTime();
    const nextTime = new Date(doc.updatedAt || doc.uploadedAt || 0).getTime();
    if (!existing || nextTime >= existingTime) {
      version.formats[format] = drawingFormatRecord(doc, format, metadata);
      version.sourceDocuments[format] = doc;
      if (format === "pdf" || !version.drawingName) {
        version.drawingName = metadata.drawingName || version.drawingName;
        version.discipline = metadata.discipline || version.discipline;
      }
    }
  });

  const entries = Array.from(entryMap.values()).map((entry) => {
    const versions = Array.from(entry.versions.values())
      .map((version) => enrichDrawingRegisterVersion(version, projectId))
      .sort((left, right) => {
        if (right.sortValue !== left.sortValue) {
          return right.sortValue - left.sortValue;
        }
        return String(right.versionDate || "").localeCompare(String(left.versionDate || ""));
      })
      .map(({ sortValue, ...version }) => version);
    const currentVersion = versions[0] || null;
    return {
      id: entry.id,
      projectId: entry.projectId,
      drawingNo: entry.drawingNo,
      name: currentVersion?.drawingName || entry.name,
      discipline: currentVersion?.discipline || entry.discipline,
      currentVersion,
      versions,
    };
  }).sort((left, right) => localeCollator("zh-CN").compare(left.drawingNo, right.drawingNo));
  const expectedPayload = buildDrawingExpectedPayload(projectId, entries, visibleDocs);
  const expectedByNo = new Map(expectedPayload.items.map((item) => [item.drawingNo, item]));
  entries.forEach((entry) => {
    const expected = expectedByNo.get(entry.drawingNo);
    entry.expected = expected || {
      statusKey: "extra",
      statusLabel: "计划外",
      statusTone: "final_review",
    };
  });

  const filteredFormat = normalizeDrawingRegisterFormat(options.format);
  const exportEntries = filteredFormat === "all"
    ? entries
    : entries.filter((entry) => Boolean(entry.currentVersion?.formats?.[filteredFormat]));
  const completeness = exportEntries.reduce(
    (summary, entry) => {
      const current = entry.currentVersion || {};
      const hasPdf = Boolean(current.formats?.pdf);
      const hasDwg = Boolean(current.formats?.dwg);
      summary.total += 1;
      if (hasPdf && hasDwg) summary.both += 1;
      if (hasPdf && !hasDwg) summary.onlyPdf += 1;
      if (!hasPdf && hasDwg) summary.onlyDwg += 1;
      if (current.consistencyStatus === "warning") summary.inconsistent += 1;
      return summary;
    },
    { total: 0, both: 0, onlyPdf: 0, onlyDwg: 0, inconsistent: 0 },
  );

  return {
    projectId,
    generatedAt: new Date().toISOString(),
    entries: exportEntries,
    completeness,
    expectedItems: expectedPayload.items,
    expectedSummary: expectedPayload.summary,
    packages: publicDrawingPackagesForUser(userContext),
  };
}

function publicDrawingPackage(pkg) {
  const normalized = normalizeDrawingPackage(pkg);
  const items = Array.isArray(normalized.items) ? normalized.items : [];
  const recipients = Array.isArray(normalized.recipients) ? normalized.recipients : [];
  const preCheckWarnings = Array.isArray(normalized.preCheckWarnings)
    ? normalized.preCheckWarnings
    : items.flatMap((item) => item.preCheckWarnings || []);
  const ackRequired = recipients.filter((recipient) => recipient.ackRequired).length;
  const acked = recipients.filter((recipient) => recipient.ackRequired && recipient.ackAt).length;
  return {
    ...normalized,
    items,
    recipients,
    preCheckWarnings,
    typeLabel: drawingPackageTypeLabel(normalized.type),
    statusLabel: drawingPackageStatusLabel(normalized.status),
    drawingCount: items.length,
    ackSummary: ackRequired ? `${acked}/${ackRequired} 方` : "—",
    preCheckWarningCount: preCheckWarnings.length,
  };
}

function publicDrawingPackagesForUser(userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  return drawingPackages
    .filter((pkg) => pkg.projectId === projectId)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
    .map(publicDrawingPackage);
}

function nextDrawingPackageNo(projectId) {
  const count = drawingPackages.filter((pkg) => pkg.projectId === projectId).length + 1;
  return `PP-${String(count).padStart(3, "0")}`;
}

function drawingRegisterVersionMap(registerPayload) {
  const map = new Map();
  (registerPayload.entries || []).forEach((entry) => {
    (entry.versions || []).forEach((version) => {
      map.set(version.id, {
        entry,
        version,
      });
    });
  });
  return map;
}

function projectDrawingExpectedItems(projectId) {
  return drawingExpectedItems
    .filter((item) => item.projectId === projectId && !item.archivedAt)
    .sort((left, right) => {
      const disciplineOrder = localeCollator("zh-CN").compare(safeText(left.discipline, ""), safeText(right.discipline, ""));
      return disciplineOrder || localeCollator("zh-CN").compare(safeText(left.drawingNo, ""), safeText(right.drawingNo, ""));
    });
}

function drawingExpectedStatusForItem(item, entry, projectDocs) {
  if (entry) {
    return {
      key: "uploaded",
      label: "已上传",
      tone: "approved",
      entryId: entry.id,
      currentVersionId: entry.currentVersion?.id || "",
    };
  }
  const drawingNo = safeText(item.drawingNo, "").toLowerCase();
  const possibleUnmarked = (projectDocs || []).find((doc) => {
    const metadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
    return !metadata.markedAsDrawing && safeText(doc.name, "").toLowerCase().includes(drawingNo);
  });
  if (possibleUnmarked) {
    return {
      key: "unmarked",
      label: "待补录",
      tone: "final_review",
      documentId: possibleUnmarked.id,
      documentName: possibleUnmarked.name,
    };
  }
  const plannedTime = Date.parse(safeText(item.plannedDate, ""));
  if (Number.isFinite(plannedTime) && plannedTime < Date.now()) {
    return {
      key: "overdue",
      label: "逾期未提交",
      tone: "rejected",
    };
  }
  return {
    key: "pending",
    label: "计划中",
    tone: "neutral",
  };
}

function buildDrawingExpectedPayload(projectId, entries, projectDocs) {
  const entryByNo = new Map((entries || []).map((entry) => [safeText(entry.drawingNo, ""), entry]));
  const expected = projectDrawingExpectedItems(projectId).map((item) => {
    const status = drawingExpectedStatusForItem(item, entryByNo.get(item.drawingNo), projectDocs);
    return {
      ...item,
      statusKey: status.key,
      statusLabel: status.label,
      statusTone: status.tone,
      entryId: status.entryId || "",
      currentVersionId: status.currentVersionId || "",
      documentId: status.documentId || "",
      documentName: status.documentName || "",
    };
  });
  const expectedNos = new Set(expected.map((item) => item.drawingNo));
  const extraEntries = (entries || [])
    .filter((entry) => !expectedNos.has(entry.drawingNo))
    .map((entry) => ({
      id: `extra_${entry.id}`,
      projectId,
      drawingNo: entry.drawingNo,
      name: entry.name,
      discipline: entry.discipline,
      plannedDate: "",
      responsible: "",
      remarks: "目录外上传",
      statusKey: "extra",
      statusLabel: "计划外",
      statusTone: "final_review",
      entryId: entry.id,
      currentVersionId: entry.currentVersion?.id || "",
    }));
  const allItems = [...expected, ...extraEntries];
  const summary = allItems.reduce(
    (result, item) => {
      result.total += 1;
      if (item.statusKey === "uploaded") result.uploaded += 1;
      if (item.statusKey === "unmarked") result.unmarked += 1;
      if (item.statusKey === "overdue") result.overdue += 1;
      if (item.statusKey === "pending") result.pending += 1;
      if (item.statusKey === "extra") result.extra += 1;
      return result;
    },
    { total: 0, uploaded: 0, unmarked: 0, overdue: 0, pending: 0, extra: 0 },
  );
  return { items: allItems, summary };
}

function drawingPackagePrecheckWarnings(version, type) {
  const warnings = [];
  if ((type === "pdf" || type === "complete") && !version.formats?.pdf) {
    warnings.push("所选图纸缺少 PDF 文件。");
  }
  if ((type === "dwg" || type === "complete") && !version.formats?.dwg) {
    warnings.push("所选图纸缺少 DWG/CAD 文件。");
  }
  if (version.approvalStatusKey !== "approved") {
    warnings.push(`审批状态为 ${version.approvalStatus}，发布前需人工确认。`);
  }
  if (version.consistencyStatus === "warning") {
    warnings.push("PDF / DWG 格式一致性存在警告。");
  }
  return warnings;
}

function createDrawingPackage(body, userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const name = safeText(body?.name, "");
  if (!name) {
    const error = new Error("请输入打印包名称。");
    error.statusCode = 400;
    throw error;
  }
  const type = normalizeDrawingPackageType(body?.type, "complete");
  const versionIds = Array.from(new Set((Array.isArray(body?.versionIds) ? body.versionIds : []).map((item) => safeText(item, "")).filter(Boolean)));
  if (!versionIds.length) {
    const error = new Error("请至少选择一张图纸版本后再创建打印包。");
    error.statusCode = 400;
    throw error;
  }
  const registerPayload = buildDrawingRegisterPayload(userContext);
  const versionMap = drawingRegisterVersionMap(registerPayload);
  const now = new Date().toISOString();
  const items = versionIds.map((versionId, index) => {
    const match = versionMap.get(versionId);
    if (!match) {
      const error = new Error("所选图纸版本不存在或当前账号无权访问。");
      error.statusCode = 404;
      throw error;
    }
    const warnings = drawingPackagePrecheckWarnings(match.version, type);
    return normalizeDrawingPackageItem({
      versionId,
      drawingNo: match.entry.drawingNo,
      drawingName: match.entry.name,
      discipline: match.entry.discipline,
      version: match.version.version,
      sortOrder: index + 1,
      preCheckWarnings: warnings,
    });
  });
  const recipients = (Array.isArray(body?.recipients) ? body.recipients : [])
    .map(normalizeDrawingPackageRecipient)
    .filter(Boolean);
  const packageRecord = normalizeDrawingPackage({
    id: crypto.randomUUID(),
    projectId,
    packageNo: nextDrawingPackageNo(projectId),
    name,
    type,
    status: "draft",
    description: safeText(body?.description, ""),
    items,
    recipients,
    preCheckWarnings: items.flatMap((item) => item.preCheckWarnings || []),
    createdBy: safeText(userContext?.user?.id, ""),
    createdByName: actorDisplayName(userContext),
    createdAt: now,
    updatedAt: now,
    note: safeText(body?.note, ""),
  });
  drawingPackages.unshift(packageRecord);
  persistStore();
  return {
    package: publicDrawingPackage(packageRecord),
    register: buildDrawingRegisterPayload(userContext),
  };
}

function upsertDrawingExpectedItems(body, userContext) {
  requireAuthenticatedUser(userContext);
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const now = new Date().toISOString();
  const rawDrawings = Array.isArray(body?.drawings) ? body.drawings : [];
  if (!rawDrawings.length) {
    const error = new Error("请至少录入一条应出图清单。");
    error.statusCode = 400;
    throw error;
  }
  const changed = [];
  rawDrawings.forEach((raw) => {
    const drawingNo = safeText(raw?.drawingNo || raw?.drawingNumber, "");
    if (!drawingNo) {
      return;
    }
    const id = `expected_${sha1Hash([projectId, drawingNo].join("|")).slice(0, 18)}`;
    const existing = drawingExpectedItems.find((item) => item.id === id || (item.projectId === projectId && item.drawingNo === drawingNo));
    const normalized = normalizeDrawingExpectedItem({
      ...(existing || {}),
      id,
      projectId,
      drawingNo,
      name: safeText(raw?.name || raw?.drawingName, existing?.name || ""),
      discipline: safeText(raw?.discipline, existing?.discipline || ""),
      plannedDate: safeText(raw?.plannedDate || raw?.planDate, existing?.plannedDate || ""),
      responsible: safeText(raw?.responsible || raw?.owner, existing?.responsible || ""),
      remarks: safeText(raw?.remarks || raw?.note, existing?.remarks || ""),
      createdBy: existing?.createdBy || safeText(userContext?.user?.id, ""),
      createdByName: existing?.createdByName || actorDisplayName(userContext),
      createdAt: existing?.createdAt || now,
      updatedAt: now,
      archivedAt: "",
    });
    if (!normalized) {
      return;
    }
    if (existing) {
      Object.assign(existing, normalized);
    } else {
      drawingExpectedItems.push(normalized);
    }
    changed.push(normalized);
  });
  if (!changed.length) {
    const error = new Error("应出图清单缺少有效图纸编号。");
    error.statusCode = 400;
    throw error;
  }
  if (body?.replace === true) {
    const activeDrawingNos = new Set(changed.map((item) => item.drawingNo));
    drawingExpectedItems.forEach((item) => {
      if (item.projectId === projectId && !item.archivedAt && !activeDrawingNos.has(item.drawingNo)) {
        item.archivedAt = now;
        item.updatedAt = now;
      }
    });
  }
  persistStore();
  return {
    expectedItems: changed,
    ...buildDrawingRegisterPayload(userContext),
  };
}

function confirmDrawingRegisterConsistency(versionId, body, userContext) {
  requireAuthenticatedUser(userContext);
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const registerPayload = buildDrawingRegisterPayload(userContext);
  const versionMap = drawingRegisterVersionMap(registerPayload);
  const match = versionMap.get(safeText(versionId, ""));
  if (!match) {
    const error = new Error("图纸目录版本不存在或当前账号无权访问。");
    error.statusCode = 404;
    throw error;
  }
  const currentStatus = safeText(match.version.consistencyStatus, "");
  if (!["warning", "confirmed"].includes(currentStatus)) {
    const error = new Error("当前版本没有需要确认的格式一致性警告。");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const id = `dcc_${sha1Hash([projectId, versionId].join("|")).slice(0, 18)}`;
  const existing = drawingConsistencyConfirmations.find((item) => item.id === id || (item.projectId === projectId && item.versionId === versionId));
  const normalized = normalizeDrawingConsistencyConfirmation({
    ...(existing || {}),
    id,
    projectId,
    versionId,
    basis: body?.basis,
    note: safeText(body?.note, ""),
    confirmedBy: safeText(userContext?.user?.id, ""),
    confirmedByName: actorDisplayName(userContext),
    confirmedAt: existing?.confirmedAt || now,
    updatedAt: now,
  });
  if (existing) {
    Object.assign(existing, normalized);
  } else {
    drawingConsistencyConfirmations.push(normalized);
  }
  persistStore();
  return {
    confirmation: normalized,
    register: buildDrawingRegisterPayload(userContext),
  };
}

function requireDrawingPackage(packageId, userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const pkg = drawingPackages.find((item) => item.id === packageId && item.projectId === projectId);
  if (!pkg) {
    const error = new Error("打印包不存在或当前账号无权访问。");
    error.statusCode = 404;
    throw error;
  }
  return pkg;
}

function publishDrawingPackage(packageId, body, userContext, req = null) {
  requireAuthenticatedUser(userContext);
  const pkg = requireDrawingPackage(packageId, userContext);
  if (pkg.status === "archived") {
    const error = new Error("已归档的打印包不能再次发布。");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const expiresAt = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString();
  pkg.status = "published";
  pkg.publishedAt = pkg.publishedAt || now;
  pkg.updatedAt = now;
  pkg.note = safeText(body?.note, pkg.note || "系统内发送，生成受控访问链接。");
  pkg.recipients = (pkg.recipients || []).map((recipient) => normalizeDrawingPackageRecipient({
    ...recipient,
    accessToken: recipient.accessToken || crypto.randomUUID(),
    accessUrl: recipient.accessUrl || `${requestOrigin(req || { headers: { host: "127.0.0.1:8080" } })}/drawing-packages/${pkg.id}?recipient=${recipient.id}`,
    linkExpiresAt: recipient.linkExpiresAt || expiresAt,
    status: recipient.ackAt ? "acknowledged" : "pending",
  })).filter(Boolean);
  persistStore();
  return {
    package: publicDrawingPackage(pkg),
    register: buildDrawingRegisterPayload(userContext),
  };
}

function acknowledgeDrawingPackageRecipient(packageId, recipientId, body, userContext) {
  requireAuthenticatedUser(userContext);
  const pkg = requireDrawingPackage(packageId, userContext);
  if (pkg.status !== "published") {
    const error = new Error("打印包发布后才允许签收。");
    error.statusCode = 400;
    throw error;
  }
  const recipient = (pkg.recipients || []).find((item) => item.id === recipientId);
  if (!recipient) {
    const error = new Error("打印包接收方不存在。");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  recipient.ackAt = recipient.ackAt || now;
  recipient.ackBy = safeText(body?.ackBy, actorDisplayName(userContext));
  recipient.status = "acknowledged";
  pkg.updatedAt = now;
  persistStore();
  return {
    package: publicDrawingPackage(pkg),
    register: buildDrawingRegisterPayload(userContext),
  };
}

async function exportDrawingRegister(body, userContext, req = null) {
  requireAuthenticatedUser(userContext);
  const format = normalizeDrawingRegisterFormat(body?.format);
  const registerPayload = buildDrawingRegisterPayload(userContext, { format });
  const exportFileName = `${registerPayload.projectId}-drawing-register-${format}-${Date.now()}.xlsx`;
  const outputPath = path.join(EXPORTS_DIR, exportFileName);
  await runDrawingRegisterExportScript(registerPayload, outputPath, { format, language: requestLanguage(req, body) });
  const exportDocIds = Array.from(new Set((registerPayload.entries || []).flatMap((entry) => (entry.versions || []).flatMap((version) => [
    version.formats?.pdf?.fileId,
    version.formats?.dwg?.fileId,
  ]).filter(Boolean))));
  registerProtectedExportFile(exportFileName, {
    kind: "drawing_register_export",
    docIds: exportDocIds,
    projectId: registerPayload.projectId,
    createdBy: safeText(userContext?.user?.id, ""),
    createdAt: new Date().toISOString(),
    format,
  });
  await bestEffortProjectEmailNotification("exportCompleted", {
    userContext,
    req,
    occurredAt: new Date().toISOString(),
    note: "图纸目录 Excel 已生成",
  });
  return {
    projectId: registerPayload.projectId,
    format,
    exportFileName,
    downloadUrl: signedExportUrl(exportFileName),
    completeness: registerPayload.completeness,
  };
}

function normalizeDrawingSmartReviewChecks(value = {}) {
  return {
    rule: value.rule !== false,
    ai: value.ai !== false,
    visual: value.visual !== false,
  };
}

function normalizeDrawingSmartReviewGate(value = {}) {
  const defaults = defaultDrawingRuleConfigRules().gate;
  return {
    blockOnError: value.blockOnError !== undefined ? Boolean(value.blockOnError) : defaults.blockOnError,
    requireWarningDisposition: value.requireWarningDisposition !== undefined ? Boolean(value.requireWarningDisposition) : defaults.requireWarningDisposition,
    requireAiDisposition: value.requireAiDisposition !== undefined ? Boolean(value.requireAiDisposition) : defaults.requireAiDisposition,
    visualFindingsBlocking: value.visualFindingsBlocking !== undefined ? Boolean(value.visualFindingsBlocking) : defaults.visualFindingsBlocking,
    manualIssueCreation: value.manualIssueCreation !== undefined
      ? Boolean(value.manualIssueCreation)
      : value.createPdfAnnotations !== undefined
        ? Boolean(value.createPdfAnnotations)
        : defaults.manualIssueCreation !== undefined
          ? Boolean(defaults.manualIssueCreation)
          : true,
  };
}

function drawingPrecheckAppliesToWorkflow(doc) {
  const extension = path.extname(String(doc?.name || "")).toLowerCase();
  return Boolean(doc?.drawingMetadata?.markedAsDrawing || APS_DRAWING_DOCUMENT_EXTENSIONS.has(extension));
}

function latestDrawingPrecheckTaskForDocument(doc) {
  return drawingPrecheckTasks
    .filter((task) => task.fileId === doc?.id && task.projectId === doc?.projectId)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0] || null;
}

function drawingPrecheckResultsForTask(task) {
  if (!task) {
    return [];
  }
  return drawingPrecheckResults.filter((item) => item.taskId === task.id);
}

function drawingPrecheckBlockingResults(results, gate) {
  const effectiveGate = normalizeDrawingSmartReviewGate(gate || {});
  return results.filter((item) => {
    if (item.status !== "open") {
      return false;
    }
    if (effectiveGate.blockOnError && item.level === "error") {
      return true;
    }
    if (effectiveGate.requireWarningDisposition && item.level === "warning") {
      return true;
    }
    if (effectiveGate.requireAiDisposition && item.checkType === "ai") {
      return true;
    }
    if (effectiveGate.visualFindingsBlocking && item.checkType === "visual") {
      return true;
    }
    return false;
  });
}

function drawingPrecheckGateSummaryForTask(task, results = drawingPrecheckResultsForTask(task), doc = null) {
  const normalizedTask = task ? normalizeDrawingPrecheckTask(task) : null;
  const targetDoc = doc || documents.find((item) => item.id === normalizedTask?.fileId) || null;
  if (!normalizedTask) {
    return {
      status: "not_run",
      canStartWorkflow: false,
      message: "尚未完成图纸智能审查。",
      blockingCount: 0,
      openCount: 0,
      taskId: "",
    };
  }
  if (normalizedTask.status === "running" || normalizedTask.status === "queued") {
    return {
      status: "running",
      canStartWorkflow: false,
      message: "图纸智能审查仍在运行，请等待完成后再发起审批。",
      blockingCount: 0,
      openCount: 0,
      taskId: normalizedTask.id,
    };
  }
  if (normalizedTask.status === "failed") {
    return {
      status: "failed",
      canStartWorkflow: false,
      message: "最近一次图纸智能审查失败，请重新运行预审。",
      blockingCount: 0,
      openCount: 0,
      taskId: normalizedTask.id,
    };
  }
  if (targetDoc && normalizedTask.versionId && normalizedTask.versionId !== targetDoc.currentVersionId) {
    return {
      status: "stale",
      canStartWorkflow: false,
      message: "当前文件版本晚于最近一次图纸智能审查，请重新运行预审。",
      blockingCount: 0,
      openCount: 0,
      taskId: normalizedTask.id,
      versionId: normalizedTask.versionId,
      currentVersionId: targetDoc.currentVersionId,
    };
  }
  const normalizedResults = results.map(normalizeDrawingPrecheckResult);
  const blockingResults = drawingPrecheckBlockingResults(normalizedResults, normalizedTask.gate);
  const openCount = normalizedResults.filter((item) => item.status === "open").length;
  const summary = summarizeDrawingPrecheckResults(normalizedResults);
  return {
    status: blockingResults.length ? "blocked" : "ready",
    canStartWorkflow: blockingResults.length === 0,
    message: blockingResults.length
      ? `仍有 ${blockingResults.length} 条预审问题需要处理。`
      : "图纸智能审查门控已通过，可发起审批。",
    blockingCount: blockingResults.length,
    openCount,
    taskId: normalizedTask.id,
    versionId: normalizedTask.versionId,
    summary,
    blockers: blockingResults.slice(0, 8).map((item) => ({
      id: item.id,
      level: item.level,
      checkType: item.checkType,
      category: item.category,
      title: item.title,
    })),
  };
}

function drawingPrecheckGateSummaryForDocument(doc) {
  const latestTask = latestDrawingPrecheckTaskForDocument(doc);
  if (!latestTask) {
    if (!drawingPrecheckAppliesToWorkflow(doc)) {
      return {
        status: "optional",
        canStartWorkflow: true,
        message: "该文件未声明为图纸，智能审查为可选项。",
        blockingCount: 0,
        openCount: 0,
        taskId: "",
      };
    }
    return {
      status: "not_run",
      canStartWorkflow: false,
      message: "标记为图纸的文件需先完成图纸智能审查。",
      blockingCount: 0,
      openCount: 0,
      taskId: "",
    };
  }
  return drawingPrecheckGateSummaryForTask(latestTask, drawingPrecheckResultsForTask(latestTask), doc);
}

function assertDrawingPrecheckGateAllowsWorkflow(doc) {
  if (!drawingPrecheckAppliesToWorkflow(doc)) {
    return;
  }
  const gate = drawingPrecheckGateSummaryForDocument(doc);
  if (gate.canStartWorkflow) {
    return;
  }
  const error = new Error(
    gate.status === "not_run"
      ? `文件 ${doc.name} 尚未完成图纸智能审查，不能发起审批流程。`
      : `文件 ${doc.name} 仍有未处理预审问题，不能发起审批流程。${gate.message || ""}`,
  );
  error.statusCode = 409;
  error.detail = gate;
  throw error;
}

function drawingExtractionSnapshotForDocument(doc) {
  const currentVersion = resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId) || currentVersionSnapshot(doc);
  const previousVersion = [...(doc.versionHistory || [])]
    .filter((entry) => !entry.isCurrent && !entry.deletedAt)
    .sort((left, right) => Number(right.versionNo || 0) - Number(left.versionNo || 0))[0] || null;
  const fileName = safeText(doc.name, "");
  const versionNote = safeText(currentVersion?.note, "");
  return normalizeDrawingExtractionSnapshot({
    id: crypto.randomUUID(),
    projectId: doc.projectId,
    fileId: doc.id,
    fileName,
    versionId: doc.currentVersionId,
    version: doc.version,
    textContent: {
      fileName,
      versionLabel: doc.version,
      versionNote,
      activity: (doc.activity || []).slice(-8).map((item) => `${safeText(item.title, "")} ${safeText(item.detail, "")}`),
      annotations: (doc.annotations || []).slice(0, 20).map((item) => `${safeText(item.title, "")} ${safeText(item.note, "")}`),
    },
    metadata: {
      mimeType: doc.mimeType,
      parseStatus: doc.parseStatus,
      size: doc.size,
      declaredDrawing: doc.drawingMetadata || {},
      uploadedAt: doc.uploadedAt,
      updatedAt: doc.updatedAt,
      pageCount: 1,
      sheetSize: inferDrawingSheetSize(fileName),
      extension: path.extname(fileName).slice(1).toLowerCase(),
    },
    diff: {
      previousVersion: previousVersion?.version || "",
      changedTextCount: previousVersion ? Math.max(1, Number(currentVersion?.versionNo || 1) - Number(previousVersion.versionNo || 1)) : 0,
      previousNote: safeText(previousVersion?.note, ""),
      currentNote: versionNote,
    },
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
}

function inferDrawingSheetSize(name) {
  const match = String(name || "").toUpperCase().match(/\bA[0-4]\b/);
  return match ? match[0] : "";
}

function inferDrawingNumber(name) {
  const base = path.basename(String(name || ""), path.extname(String(name || "")));
  const match = base.match(/[A-Z]{1,6}[-_]\d{2,}[-_A-Z0-9]*/i);
  return match ? match[0].replace(/_/g, "-").replace(/-+$/g, "").toUpperCase() : "";
}

function inferDrawingRevision(name) {
  const match = String(name || "").match(/(?:^|[_\-\s.])((?:rev[._-]?\s*[A-Z0-9]+|R\d+|V\d+))(?:$|[_\-\s.]|\b)/i);
  return match ? match[1].toUpperCase().replace(/\s+/g, "") : "";
}

function buildDrawingPrecheckFinding(base) {
  return normalizeDrawingPrecheckResult({
    id: crypto.randomUUID(),
    status: "open",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    ...base,
  });
}

function generateDrawingPrecheckFindings(doc, snapshot, task, checks) {
  const findings = [];
  const declaredDrawing = doc.drawingMetadata?.markedAsDrawing ? doc.drawingMetadata : {};
  const drawingNumber = safeText(declaredDrawing.drawingNumber, inferDrawingNumber(doc.name));
  const revision = safeText(declaredDrawing.revision, inferDrawingRevision(doc.name));
  const sheetSize = snapshot.metadata?.sheetSize || "";
  const base = {
    taskId: task.id,
    projectId: task.projectId,
    fileId: doc.id,
    fileName: doc.name,
    versionId: doc.currentVersionId,
    version: doc.version,
    page: 1,
  };
  const pos = [
    { x: 0.08, y: 0.08, width: 0.32, height: 0.08 },
    { x: 0.62, y: 0.08, width: 0.25, height: 0.08 },
    { x: 0.08, y: 0.78, width: 0.32, height: 0.08 },
    { x: 0.6, y: 0.72, width: 0.24, height: 0.12 },
    { x: 0.38, y: 0.42, width: 0.28, height: 0.1 },
  ];

  if (checks.rule) {
    if (!drawingNumber) {
      findings.push(buildDrawingPrecheckFinding({
        ...base,
        checkType: "rule",
        source: "rule",
        level: "error",
        category: "图框",
        title: "图纸编号缺失或无法识别",
        description: "文件名中未识别到符合项目编号规则的图纸编号，请补充图框编号或按项目命名规则重命名。",
        position: pos[0],
      }));
    }
    if (!revision) {
      findings.push(buildDrawingPrecheckFinding({
        ...base,
        checkType: "rule",
        source: "rule",
        level: "error",
        category: "版本",
        title: "版本号缺失",
        description: "未识别到 Rev.A / Rev.01 / V2 等版本号，审批前需要明确当前提交版本。",
        position: pos[1],
      }));
    }
    if (!sheetSize) {
      findings.push(buildDrawingPrecheckFinding({
        ...base,
        checkType: "rule",
        source: "rule",
        level: "warning",
        category: "格式",
        title: "图幅未识别",
        description: "未从文件名或元数据识别 A0/A1/A2/A3 图幅，请确认图框字段是否完整。",
        position: pos[2],
      }));
    }
    findings.push(buildDrawingPrecheckFinding({
      ...base,
      checkType: "rule",
      source: "rule",
      level: "info",
      category: "图例",
      title: "图例与说明待校验",
      description: "已进入图例与说明栏校验队列；如提取到符号表，系统会继续检查未使用图例和未登记符号。",
      position: pos[3],
    }));
  }

  if (checks.ai) {
    const textBlob = [
      doc.name,
      snapshot.textContent?.versionNote,
      ...(snapshot.textContent?.activity || []),
      ...(snapshot.textContent?.annotations || []),
    ].join(" ");
    if (/待定|TBD|临时|删除|错误|TEST|test|smoke/i.test(textBlob)) {
      findings.push(buildDrawingPrecheckFinding({
        ...base,
        checkType: "ai",
        source: "ai",
        level: "warning",
        category: "标注",
        title: "疑似存在占位或临时说明",
        description: "AI 在文件名、版本说明或批注上下文中识别到测试、临时或待定类词汇，建议设计人确认是否应进入正式审批。",
        confidence: "medium",
        position: pos[4],
      }));
    }
    if (snapshot.diff?.changedTextCount && !snapshot.diff?.currentNote) {
      findings.push(buildDrawingPrecheckFinding({
        ...base,
        checkType: "ai",
        source: "ai",
        level: "warning",
        category: "变更说明",
        title: "变更说明可能不完整",
        description: "检测到与上一版本存在差异，但当前版本说明为空，需补充修订记录覆盖实质性改动。",
        confidence: "high",
        position: pos[1],
      }));
    }
    findings.push(buildDrawingPrecheckFinding({
      ...base,
      checkType: "ai",
      source: "ai",
      level: "info",
      category: "一致性",
      title: "跨图纸引用需人工确认",
      description: "AI 预审会将图纸引用编号与文档中心目录交叉比对；当前未发现可自动拦截的问题。",
      confidence: "low",
      position: pos[3],
    }));
  }

  if (checks.visual) {
    findings.push(buildDrawingPrecheckFinding({
      ...base,
      checkType: "visual",
      source: "visual",
      level: "info",
      category: "视觉",
      title: "图面完整性视觉提示",
      description: "图像渲染后将检查明显空白、文字叠压和无尺寸标注区域；视觉结果置信度较低，仅作提示。",
      confidence: "low",
      position: pos[4],
    }));
  }

  return findings;
}

function summarizeDrawingPrecheckResults(results) {
  const summary = {
    total: results.length,
    errorCount: 0,
    warningCount: 0,
    infoCount: 0,
    openCount: 0,
    resolvedCount: 0,
    acceptedCount: 0,
    falsePositiveCount: 0,
  };
  results.forEach((item) => {
    if (item.level === "error") summary.errorCount += 1;
    if (item.level === "warning") summary.warningCount += 1;
    if (item.level === "info") summary.infoCount += 1;
    if (item.status === "open") summary.openCount += 1;
    if (item.status === "resolved") summary.resolvedCount += 1;
    if (item.status === "accepted") summary.acceptedCount += 1;
    if (item.status === "false_positive") summary.falsePositiveCount += 1;
  });
  summary.pass = summary.errorCount === 0 && summary.openCount === 0;
  return summary;
}

function drawingPrecheckIssueSummary(results) {
  const linkedResults = results.filter((item) => Boolean(item.annotationId));
  return {
    total: results.length,
    linkedCount: linkedResults.length,
    reportOnlyCount: Math.max(0, results.length - linkedResults.length),
    openCount: results.filter((item) => item.status === "open").length,
    resolvedCount: results.filter((item) => item.status === "resolved").length,
    acceptedCount: results.filter((item) => item.status === "accepted").length,
    falsePositiveCount: results.filter((item) => item.status === "false_positive").length,
    workflowIssueBoard: linkedResults.length
      ? "部分预审问题已手动写入批注层，并在流程 Issue 列表中按普通批注聚合。"
      : "当前预审问题仅作为报告项归档；需要进入审阅或流程 Issue 时，请在报告中手动生成批注 Issue。",
  };
}

function buildDrawingPrecheckReport(task, results) {
  const summary = summarizeDrawingPrecheckResults(results);
  const issueSummary = drawingPrecheckIssueSummary(results);
  const byType = (type) => results.filter((item) => item.checkType === type);
  const gate = drawingPrecheckGateSummaryForTask(task, results);
  return {
    title: "图纸智能审查预审报告",
    generatedAt: task.completedAt || new Date().toISOString(),
    conclusion: summary.errorCount ? "有问题需处理" : "可进入人工确认",
    summary,
    issueSummary,
    issuePolicy: {
      source: "drawing_precheck_result",
      linkedIssueEntity: "annotation",
      workflowAggregation: "workflow_issue_board",
      dispositionSync: "处理预审问题时同步关闭对应批注并追加处理说明。",
    },
    gate,
    sections: [
      { key: "basic", title: "基本信息", items: [`${task.fileName} · ${task.version}`, `检查时间：${task.completedAt || task.updatedAt}`] },
      { key: "gate", title: "审批前置门控", items: [gate.message, `阻断项：${gate.blockingCount}，未处理：${gate.openCount}`] },
      { key: "issue", title: "Issue 联动", items: [`批注联动：${issueSummary.linkedCount}，报告项：${issueSummary.reportOnlyCount}`, issueSummary.workflowIssueBoard] },
      { key: "rule", title: "规则检查结果", items: byType("rule").map((item) => `${item.level.toUpperCase()} · ${item.category} · ${item.title}`) },
      { key: "ai", title: "AI 审查结果", items: byType("ai").map((item) => `${item.confidence || "medium"} · ${item.category} · ${item.title}`) },
      { key: "visual", title: "视觉提示", items: byType("visual").map((item) => `${item.confidence || "low"} · ${item.title}`) },
    ],
  };
}

function drawingAnnotationColor(level, checkType) {
  if (level === "error") return "#d34a4a";
  if (level === "warning") return "#f2b84b";
  if (checkType === "ai") return "#f08a3c";
  return "#237df0";
}

async function createDrawingPrecheckAnnotation(doc, result, userContext) {
  const annotation = await createAnnotation({
    type: "mark",
    variant: result.checkType === "ai" ? "ai-precheck" : "precheck",
    page: result.page,
    x: result.position?.x,
    y: result.position?.y,
    width: result.position?.width,
    height: result.position?.height,
    title: `预审：${result.title}`,
    note: result.description,
    actor: "图纸智能审查",
    color: drawingAnnotationColor(result.level, result.checkType),
    status: "open",
  }, doc.currentVersionId, {
    modelUrn: doc.aps?.urn,
    boundModelVersion: doc.version,
  });
  annotation.precheckTaskId = result.taskId;
  annotation.precheckResultId = result.id;
  annotation.precheckLevel = result.level;
  annotation.precheckCategory = result.category;
  annotation.source = "drawing_precheck";
  doc.annotations.push(normalizeAnnotation(annotation, doc.currentVersionId));
  result.annotationId = annotation.id;
  addActivity(doc, actorDisplayName(userContext), "生成预审批注", result.title);
}

async function createDrawingPrecheckIssue(resultId, body, userContext) {
  const result = drawingPrecheckResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("预审问题不存在或已不在当前项目，请刷新图纸智能审查工作台后重试。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(result.fileId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该图纸的权限。");
  }
  const extension = path.extname(String(doc.name || "")).toLowerCase();
  if (doc.mimeType !== "application/pdf" && extension !== ".pdf" && !APS_DRAWING_DOCUMENT_EXTENSIONS.has(extension)) {
    const error = new Error("当前文件类型不支持从预审报告手动生成审阅 Issue。");
    error.statusCode = 400;
    throw error;
  }
  if (!permissions.annotations.create) {
    throw permissionDeniedError("你没有创建预审批注 Issue 的权限。");
  }

  const created = !result.annotationId;
  if (created) {
    await createDrawingPrecheckAnnotation(doc, result, userContext);
  }
  result.updatedAt = new Date().toISOString();
  const task = drawingPrecheckTasks.find((item) => item.id === result.taskId);
  if (task) {
    const taskResults = drawingPrecheckResults.filter((item) => item.taskId === task.id);
    task.summary = summarizeDrawingPrecheckResults(taskResults);
    task.gateStatus = drawingPrecheckGateSummaryForTask(task, taskResults, doc);
    task.report = buildDrawingPrecheckReport(task, taskResults);
    task.updatedAt = result.updatedAt;
  }
  touchDocument(doc);
  persistStore();
  return {
    created,
    result: publicDrawingPrecheckResult(result),
    document: toPublicDocument(doc, userContext),
    ...drawingSmartReviewPayload(userContext),
  };
}

async function exportDrawingPrecheckReport(taskId, userContext, req = null, body = null) {
  const task = drawingPrecheckTasks.find((item) => item.id === taskId);
  if (!task) {
    const error = new Error("预审任务不存在或已不在当前项目，请刷新图纸智能审查工作台后重试。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(task.fileId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview && !permissions.annotations.export) {
    throw permissionDeniedError("你没有导出该图纸预审报告的权限。");
  }
  const exportFileName = `${task.id}-drawing-precheck-${Date.now()}.xlsx`;
  const outputPath = path.join(EXPORTS_DIR, exportFileName);
  await runDrawingPrecheckReportExportScript(task, outputPath, { language: requestLanguage(req, body) });
  registerProtectedExportFile(exportFileName, {
    kind: "drawing_precheck_report_export",
    docIds: [doc.id],
    taskId: task.id,
    createdBy: safeText(userContext?.user?.id, ""),
    createdAt: new Date().toISOString(),
  });
  addActivity(doc, actorDisplayName(userContext), "导出预审报告", `${doc.name} ${task.version} 的图纸智能审查报告已导出`);
  await bestEffortProjectEmailNotification("exportCompleted", {
    document: doc,
    userContext,
    req,
    occurredAt: new Date().toISOString(),
    note: "图纸智能审查预审报告已生成",
  });
  persistStore();
  return {
    task: publicDrawingPrecheckTasks(userContext).find((item) => item.id === task.id) || task,
    exportFileName,
    downloadUrl: signedExportUrl(exportFileName),
  };
}

async function runDrawingSmartReview(body, userContext) {
  const documentIds = Array.from(new Set((Array.isArray(body?.documentIds) ? body.documentIds : []).map((item) => safeText(item, "")).filter(Boolean)));
  if (!documentIds.length) {
    const error = new Error("请至少选择一张图纸。");
    error.statusCode = 400;
    throw error;
  }
  const checks = normalizeDrawingSmartReviewChecks(body?.checks || {});
  const gate = normalizeDrawingSmartReviewGate(body?.gate || {});
  const actor = safeText(body?.actor, actorDisplayName(userContext));
  const tasks = [];
  const results = [];
  const snapshots = [];

  for (const documentId of documentIds) {
    const doc = requireDocument(documentId, userContext);
    if (!drawingSmartReviewDocumentCandidate(doc)) {
      const error = new Error(`文件 ${doc.name} 不是可审查的图纸文件。`);
      error.statusCode = 400;
      throw error;
    }
    const permissions = documentPermissionsForUser(doc, userContext);
    if (!permissions.preview) {
      throw permissionDeniedError("你没有查看该图纸的权限。");
    }
    const startedAt = new Date().toISOString();
    const snapshot = drawingExtractionSnapshotForDocument(doc);
    const task = normalizeDrawingPrecheckTask({
      id: crypto.randomUUID(),
      projectId: doc.projectId,
      fileId: doc.id,
      fileName: doc.name,
      versionId: doc.currentVersionId,
      version: doc.version,
      status: "completed",
      checks,
      gate,
      resultIds: [],
      triggeredBy: safeText(userContext?.user?.id, ""),
      triggeredByName: actor,
      createdAt: startedAt,
      updatedAt: startedAt,
      completedAt: new Date().toISOString(),
    });
    const docResults = generateDrawingPrecheckFindings(doc, snapshot, task, checks);
    for (const result of docResults) {
      task.resultIds.push(result.id);
    }
    task.summary = summarizeDrawingPrecheckResults(docResults);
    task.gateStatus = drawingPrecheckGateSummaryForTask(task, docResults, doc);
    task.report = buildDrawingPrecheckReport(task, docResults);
    drawingExtractionSnapshots.unshift(snapshot);
    drawingPrecheckTasks.unshift(task);
    drawingPrecheckResults.unshift(...docResults);
    touchDocument(doc);
    addActivity(doc, actor, "完成图纸智能审查", `生成 ${docResults.length} 条预审问题`);
    tasks.push(task);
    results.push(...docResults);
    snapshots.push(snapshot);
  }

  persistStore();
  const batchIssueSummary = drawingPrecheckIssueSummary(results);
  return {
    tasks,
    results: results.map(publicDrawingPrecheckResult),
    snapshots,
    summary: summarizeDrawingPrecheckResults(results),
    report: {
      title: "批量图纸智能审查汇总",
      generatedAt: new Date().toISOString(),
      issueSummary: batchIssueSummary,
      gate: {
        status: tasks.some((task) => task.gateStatus?.status === "blocked") ? "blocked" : "ready",
        blockingCount: tasks.reduce((sum, task) => sum + Number(task.gateStatus?.blockingCount || 0), 0),
        message: tasks.some((task) => task.gateStatus?.status === "blocked")
          ? "批量预审存在未处理阻断项。"
          : "批量预审门控已通过。",
      },
      sections: [
        {
          key: "issue",
          title: "Issue 联动",
          items: [
            `PDF 批注联动：${batchIssueSummary.linkedCount}`,
            `仅报告归档：${batchIssueSummary.reportOnlyCount}`,
          ],
        },
        ...tasks.map((task) => ({
          key: task.id,
          title: task.fileName,
          items: [
            `版本：${task.version}`,
            `问题：${task.summary.total}，Error：${task.summary.errorCount}，Warning：${task.summary.warningCount}`,
            `门控：${task.gateStatus?.message || "未计算"}`,
          ],
        })),
      ],
    },
    payload: drawingSmartReviewPayload(userContext),
  };
}

function updateDrawingPrecheckResult(resultId, body, userContext) {
  const result = drawingPrecheckResults.find((item) => item.id === resultId);
  if (!result) {
    const error = new Error("预审问题不存在或已不在当前项目，请刷新图纸智能审查工作台后重试。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(result.fileId, userContext);
  assertDocumentCapability(doc, "annotations.updateOwn", userContext, "你没有处理预审问题的权限。");
  result.status = normalizeDrawingPrecheckStatus(body?.status, result.status);
  result.disposition = safeText(body?.disposition, result.disposition);
  result.updatedAt = new Date().toISOString();
  const annotation = result.annotationId ? doc.annotations.find((item) => item.id === result.annotationId) : null;
  if (annotation && ["resolved", "accepted", "false_positive"].includes(result.status)) {
    annotation.status = "resolved";
    annotation.resolved = true;
    annotation.resolvedAt = result.updatedAt;
    if (result.disposition) {
      annotation.replies.push(normalizeReply({
        id: crypto.randomUUID(),
        actor: safeText(body?.actor, actorDisplayName(userContext)),
        content: result.disposition,
        createdAt: result.updatedAt,
        attachments: [],
      }));
    }
  }
  const task = drawingPrecheckTasks.find((item) => item.id === result.taskId);
  if (task) {
    const taskResults = drawingPrecheckResults.filter((item) => item.taskId === task.id);
    task.summary = summarizeDrawingPrecheckResults(taskResults);
    task.gateStatus = drawingPrecheckGateSummaryForTask(task, taskResults, doc);
    task.report = buildDrawingPrecheckReport(task, taskResults);
    task.updatedAt = result.updatedAt;
  }
  touchDocument(doc);
  persistStore();
  return { ...result };
}

function drawingRedlineDocumentCandidate(doc) {
  const extension = path.extname(String(doc?.name || "")).toLowerCase();
  const isPdf = doc?.mimeType === "application/pdf" || extension === ".pdf";
  const versions = activeVersionEntries(doc).filter((entry) => {
    const versionExt = path.extname(String(entry.name || doc?.name || "")).toLowerCase();
    return entry.mimeType === "application/pdf" || versionExt === ".pdf";
  });
  return Boolean(isPdf && doc?.drawingMetadata?.markedAsDrawing && versions.length >= 2);
}

function publicDrawingRedlineDocuments(userContext) {
  return publicDocumentsForUser(userContext)
    .filter((doc) => drawingRedlineDocumentCandidate(doc))
    .map((doc) => ({
      ...doc,
      versionHistory: activeVersionEntries(doc)
        .filter((entry) => entry.mimeType === "application/pdf" || path.extname(String(entry.name || doc.name || "")).toLowerCase() === ".pdf")
        .sort((left, right) => Number(left.versionNo || 0) - Number(right.versionNo || 0) || safeText(left.uploadedAt, "").localeCompare(safeText(right.uploadedAt, ""))),
    }));
}

function drawingRedlineTaskById(taskId) {
  const id = safeText(taskId, "");
  return drawingRedlineTasks.find((task) => task.id === id) || null;
}

function drawingRedlineRecordsForTask(taskId) {
  const id = safeText(taskId, "");
  return drawingRedlineRecords.filter((record) => record.taskId === id);
}

function drawingRedlineTitleBlockChangesForTask(taskId) {
  const id = safeText(taskId, "");
  return drawingRedlineTitleBlockChanges.filter((change) => change.taskId === id);
}

function drawingRedlineAiResultForTask(taskId) {
  const id = safeText(taskId, "");
  return drawingRedlineAiResults.find((result) => result.taskId === id) || null;
}

function publicDrawingRedlineTask(task) {
  return task ? normalizeDrawingRedlineTask(task) : null;
}

function publicDrawingRedlineRecord(record, doc = null) {
  const normalized = normalizeDrawingRedlineRecord(record);
  if (!normalized.issueId || !doc) {
    return normalized;
  }
  const issue = (Array.isArray(doc.annotations) ? doc.annotations : []).find((annotation) => annotation.id === normalized.issueId);
  if (issue) {
    normalized.issueStatus = safeText(issue.status, issue.resolved ? "resolved" : "open");
  }
  return normalized;
}

function buildDrawingRedlineHomePayload(userContext = SYSTEM_USER_CONTEXT) {
  const docs = publicDrawingRedlineDocuments(userContext);
  const visibleIds = new Set(docs.map((doc) => doc.id));
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  return {
    documents: docs,
    tasks: drawingRedlineTasks
      .filter((task) => task.projectId === projectId && visibleIds.has(task.documentId))
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
      .map(publicDrawingRedlineTask),
  };
}

function buildDrawingRedlineTaskPayload(task, userContext = SYSTEM_USER_CONTEXT) {
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task || !doc) {
    const error = new Error("红线对比任务不存在或已不在当前项目。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该红线对比报告的权限。");
  }
  const records = drawingRedlineRecordsForTask(task.id).map((record) => publicDrawingRedlineRecord(record, doc));
  const titleBlockChanges = drawingRedlineTitleBlockChangesForTask(task.id).map(normalizeDrawingRedlineTitleBlockChange).filter(Boolean);
  const aiResult = normalizeDrawingRedlineAiResult(drawingRedlineAiResultForTask(task.id) || {});
  return {
    document: toPublicDocument(doc, userContext),
    task: publicDrawingRedlineTask(task),
    records,
    titleBlockChanges,
    aiResult,
    report: task.report || buildDrawingRedlineReport(task, records, titleBlockChanges, aiResult),
    history: drawingRedlineTasks
      .filter((item) => item.documentId === doc.id && item.projectId === task.projectId)
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
      .map(publicDrawingRedlineTask),
  };
}

function assertDrawingRedlineCapability(doc, userContext) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该图纸的权限。");
  }
  if (!drawingRedlineDocumentCandidate(doc)) {
    const error = new Error("图纸红线对比仅支持已声明为图纸且至少包含两个 PDF 版本的文件。");
    error.statusCode = 400;
    throw error;
  }
  if (!permissions.rename && !permissions.annotations.create) {
    throw permissionDeniedError("你没有发起图纸红线对比任务的权限。");
  }
}

function assertPdfVersionForRedline(doc, versionEntry, label) {
  const extension = path.extname(String(versionEntry?.name || doc?.name || "")).toLowerCase();
  if (versionEntry?.mimeType !== "application/pdf" && extension !== ".pdf") {
    const error = new Error(`${label} 不是 PDF 版本。DWG 对比需先通过 Model Derivative 转换为 PDF 后再发起。`);
    error.statusCode = 400;
    throw error;
  }
}

function latestDrawingRedlineTaskForPair(doc, versionAId, versionBId) {
  return drawingRedlineTasks
    .filter((task) =>
      task.documentId === doc.id &&
      task.versionAId === versionAId &&
      task.versionBId === versionBId &&
      !["failed", "canceled"].includes(task.status),
    )
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))[0] || null;
}

function drawingRedlineJobForTask(taskId) {
  const id = safeText(taskId, "");
  return jobs.find((job) => job.type === "drawing.redline" && job.payload?.taskId === id && ["queued", "running"].includes(job.status)) || null;
}

function normalizeDrawingRedlineOptions(options = {}) {
  const value = options && typeof options === "object" ? options : {};
  const includeTypes = Array.isArray(value.includeTypes)
    ? value.includeTypes.map((item) => normalizeDrawingRedlineDiffType(item, "")).filter(Boolean)
    : ["added", "deleted", "modified", "moved"];
  return {
    minPixelArea: Math.max(1, Number(value.minPixelArea || 50) || 50),
    opacity: Math.max(0, Math.min(100, Number(value.opacity ?? 72) || 72)),
    includeTypes: includeTypes.length ? Array.from(new Set(includeTypes)) : ["added", "deleted", "modified", "moved"],
    ignoreTitleBlock: value.ignoreTitleBlock !== undefined ? Boolean(value.ignoreTitleBlock) : true,
    onlyDifferences: value.onlyDifferences !== undefined ? Boolean(value.onlyDifferences) : false,
  };
}

function enqueueDrawingRedlineTask(doc, body, userContext, req = null) {
  const versionA = requireVersionEntry(doc, safeText(body.versionAId || body.versionA, ""));
  const versionB = requireVersionEntry(doc, safeText(body.versionBId || body.versionB, ""));
  if (versionA.id === versionB.id) {
    const error = new Error("请选择两个不同版本进行红线对比。");
    error.statusCode = 400;
    throw error;
  }
  assertPdfVersionForRedline(doc, versionA, "版本 A");
  assertPdfVersionForRedline(doc, versionB, "版本 B");
  const existing = latestDrawingRedlineTaskForPair(doc, versionA.id, versionB.id);
  if (existing && body.force !== true) {
    return {
      task: existing,
      job: drawingRedlineJobForTask(existing.id),
      reused: true,
    };
  }

  const now = new Date().toISOString();
  const metadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
  const task = normalizeDrawingRedlineTask({
    id: crypto.randomUUID(),
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    documentId: doc.id,
    fileId: doc.id,
    fileName: doc.name,
    drawingNo: metadata.drawingNumber,
    drawingName: metadata.drawingName,
    discipline: metadata.discipline,
    versionAId: versionA.id,
    versionALabel: versionA.version,
    versionAUploadedAt: versionA.uploadedAt,
    versionBId: versionB.id,
    versionBLabel: versionB.version,
    versionBUploadedAt: versionB.uploadedAt,
    status: "queued",
    progress: 5,
    options: normalizeDrawingRedlineOptions(body.options || {}),
    createdBy: actorDisplayName(userContext),
    createdByUserId: safeText(userContext?.user?.id, ""),
    createdAt: now,
    updatedAt: now,
  });
  drawingRedlineTasks = drawingRedlineTasks.filter((item) => !(item.documentId === doc.id && item.versionAId === versionA.id && item.versionBId === versionB.id));
  drawingRedlineRecords = drawingRedlineRecords.filter((record) => record.taskId !== task.id);
  drawingRedlineTitleBlockChanges = drawingRedlineTitleBlockChanges.filter((change) => change.taskId !== task.id);
  drawingRedlineAiResults = drawingRedlineAiResults.filter((result) => result.taskId !== task.id);
  drawingRedlineTasks.unshift(task);
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "drawing.redline",
    status: "queued",
    resourceType: "document",
    resourceId: doc.id,
    payload: {
      taskId: task.id,
      documentId: doc.id,
      actor: actorDisplayName(userContext),
      actorUserId: safeText(userContext?.user?.id, ""),
    },
    attempts: 0,
    maxAttempts: Math.max(1, Number(body.maxAttempts || CDE_BACKGROUND_JOB_MAX_ATTEMPTS) || CDE_BACKGROUND_JOB_MAX_ATTEMPTS),
    createdAt: now,
    updatedAt: now,
  });
  jobs.unshift(job);
  touchDocument(doc);
  addActivity(doc, actorDisplayName(userContext), "图纸红线对比排队", `${versionA.version} → ${versionB.version} 已加入红线对比队列`);
  appendAuditLog(userContext, "drawing_redline.enqueue", "drawing_redline_task", task.id, {
    documentId: doc.id,
    versionAId: versionA.id,
    versionBId: versionB.id,
  }, req);
  persistStore();
  return { task, job, reused: false };
}

function drawingRedlineTypeLabel(type) {
  return {
    added: "新增内容",
    deleted: "删除内容",
    modified: "修改内容",
    moved: "移动内容",
  }[type] || "修改内容";
}

function drawingRedlineColor(type) {
  return {
    added: "#2da66f",
    deleted: "#d9473f",
    modified: "#d6a617",
    moved: "#ea7a24",
  }[type] || "#d6a617";
}

function drawingRedlineContentSummary(type, textA, textB) {
  if (type === "added") return `新增：${textB || "图形/文字内容"}`;
  if (type === "deleted") return `删除：${textA || "图形/文字内容"}`;
  if (type === "moved") return `${textA || textB || "内容"} 位置移动`;
  return `${textA || "空"} → ${textB || "空"}`;
}

function buildDrawingRedlineRecord(task, base) {
  return normalizeDrawingRedlineRecord({
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    documentId: task.documentId,
    versionAId: task.versionAId,
    versionBId: task.versionBId,
    source: "pdf-render-text-layer",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    ...base,
    contentSummary: base.contentSummary || drawingRedlineContentSummary(base.diffType, base.textA, base.textB),
  });
}

async function detectDrawingRedlineRecords(doc, task, versionA, versionB) {
  const storedA = safeText(versionA?.storedFileName, "");
  const storedB = safeText(versionB?.storedFileName, "");
  if (!storedA || !storedB) {
    const error = new Error("红线对比缺少版本文件存储对象，无法进行真实 PDF 渲染比对。");
    error.statusCode = 400;
    throw error;
  }
  if (!(await storageService.uploads.exists(storedA)) || !(await storageService.uploads.exists(storedB))) {
    const error = new Error("红线对比版本文件不存在或对象存储不可读。");
    error.statusCode = 404;
    throw error;
  }

  const sourceAPath = await storageService.uploads.materializeToTempPath(storedA);
  const sourceBPath = await storageService.uploads.materializeToTempPath(storedB);
  try {
    const payload = await runPdfRedlineDetection({
      pythonBin: PYTHON_BIN,
      scriptPath: DRAWING_REDLINE_DETECT_SCRIPT,
      sourceAPath,
      sourceBPath,
      options: {
        ...(task.options || {}),
        drawingNo: task.drawingNo,
        drawingName: task.drawingName || task.fileName,
        versionA: task.versionALabel,
        versionB: task.versionBLabel,
      },
    });
    const include = new Set(task.options?.includeTypes || ["added", "deleted", "modified", "moved"]);
    const records = (payload.records || [])
      .filter((record) => include.has(record.diffType))
      .map((record) => buildDrawingRedlineRecord(task, {
        page: record.page,
        diffType: record.diffType,
        bbox: record.bbox,
        textA: record.textA,
        textB: record.textB,
        contentSummary: record.contentSummary,
        area: record.area,
        heat: record.heat,
        aiConfidence: record.aiConfidence,
        aiInterpretation: record.aiInterpretation || "该差异由真实 PDF 渲染比对引擎定位，建议结合图面确认变更含义。",
        source: record.source || "pdf-pixel-render",
      }));
    task.detector = {
      engine: "pdf-render-pixel",
      backend: safeText(payload.diagnostics?.backend, ""),
      pagesA: Number(payload.diagnostics?.pagesA || 0) || 0,
      pagesB: Number(payload.diagnostics?.pagesB || 0) || 0,
      dpi: Number(payload.diagnostics?.dpi || 0) || 0,
      maxRenderDimension: Number(payload.diagnostics?.maxRenderDimension || 0) || 0,
    };
    return records;
  } finally {
    storageService.uploads.cleanupTempPath?.(sourceAPath);
    storageService.uploads.cleanupTempPath?.(sourceBPath);
  }
}

function generateDrawingRedlineTitleBlockChanges(task, versionA, versionB) {
  const rows = [
    ["版本号", versionA.version, versionB.version],
    ["日期", formatDate(versionA.uploadedAt), formatDate(versionB.uploadedAt)],
    ["修订记录", safeText(versionA.note, "—"), safeText(versionB.note, "—")],
  ];
  return rows
    .filter(([, valueA, valueB]) => valueA !== valueB)
    .map(([field, valueA, valueB]) => normalizeDrawingRedlineTitleBlockChange({
      id: crypto.randomUUID(),
      taskId: task.id,
      projectId: task.projectId,
      documentId: task.documentId,
      field,
      valueA,
      valueB,
      category: "title_block",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }))
    .filter(Boolean);
}

function summarizeDrawingRedlineRecords(records) {
  const summary = {
    total: records.length,
    pages: Array.from(new Set(records.map((record) => Number(record.page || 1)))).length,
    added: 0,
    deleted: 0,
    modified: 0,
    moved: 0,
    linkedIssues: 0,
    openIssues: 0,
  };
  records.forEach((record) => {
    if (summary[record.diffType] !== undefined) {
      summary[record.diffType] += 1;
    }
    if (record.issueId) {
      summary.linkedIssues += 1;
      if (record.issueStatus !== "resolved") {
        summary.openIssues += 1;
      }
    }
  });
  return summary;
}

function generateDrawingRedlineAiResult(task, records, titleBlockChanges) {
  const summary = summarizeDrawingRedlineRecords(records);
  const concentratedPage = records.reduce((acc, record) => {
    const key = String(record.page || 1);
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  const focusPage = Object.entries(concentratedPage).sort((left, right) => right[1] - left[1])[0]?.[0] || "1";
  return normalizeDrawingRedlineAiResult({
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    summary: `本次修版（${task.versionALabel} → ${task.versionBLabel}）共涉及 ${summary.pages} 页图纸的 ${summary.total} 处变更，主要集中在第 ${focusPage} 页。主要变更为管线规格调整、设备增减和局部标注移动，建议重点核查工艺系统及相关规格书。`,
    diffInterpretations: records.map((record) => ({
      diffId: record.id,
      diffType: record.diffType,
      page: record.page,
      contentSummary: record.contentSummary,
      interpretation: record.aiInterpretation,
      confidence: record.aiConfidence,
    })),
    relatedDrawingHints: [
      "管径变更可能影响相关系统图、材料表和规格书，建议联动核查。",
      "新增设备位号 P-101 建议在设备台账和布置图中同步确认。",
      titleBlockChanges.length ? "图框字段变化已单独列出，不混入主差异图层。" : "未发现需要单独提示的图框字段变化。",
    ],
    generatedAt: new Date().toISOString(),
  });
}

function buildDrawingRedlineReport(task, records = drawingRedlineRecordsForTask(task?.id), titleBlockChanges = drawingRedlineTitleBlockChangesForTask(task?.id), aiResult = drawingRedlineAiResultForTask(task?.id)) {
  const summary = summarizeDrawingRedlineRecords(records || []);
  return {
    title: "图纸版本红线对比报告",
    generatedAt: task?.completedAt || new Date().toISOString(),
    basic: {
      drawingNo: task?.drawingNo || "",
      drawingName: task?.drawingName || task?.fileName || "",
      discipline: task?.discipline || "",
      versionA: task?.versionALabel || "",
      versionB: task?.versionBLabel || "",
    },
    titleBlockChanges: titleBlockChanges || [],
    aiSummary: aiResult?.summary || "",
    summary,
    issuePolicy: {
      source: "drawing_redline_diff",
      linkedIssueEntity: "annotation",
      workflowAggregation: "workflow_issue_board",
      dispositionSync: "Issue 关闭后对应差异标记为已处理。",
    },
    sections: [
      {
        key: "basic",
        title: "基本信息",
        items: [
          `${task?.drawingNo || "—"} · ${task?.drawingName || task?.fileName || "—"}`,
          `版本 A：${task?.versionALabel || "—"}；版本 B：${task?.versionBLabel || "—"}`,
          `完成时间：${task?.completedAt || task?.updatedAt || "—"}`,
        ],
      },
      {
        key: "title_block",
        title: "图框变更摘要",
        items: (titleBlockChanges || []).map((item) => `${item.field}：${item.valueA || "—"} → ${item.valueB || "—"}`),
      },
      {
        key: "ai",
        title: "AI 变更说明",
        items: [aiResult?.summary || "AI 语义解读等待生成。"],
      },
      {
        key: "stats",
        title: "差异统计",
        items: [
          `涉及页数：${summary.pages}`,
          `新增内容：${summary.added}`,
          `删除内容：${summary.deleted}`,
          `修改内容：${summary.modified}`,
          `移动内容：${summary.moved}`,
        ],
      },
    ],
  };
}

async function runDrawingRedlineJob(doc, task, job) {
  const versionA = requireVersionEntry(doc, task.versionAId);
  const versionB = requireVersionEntry(doc, task.versionBId);
  task.status = "rendering";
  task.progress = 25;
  task.error = "";
  task.updatedAt = new Date().toISOString();
  persistStore();

  task.status = "detecting";
  task.progress = 58;
  task.updatedAt = new Date().toISOString();
  const records = await detectDrawingRedlineRecords(doc, task, versionA, versionB);
  const titleBlockChanges = generateDrawingRedlineTitleBlockChanges(task, versionA, versionB);
  drawingRedlineRecords = drawingRedlineRecords.filter((record) => record.taskId !== task.id);
  drawingRedlineTitleBlockChanges = drawingRedlineTitleBlockChanges.filter((change) => change.taskId !== task.id);
  drawingRedlineRecords.unshift(...records);
  drawingRedlineTitleBlockChanges.unshift(...titleBlockChanges);
  task.summary = summarizeDrawingRedlineRecords(records);
  task.recordCount = records.length;
  persistStore();

  task.status = "ai_analyzing";
  task.progress = 82;
  task.updatedAt = new Date().toISOString();
  persistStore();
  const aiResult = generateDrawingRedlineAiResult(task, records, titleBlockChanges);
  drawingRedlineAiResults = drawingRedlineAiResults.filter((result) => result.taskId !== task.id);
  drawingRedlineAiResults.unshift(aiResult);
  const completedAt = new Date().toISOString();
  task.status = "completed";
  task.progress = 100;
  task.completedAt = completedAt;
  task.updatedAt = completedAt;
  task.report = buildDrawingRedlineReport(task, records, titleBlockChanges, aiResult);
  touchDocument(doc);
  addActivity(doc, safeText(job.payload?.actor, "系统"), "图纸红线对比完成", `${versionA.version} → ${versionB.version}：${records.length} 处差异`);
  persistStore();
  return task;
}

function markDrawingRedlineFailed(job, error) {
  const task = drawingRedlineTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task) {
    return;
  }
  task.status = "failed";
  task.progress = 100;
  task.error = safeText(error?.message, "图纸红线对比失败");
  task.updatedAt = new Date().toISOString();
  if (doc) {
    addActivity(doc, safeText(job?.payload?.actor, "系统"), "图纸红线对比失败", task.error);
  }
}

function markDrawingRedlineRetryQueued(job, error) {
  const task = drawingRedlineTaskById(job?.payload?.taskId);
  if (!task) {
    return;
  }
  task.status = "queued";
  task.progress = 5;
  task.error = safeText(error?.message, "图纸红线对比失败，等待自动重试");
  task.updatedAt = new Date().toISOString();
}

async function createIssueFromDrawingRedlineRecord(recordId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const record = drawingRedlineRecords.find((item) => item.id === recordId);
  if (!record) {
    const error = new Error("红线差异记录不存在。");
    error.statusCode = 404;
    throw error;
  }
  const task = drawingRedlineTaskById(record.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task || !doc) {
    const error = new Error("红线对比任务不存在。");
    error.statusCode = 404;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.annotations.create) {
    throw permissionDeniedError("你没有从红线差异创建 Issue 的权限。");
  }
  const noteParts = [
    `差异类型：${drawingRedlineTypeLabel(record.diffType)}`,
    `版本对比：${task.versionALabel} → ${task.versionBLabel}`,
    `页码：P${record.page}`,
    `区域：x=${Math.round(record.bbox.x * 100)}%, y=${Math.round(record.bbox.y * 100)}%, w=${Math.round(record.bbox.width * 100)}%, h=${Math.round(record.bbox.height * 100)}%`,
    record.textA || record.textB ? `内容：${record.textA || "空"} → ${record.textB || "空"}` : "",
    record.aiInterpretation ? `AI 解读：${record.aiInterpretation}` : "",
    body.responsible ? `责任人：${safeText(body.responsible, "")}` : "",
    body.dueDate ? `截止日期：${safeText(body.dueDate, "")}` : "",
  ].filter(Boolean);
  const customNote = safeText(body.note, "");
  const annotation = await createAnnotation({
    type: "mark",
    variant: "drawing-redline",
    page: record.page,
    x: record.bbox.x,
    y: record.bbox.y,
    width: record.bbox.width,
    height: record.bbox.height,
    title: safeText(body.title, `红线差异复核：${drawingRedlineTypeLabel(record.diffType)}`),
    note: customNote ? `${noteParts.join("\n")}\n补充说明：${customNote}` : noteParts.join("\n"),
    actor: actorDisplayName(userContext),
    color: drawingRedlineColor(record.diffType),
    status: "open",
    source: "drawing_redline",
  }, task.versionBId || doc.currentVersionId, {
    boundModelVersion: task.versionBLabel || doc.version,
  });
  annotation.redlineTaskId = task.id;
  annotation.redlineDiffId = record.id;
  annotation.redlineDiffType = record.diffType;
  annotation.redlineVersionA = task.versionALabel;
  annotation.redlineVersionB = task.versionBLabel;
  doc.annotations.unshift(normalizeAnnotation(annotation, task.versionBId || doc.currentVersionId));
  record.issueId = annotation.id;
  record.annotationId = annotation.id;
  record.issueStatus = "open";
  record.updatedAt = new Date().toISOString();
  drawingRedlineAnnotationLinks.unshift(normalizeDrawingRedlineAnnotationLink({
    id: crypto.randomUUID(),
    taskId: task.id,
    diffId: record.id,
    annotationId: annotation.id,
    projectId: task.projectId,
    documentId: doc.id,
    createdAt: record.updatedAt,
    updatedAt: record.updatedAt,
  }));
  task.summary = summarizeDrawingRedlineRecords(drawingRedlineRecordsForTask(task.id));
  task.report = buildDrawingRedlineReport(task);
  task.updatedAt = record.updatedAt;
  touchDocument(doc);
  addActivity(doc, actorDisplayName(userContext), "红线差异转 Issue", `${drawingRedlineTypeLabel(record.diffType)} 差异已创建 Issue`);
  persistStore();
  await bestEffortProjectEmailNotification("annotationCreated", {
    document: doc,
    annotation,
    userContext,
    occurredAt: annotation.createdAt,
  });
  return {
    record: publicDrawingRedlineRecord(record, doc),
    issue: normalizeAnnotation(annotation, task.versionBId || doc.currentVersionId),
    document: toPublicDocument(doc, userContext),
    task: publicDrawingRedlineTask(task),
  };
}

async function exportDrawingRedlineReport(taskId, userContext, req = null, body = null) {
  const task = drawingRedlineTaskById(taskId);
  if (!task) {
    const error = new Error("红线对比任务不存在或已不在当前项目。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(task.documentId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview && !permissions.annotations.export) {
    throw permissionDeniedError("你没有导出该图纸红线报告的权限。");
  }
  if (task.status !== "completed") {
    const error = new Error("红线对比尚未完成，不能导出报告。");
    error.statusCode = 409;
    throw error;
  }
  const exportFileName = `${task.id}-drawing-redline-${Date.now()}.pdf`;
  const outputPath = path.join(EXPORTS_DIR, exportFileName);
  await runDrawingRedlineReportExportScript(task, outputPath, { language: requestLanguage(req, body) });
  task.exportFileName = exportFileName;
  task.updatedAt = new Date().toISOString();
  registerProtectedExportFile(exportFileName, {
    kind: "drawing_redline_report_export",
    docIds: [doc.id],
    taskId: task.id,
    createdBy: safeText(userContext?.user?.id, ""),
    createdAt: new Date().toISOString(),
  });
  addActivity(doc, actorDisplayName(userContext), "导出红线报告", `${doc.name} ${task.versionALabel} → ${task.versionBLabel} 的红线报告已导出`);
  await bestEffortProjectEmailNotification("exportCompleted", {
    document: doc,
    userContext,
    req,
    occurredAt: new Date().toISOString(),
    note: "图纸版本红线对比报告已生成",
  });
  persistStore();
  return {
    task: publicDrawingRedlineTask(task),
    exportFileName,
    downloadUrl: signedExportUrl(exportFileName),
  };
}

function drawingOcrDocumentCandidate(doc) {
  const extension = path.extname(String(doc?.name || "")).toLowerCase();
  const isPdf = doc?.mimeType === "application/pdf" || extension === ".pdf";
  return Boolean(isPdf && doc?.drawingMetadata?.markedAsDrawing);
}

function drawingOcrVersionCandidate(doc, versionEntry) {
  const extension = path.extname(String(versionEntry?.name || doc?.name || "")).toLowerCase();
  return Boolean(drawingOcrDocumentCandidate(doc) && (versionEntry?.mimeType === "application/pdf" || extension === ".pdf"));
}

function drawingOcrTaskById(taskId) {
  const id = safeText(taskId, "");
  return drawingOcrTasks.find((task) => task.id === id) || null;
}

function drawingOcrTasksForDocument(doc) {
  return drawingOcrTasks
    .filter((task) => task.documentId === doc?.id)
    .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")));
}

function latestDrawingOcrTaskForVersion(doc, versionId = doc?.currentVersionId) {
  const normalizedVersionId = safeText(versionId, "");
  return drawingOcrTasksForDocument(doc)
    .find((task) => task.versionId === normalizedVersionId) || null;
}

function drawingOcrPagesForTask(taskId) {
  const id = safeText(taskId, "");
  return drawingOcrPages.filter((page) => page.taskId === id).sort((left, right) => left.page - right.page);
}

function drawingOcrBlocksForTask(taskId) {
  const id = safeText(taskId, "");
  return drawingOcrBlocks.filter((block) => block.taskId === id).sort((left, right) =>
    left.page - right.page ||
    Number(left.bbox?.y || 0) - Number(right.bbox?.y || 0) ||
    Number(left.bbox?.x || 0) - Number(right.bbox?.x || 0),
  );
}

function publicDrawingOcrTask(task) {
  return task ? normalizeDrawingOcrTask(task) : null;
}

function drawingOcrStatusLabel(status) {
  return {
    queued: "排队中",
    processing: "处理中",
    indexing: "索引构建中",
    completed: "已完成",
    quality_warning: "质量警告",
    failed: "失败",
    canceled: "已取消",
  }[safeText(status, "queued")] || "排队中";
}

function drawingOcrSourceTypeLabel(sourceType) {
  return {
    native_text: "原生文字层 PDF",
    native_text_partial: "部分原生文字层",
    mixed: "混合 PDF",
    ocr: "OCR 识别",
    image_pdf: "图像 PDF",
    dwg_derivative: "DWG 转换文字层",
    unknown: "待识别",
  }[safeText(sourceType, "unknown")] || "待识别";
}

function drawingOcrZoneLabel(zoneType) {
  return {
    title: "图框标题",
    note: "技术说明",
    dimension: "尺寸标注",
    tag: "设备位号",
    table: "表格内容",
    legend: "图例",
  }[safeText(zoneType, "note")] || "技术说明";
}

function drawingOcrPositionLabel(bbox) {
  const x = Number(bbox?.x || 0);
  const y = Number(bbox?.y || 0);
  const vertical = y < 0.33 ? "上部" : y > 0.66 ? "下部" : "中部";
  const horizontal = x < 0.33 ? "左侧" : x > 0.66 ? "右侧" : "中部";
  return vertical === horizontal ? vertical : `${vertical}${horizontal}`;
}

function publicDrawingOcrDocument(doc, userContext) {
  const publicDoc = toPublicDocument(doc, userContext);
  const task = latestDrawingOcrTaskForVersion(doc, doc.currentVersionId);
  const metadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
  return {
    id: publicDoc.id,
    name: publicDoc.name,
    fileName: publicDoc.name,
    version: publicDoc.version,
    currentVersionId: publicDoc.currentVersionId,
    status: publicDoc.status,
    uploadedAt: publicDoc.uploadedAt,
    updatedAt: publicDoc.updatedAt,
    drawingMetadata: metadata,
    drawingNo: metadata.drawingNumber,
    drawingName: metadata.drawingName,
    discipline: metadata.discipline,
    ocrTask: publicDrawingOcrTask(task),
  };
}

function publicDrawingOcrDocuments(userContext) {
  return publicDocumentsForUser(userContext)
    .filter((doc) => drawingOcrDocumentCandidate(doc))
    .sort((left, right) => {
      const leftMeta = normalizeDocumentDrawingMetadata(left.drawingMetadata || {});
      const rightMeta = normalizeDocumentDrawingMetadata(right.drawingMetadata || {});
      return localeCollator("zh-CN").compare(safeText(leftMeta.drawingNumber || left.name, ""), safeText(rightMeta.drawingNumber || right.name, ""));
    })
    .map((doc) => publicDrawingOcrDocument(doc, userContext));
}

function drawingOcrSearchSummary(userContext) {
  const visibleDocs = publicDocumentsForUser(userContext);
  const pdfDocs = visibleDocs.filter((doc) => doc.mimeType === "application/pdf" || path.extname(String(doc.name || "")).toLowerCase() === ".pdf");
  const docs = pdfDocs.filter((doc) => drawingOcrDocumentCandidate(doc));
  const visibleIds = new Set(docs.map((doc) => doc.id));
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const tasks = drawingOcrTasks.filter((task) => task.projectId === projectId && visibleIds.has(task.documentId));
  return {
    pdfCount: pdfDocs.length,
    unmarkedPdfCount: Math.max(0, pdfDocs.length - docs.length),
    documentCount: docs.length,
    indexedCount: tasks.filter((task) => ["completed", "quality_warning"].includes(task.status)).length,
    queuedCount: tasks.filter((task) => ["queued", "processing", "indexing"].includes(task.status)).length,
    qualityWarningCount: tasks.filter((task) => task.status === "quality_warning").length,
    failedCount: tasks.filter((task) => task.status === "failed").length,
    blockCount: tasks.reduce((sum, task) => sum + Number(task.blockCount || 0), 0),
    lowQualityPageCount: tasks.reduce((sum, task) => sum + (Array.isArray(task.lowQualityPages) ? task.lowQualityPages.length : 0), 0),
  };
}

function drawingOcrDictionary(projectId = DEFAULT_PROJECT_ID) {
  return {
    projectId: safeText(projectId, DEFAULT_PROJECT_ID),
    categories: [
      {
        key: "pipe",
        label: "管道类",
        terms: ["DN", "NPS", "PN", "SCH", "SMLS", "ERW", "BW", "SW"],
      },
      {
        key: "equipment",
        label: "设备类",
        terms: ["RO", "UF", "MF", "NF", "MCC", "AHU", "FCU", "VFD", "UPS"],
      },
      {
        key: "material",
        label: "材质类",
        terms: ["SS", "CS", "GRP", "FRP", "HDPE", "CPVC", "PVDF", "Duplex"],
      },
      {
        key: "standard",
        label: "标准类",
        terms: ["ASME", "API", "ANSI", "EN", "ISO", "IEC", "NEMA", "IP"],
      },
      {
        key: "unit",
        label: "单位类",
        terms: ["barg", "bara", "MPa", "kPa", "m3/h", "gpm", "kW", "kVA", "RPM"],
      },
      {
        key: "tag",
        label: "位号前缀",
        terms: ["P-", "E-", "T-", "V-", "FT-", "PT-", "LT-", "AT-", "TT-"],
      },
    ],
  };
}

function buildDrawingOcrSearchPayload(userContext = SYSTEM_USER_CONTEXT) {
  const docs = publicDrawingOcrDocuments(userContext);
  const visibleIds = new Set(docs.map((doc) => doc.id));
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  return {
    documents: docs,
    tasks: drawingOcrTasks
      .filter((task) => task.projectId === projectId && visibleIds.has(task.documentId))
      .sort((left, right) => safeText(right.createdAt, "").localeCompare(safeText(left.createdAt, "")))
      .map(publicDrawingOcrTask),
    summary: drawingOcrSearchSummary(userContext),
    dictionary: drawingOcrDictionary(projectId),
    syntax: {
      modes: ["exact", "semantic"],
      examples: ["DN150", "\"High Pressure Pump\"", "P-001A AND DN150", "DN100 OR DN150", "RO NOT UF", "P-001*", "/P-\\d{3}[AB]/"],
      filters: ["discipline", "versionScope", "status", "zoneType", "qualityMin"],
    },
  };
}

function enqueueDrawingOcrTask(doc, versionEntry, userContext = SYSTEM_USER_CONTEXT, options = {}) {
  if (!doc || !versionEntry || !drawingOcrVersionCandidate(doc, versionEntry)) {
    return { task: null, job: null, reused: false };
  }
  const existing = latestDrawingOcrTaskForVersion(doc, versionEntry.id);
  if (existing && options.force !== true) {
    return {
      task: existing,
      job: jobs.find((job) => job.type === "drawing.ocr" && job.payload?.taskId === existing.id && ["queued", "running"].includes(job.status)) || null,
      reused: true,
    };
  }

  const now = new Date().toISOString();
  const metadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
  const task = normalizeDrawingOcrTask({
    id: crypto.randomUUID(),
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    documentId: doc.id,
    fileId: doc.id,
    fileName: doc.name,
    drawingNo: metadata.drawingNumber,
    drawingName: metadata.drawingName,
    discipline: metadata.discipline,
    versionId: versionEntry.id,
    versionLabel: versionEntry.version || doc.version,
    status: "queued",
    progress: 5,
    sourceType: "unknown",
    createdBy: actorDisplayName(userContext),
    createdByUserId: safeText(userContext?.user?.id, ""),
    engine: {
      nativeText: "PyMuPDF",
      ocr: "Tesseract/pytesseract when installed",
      semantic: "keyword+heuristic fallback; vector provider can replace this layer",
    },
    createdAt: now,
    updatedAt: now,
  });
  const job = normalizeJob({
    id: crypto.randomUUID(),
    type: "drawing.ocr",
    status: "queued",
    resourceType: "document",
    resourceId: doc.id,
    payload: {
      taskId: task.id,
      documentId: doc.id,
      versionId: versionEntry.id,
      actor: actorDisplayName(userContext),
      actorUserId: safeText(userContext?.user?.id, ""),
    },
    attempts: 0,
    maxAttempts: Math.max(1, Number(options.maxAttempts || CDE_BACKGROUND_JOB_MAX_ATTEMPTS) || CDE_BACKGROUND_JOB_MAX_ATTEMPTS),
    createdAt: now,
    updatedAt: now,
  });
  drawingOcrTasks.unshift(task);
  jobs.unshift(job);
  addActivity(doc, actorDisplayName(userContext), "图纸 OCR 索引排队", `${versionEntry.version || doc.version} 已加入全文索引队列`);
  persistStore();
  return { task, job, reused: false };
}

function enqueueDrawingOcrReindex(body = {}, userContext = SYSTEM_USER_CONTEXT, req = null) {
  requireAuthenticatedUser(userContext);
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const documentIds = new Set((Array.isArray(body.documentIds) ? body.documentIds : [])
    .map((item) => safeText(item, ""))
    .filter(Boolean));
  const versionIds = new Set((Array.isArray(body.versionIds) ? body.versionIds : [])
    .map((item) => safeText(item, ""))
    .filter(Boolean));
  const force = body.force !== false;
  const targetDocs = publicDocumentsForUser(userContext)
    .filter((doc) => drawingOcrDocumentCandidate(doc))
    .filter((doc) => !documentIds.size || documentIds.has(doc.id))
    .filter((doc) => safeText(doc.projectId, DEFAULT_PROJECT_ID) === projectId);
  const tasks = [];
  const jobsToSchedule = [];
  targetDocs.forEach((doc) => {
    const versions = activeVersionEntries(doc).filter((entry) => drawingOcrVersionCandidate(doc, entry));
    const selectedVersions = versionIds.size ? versions.filter((entry) => versionIds.has(entry.id)) : versions.filter((entry) => entry.id === doc.currentVersionId);
    selectedVersions.forEach((entry) => {
      const permissions = documentPermissionsForUser(doc, userContext);
      if (!permissions.preview) {
        return;
      }
      const result = enqueueDrawingOcrTask(doc, entry, userContext, { force });
      if (result.task) {
        tasks.push(publicDrawingOcrTask(result.task));
      }
      if (result.job) {
        jobsToSchedule.push(result.job);
      }
    });
  });
  appendAuditLog(userContext, "drawing_ocr.reindex", "drawing_ocr_task", tasks[0]?.id || "", {
    taskCount: tasks.length,
    documentCount: targetDocs.length,
    versionCount: versionIds.size,
  }, req);
  return {
    tasks,
    jobs: jobsToSchedule,
  };
}

function markDrawingOcrFailed(job, error) {
  const task = drawingOcrTaskById(job?.payload?.taskId);
  const doc = task ? documents.find((item) => item.id === task.documentId) : null;
  if (!task) {
    return;
  }
  task.status = "failed";
  task.progress = 100;
  task.error = safeText(error?.message, "图纸 OCR 索引失败");
  task.updatedAt = new Date().toISOString();
  if (doc) {
    addActivity(doc, safeText(job?.payload?.actor, "系统"), "图纸 OCR 索引失败", task.error);
  }
}

function markDrawingOcrRetryQueued(job, error) {
  const task = drawingOcrTaskById(job?.payload?.taskId);
  if (!task) {
    return;
  }
  task.status = "queued";
  task.progress = 5;
  task.error = safeText(error?.message, "图纸 OCR 索引失败，等待自动重试");
  task.updatedAt = new Date().toISOString();
}

async function runDrawingOcrJob(doc, task, job) {
  const versionEntry = requireVersionEntry(doc, task.versionId);
  if (!drawingOcrVersionCandidate(doc, versionEntry)) {
    const error = new Error("图纸 OCR 全文检索仅支持已声明为图纸的 PDF 版本。");
    error.statusCode = 400;
    throw error;
  }
  const storedFileName = safeText(versionEntry.storedFileName, "");
  if (!storedFileName || !(await storageService.uploads.exists(storedFileName))) {
    const error = new Error("OCR 索引缺少版本文件或对象存储不可读。");
    error.statusCode = 404;
    throw error;
  }

  task.status = "processing";
  task.progress = 24;
  task.error = "";
  task.updatedAt = new Date().toISOString();
  persistStore();

  const sourcePath = await storageService.uploads.materializeToTempPath(storedFileName);
  let payload;
  try {
    payload = await runDrawingOcrExtraction({
      sourcePath,
      options: {
        minNativeWords: 3,
        maxPages: 120,
        ocrDpi: 220,
      },
    });
  } finally {
    storageService.uploads.cleanupTempPath?.(sourcePath);
  }

  task.status = "indexing";
  task.progress = 72;
  task.updatedAt = new Date().toISOString();
  persistStore();

  const now = new Date().toISOString();
  const pages = (Array.isArray(payload.pages) ? payload.pages : []).map((page) => normalizeDrawingOcrPage({
    ...page,
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    documentId: doc.id,
    fileId: doc.id,
    versionId: versionEntry.id,
    createdAt: now,
    updatedAt: now,
  })).filter(Boolean);
  const blocks = (Array.isArray(payload.blocks) ? payload.blocks : []).map((block) => normalizeDrawingOcrBlock({
    ...block,
    id: crypto.randomUUID(),
    taskId: task.id,
    projectId: task.projectId,
    documentId: doc.id,
    fileId: doc.id,
    versionId: versionEntry.id,
    createdAt: now,
    updatedAt: now,
  })).filter(Boolean);
  const lowQualityPages = pages.filter((page) => Number(page.qualityScore || 0) < 70).map((page) => page.page);
  const warnings = pages.map((page) => safeText(page.warning, "")).filter(Boolean);
  drawingOcrPages = drawingOcrPages.filter((page) => !(page.documentId === doc.id && page.versionId === versionEntry.id));
  drawingOcrBlocks = drawingOcrBlocks.filter((block) => !(block.documentId === doc.id && block.versionId === versionEntry.id));
  drawingOcrPages.unshift(...pages);
  drawingOcrBlocks.unshift(...blocks);

  const completedAt = new Date().toISOString();
  task.sourceType = normalizeDrawingOcrSourceType(payload.sourceType, "unknown");
  task.qualityScore = Math.max(0, Math.min(100, Number(payload.qualityScore || 0) || 0));
  task.pageCount = pages.length || Number(payload.pageCount || 0) || 0;
  task.blockCount = blocks.length || Number(payload.blockCount || 0) || 0;
  task.lowQualityPages = lowQualityPages;
  task.warning = warnings.length
    ? Array.from(new Set(warnings)).slice(0, 4).join("；")
    : lowQualityPages.length
      ? `第 ${lowQualityPages.join("、")} 页 OCR 质量一般，检索结果需人工确认。`
      : "";
  task.status = (task.qualityScore < 70 || lowQualityPages.length || warnings.length) ? "quality_warning" : "completed";
  task.progress = 100;
  task.completedAt = completedAt;
  task.updatedAt = completedAt;
  task.error = "";
  touchDocument(doc);
  addActivity(
    doc,
    safeText(job?.payload?.actor, "系统"),
    task.status === "quality_warning" ? "图纸 OCR 索引完成（质量警告）" : "图纸 OCR 索引完成",
    `${versionEntry.version || doc.version} 已建立 ${task.blockCount} 个文字块索引，质量评分 ${task.qualityScore}`,
  );
  persistStore();
  return task;
}

function drawingOcrVisibleDocumentMap(userContext) {
  return new Map(publicDocumentsForUser(userContext).map((doc) => [doc.id, doc]));
}

function normalizeOcrSearchMode(value) {
  return ["exact", "semantic"].includes(safeText(value, "exact")) ? safeText(value, "exact") : "exact";
}

function normalizeOcrSearchFilters(filters = {}) {
  const value = filters && typeof filters === "object" ? filters : {};
  return {
    discipline: safeText(value.discipline, "all") || "all",
    versionScope: ["current", "all"].includes(safeText(value.versionScope, "current")) ? safeText(value.versionScope, "current") : "current",
    status: safeText(value.status, "all") || "all",
    zoneType: ["all", "title", "note", "dimension", "tag", "table", "legend"].includes(safeText(value.zoneType, "all")) ? safeText(value.zoneType, "all") : "all",
    qualityMin: Math.max(0, Math.min(100, Number(value.qualityMin ?? 0) || 0)),
  };
}

function stripOcrQueryQuotes(value) {
  const textValue = safeText(value, "");
  if ((textValue.startsWith("\"") && textValue.endsWith("\"")) || (textValue.startsWith("'") && textValue.endsWith("'"))) {
    return textValue.slice(1, -1);
  }
  return textValue;
}

function parseDrawingOcrQuery(rawQuery, mode = "exact") {
  const query = safeText(rawQuery, "").trim();
  const parsed = {
    raw: query,
    mode: normalizeOcrSearchMode(mode),
    includeAll: [],
    includeAny: [],
    exclude: [],
    regex: [],
    semanticExpandedTerms: [],
  };
  if (!query) {
    return parsed;
  }

  if (parsed.mode === "semantic") {
    parsed.semanticExpandedTerms = expandDrawingOcrSemanticTerms(query);
    parsed.includeAny = parsed.semanticExpandedTerms.length ? parsed.semanticExpandedTerms : [query];
    return parsed;
  }

  let working = query;
  const regexMatches = Array.from(working.matchAll(/\/([^/\n]+)\//g));
  regexMatches.forEach((match) => {
    if (match[1]) {
      parsed.regex.push(match[1]);
    }
  });
  working = working.replace(/\/([^/\n]+)\//g, " ");

  const phraseMatches = Array.from(working.matchAll(/"([^"]+)"/g));
  phraseMatches.forEach((match) => {
    if (match[1]) {
      parsed.includeAll.push(match[1]);
    }
  });
  working = working.replace(/"([^"]+)"/g, " ");

  working = working.replace(/\bNOT\s+([^\s]+)/gi, (_, term) => {
    parsed.exclude.push(stripOcrQueryQuotes(term));
    return " ";
  });

  if (/\s+OR\s+/i.test(working)) {
    parsed.includeAny.push(...working.split(/\s+OR\s+/i).map((item) => safeText(item, "")).filter(Boolean));
  } else {
    parsed.includeAll.push(...working.split(/\s+AND\s+|\s+/i).map((item) => safeText(item, "")).filter(Boolean));
  }
  parsed.includeAll = Array.from(new Set(parsed.includeAll.map(stripOcrQueryQuotes).filter(Boolean)));
  parsed.includeAny = Array.from(new Set(parsed.includeAny.map(stripOcrQueryQuotes).filter(Boolean)));
  parsed.exclude = Array.from(new Set(parsed.exclude.map(stripOcrQueryQuotes).filter(Boolean)));
  return parsed;
}

function expandDrawingOcrSemanticTerms(query) {
  const normalized = normalizeSearchText(query);
  const terms = new Set();
  const add = (items) => items.forEach((item) => terms.add(item));
  if (/泵|pump/.test(normalized)) add(["pump", "p-", "泵"]);
  if (/高压|high\s*pressure|hp/.test(normalized)) add(["high pressure", "hp", "高压"]);
  if (/管|管线|pipe|pipeline/.test(normalized)) add(["dn", "pn", "pipe", "管线"]);
  if (/ro|反渗透/.test(normalized)) add(["ro", "reverse osmosis", "反渗透"]);
  if (/加药|chemical|dosing/.test(normalized)) add(["chemical", "dosing", "加药"]);
  if (/电|mcc|vfd|ups/.test(normalized)) add(["mcc", "vfd", "ups", "电气"]);
  normalized.split(/\s+/).filter((item) => item.length > 1 && !["相关", "图纸", "文件", "查找", "涉及"].includes(item)).forEach((item) => terms.add(item));
  return Array.from(terms);
}

function drawingOcrClauseMatchesText(clause, textValue) {
  const normalizedText = normalizeSearchText(textValue);
  const rawClause = safeText(clause, "");
  if (!rawClause) {
    return false;
  }
  if (rawClause.includes("*")) {
    const pattern = rawClause
      .split("*")
      .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
      .join(".*");
    try {
      return new RegExp(pattern, "i").test(textValue);
    } catch {
      return normalizedText.includes(normalizeSearchText(rawClause.replace(/\*/g, "")));
    }
  }
  return normalizedText.includes(normalizeSearchText(rawClause));
}

function drawingOcrRegexMatchesText(pattern, textValue) {
  try {
    return new RegExp(pattern, "i").test(textValue);
  } catch {
    return false;
  }
}

function drawingOcrGroupMatchesQuery(groupText, parsed) {
  if (!parsed.raw) {
    return true;
  }
  if (parsed.exclude.some((term) => drawingOcrClauseMatchesText(term, groupText))) {
    return false;
  }
  if (parsed.regex.length && !parsed.regex.some((pattern) => drawingOcrRegexMatchesText(pattern, groupText))) {
    return false;
  }
  if (parsed.includeAll.length && !parsed.includeAll.every((term) => drawingOcrClauseMatchesText(term, groupText))) {
    return false;
  }
  if (parsed.includeAny.length && !parsed.includeAny.some((term) => drawingOcrClauseMatchesText(term, groupText))) {
    return false;
  }
  return Boolean(parsed.regex.length || parsed.includeAll.length || parsed.includeAny.length || !parsed.raw);
}

function drawingOcrBlockMatchesQuery(block, parsed) {
  const textValue = safeText(block?.text, "");
  if (!parsed.raw) {
    return true;
  }
  if (parsed.exclude.some((term) => drawingOcrClauseMatchesText(term, textValue))) {
    return false;
  }
  if (parsed.regex.some((pattern) => drawingOcrRegexMatchesText(pattern, textValue))) {
    return true;
  }
  const terms = [...parsed.includeAll, ...parsed.includeAny];
  return terms.some((term) => drawingOcrClauseMatchesText(term, textValue));
}

function drawingOcrContextForBlock(block, pageText) {
  const textValue = safeText(block?.text, "");
  const fullText = safeText(pageText, "");
  if (!textValue || !fullText) {
    return textValue;
  }
  const normalizedFull = normalizeSearchText(fullText);
  const normalizedNeedle = normalizeSearchText(textValue);
  const index = normalizedFull.indexOf(normalizedNeedle);
  if (index < 0) {
    return textValue;
  }
  const start = Math.max(0, index - 30);
  const end = Math.min(fullText.length, index + textValue.length + 30);
  return fullText.slice(start, end).trim();
}

function drawingOcrScoreForBlock(block, doc, parsed) {
  const zoneWeight = {
    tag: 3.2,
    dimension: 2.7,
    title: 2.2,
    table: 1.8,
    legend: 1.5,
    note: 1.2,
  }[block.zoneType] || 1;
  const confidence = Math.max(0.2, Number(block.confidence || 0.8));
  const quality = Math.max(0.3, Number(block.qualityScore || 70) / 100);
  const statusWeight = doc.status === "approved" ? 1.15 : doc.status === "reviewing" ? 1.05 : 1;
  const queryBoost = parsed.mode === "semantic" ? 0.85 : 1;
  return Number((zoneWeight * confidence * quality * statusWeight * queryBoost).toFixed(4));
}

function drawingOcrMatchId(blockId) {
  return `ocrm_${safeText(blockId, "")}`;
}

function buildPublicDrawingOcrMatch(block, page, doc, task, parsed, score = 0) {
  const context = drawingOcrContextForBlock(block, page?.text || block.text);
  return {
    id: drawingOcrMatchId(block.id),
    blockId: block.id,
    taskId: block.taskId,
    documentId: block.documentId,
    versionId: block.versionId,
    versionLabel: task?.versionLabel || doc?.version || "",
    page: block.page,
    text: block.text,
    context,
    bbox: block.bbox,
    zoneType: block.zoneType,
    zoneLabel: drawingOcrZoneLabel(block.zoneType),
    positionLabel: drawingOcrPositionLabel(block.bbox),
    confidence: block.confidence,
    qualityScore: block.qualityScore,
    score,
    queryMode: parsed?.mode || "exact",
  };
}

function queryDrawingOcrSearch(body = {}, userContext = SYSTEM_USER_CONTEXT, req = null) {
  const query = safeText(body.query, "").trim();
  if (!query) {
    const error = new Error("请输入图纸内容检索关键词。");
    error.statusCode = 400;
    throw error;
  }
  const mode = normalizeOcrSearchMode(body.mode);
  const parsed = parseDrawingOcrQuery(query, mode);
  const filters = normalizeOcrSearchFilters(body.filters || {});
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const visibleDocs = drawingOcrVisibleDocumentMap(userContext);
  const groups = new Map();
  drawingOcrBlocks.forEach((block) => {
    if (block.projectId !== projectId || !visibleDocs.has(block.documentId)) {
      return;
    }
    const doc = visibleDocs.get(block.documentId);
    const metadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
    if (filters.discipline !== "all" && metadata.discipline !== filters.discipline) {
      return;
    }
    if (filters.status !== "all" && safeText(doc.status, "uploaded") !== filters.status) {
      return;
    }
    if (filters.versionScope === "current" && block.versionId !== doc.currentVersionId) {
      return;
    }
    if (filters.zoneType !== "all" && block.zoneType !== filters.zoneType) {
      return;
    }
    if (Number(block.qualityScore || 0) < filters.qualityMin) {
      return;
    }
    const task = drawingOcrTaskById(block.taskId);
    if (!task || !["completed", "quality_warning"].includes(task.status)) {
      return;
    }
    const key = `${block.documentId}:${block.versionId}:${block.taskId}`;
    if (!groups.has(key)) {
      groups.set(key, {
        doc,
        task,
        blocks: [],
        pages: drawingOcrPagesForTask(block.taskId),
      });
    }
    groups.get(key).blocks.push(block);
  });

  const results = [];
  groups.forEach((group) => {
    const pageText = group.pages.map((page) => page.text).join(" ");
    const blockText = group.blocks.map((block) => block.text).join(" ");
    const groupText = `${pageText} ${blockText}`;
    if (!drawingOcrGroupMatchesQuery(groupText, parsed)) {
      return;
    }
    const pagesByNumber = new Map(group.pages.map((page) => [page.page, page]));
    let matchedBlocks = group.blocks.filter((block) => drawingOcrBlockMatchesQuery(block, parsed));
    if (!matchedBlocks.length) {
      matchedBlocks = group.blocks.slice(0, 5);
    }
    const matches = matchedBlocks
      .slice(0, 24)
      .map((block) => {
        const score = drawingOcrScoreForBlock(block, group.doc, parsed);
        return buildPublicDrawingOcrMatch(block, pagesByNumber.get(block.page), group.doc, group.task, parsed, score);
      })
      .sort((left, right) => right.score - left.score || left.page - right.page);
    const metadata = normalizeDocumentDrawingMetadata(group.doc.drawingMetadata || {});
    const totalScore = matches.reduce((sum, item) => sum + Number(item.score || 0), 0);
    results.push({
      documentId: group.doc.id,
      fileName: group.doc.name,
      drawingNo: metadata.drawingNumber,
      drawingName: metadata.drawingName,
      discipline: metadata.discipline,
      versionId: group.task.versionId,
      versionLabel: group.task.versionLabel,
      approvalStatus: group.doc.status,
      taskId: group.task.id,
      taskStatus: group.task.status,
      sourceType: group.task.sourceType,
      qualityScore: group.task.qualityScore,
      matchCount: matches.length,
      pages: Array.from(new Set(matches.map((match) => match.page))).sort((left, right) => left - right),
      score: Number(totalScore.toFixed(4)),
      matches,
    });
  });
  results.sort((left, right) => right.score - left.score || localeCollator("zh-CN").compare(safeText(left.drawingNo || left.fileName, ""), safeText(right.drawingNo || right.fileName, "")));
  appendAuditLog(userContext, "drawing_ocr.search", "drawing_ocr_index", "", {
    query,
    mode,
    resultCount: results.length,
  }, req);
  return {
    query,
    mode,
    filters,
    parsed,
    total: results.length,
    matchTotal: results.reduce((sum, item) => sum + Number(item.matchCount || 0), 0),
    results,
    suggestions: drawingOcrSearchSuggestions(query, results),
  };
}

function drawingOcrSearchSuggestions(query, results) {
  const values = new Set();
  results.slice(0, 8).forEach((result) => {
    (result.matches || []).forEach((match) => {
      const tag = safeText(match.text, "").match(/\b(P|E|T|V|FT|PT|LT|AT|TT)-\d{2,5}[A-Z]?\b/i)?.[0];
      if (tag) values.add(tag.toUpperCase());
      const dimension = safeText(match.text, "").match(/\b(DN|NPS|PN|SCH)\s*[-.]?\s*\d+\b/i)?.[0];
      if (dimension) values.add(dimension.toUpperCase().replace(/\s+/g, ""));
    });
  });
  if (!values.size && /泵|pump/i.test(query)) {
    values.add("P-001A");
    values.add("High Pressure Pump");
  }
  return Array.from(values).slice(0, 8);
}

function drawingOcrBlockFromMatchId(matchId) {
  const id = safeText(matchId, "").replace(/^ocrm_/, "");
  return drawingOcrBlocks.find((block) => block.id === id) || null;
}

async function createIssueFromDrawingOcrMatch(matchId, body = {}, userContext = SYSTEM_USER_CONTEXT) {
  const block = drawingOcrBlockFromMatchId(matchId);
  if (!block) {
    const error = new Error("OCR 检索结果不存在或索引已更新，请重新检索后再创建 Issue。");
    error.statusCode = 404;
    throw error;
  }
  const doc = requireDocument(block.documentId, userContext);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview) {
    throw permissionDeniedError("你没有查看该图纸 OCR 检索结果的权限。");
  }
  if (!permissions.annotations.create) {
    throw permissionDeniedError("你没有从 OCR 检索结果创建 Issue 的权限。");
  }
  const task = drawingOcrTaskById(block.taskId);
  const page = drawingOcrPagesForTask(block.taskId).find((item) => item.page === block.page) || null;
  const noteParts = [
    `检索文字：${block.text}`,
    `图纸：${doc.name}`,
    `版本：${task?.versionLabel || doc.version}`,
    `页码：P${block.page}`,
    `区域：${drawingOcrZoneLabel(block.zoneType)} · ${drawingOcrPositionLabel(block.bbox)}`,
    `坐标：x=${Math.round(block.bbox.x * 100)}%, y=${Math.round(block.bbox.y * 100)}%, w=${Math.round(block.bbox.width * 100)}%, h=${Math.round(block.bbox.height * 100)}%`,
    `上下文：${drawingOcrContextForBlock(block, page?.text || block.text)}`,
    body.note ? `补充说明：${safeText(body.note, "")}` : "",
  ].filter(Boolean);
  const annotation = await createAnnotation({
    type: "mark",
    variant: "ocr-search",
    page: block.page,
    x: block.bbox.x,
    y: block.bbox.y,
    width: block.bbox.width,
    height: block.bbox.height,
    title: safeText(body.title, `OCR 检索复核：${block.text}`),
    note: noteParts.join("\n"),
    actor: actorDisplayName(userContext),
    color: "#f1a208",
    status: "open",
    source: "drawing_ocr_search",
  }, block.versionId || doc.currentVersionId, {
    boundModelVersion: task?.versionLabel || doc.version,
  });
  annotation.ocrTaskId = block.taskId;
  annotation.ocrBlockId = block.id;
  annotation.ocrSearchText = block.text;
  annotation.source = "drawing_ocr_search";
  doc.annotations.unshift(normalizeAnnotation(annotation, block.versionId || doc.currentVersionId));
  touchDocument(doc);
  addActivity(doc, actorDisplayName(userContext), "OCR 检索转 Issue", `${block.text} 已创建审阅 Issue`);
  persistStore();
  await bestEffortProjectEmailNotification("annotationCreated", {
    document: doc,
    annotation,
    userContext,
    occurredAt: annotation.createdAt,
  });
  return {
    match: buildPublicDrawingOcrMatch(block, page, doc, task, { mode: "exact" }, drawingOcrScoreForBlock(block, doc, { mode: "exact" })),
    issue: normalizeAnnotation(annotation, block.versionId || doc.currentVersionId),
    document: toPublicDocument(doc, userContext),
  };
}

function notificationReadSignature(entry) {
  return `${safeText(entry?.userId, "")}:${safeText(entry?.projectId, DEFAULT_PROJECT_ID)}:${safeText(entry?.key, "")}`;
}

function pruneNotificationReads() {
  const deduped = [];
  const seen = new Set();
  const sorted = [...notificationReads].sort((left, right) => String(right.readAt || "").localeCompare(String(left.readAt || "")));
  sorted.forEach((entry) => {
    const normalized = normalizeNotificationRead(entry);
    if (!normalized) {
      return;
    }
    const signature = notificationReadSignature(normalized);
    if (!signature || seen.has(signature)) {
      return;
    }
    seen.add(signature);
    deduped.push(normalized);
  });
  notificationReads = deduped.slice(0, NOTIFICATION_READ_RETENTION_LIMIT);
}

function notificationReadKeySetForUser(userContext) {
  const userId = safeText(userContext?.user?.id, "");
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  return new Set(
    notificationReads
      .filter((entry) => safeText(entry?.userId, "") === userId && safeText(entry?.projectId, DEFAULT_PROJECT_ID) === projectId)
      .map((entry) => safeText(entry?.key, ""))
      .filter(Boolean),
  );
}

function workflowNotificationRelevantForUser(workflow, userContext) {
  if (!workflow) {
    return false;
  }
  if (isProjectAdminRole(safeText(userContext?.projectRole, "guest")) || isSuperAdmin(userContext)) {
    return true;
  }
  const actorName = actorDisplayName(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  if (
    safeText(workflow.initiator, "") === actorName ||
    (actorUserId && safeText(workflow.initiatorUserId, "") === actorUserId)
  ) {
    return true;
  }
  return (workflow.steps || []).some((step) =>
    (step.reviewers || []).some(
      (reviewer) =>
        safeText(reviewer?.name, "") === actorName ||
        (actorUserId && safeText(reviewer?.userId, "") === actorUserId),
    ),
  );
}

function documentNotificationRelevantForUser(doc, userContext) {
  if (!doc?.permissions?.visible) {
    return false;
  }
  if (isProjectAdminRole(safeText(userContext?.projectRole, "guest")) || isSuperAdmin(userContext)) {
    return true;
  }
  const actorName = actorDisplayName(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  return (
    [doc.initiator, doc.reviewer, doc.approver, doc.owner, doc.uploader].some((value) => safeText(value, "") === actorName) ||
    (actorUserId && safeText(doc.uploaderId, "") === actorUserId)
  );
}

function notificationToneForLabel(label) {
  if (["退回发起者", "驳回修改", "APS 转换失败", "生成 CRS 草稿失败"].includes(label)) {
    return "alert";
  }
  if (["批准归档", "导出文件", "自动导出", "APS 转换完成", "处理批注", "确认 CRS 草稿"].includes(label)) {
    return "success";
  }
  return "info";
}

function workflowTodoComparator(left, right) {
  const leftDue = safeText(left?.dueDate, "9999-12-31");
  const rightDue = safeText(right?.dueDate, "9999-12-31");
  if (leftDue !== rightDue) {
    return leftDue.localeCompare(rightDue);
  }
  return String(right?.updatedAt || "").localeCompare(String(left?.updatedAt || ""));
}

function buildNotificationTodoItems(userContext, workflowList = publicWorkflowsForUser(userContext)) {
  return workflowList
    .filter((workflow) => workflow?.status === "running" && workflow?.permissions?.run)
    .map((workflow) => {
      const currentStep = workflow.currentStep || null;
      const fileCount = Array.isArray(workflow.fileRefs) ? workflow.fileRefs.length : 0;
      const primaryRef = workflow.fileRefs?.[0] || null;
      const assignees = workflowStepPendingReviewerNames(currentStep);
      return {
        key: `todo:${workflow.id}:${safeText(currentStep?.id, "current")}@${safeText(workflow.updatedAt, workflow.createdAt)}`,
        workflowId: workflow.id,
        documentId: safeText(primaryRef?.docId, ""),
        title: safeText(workflow.workflowName, "未命名流程"),
        subject: fileCount === 1 ? safeText(primaryRef?.name, "当前文件") : `${fileCount} 个文件`,
        stepName: safeText(currentStep?.name, "当前节点"),
        assignees,
        note: assignees.length ? `待 ${assignees.join(" / ")} 处理` : "当前节点待处理",
        updatedAt: safeText(workflow.updatedAt, workflow.createdAt),
        dueDate: safeText(workflow.dueDate, ""),
        fileCount,
        action: fileCount === 1 ? "openWorkflowReview" : "openWorkflow",
      };
    })
    .sort(workflowTodoComparator);
}

function buildWorkflowNotificationItems(userContext, readSet, workflowList = publicWorkflowsForUser(userContext)) {
  return workflowList
    .filter((workflow) => workflowNotificationRelevantForUser(workflow, userContext))
    .flatMap((workflow) => {
      const fileCount = Array.isArray(workflow.fileRefs) ? workflow.fileRefs.length : 0;
      const primaryRef = workflow.fileRefs?.[0] || null;
      return (workflow.activity || []).map((item) => {
        const key = `workflow:${workflow.id}:activity:${safeText(item?.id, "")}`;
        return {
          key,
          source: "workflow",
          workflowId: workflow.id,
          documentId: safeText(primaryRef?.docId, ""),
          title: safeText(workflow.workflowName, "未命名流程"),
          subject: fileCount === 1 ? safeText(primaryRef?.name, "当前文件") : `${fileCount} 个文件`,
          label: safeText(item?.label, "流程更新"),
          note: safeText(item?.note, ""),
          actor: safeText(item?.actor, "系统"),
          timestamp: safeText(item?.timestamp, workflow.updatedAt),
          tone: notificationToneForLabel(safeText(item?.label, "")),
          read: readSet.has(key),
          action: fileCount === 1 ? "openWorkflowReview" : "openWorkflow",
        };
      });
    });
}

function buildDocumentNotificationItems(userContext, readSet, documentList = publicDocumentsForUser(userContext)) {
  return documentList
    .filter((doc) => documentNotificationRelevantForUser(doc, userContext))
    .flatMap((doc) =>
      (doc.activity || [])
        .filter((item) => DOCUMENT_NOTIFICATION_LABELS.has(safeText(item?.label, "")))
        .map((item) => {
          const key = `document:${doc.id}:activity:${safeText(item?.id, "")}`;
          return {
            key,
            source: "document",
            workflowId: safeText(doc.activeWorkflowId, ""),
            documentId: doc.id,
            title: safeText(doc.name, "未命名文件"),
            subject: safeText(doc.version, ""),
            label: safeText(item?.label, "文件更新"),
            note: safeText(item?.note, ""),
            actor: safeText(item?.actor, "系统"),
            timestamp: safeText(item?.timestamp, doc.updatedAt),
            tone: notificationToneForLabel(safeText(item?.label, "")),
            read: readSet.has(key),
            action: "openDocument",
          };
        }),
    );
}

function buildInviteNotificationItems(userContext, readSet) {
  if (!isProjectAdminRole(safeText(userContext?.projectRole, "guest")) && !isSuperAdmin(userContext)) {
    return [];
  }

  return pendingProjectInvites(safeText(userContext?.projectId, DEFAULT_PROJECT_ID))
    .map((inviteMember) => {
      const inviteUser = userById(inviteMember.userId);
      if (!inviteUser) {
        return null;
      }
      const roleLabel = projectRoleLabel(safeText(inviteMember.role, "guest"));
      const key = `invite:${inviteMember.id}:${safeText(inviteMember.invitedAt, "")}`;
      return {
        key,
        source: "invite",
        workflowId: "",
        documentId: "",
        title: safeText(inviteUser.name, safeText(inviteUser.email, "待接受邀请")),
        subject: safeText(inviteUser.email, ""),
        label: "成员邀请",
        note: `${roleLabel} 邀请已发出，等待对方完成密码设置并加入项目。`,
        actor: userById(inviteMember.invitedBy)?.name || safeText(inviteMember.invitedBy, "系统"),
        timestamp: safeText(inviteMember.invitedAt, new Date().toISOString()),
        tone: "info",
        read: readSet.has(key),
        action: "openAccessMembers",
      };
    })
    .filter(Boolean);
}

function buildNotificationCenterPayload(userContext, source = {}) {
  if (!userContext?.user?.id) {
    return {
      todos: [],
      notifications: [],
      todoCount: 0,
      notificationCount: 0,
      unreadCount: 0,
      badgeCount: 0,
    };
  }

  const visibleDocuments = Array.isArray(source.documents) ? source.documents : publicDocumentsForUser(userContext);
  const visibleWorkflows = Array.isArray(source.workflows) ? source.workflows : publicWorkflowsForUser(userContext);
  const readSet = notificationReadKeySetForUser(userContext);
  const todos = buildNotificationTodoItems(userContext, visibleWorkflows);
  const notifications = [
    ...buildInviteNotificationItems(userContext, readSet),
    ...buildWorkflowNotificationItems(userContext, readSet, visibleWorkflows),
    ...buildDocumentNotificationItems(userContext, readSet, visibleDocuments),
  ]
    .sort((left, right) => String(right.timestamp || "").localeCompare(String(left.timestamp || "")));
  const unreadCount = notifications.reduce((count, item) => count + (item.read ? 0 : 1), 0);
  return {
    todos: todos.slice(0, NOTIFICATION_TODO_LIMIT),
    notifications: notifications.slice(0, NOTIFICATION_FEED_LIMIT),
    todoCount: todos.length,
    notificationCount: notifications.length,
    unreadCount,
    badgeCount: todos.length + unreadCount,
  };
}

function markNotificationItemsRead(userContext, keys = []) {
  const normalizedKeys = [...new Set((Array.isArray(keys) ? keys : []).map((item) => safeText(item, "")).filter(Boolean))];
  if (!normalizedKeys.length) {
    return buildNotificationCenterPayload(userContext);
  }

  const currentCenter = buildNotificationCenterPayload(userContext);
  const allowedKeys = new Set((currentCenter.notifications || []).map((item) => safeText(item?.key, "")).filter(Boolean));
  const userId = safeText(userContext?.user?.id, "");
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  let mutated = false;

  normalizedKeys.forEach((key) => {
    if (!allowedKeys.has(key)) {
      return;
    }
    const exists = notificationReads.some(
      (entry) =>
        safeText(entry?.userId, "") === userId &&
        safeText(entry?.projectId, DEFAULT_PROJECT_ID) === projectId &&
        safeText(entry?.key, "") === key,
    );
    if (exists) {
      return;
    }
    notificationReads.unshift(
      normalizeNotificationRead({
        userId,
        projectId,
        key,
        readAt: new Date().toISOString(),
      }),
    );
    mutated = true;
  });

  if (mutated) {
    pruneNotificationReads();
    persistStore();
  }

  return buildNotificationCenterPayload(userContext);
}

function activeProjectMemberByUserId(userId, projectId = DEFAULT_PROJECT_ID) {
  return projectMembers.find(
    (item) =>
      item.projectId === projectId &&
      item.userId === userId &&
      !safeText(item.removedAt, "") &&
      safeText(userById(item.userId)?.status, "active") === "active",
  ) || null;
}

function activeProjectMembers(projectId = DEFAULT_PROJECT_ID) {
  return projectMembers.filter(
    (item) =>
      item.projectId === projectId &&
      !safeText(item.removedAt, "") &&
      safeText(userById(item.userId)?.status, "active") === "active",
  );
}

function pendingProjectInvites(projectId = DEFAULT_PROJECT_ID) {
  return projectMembers.filter(
    (item) =>
      item.projectId === projectId &&
      !safeText(item.removedAt, "") &&
      safeText(item.inviteToken, "") &&
      safeText(userById(item.userId)?.status, "") === "invited",
  );
}

function memberInviteStatus(member) {
  const expiresAt = safeText(member?.inviteExpiresAt, "");
  if (!expiresAt) {
    return "pending";
  }
  return new Date(expiresAt).getTime() < Date.now() ? "expired" : "pending";
}

function appBaseUrl(req = null) {
  if (CDE_PUBLIC_BASE_URL) {
    return CDE_PUBLIC_BASE_URL;
  }
  if (ONLYOFFICE_PUBLIC_BASE_URL) {
    return ONLYOFFICE_PUBLIC_BASE_URL;
  }
  const host = safeText(req?.headers?.host, "");
  if (!host) {
    return "";
  }
  const forwardedProto = safeText(req?.headers?.["x-forwarded-proto"], "").split(",")[0].trim();
  const protocol = forwardedProto || (req?.socket?.encrypted ? "https" : "http");
  return normalizeExternalUrl(`${protocol}://${host}`);
}

function inviteLinkForRequest(req, member) {
  const baseUrl = appBaseUrl(req);
  return `${baseUrl}/invite.html?invite=${encodeURIComponent(safeText(member?.inviteToken, ""))}`;
}

function actorDisplayName(userContext = SYSTEM_USER_CONTEXT) {
  return safeText(userContext?.user?.name, "系统");
}

function isProjectAdminRole(role) {
  return ["super_admin", "project_admin"].includes(role);
}

function isSuperAdmin(userContext) {
  return Boolean(userContext?.isSuperAdmin || userContext?.projectRole === "super_admin");
}

function isWorkflowStarterRole(role) {
  return WORKFLOW_STARTER_ROLE_VALUES.has(normalizeProjectRole(role, "guest"));
}

function isWorkflowApproverRole(role) {
  return WORKFLOW_APPROVER_ROLE_VALUES.has(normalizeProjectRole(role, "guest"));
}

function workflowTemplateDefaultStarterRoles() {
  return Array.from(WORKFLOW_STARTER_ROLE_VALUES);
}

function workflowTemplateRoleValueFromInput(value) {
  return workflowTemplateRoleFromValue(value) || normalizeProjectRole(value, "");
}

function permissionRank(level) {
  return FOLDER_PERMISSION_RANK[level] ?? 0;
}

function rankToPermissionLevel(rank) {
  return (
    Object.entries(FOLDER_PERMISSION_RANK).find(([, value]) => value === rank)?.[0] || "none"
  );
}

function minPermissionLevel(left, right) {
  return rankToPermissionLevel(Math.min(permissionRank(left), permissionRank(right)));
}

function projectRoleFileLevel(role = "guest") {
  return ROLE_FILE_PERMISSION[role] || "viewer";
}

function folderByIdOrNull(folderId) {
  if (!folderId) {
    return null;
  }
  return folders.find((item) => item.id === folderId) || null;
}

function folderPathIds(folderId) {
  const ids = [];
  let cursor = folderByIdOrNull(folderId);
  while (cursor) {
    ids.push(cursor.id);
    cursor = folderByIdOrNull(cursor.parentId);
  }
  return ids;
}

function folderPermissionOverride(folderId, userId, projectId = DEFAULT_PROJECT_ID) {
  const pathIds = folderPathIds(folderId);
  for (const id of pathIds) {
    const record = folderPermissions.find(
      (item) => item.projectId === projectId && item.folderId === id && item.userId === userId,
    );
    if (record) {
      return record;
    }
  }
  return null;
}

function isPublishFolderId(folderId) {
  if (!folderId) {
    return false;
  }
  const folder = folderByIdOrNull(folderId);
  if (!folder) {
    return false;
  }
  if (String(folder.name || "").trim().toUpperCase() === "03 PUBLISH") {
    return true;
  }
  return isPublishFolderId(folder.parentId);
}

function folderFilePermissionLevel(folderId, userContext) {
  if (isSuperAdmin(userContext)) {
    return "admin";
  }

  const role = safeText(userContext?.projectRole, "guest");
  const member = userContext?.member;
  if (!member) {
    return "none";
  }

  const baseLevel = projectRoleFileLevel(role);
  const override = folderPermissionOverride(folderId, member.userId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  return override ? minPermissionLevel(baseLevel, override.permission) : baseLevel;
}

function isWorkflowParticipant(doc, actorName) {
  const name = safeText(actorName, "");
  if (!name) {
    return false;
  }
  return [doc.initiator, doc.reviewer, doc.approver].some((item) => safeText(item, "") === name);
}

function isDocumentOwner(doc, userContext) {
  const name = actorDisplayName(userContext);
  return [doc.owner, doc.uploader, doc.initiator].some((item) => safeText(item, "") === name);
}

function isAnnotationOwner(annotation, userContext) {
  return safeText(annotation?.actor, "") === actorDisplayName(userContext);
}

function isReplyOwner(reply, userContext) {
  return safeText(reply?.actor, "") === actorDisplayName(userContext);
}

function isApprovalLocked(doc) {
  return ["in_review", "final_review"].includes(safeText(doc?.status, ""));
}

function canDownloadDocumentForUser(doc, userContext, fileLevel) {
  const project = userContext?.project || projectById(userContext?.projectId) || seedDefaultProject();
  const role = safeText(userContext?.projectRole, "guest");
  if (permissionRank(fileLevel) < permissionRank("viewer")) {
    return false;
  }
  if (isProjectAdminRole(role)) {
    return true;
  }
  if (doc.downloadScope === "admins") {
    return false;
  }
  if (role === "guest") {
    if (!project.guestPolicy.canDownload) {
      return false;
    }
    return doc.downloadScope !== "restricted";
  }
  return true;
}

function buildProjectPermissionProfile(userContext) {
  const role = safeText(userContext?.projectRole, "guest");
  const project = userContext?.project || projectById(userContext?.projectId) || null;
  const guestPolicy = project?.guestPolicy || {};
  return {
    role,
    label: projectRoleLabel(role),
    manageMembers: isProjectAdminRole(role),
    setFolderPermissions: isProjectAdminRole(role),
    viewAuditLogs: isProjectAdminRole(role),
    manageGuestPolicy: isProjectAdminRole(role),
    manageEmailChannel: Boolean(userContext?.isSuperAdmin),
    manageAiSettings: Boolean(userContext?.isSuperAdmin),
    manageApsSettings: Boolean(userContext?.isSuperAdmin),
    manageProjectNotifications: isProjectAdminRole(role),
    manageProjects: Boolean(userContext?.isSuperAdmin),
    createProject: Boolean(userContext?.isSuperAdmin),
    startWorkflow: isWorkflowStarterRole(role),
    manageWorkflowTemplates: isProjectAdminRole(role),
    exportWorkflow: isProjectAdminRole(role),
    createAnnotation:
      ["super_admin", "project_admin", "reviewer", "editor"].includes(role) ||
      (role === "guest" && Boolean(guestPolicy.canAnnotate)),
    replyAnnotation:
      ["super_admin", "project_admin", "reviewer", "editor"].includes(role) ||
      (role === "guest" && Boolean(guestPolicy.canReply)),
    changeAnnotationStatus: ["super_admin", "project_admin", "reviewer", "editor"].includes(role),
    deleteOthersAnnotation: isProjectAdminRole(role),
    exportReview: ["super_admin", "project_admin", "reviewer"].includes(role),
    createIssue: ["super_admin", "project_admin", "reviewer", "editor"].includes(role),
    assignIssue: ["super_admin", "project_admin", "reviewer", "editor"].includes(role),
    closeIssue: ["super_admin", "project_admin", "reviewer", "editor"].includes(role),
  };
}

function normalizeSmtpEncryption(value, fallback = "starttls") {
  return SMTP_ENCRYPTION_ORDER.includes(String(value || "").trim()) ? String(value || "").trim() : fallback;
}

function normalizeEmailDigestMode(value, fallback = "immediate") {
  return EMAIL_DIGEST_MODE_ORDER.includes(String(value || "").trim()) ? String(value || "").trim() : fallback;
}

function normalizeEmailNotificationBooleanMap(value, keys, fallbackFactory) {
  const source = value && typeof value === "object" ? value : {};
  const fallback = typeof fallbackFactory === "function" ? fallbackFactory() : {};
  return keys.reduce((result, key) => {
    result[key] = source[key] !== undefined ? Boolean(source[key]) : Boolean(fallback[key]);
    return result;
  }, {});
}

function normalizeSystemEmailSettings(settings) {
  const value = settings && typeof settings === "object" ? settings : {};
  const encryption = normalizeSmtpEncryption(value.encryption, normalizeSmtpEncryption(DEFAULT_SMTP_ENCRYPTION, "starttls"));
  const port = Number(value.port || 0) > 0 ? Number(value.port) : DEFAULT_SMTP_PORT || (encryption === "ssl_tls" ? 465 : 587);
  return {
    id: safeText(value.id, "system-email-default"),
    enabled: value.enabled !== undefined ? Boolean(value.enabled) : false,
    provider: "smtp",
    host: safeText(value.host, DEFAULT_SMTP_HOST),
    port: Math.max(1, Math.min(65535, Math.round(port))),
    encryption,
    authRequired: value.authRequired !== undefined ? Boolean(value.authRequired) : DEFAULT_SMTP_AUTH_REQUIRED,
    username: safeText(value.username, DEFAULT_SMTP_USERNAME),
    password: safeText(value.password, DEFAULT_SMTP_PASSWORD),
    senderName: safeText(value.senderName, DEFAULT_SMTP_SENDER_NAME),
    senderEmail: normalizeEmail(value.senderEmail) || DEFAULT_SMTP_SENDER_EMAIL,
    replyTo: normalizeEmail(value.replyTo) || DEFAULT_SMTP_REPLY_TO,
    subjectPrefix: safeText(value.subjectPrefix, DEFAULT_SMTP_SUBJECT_PREFIX).slice(0, 48),
    updatedBy: safeText(value.updatedBy, "system"),
    updatedAt: safeText(value.updatedAt, "2026-04-25T00:00:00.000Z"),
  };
}

function normalizeSystemAiSettings(settings) {
  const value = settings && typeof settings === "object" ? settings : {};
  return {
    id: safeText(value.id, "system-ai-default"),
    enabled: value.enabled !== undefined ? Boolean(value.enabled) : false,
    provider: "http",
    endpoint: normalizeExternalUrl(value.endpoint || ""),
    apiKey: safeText(value.apiKey, ""),
    model: safeText(value.model, ""),
    timeoutMs: Math.max(3000, Math.min(120000, Math.round(Number(value.timeoutMs || 20000)))),
    batchSize: Math.max(1, Math.min(500, Math.round(Number(value.batchSize || 100)))),
    lastTestStatus: safeText(value.lastTestStatus, ""),
    lastTestedAt: safeText(value.lastTestedAt, ""),
    lastTestLatencyMs: Number(value.lastTestLatencyMs || 0) > 0 ? Math.round(Number(value.lastTestLatencyMs)) : 0,
    lastTestResponseShape: safeText(value.lastTestResponseShape, ""),
    lastTestedFingerprint: safeText(value.lastTestedFingerprint, ""),
    updatedBy: safeText(value.updatedBy, "system"),
    updatedAt: safeText(value.updatedAt, "2026-04-25T00:00:00.000Z"),
  };
}

function normalizeApsBucketPolicy(value, fallback = "persistent") {
  const policy = safeText(value, fallback).toLowerCase();
  return ["transient", "temporary", "persistent"].includes(policy) ? policy : "persistent";
}

function normalizeApsBucketRegion(value, fallback = "US") {
  const region = safeText(value, fallback).toUpperCase();
  return region || "US";
}

function normalizeSystemApsSettings(settings) {
  const value = settings && typeof settings === "object" ? settings : {};
  return {
    id: safeText(value.id, "system-aps-default"),
    enabled: value.enabled !== undefined ? Boolean(value.enabled) : false,
    provider: "aps",
    clientId: safeText(value.clientId, ""),
    clientSecret: safeText(value.clientSecret, ""),
    bucketKey: normalizeApsBucketKey(value.bucketKey || ""),
    bucketPolicy: normalizeApsBucketPolicy(value.bucketPolicy),
    bucketRegion: normalizeApsBucketRegion(value.bucketRegion),
    viewerVersion: safeText(value.viewerVersion, "7.*").replace(/\/+$/g, "") || "7.*",
    viewerEnv: safeText(value.viewerEnv, "AutodeskProduction2"),
    viewerApi: safeText(value.viewerApi, "streamingV2"),
    updatedBy: safeText(value.updatedBy, "system"),
    updatedAt: safeText(value.updatedAt, "2026-04-25T00:00:00.000Z"),
  };
}

function normalizeProjectEmailNotificationSettings(settings) {
  const value = settings && typeof settings === "object" ? settings : {};
  const projectId = Object.prototype.hasOwnProperty.call(value, "projectId")
    ? safeText(value.projectId, "")
    : DEFAULT_PROJECT_ID;
  return {
    id: safeText(value.id, `project-email-${projectId}`),
    projectId,
    enabled: value.enabled !== undefined ? Boolean(value.enabled) : false,
    includeGuests: value.includeGuests !== undefined ? Boolean(value.includeGuests) : false,
    digestMode: normalizeEmailDigestMode(value.digestMode, "immediate"),
    recipients: normalizeEmailNotificationBooleanMap(
      value.recipients,
      EMAIL_NOTIFICATION_RECIPIENT_KEYS,
      defaultEmailNotificationRecipients,
    ),
    events: normalizeEmailNotificationBooleanMap(value.events, EMAIL_NOTIFICATION_EVENT_KEYS, defaultEmailNotificationEvents),
    updatedBy: safeText(value.updatedBy, "system"),
    updatedAt: safeText(value.updatedAt, "2026-04-25T00:00:00.000Z"),
  };
}

function enabledEmailFlagCount(value) {
  if (!value || typeof value !== "object") {
    return 0;
  }
  return Object.values(value).filter(Boolean).length;
}

function systemEmailSettingsReady(settings = systemEmailSettings) {
  const current = normalizeSystemEmailSettings(settings);
  if (!current.enabled) {
    return false;
  }
  if (!current.host || !current.port || !current.senderName || !current.senderEmail) {
    return false;
  }
  if (current.authRequired && (!current.username || !current.password)) {
    return false;
  }
  return true;
}

function systemEmailSettingsStatus(settings = systemEmailSettings) {
  const current = normalizeSystemEmailSettings(settings);
  if (!current.enabled) {
    return "disabled";
  }
  return systemEmailSettingsReady(current) ? "configured" : "incomplete";
}

function systemAiSettingsReady(settings = systemAiSettings) {
  const current = normalizeSystemAiSettings(settings);
  return Boolean(current.enabled && current.endpoint && systemAiSettingsTestPassed(current));
}

function systemAiSettingsStatus(settings = systemAiSettings) {
  const current = normalizeSystemAiSettings(settings);
  if (!current.enabled) {
    return current.endpoint && systemAiSettingsTestPassed(current) ? "tested" : "disabled";
  }
  if (!current.endpoint) {
    return "incomplete";
  }
  return systemAiSettingsTestPassed(current) ? "configured" : "needs_test";
}

function systemAiConfigFingerprint(settings) {
  const current = normalizeSystemAiSettings(settings);
  return sha1Hash(JSON.stringify(canonicalizeJson({
    endpoint: current.endpoint,
    model: current.model,
    apiKeyHash: current.apiKey ? sha1Hash(current.apiKey) : "",
    timeoutMs: current.timeoutMs,
    batchSize: current.batchSize,
  })));
}

function systemAiSettingsTestPassed(settings = systemAiSettings) {
  const current = normalizeSystemAiSettings(settings || seedDefaultSystemAiSettings());
  return Boolean(
    current.endpoint &&
    current.lastTestStatus === "success" &&
    current.lastTestedFingerprint &&
    current.lastTestedFingerprint === systemAiConfigFingerprint(current),
  );
}

function effectiveApsSettings(settings = systemApsSettings) {
  const current = normalizeSystemApsSettings(settings || seedDefaultSystemApsSettings());
  return normalizeSystemApsSettings({
    ...current,
    enabled: Boolean(current.enabled),
    clientId: current.clientId,
    clientSecret: current.clientSecret,
    bucketKey: current.bucketKey || `cde-docs-${sha1Hash(current.clientId || "local").slice(0, 18)}`,
    bucketPolicy: current.bucketPolicy || "persistent",
    bucketRegion: current.bucketRegion || "US",
    viewerVersion: current.viewerVersion || "7.*",
    viewerEnv: current.viewerEnv || "AutodeskProduction2",
    viewerApi: current.viewerApi || "streamingV2",
  });
}

function apsSettingsReady(settings = systemApsSettings) {
  const current = effectiveApsSettings(settings);
  return Boolean(current.enabled && current.clientId && current.clientSecret);
}

function apsSettingsStatus(settings = systemApsSettings) {
  const current = effectiveApsSettings(settings);
  if (!current.enabled) {
    return "disabled";
  }
  return apsSettingsReady(current) ? "configured" : "incomplete";
}

function effectiveWorkflowCrsAiSettings() {
  return normalizeSystemAiSettings(systemAiSettings || seedDefaultSystemAiSettings());
}

function projectEmailNotificationSettingByProjectId(projectId) {
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  const record = projectEmailNotificationSettings.find((item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === normalizedProjectId);
  if (record) {
    return normalizeProjectEmailNotificationSettings(record);
  }
  return normalizeProjectEmailNotificationSettings({
    projectId: normalizedProjectId,
    updatedBy: "system",
  });
}

function upsertProjectEmailNotificationSetting(record) {
  const nextRecord = normalizeProjectEmailNotificationSettings(record);
  const index = projectEmailNotificationSettings.findIndex(
    (item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === nextRecord.projectId,
  );
  if (index >= 0) {
    projectEmailNotificationSettings.splice(index, 1, nextRecord);
    return nextRecord;
  }
  projectEmailNotificationSettings.push(nextRecord);
  return nextRecord;
}

function buildEmailConfigurationPayload(userContext) {
  const project = userContext?.project || projectById(userContext?.projectId) || null;
  const systemSettings = normalizeSystemEmailSettings(systemEmailSettings);
  const projectSettings = project
    ? projectEmailNotificationSettingByProjectId(project.id)
    : normalizeProjectEmailNotificationSettings({
        projectId: "",
        updatedBy: "system",
      });
  return {
    system: {
      id: systemSettings.id,
      enabled: systemSettings.enabled,
      provider: systemSettings.provider,
      host: systemSettings.host,
      port: systemSettings.port,
      encryption: systemSettings.encryption,
      authRequired: systemSettings.authRequired,
      username: systemSettings.username,
      senderName: systemSettings.senderName,
      senderEmail: systemSettings.senderEmail,
      replyTo: systemSettings.replyTo,
      subjectPrefix: systemSettings.subjectPrefix,
      hasPassword: Boolean(systemSettings.password),
      status: systemEmailSettingsStatus(systemSettings),
      updatedAt: systemSettings.updatedAt,
      updatedBy: systemSettings.updatedBy,
      updatedByName: userById(systemSettings.updatedBy)?.name || safeText(systemSettings.updatedBy, "系统"),
    },
    project: {
      ...projectSettings,
      status: !projectSettings.enabled
        ? "disabled"
        : systemEmailSettingsReady(systemSettings)
          ? "ready"
          : "waiting_channel",
      updatedByName: userById(projectSettings.updatedBy)?.name || safeText(projectSettings.updatedBy, "系统"),
      enabledRecipientCount: enabledEmailFlagCount(projectSettings.recipients),
      enabledEventCount: enabledEmailFlagCount(projectSettings.events),
    },
  };
}

function buildAiConfigurationPayload(userContext) {
  const settings = normalizeSystemAiSettings(systemAiSettings || seedDefaultSystemAiSettings());
  return {
    system: {
      id: settings.id,
      enabled: settings.enabled,
      provider: settings.provider,
      endpoint: settings.endpoint,
      model: settings.model,
      timeoutMs: settings.timeoutMs,
      batchSize: settings.batchSize,
      hasApiKey: Boolean(settings.apiKey),
      status: systemAiSettingsStatus(settings),
      testPassed: systemAiSettingsTestPassed(settings),
      lastTestStatus: settings.lastTestStatus,
      lastTestedAt: settings.lastTestedAt,
      lastTestLatencyMs: settings.lastTestLatencyMs,
      lastTestResponseShape: settings.lastTestResponseShape,
      updatedAt: settings.updatedAt,
      updatedBy: settings.updatedBy,
      updatedByName: userById(settings.updatedBy)?.name || safeText(settings.updatedBy, "系统"),
      canManage: Boolean(userContext?.isSuperAdmin),
    },
  };
}

function buildApsConfigurationPayload(userContext) {
  const stored = normalizeSystemApsSettings(systemApsSettings || seedDefaultSystemApsSettings());
  const effective = effectiveApsSettings(stored);
  return {
    system: {
      id: stored.id,
      enabled: effective.enabled,
      provider: stored.provider,
      clientId: effective.clientId,
      bucketKey: effective.bucketKey,
      bucketPolicy: effective.bucketPolicy,
      bucketRegion: effective.bucketRegion,
      viewerVersion: effective.viewerVersion,
      viewerEnv: effective.viewerEnv,
      viewerApi: effective.viewerApi,
      hasClientSecret: Boolean(effective.clientSecret),
      status: apsSettingsStatus(stored),
      source: "system_settings",
      updatedAt: stored.updatedAt,
      updatedBy: stored.updatedBy,
      updatedByName: userById(stored.updatedBy)?.name || safeText(stored.updatedBy, "系统"),
      canManage: Boolean(userContext?.isSuperAdmin),
    },
  };
}

function emailEventLabel(eventKey) {
  return {
    memberInvite: "成员邀请",
    workflowStarted: "流程发起",
    workflowStepAssigned: "流程待办",
    workflowReturned: "流程退回",
    workflowApproved: "流程完成",
    annotationCreated: "新增批注",
    annotationReplied: "批注回复",
    annotationResolved: "批注闭环",
    versionUploaded: "新版本上传",
    parseCompleted: "解析完成",
    parseFailed: "解析失败",
    exportCompleted: "导出完成",
    exportFailed: "导出失败",
    modelDiffCompleted: "模型差异完成",
  }[safeText(eventKey, "")] || safeText(eventKey, "邮件通知");
}

function emailMessageSubject(prefix, title) {
  const normalizedPrefix = safeText(prefix, "");
  return normalizedPrefix ? `${normalizedPrefix} ${title}` : title;
}

function escapeEmailHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function uniqueStrings(values = []) {
  return [...new Set((Array.isArray(values) ? values : [values]).map((value) => safeText(value, "")).filter(Boolean))];
}

function notificationProject(context = {}) {
  return (
    projectById(
      safeText(
        context.projectId,
        context.workflow?.projectId || context.document?.projectId || context.userContext?.projectId || DEFAULT_PROJECT_ID,
      ),
    ) ||
    seedDefaultProject()
  );
}

function notificationDocuments(context = {}) {
  const explicitDocuments = Array.isArray(context.documents)
    ? context.documents.filter(Boolean)
    : [];
  if (explicitDocuments.length) {
    return explicitDocuments;
  }
  if (context.document) {
    return [context.document];
  }
  if (context.workflow) {
    return (context.workflow.fileRefs || [])
      .map((fileRef) => documents.find((item) => item.id === fileRef.docId))
      .filter(Boolean);
  }
  return [];
}

function notificationWorkflow(context = {}) {
  if (context.workflow) {
    return context.workflow;
  }
  const doc = context.document || notificationDocuments(context)[0];
  if (!doc || !safeText(doc.activeWorkflowId, "")) {
    return null;
  }
  return workflowById(doc.activeWorkflowId, safeText(doc.projectId, DEFAULT_PROJECT_ID));
}

function workflowStepForNotification(workflow) {
  if (!workflow || !Array.isArray(workflow.steps) || !workflow.steps.length) {
    return null;
  }
  const index = Math.max(0, Math.min(Number(workflow.currentStepIndex || 0), workflow.steps.length - 1));
  return workflow.steps[index] || null;
}

function resolveNotificationUser(candidate) {
  if (!candidate) {
    return null;
  }
  if (typeof candidate === "string") {
    return userById(candidate) || userByEmail(candidate) || userByName(candidate) || null;
  }
  const value = candidate && typeof candidate === "object" ? candidate : {};
  return (
    userById(safeText(value.userId || value.id, "")) ||
    userByEmail(value.email) ||
    userByName(safeText(value.name || value.label, "")) ||
    (normalizeEmail(value.email)
      ? {
          id: safeText(value.userId || value.id, ""),
          name: safeText(value.name || value.label, ""),
          email: normalizeEmail(value.email),
          status: safeText(value.status, "external"),
        }
      : null)
  );
}

function canReceiveProjectNotification(user, projectId, projectSettings) {
  const email = normalizeEmail(user?.email);
  if (!email) {
    return false;
  }
  const member = user?.id ? activeProjectMemberByUserId(user.id, projectId) : null;
  if (member && member.role === "guest" && !projectSettings.includeGuests) {
    return false;
  }
  return true;
}

function pushNotificationRecipient(target, seen, candidate, projectId, projectSettings, options = {}) {
  const user = resolveNotificationUser(candidate);
  if (!user) {
    return;
  }
  if (!options.allowExternal && !user.id) {
    return;
  }
  if (!options.allowInvited && safeText(user.status, "") === "invited") {
    return;
  }
  if (!options.allowProjectFilterBypass && !canReceiveProjectNotification(user, projectId, projectSettings)) {
    return;
  }
  const email = normalizeEmail(user.email);
  if (!email || seen.has(email)) {
    return;
  }
  seen.add(email);
  target.push({
    userId: safeText(user.id, ""),
    name: safeText(user.name, email),
    email,
  });
}

function projectAdminNotificationUsers(projectId) {
  return activeProjectMembers(projectId)
    .filter((member) => isProjectAdminRole(member.role))
    .map((member) => userById(member.userId))
    .filter(Boolean);
}

function workflowInitiatorNotificationUser(workflow) {
  if (!workflow) {
    return null;
  }
  return userById(safeText(workflow.initiatorUserId, "")) || userByName(safeText(workflow.initiator, ""));
}

function workflowStepReviewerUsers(step, { pendingOnly = false } = {}) {
  return Array.isArray(step?.reviewers)
    ? step.reviewers
        .filter((reviewer) => !pendingOnly || reviewer.status === "pending")
        .map((reviewer) => resolveNotificationUser({ userId: reviewer.userId, name: reviewer.name }))
        .filter(Boolean)
    : [];
}

function documentUploaderNotificationUsers(documentsList = [], versionEntry = null) {
  const resolved = [];
  const seen = new Set();
  const pushUser = (user) => {
    const email = normalizeEmail(user?.email);
    if (!email || seen.has(email)) {
      return;
    }
    seen.add(email);
    resolved.push(user);
  };

  if (versionEntry) {
    pushUser(
      userById(safeText(versionEntry.uploadedById, "")) ||
      userByName(safeText(versionEntry.uploadedBy, "")),
    );
  }

  documentsList.forEach((doc) => {
    pushUser(
      userById(safeText(doc?.uploaderId, "")) ||
      userByName(safeText(doc?.uploader, "")),
    );
  });

  return resolved;
}

function extractMentionTokens(text) {
  const source = String(text || "");
  if (!source.includes("@")) {
    return [];
  }
  const tokens = [];
  const matcher = /(^|[\s(（])@([^\s@，。,；;：:）)、<>]+)/g;
  let match = matcher.exec(source);
  while (match) {
    const token = safeText(match[2], "");
    if (token) {
      tokens.push(token);
    }
    match = matcher.exec(source);
  }
  return uniqueStrings(tokens);
}

function resolveMentionedNotificationUsers(projectId, values = []) {
  const tokens = uniqueStrings(
    (Array.isArray(values) ? values : [values]).flatMap((value) => {
      if (!value) {
        return [];
      }
      if (typeof value === "string") {
        return [...extractMentionTokens(value), value];
      }
      const objectValue = value && typeof value === "object" ? value : {};
      return [
        safeText(objectValue.userId || objectValue.id, ""),
        normalizeEmail(objectValue.email),
        safeText(objectValue.name || objectValue.label, ""),
      ];
    }),
  );
  return tokens
    .map((token) => resolveNotificationUser(token))
    .filter((user) => {
      if (!user) {
        return false;
      }
      if (!safeText(user.id, "")) {
        return false;
      }
      const member = activeProjectMemberByUserId(user.id, projectId);
      return Boolean(member);
    });
}

function resolveEventRecipients(eventKey, context = {}, projectSettings, project) {
  const recipients = [];
  const seen = new Set();
  const workflow = notificationWorkflow(context);
  const docs = notificationDocuments(context);
  const workflowStep = context.workflowStep || workflowStepForNotification(workflow);
  const initiator = workflowInitiatorNotificationUser(workflow);
  const documentInitiators = docs
    .map((doc) => userById(safeText(doc?.initiatorUserId, "")) || userByName(safeText(doc?.initiator, "")))
    .filter(Boolean);
  const uploaderUsers = documentUploaderNotificationUsers(docs, context.versionEntry);
  const adminUsers = projectAdminNotificationUsers(project.id);
  const currentStepUsers = workflowStepReviewerUsers(workflowStep, {
    pendingOnly: eventKey === "workflowStepAssigned" && safeText(workflow?.status, "") === "running",
  });
  const mentionedUsers = resolveMentionedNotificationUsers(project.id, [
    ...(Array.isArray(context.mentionedUsers) ? context.mentionedUsers : []),
    safeText(context.annotation?.note, ""),
    safeText(context.reply?.content, ""),
  ]);
  const addUsers = (users, options = {}) => {
    users.forEach((user) => {
      pushNotificationRecipient(recipients, seen, user, project.id, projectSettings, options);
    });
  };
  const recipientFlags = projectSettings.recipients || {};

  if (eventKey === "memberInvite" && context.inviteUser) {
    pushNotificationRecipient(
      recipients,
      seen,
      context.inviteUser,
      project.id,
      projectSettings,
      {
        allowExternal: true,
        allowInvited: true,
        allowProjectFilterBypass: true,
      },
    );
    if (recipientFlags.projectAdmins) {
      addUsers(adminUsers);
    }
    if (recipientFlags.initiator && context.userContext?.user) {
      addUsers([context.userContext.user]);
    }
    return recipients;
  }

  if (recipientFlags.initiator) {
    addUsers(initiator ? [initiator] : documentInitiators);
  }
  if (recipientFlags.currentStepAssignees) {
    addUsers(currentStepUsers);
  }
  if (recipientFlags.uploader) {
    addUsers(uploaderUsers);
  }
  if (recipientFlags.projectAdmins) {
    addUsers(adminUsers);
  }
  if (recipientFlags.mentionedUsers) {
    addUsers(mentionedUsers);
  }

  return recipients;
}

function buildNotificationSummary(eventKey, context = {}, project, workflow, doc, versionEntry) {
  const resolvedVersionLabel = safeText(versionEntry?.version, safeText(doc?.version, ""));
  if (eventKey === "memberInvite") {
    return `${safeText(context.userContext?.user?.name, "系统")} 邀请你加入项目 ${project.name}。`;
  }
  if (eventKey === "workflowStarted") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 已发起。`;
  }
  if (eventKey === "workflowStepAssigned") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 已到达新的待办节点。`;
  }
  if (eventKey === "workflowReturned") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 已退回修改。`;
  }
  if (eventKey === "workflowApproved") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 已完成。`;
  }
  if (eventKey === "annotationCreated") {
    return `文件 ${safeText(doc?.name, "未命名文件")} 新增了一条批注。`;
  }
  if (eventKey === "annotationReplied") {
    return `批注 ${safeText(context.annotation?.title, "未命名批注")} 收到了新回复。`;
  }
  if (eventKey === "annotationResolved") {
    return `批注 ${safeText(context.annotation?.title, "未命名批注")} 状态已更新。`;
  }
  if (eventKey === "versionUploaded") {
    return `文件 ${safeText(doc?.name, "未命名文件")} 已上传新版本 ${resolvedVersionLabel || safeText(doc?.version, "")}。`;
  }
  if (eventKey === "parseCompleted") {
    return `文件 ${safeText(doc?.name, "未命名文件")} 的解析已完成。`;
  }
  if (eventKey === "parseFailed") {
    return `文件 ${safeText(doc?.name, "未命名文件")} 的解析失败。`;
  }
  if (eventKey === "exportCompleted") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 的导出文件已生成。`;
  }
  if (eventKey === "exportFailed") {
    return `流程 ${safeText(workflow?.workflowName, "未命名流程")} 的导出失败。`;
  }
  if (eventKey === "modelDiffCompleted") {
    return `模型 ${safeText(doc?.name, "未命名模型")} 的版本差异对比已完成。${context.note ? ` ${safeText(context.note, "")}` : ""}`;
  }
  return `${emailEventLabel(eventKey)}事件已触发。`;
}

function notificationSubjectTitle(eventKey, context = {}, workflow, doc, versionEntry) {
  if (eventKey === "memberInvite") {
    return `项目邀请｜${notificationProject(context).name}`;
  }
  if (eventKey === "workflowStarted") {
    return `流程发起｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "workflowStepAssigned") {
    return `流程待办｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "workflowReturned") {
    return `流程退回｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "workflowApproved") {
    return `流程完成｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "annotationCreated") {
    return `新增批注｜${safeText(doc?.name, "未命名文件")}`;
  }
  if (eventKey === "annotationReplied") {
    return `批注回复｜${safeText(doc?.name, "未命名文件")}`;
  }
  if (eventKey === "annotationResolved") {
    return `批注闭环｜${safeText(doc?.name, "未命名文件")}`;
  }
  if (eventKey === "versionUploaded") {
    return `新版本上传｜${safeText(doc?.name, "未命名文件")} ${safeText(versionEntry?.version, safeText(doc?.version, ""))}`.trim();
  }
  if (eventKey === "parseCompleted") {
    return `解析完成｜${safeText(doc?.name, "未命名文件")}`;
  }
  if (eventKey === "parseFailed") {
    return `解析失败｜${safeText(doc?.name, "未命名文件")}`;
  }
  if (eventKey === "exportCompleted") {
    return `导出完成｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "exportFailed") {
    return `导出失败｜${safeText(workflow?.workflowName, "未命名流程")}`;
  }
  if (eventKey === "modelDiffCompleted") {
    return `模型差异完成｜${safeText(doc?.name, "未命名模型")}`;
  }
  return emailEventLabel(eventKey);
}

function buildNotificationDetails(eventKey, context = {}, project, workflow, doc, versionEntry) {
  const lines = [
    ["项目", project.name],
    workflow ? ["流程", safeText(workflow.workflowName, "")] : null,
    doc ? ["文件", safeText(doc.name, "")] : null,
    versionEntry || doc?.version ? ["版本", safeText(versionEntry?.version, safeText(doc?.version, ""))] : null,
    workflow && workflowStepForNotification(workflow)
      ? ["当前节点", safeText(workflowStepForNotification(workflow)?.name, "")]
      : null,
    context.annotation ? ["批注", safeText(context.annotation.title, safeText(context.annotation.note, ""))] : null,
    context.reply ? ["回复", safeText(context.reply.content, "")] : null,
    context.comment ? ["审批意见", safeText(context.comment, "")] : null,
    context.note ? ["说明", safeText(context.note, "")] : null,
    context.errorMessage ? ["错误", safeText(context.errorMessage, "")] : null,
    ["触发时间", formatOnlyOfficeInfoDate(context.occurredAt || new Date().toISOString())],
  ].filter(Boolean);

  if (eventKey === "memberInvite") {
    lines.push(
      ["角色", projectRoleLabel(safeText(context.invite?.member?.role, ""))],
      ["邀请失效时间", formatOnlyOfficeInfoDate(safeText(context.invite?.member?.inviteExpiresAt, ""))],
    );
  }

  return lines.filter((item) => safeText(item?.[1], ""));
}

function buildNotificationMessage(eventKey, context = {}, project, systemSettings, recipients) {
  const workflow = notificationWorkflow(context);
  const doc = notificationDocuments(context)[0] || null;
  const versionEntry =
    context.versionEntry ||
    (doc ? resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId) : null);
  const summary = buildNotificationSummary(eventKey, context, project, workflow, doc, versionEntry);
  const details = buildNotificationDetails(eventKey, context, project, workflow, doc, versionEntry);
  const inviteUrl = safeText(context.invite?.inviteUrl, "") || (context.req && context.invite?.member ? inviteLinkForRequest(context.req, context.invite.member) : "");
  const appUrl = appBaseUrl(context.req);
  const subject = emailMessageSubject(
    systemSettings.subjectPrefix,
    notificationSubjectTitle(eventKey, context, workflow, doc, versionEntry),
  );
  const detailText = details.map(([label, value]) => `${label}：${value}`).join("\n");
  const textBlocks = [
    summary,
    detailText,
    inviteUrl ? `邀请链接：${inviteUrl}` : "",
    appUrl ? `系统入口：${appUrl}` : "",
  ].filter(Boolean);
  const detailHtml = details
    .map(([label, value]) => `<li><strong>${escapeEmailHtml(label)}：</strong>${escapeEmailHtml(value)}</li>`)
    .join("");
  const htmlBlocks = [
    `<p>${escapeEmailHtml(summary)}</p>`,
    detailHtml ? `<ul>${detailHtml}</ul>` : "",
    inviteUrl ? `<p><a href="${escapeEmailHtml(inviteUrl)}">打开邀请链接</a></p>` : "",
    appUrl ? `<p><a href="${escapeEmailHtml(appUrl)}">进入系统查看详情</a></p>` : "",
  ].filter(Boolean);
  const mailboxList = recipients.map((recipient) => ({
    name: recipient.name,
    email: recipient.email,
  }));

  if (mailboxList.length <= 1) {
    return {
      to: mailboxList[0]?.email || systemSettings.senderEmail,
      subject,
      text: textBlocks.join("\n\n"),
      html: htmlBlocks.join(""),
    };
  }

  return {
    to: systemSettings.senderEmail,
    bcc: mailboxList.map((item) => item.email).join(", "),
    subject,
    text: textBlocks.join("\n\n"),
    html: htmlBlocks.join(""),
  };
}

async function bestEffortProjectEmailNotification(eventKey, context = {}) {
  const project = notificationProject(context);
  const systemSettings = normalizeSystemEmailSettings(systemEmailSettings);
  const projectSettings = projectEmailNotificationSettingByProjectId(project.id);

  if (!projectSettings.enabled || !projectSettings.events?.[eventKey]) {
    return { status: "skipped", reason: "event_disabled" };
  }
  if (!systemEmailSettingsReady(systemSettings)) {
    return { status: "skipped", reason: "channel_unavailable" };
  }

  const recipients = resolveEventRecipients(eventKey, context, projectSettings, project);
  if (!recipients.length) {
    return { status: "skipped", reason: "no_recipients" };
  }

  const message = buildNotificationMessage(eventKey, context, project, systemSettings, recipients);
  const auditUserContext = context.userContext || buildUserContext(SYSTEM_USER_CONTEXT.user, project.id);
  try {
    const info = await sendSmtpMail(systemSettings, message);
    appendAuditLog(
      auditUserContext,
      "notification.email.sent",
      "email_notification",
      project.id,
      {
        eventKey,
        recipientCount: recipients.length,
        recipients: recipients.map((item) => item.email),
        subject: safeText(message.subject, ""),
        digestMode: projectSettings.digestMode,
        messageId: safeText(info?.messageId, ""),
      },
      context.req || null,
    );
    persistStore();
    return { status: "sent", recipients };
  } catch (error) {
    console.error(`[mail:${eventKey}]`, error);
    appendAuditLog(
      auditUserContext,
      "notification.email.failed",
      "email_notification",
      project.id,
      {
        eventKey,
        recipientCount: recipients.length,
        recipients: recipients.map((item) => item.email),
        subject: safeText(message.subject, ""),
        digestMode: projectSettings.digestMode,
        error: safeText(error?.message, "Unknown email delivery error"),
      },
      context.req || null,
    );
    persistStore();
    return { status: "failed", error };
  }
}

function workflowPermissionsForDocument(doc, userContext, profile) {
  const activeWorkflow = safeText(doc.activeWorkflowId, "")
    ? workflowById(doc.activeWorkflowId, safeText(doc.projectId, DEFAULT_PROJECT_ID))
    : null;
  if (activeWorkflow && activeWorkflow.status === "running") {
    const workflowPermissions = workflowPermissionsForInstance(activeWorkflow, userContext);
    return {
      visible: workflowPermissions.visible,
      start: false,
      run: workflowPermissions.run,
      assignedReviewer: workflowPermissions.currentStepReviewer && !workflowPermissions.isFinalStep,
      assignedApprover: workflowPermissions.currentStepReviewer && workflowPermissions.isFinalStep,
      export: profile.exportWorkflow,
      withdraw: workflowPermissions.withdraw,
      activeWorkflowId: activeWorkflow.id,
    };
  }

  const role = safeText(userContext?.projectRole, "guest");
  const actorName = actorDisplayName(userContext);
  const isAdmin = isProjectAdminRole(role);
  const isAssignedReviewer = safeText(doc.reviewer, "") === actorName;
  const isAssignedApprover = safeText(doc.approver, "") === actorName;
  const isInitiator = safeText(doc.initiator, "") === actorName;
  const canRunCurrentAction =
    isAdmin ||
    (role === "reviewer" && doc.status === "in_review" && isAssignedReviewer) ||
    (role === "reviewer" && doc.status === "final_review" && isAssignedApprover);
  const canWithdraw = (isAdmin || isInitiator) && ["in_review", "final_review"].includes(doc.status);

  const visible =
    isAdmin ||
    (role === "reviewer" && isWorkflowParticipant(doc, actorName)) ||
    (role === "editor" && isDocumentOwner(doc, userContext));

  return {
    visible,
    start: profile.startWorkflow && ["uploaded", "rejected"].includes(doc.status),
    run: canRunCurrentAction,
    assignedReviewer: isAssignedReviewer,
    assignedApprover: isAssignedApprover,
    export: profile.exportWorkflow,
      withdraw: canWithdraw,
  };
}

function workflowInitiatorMatches(workflow, userContext) {
  const actorUserId = safeText(userContext?.user?.id, "");
  const actorName = actorDisplayName(userContext);
  return (
    safeText(workflow?.initiator, "") === actorName ||
    (actorUserId && safeText(workflow?.initiatorUserId, "") === actorUserId)
  );
}

function annotationPermissionsForDocument(doc, userContext, profile, { visible = true, isAdmin = false } = {}) {
  if (!visible) {
    return {
      create: false,
      updateOwn: false,
      deleteOwn: false,
      reply: false,
      changeStatus: false,
      changeStatusAny: false,
      deleteOthers: false,
      export: false,
    };
  }

  const activeWorkflow = safeText(doc.activeWorkflowId, "")
    ? workflowById(doc.activeWorkflowId, safeText(doc.projectId, DEFAULT_PROJECT_ID))
    : null;
  const workflowPermissions = activeWorkflow ? workflowPermissionsForInstance(activeWorkflow, userContext) : null;
  const currentStepReviewer = Boolean(workflowPermissions?.currentStepReviewer);
  const canHandleCurrentStep = isAdmin || currentStepReviewer;
  const isInitiator = activeWorkflow
    ? workflowInitiatorMatches(activeWorkflow, userContext)
    : safeText(doc.initiator, "") === actorDisplayName(userContext);

  if (safeText(doc.status, "") === "approved") {
    return {
      create: false,
      updateOwn: false,
      deleteOwn: false,
      reply: false,
      changeStatus: false,
      changeStatusAny: false,
      deleteOthers: false,
      export: visible && profile.exportReview,
    };
  }

  if ((activeWorkflow && activeWorkflow.status === "running") || ["in_review", "final_review"].includes(safeText(doc.status, ""))) {
    return {
      create: canHandleCurrentStep && profile.createAnnotation,
      updateOwn: canHandleCurrentStep && profile.createAnnotation,
      deleteOwn: canHandleCurrentStep && profile.createAnnotation,
      reply: (canHandleCurrentStep || isInitiator) && profile.replyAnnotation,
      changeStatus: canHandleCurrentStep && profile.changeAnnotationStatus,
      changeStatusAny: canHandleCurrentStep,
      deleteOthers: isAdmin && profile.deleteOthersAnnotation,
      export: visible && profile.exportReview,
    };
  }

  return {
    create: visible && profile.createAnnotation,
    updateOwn: visible && profile.createAnnotation,
    deleteOwn: visible && profile.createAnnotation,
    reply: visible && profile.replyAnnotation,
    changeStatus: visible && profile.changeAnnotationStatus,
    changeStatusAny: false,
    deleteOthers: visible && profile.deleteOthersAnnotation,
    export: visible && profile.exportReview,
  };
}

function documentPermissionsForUser(doc, userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const sameProject = safeText(doc?.projectId, DEFAULT_PROJECT_ID) === projectId;
  const profile = buildProjectPermissionProfile(userContext);
  const role = safeText(userContext?.projectRole, "guest");
  const fileLevel = folderFilePermissionLevel(doc.parentId, userContext);
  if (!sameProject) {
    return {
      visible: false,
      fileLevel: "none",
      preview: false,
      download: false,
      uploadVersion: false,
      rename: false,
      move: false,
      share: false,
      onlyOfficeEdit: false,
      delete: false,
      checkout: false,
      forceUnlock: false,
      approvalLocked: isApprovalLocked(doc),
      publishLocked: false,
      annotations: {
        create: false,
        updateOwn: false,
        deleteOwn: false,
        reply: false,
        changeStatus: false,
        changeStatusAny: false,
        deleteOthers: false,
        export: false,
      },
      workflow: {
        visible: false,
        start: false,
        run: false,
        assignedReviewer: false,
        assignedApprover: false,
        export: false,
        withdraw: false,
      },
    };
  }
  const visible = permissionRank(fileLevel) >= permissionRank("viewer");
  const isAdmin = isProjectAdminRole(role);
  const checkedOutBy = currentCheckedOutBy(doc);
  const actorName = actorDisplayName(userContext);
  const canBypassCheckout = isAdmin;
  const canOwnCheckout = !checkedOutBy || checkedOutBy === actorName;
  const approvalLocked = isApprovalLocked(doc);
  const publishLocked = isPublishFolderId(doc.parentId) && !isAdmin;
  const canWriteFile = permissionRank(fileLevel) >= permissionRank("reviewer") && !publishLocked;
  const canManageFile = permissionRank(fileLevel) >= permissionRank("editor") && !publishLocked;
  const canDeleteOwn = isDocumentOwner(doc, userContext);
  const annotationPermissions = annotationPermissionsForDocument(doc, userContext, profile, {
    visible,
    isAdmin,
  });

  return {
    visible,
    fileLevel,
    preview: visible,
    download: canDownloadDocumentForUser(doc, userContext, fileLevel),
    uploadVersion: canWriteFile && !approvalLocked && (canOwnCheckout || canBypassCheckout),
    rename: canManageFile,
    move: canManageFile,
    share: canManageFile,
    onlyOfficeEdit:
      canManageFile &&
      !approvalLocked &&
      (canOwnCheckout || canBypassCheckout) &&
      isOnlyOfficeSupportedDocument(doc.name),
    delete: isAdmin || (canDeleteOwn && permissionRank(fileLevel) >= permissionRank("reviewer")),
    checkout:
      canWriteFile &&
      (!checkedOutBy || checkedOutBy === actorName || canBypassCheckout) &&
      !approvalLocked,
    forceUnlock: Boolean(checkedOutBy) && checkedOutBy !== actorName && canBypassCheckout,
    approvalLocked,
    publishLocked,
    annotations: annotationPermissions,
    workflow: workflowPermissionsForDocument(doc, userContext, profile),
  };
}

function folderPermissionsForUser(folder, userContext) {
  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  if (folder && safeText(folder.projectId, DEFAULT_PROJECT_ID) !== projectId) {
    return {
      visible: false,
      fileLevel: "none",
      upload: false,
      createFolder: false,
      rename: false,
      move: false,
      delete: false,
      setFolderPermissions: false,
      publishLocked: false,
    };
  }
  const role = safeText(userContext?.projectRole, "guest");
  const fileLevel = folderFilePermissionLevel(folder?.id || null, userContext);
  const isAdmin = isProjectAdminRole(role);
  const publishLocked = folder ? isPublishFolderId(folder.id) && !isAdmin : false;
  const canWrite = permissionRank(fileLevel) >= permissionRank("reviewer") && !publishLocked;
  const canManage = permissionRank(fileLevel) >= permissionRank("editor") && !publishLocked;
  return {
    visible: permissionRank(fileLevel) >= permissionRank("viewer"),
    fileLevel,
    upload: canWrite,
    createFolder: canManage,
    rename: canManage,
    move: canManage,
    delete: canManage,
    setFolderPermissions: isAdmin,
    publishLocked,
  };
}

function visibleDocumentForUser(doc, userContext) {
  return documentPermissionsForUser(doc, userContext).visible;
}

function visibleFolderIdsForUser(userContext) {
  const ids = new Set();

  folders.forEach((folder) => {
    const permissions = folderPermissionsForUser(folder, userContext);
    if (permissions.visible) {
      let cursor = folder;
      while (cursor) {
        ids.add(cursor.id);
        cursor = folderByIdOrNull(cursor.parentId);
      }
    }
  });

  documents.forEach((doc) => {
    if (!visibleDocumentForUser(doc, userContext)) {
      return;
    }
    let cursor = folderByIdOrNull(doc.parentId);
    while (cursor) {
      ids.add(cursor.id);
      cursor = folderByIdOrNull(cursor.parentId);
    }
  });

  return ids;
}

function publicDocumentsForUser(userContext) {
  return [...documents]
    .filter((doc) => safeText(doc.projectId, DEFAULT_PROJECT_ID) === safeText(userContext?.projectId, DEFAULT_PROJECT_ID))
    .filter((doc) => visibleDocumentForUser(doc, userContext))
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .map((doc) => toPublicDocument(doc, userContext));
}

function publicFoldersForUser(userContext) {
  const visibleIds = visibleFolderIdsForUser(userContext);
  return [...folders]
    .filter((folder) => safeText(folder.projectId, DEFAULT_PROJECT_ID) === safeText(userContext?.projectId, DEFAULT_PROJECT_ID))
    .filter((folder) => visibleIds.has(folder.id))
    .sort((left, right) => localeCollator("zh-CN").compare(left.name, right.name))
    .map((folder) => toPublicFolder(folder, userContext));
}

function requestIp(req) {
  return safeText(req.headers["x-forwarded-for"], "").split(",")[0].trim() || safeText(req.socket?.remoteAddress, "");
}

function normalizeUiLanguage(value) {
  const raw = safeText(value, "").toLowerCase();
  return raw.startsWith("en") ? "en" : "zh";
}

function requestLanguage(req, body = null) {
  const explicit =
    safeText(body?.language, "") ||
    safeText(body?.locale, "") ||
    safeText(req?.headers?.["x-cde-language"], "");
  if (explicit) {
    return normalizeUiLanguage(explicit);
  }
  return normalizeUiLanguage(String(req?.headers?.["accept-language"] || "").split(",")[0]);
}

function exportSpawnOptions(language) {
  return {
    env: {
      ...process.env,
      CDE_REPORT_LANGUAGE: normalizeUiLanguage(language),
    },
  };
}

function requestUserContext(req) {
  return requestAuthState(req).userContext;
}

function projectRoleLabel(role) {
  return {
    super_admin: "超级管理员",
    project_admin: "项目管理员",
    reviewer: "审阅者",
    editor: "编辑者",
    guest: "访客",
  }[role] || "访客";
}

function folderPermissionLabel(value) {
  return {
    admin: "管理员",
    editor: "编辑者",
    reviewer: "审阅者",
    viewer: "查看者",
    none: "不可见",
  }[value] || "查看者";
}

function permissionDeniedError(message = "你没有执行该操作的权限。") {
  const error = new Error(message);
  error.statusCode = 403;
  return error;
}

function requireAuthenticatedUser(userContext) {
  if (!userContext?.user) {
    throw permissionDeniedError("请先登录后再执行该操作。");
  }
  return userContext;
}

function assertFolderCapability(folderId, capability, userContext, message) {
  const resolvedFolderId = resolveFolderParentId(folderId, userContext, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  const folder = resolvedFolderId ? requireFolder(resolvedFolderId, userContext) : null;
  const permissions = folderPermissionsForUser(folder, userContext);
  if (!permissions[capability]) {
    throw permissionDeniedError(message);
  }
  return { folder, folderId: resolvedFolderId, permissions };
}

function assertDocumentCapability(doc, capability, userContext, message) {
  const permissions = documentPermissionsForUser(doc, userContext);
  const path = capability.split(".");
  let current = permissions;
  for (const segment of path) {
    current = current?.[segment];
  }
  if (!current) {
    throw permissionDeniedError(message);
  }
  return permissions;
}

function appendAuditLog(userContext, action, resourceType, resourceId, detail = {}, req = null) {
  const createdAt = new Date().toISOString();
  const previousHash = safeText(auditLogs[0]?.hash, "");
  const entry = normalizeAuditLog({
    id: crypto.randomUUID(),
    userId: safeText(userContext?.user?.id, "system"),
    projectId: safeText(userContext?.projectId, DEFAULT_PROJECT_ID),
    action,
    resourceType,
    resourceId,
    detail,
    ip: req ? requestIp(req) : "",
    createdAt,
    previousHash,
  });
  if (!entry) {
    return;
  }
  entry.hash = auditLogHash(entry);
  auditLogs.unshift(entry);
  auditLogs = auditLogs.slice(0, AUDIT_LOG_RETENTION_LIMIT);
}

function auditLogHash(entry) {
  return sha256Hash(JSON.stringify(canonicalizeJson({
    id: safeText(entry.id, ""),
    userId: safeText(entry.userId, ""),
    projectId: safeText(entry.projectId, ""),
    action: safeText(entry.action, ""),
    resourceType: safeText(entry.resourceType, ""),
    resourceId: safeText(entry.resourceId, ""),
    detail: entry.detail && typeof entry.detail === "object" ? entry.detail : {},
    ip: safeText(entry.ip, ""),
    createdAt: safeText(entry.createdAt, ""),
    previousHash: safeText(entry.previousHash, ""),
  })));
}

function verifyAuditLogChain(records = auditLogs) {
  const ordered = Array.isArray(records) ? records : [];
  for (let index = 0; index < ordered.length; index += 1) {
    const entry = ordered[index];
    if (!safeText(entry?.hash, "") || auditLogHash(entry) !== entry.hash) {
      return { ok: false, index, id: safeText(entry?.id, ""), reason: "hash_mismatch" };
    }
    const nextEntry = ordered[index + 1];
    const expectedPreviousHash = nextEntry ? safeText(nextEntry.hash, "") : "";
    if (safeText(entry.previousHash, "") !== expectedPreviousHash) {
      return { ok: false, index, id: safeText(entry.id, ""), reason: "previous_hash_mismatch" };
    }
  }
  return { ok: true, count: ordered.length, headHash: safeText(ordered[0]?.hash, "") };
}

function userSummaryRecord(userContext) {
  const user = userContext?.user || SYSTEM_USER_CONTEXT.user;
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    avatarUrl: user.avatarUrl,
    status: user.status,
    mustChangePassword: Boolean(user.mustChangePassword),
    passwordUpdatedAt: safeText(user.passwordUpdatedAt, ""),
    lastLoginAt: safeText(user.lastLoginAt, ""),
    projectRole: userContext?.projectRole || "guest",
    roleLabel: projectRoleLabel(userContext?.projectRole || "guest"),
    isSuperAdmin: isSuperAdmin(userContext),
    larkBinding: userLarkBindingSummary(user),
  };
}

function parseAuditLogDate(value, boundary = "start") {
  const normalized = safeText(value, "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    return null;
  }
  const date = new Date(`${normalized}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) {
    return null;
  }
  if (boundary === "end") {
    date.setUTCDate(date.getUTCDate() + 1);
  }
  return date;
}

function auditLogFilterFromSearchParams(searchParams) {
  const source = searchParams instanceof URLSearchParams ? searchParams : new URLSearchParams();
  return {
    from: safeText(source.get("auditFrom") || source.get("auditDateFrom"), "").slice(0, 10),
    to: safeText(source.get("auditTo") || source.get("auditDateTo"), "").slice(0, 10),
  };
}

function auditLogMatchesDateFilter(log, filter = {}) {
  const fromDate = parseAuditLogDate(filter.from, "start");
  const toDate = parseAuditLogDate(filter.to, "end");
  if (!fromDate && !toDate) {
    return true;
  }
  const createdAtMs = Date.parse(safeText(log?.createdAt, ""));
  if (Number.isNaN(createdAtMs)) {
    return false;
  }
  if (fromDate && createdAtMs < fromDate.getTime()) {
    return false;
  }
  if (toDate && createdAtMs >= toDate.getTime()) {
    return false;
  }
  return true;
}

function accessPayload(userContext, options = {}) {
  const project = userContext?.project || projectById(userContext?.projectId) || null;
  const projectId = safeText(project?.id, "");
  const hasProject = Boolean(projectId);
  const activeMembers = hasProject ? activeProjectMembers(projectId) : [];
  const memberRecords = activeMembers
    .map((member) => {
      const user = userById(member.userId);
      if (!user) {
        return null;
      }
      return {
        ...member,
        user: sanitizeUserForClient(user),
        roleLabel: projectRoleLabel(member.role),
      };
    })
    .filter(Boolean)
    .sort((left, right) => permissionRank(projectRoleFileLevel(right.role)) - permissionRank(projectRoleFileLevel(left.role)));

  const visibleFolderIds = hasProject ? visibleFolderIdsForUser(userContext) : new Set();
  const folderPermissionRecords = hasProject
    ? folderPermissions
        .filter(
          (item) =>
            item.projectId === projectId &&
            (visibleFolderIds.has(item.folderId) || isProjectAdminRole(userContext.projectRole)),
        )
        .map((item) => ({
          ...item,
          permissionLabel: folderPermissionLabel(item.permission),
          folderName: folderName(item.folderId),
          userName: userById(item.userId)?.name || "未知用户",
          setByName: userById(item.setBy)?.name || safeText(item.setBy, "系统"),
        }))
        .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    : [];

  const auditFilter = options.auditLogFilter || {};
  const allProjectAuditRecords = hasProject && buildProjectPermissionProfile(userContext).viewAuditLogs
    ? auditLogs
        .filter((item) => item.projectId === projectId)
    : [];
  const filteredAuditRecords = allProjectAuditRecords
    .filter((item) => auditLogMatchesDateFilter(item, auditFilter));
  const auditRecords = filteredAuditRecords
    .map((item) => ({
      ...item,
      userName: userById(item.userId)?.name || "已离开",
    }))
    .slice(0, 120);
  const inviteRecords = hasProject
    ? pendingProjectInvites(projectId)
        .map((member) => {
          const user = userById(member.userId);
          if (!user) {
            return null;
          }
          return {
            id: member.id,
            userId: member.userId,
            name: user.name,
            email: user.email,
            role: member.role,
            roleLabel: projectRoleLabel(member.role),
            invitedAt: safeText(member.invitedAt, ""),
            expiresAt: safeText(member.inviteExpiresAt, ""),
            invitedByName: userById(member.invitedBy)?.name || safeText(member.invitedBy, "系统"),
            status: memberInviteStatus(member),
            inviteToken: safeText(member.inviteToken, ""),
          };
        })
        .filter(Boolean)
        .sort((left, right) => String(right.invitedAt || "").localeCompare(String(left.invitedAt || "")))
    : [];

  const availableProjects = projectsForUser(userContext?.user).map((item) => {
    const member = activeProjectMemberByUserId(safeText(userContext?.user?.id, ""), item.id);
    return {
      id: item.id,
      name: item.name,
      code: item.code,
      role: member?.role || (isSuperAdmin(userContext) ? "super_admin" : "guest"),
      roleLabel: projectRoleLabel(member?.role || (isSuperAdmin(userContext) ? "super_admin" : "guest")),
      isCurrent: item.id === projectId,
      memberCount: activeProjectMembers(item.id).length,
      documentCount: documents.filter((doc) => safeText(doc.projectId, DEFAULT_PROJECT_ID) === item.id).length,
      workflowCount: workflows.filter((workflow) => safeText(workflow.projectId, DEFAULT_PROJECT_ID) === item.id).length,
    };
  });

  return {
    project,
    projects: availableProjects,
    currentUser: userSummaryRecord(userContext),
    capabilities: buildProjectPermissionProfile(userContext),
    roleOptions: PROJECT_ROLE_ORDER.map((value) => ({ value, label: projectRoleLabel(value) })),
    folderPermissionOptions: FOLDER_PERMISSION_ORDER.map((value) => ({
      value,
      label: folderPermissionLabel(value),
    })),
    users: users.map(sanitizeUserForClient),
    folders: hasProject ? publicFoldersForUser(userContext).map((folder) => ({
      id: folder.id,
      name: folder.name,
      parentId: folder.parentId,
      path: folderPathIds(folder.id)
        .slice()
        .reverse()
        .map((id) => folderByIdOrNull(id)?.name)
        .filter(Boolean)
        .join(" / "),
      permissions: folder.permissions,
    })) : [],
    projectMembers: memberRecords,
    memberInvites: inviteRecords,
    folderPermissions: folderPermissionRecords,
    auditLogs: auditRecords,
    auditLogFilter: {
      from: safeText(auditFilter.from, ""),
      to: safeText(auditFilter.to, ""),
      matchedCount: filteredAuditRecords.length,
      totalCount: allProjectAuditRecords.length,
      limit: 120,
    },
    emailConfiguration: buildEmailConfigurationPayload(userContext),
    aiConfiguration: buildAiConfigurationPayload(userContext),
    apsConfiguration: buildApsConfigurationPayload(userContext),
    projectManagement: buildProjectManagementPayload(userContext),
  };
}

function normalizeDocument(doc) {
  const currentSnapshot = currentVersionSnapshot(doc);
  const versionHistory = normalizeVersionHistory(doc.versionHistory, currentSnapshot, doc.currentVersionId);
  const currentVersion = resolveCurrentVersionEntry(versionHistory, doc.currentVersionId) || currentSnapshot;
  const checkedOutBy = normalizeCheckedOutBy(doc);
  const checkedOutAt = checkedOutBy
    ? safeText(doc.checkedOutAt || doc.lockedAt, doc.updatedAt || doc.uploadedAt || new Date().toISOString())
    : "";
  const mimeType = inferDocumentMimeType(currentVersion.name || doc.name, currentVersion.mimeType || doc.mimeType);
  const currentVersionId = safeText(currentVersion.id, currentSnapshot.id);
  return {
    id: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    name: safeText(doc.name, currentVersion.name || "未命名文件"),
    parentId: normalizeFolderId(doc.parentId),
    currentVersionId,
    parseStatus: normalizeParseStatus(currentVersion.parseStatus, "done"),
    parseReadyAt: safeText(currentVersion.parseReadyAt, ""),
    parseError: safeText(currentVersion.parseError, ""),
    storedFileName: safeText(currentVersion.storedFileName, doc.storedFileName),
    size: Number(currentVersion.size || doc.size || 0),
    version: safeText(currentVersion.version, doc.version || "V1"),
    status: doc.status || "uploaded",
    workflowName: doc.workflowName || "BIM 模型审核",
    initiator: doc.initiator || "翔宇 洪",
    reviewer: doc.reviewer || "结构工程师",
    approver: doc.approver || "总工",
    dueDate: doc.dueDate || defaultDueDate(),
    uploadedAt: doc.uploadedAt || new Date().toISOString(),
    updatedAt: doc.updatedAt || new Date().toISOString(),
    uploaderId: safeText(currentVersion.uploadedById, safeText(doc.uploaderId, "")),
    uploader: safeText(currentVersion.uploadedBy, safeText(doc.uploader, inferUploadActor(doc))),
    owner: safeText(doc.owner, doc.initiator || inferUploadActor(doc)),
    mimeType,
    isPdf: mimeType === "application/pdf",
    accessLevel: normalizeAccessLevel(doc.accessLevel, "edit"),
    downloadScope: normalizeDownloadScope(doc.downloadScope, "team"),
    watermarkEnabled: doc.watermarkEnabled !== undefined ? Boolean(doc.watermarkEnabled) : true,
    checkedOutBy,
    checkedOutAt,
    checkedOut: Boolean(checkedOutBy),
    locked: Boolean(checkedOutBy),
    activeWorkflowId: safeText(doc.activeWorkflowId, ""),
    workflowIds: Array.isArray(doc.workflowIds) ? doc.workflowIds.map((item) => safeText(item, "")).filter(Boolean) : [],
    share: normalizeShare(doc.share),
    drawingMetadata: normalizeDocumentDrawingMetadata(doc.drawingMetadata || doc.drawing_metadata),
    specMetadata: normalizeDocumentSpecMetadata(doc.specMetadata || doc.spec_metadata),
    versionHistory,
    aps: normalizeApsConfig(doc.aps),
    remarks: typeof doc.remarks === "string" ? doc.remarks : "",
    annotations: Array.isArray(doc.annotations) ? doc.annotations.map((item) => normalizeAnnotation(item, currentVersionId)) : [],
    activity: Array.isArray(doc.activity) ? doc.activity : [],
    lastExportFileName: doc.lastExportFileName || "",
  };
}

function normalizeDocumentDrawingMetadata(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const markedAsDrawing = Boolean(source.markedAsDrawing || source.isDrawing || source.enabled);
  const relatedDrawingNumber = safeText(source.relatedDrawingNumber || source.relatedNumber || "", "");
  const relatedDrawingId = safeText(source.relatedDrawingId || "", "");
  return {
    markedAsDrawing,
    drawingNumber: markedAsDrawing ? safeText(source.drawingNumber || source.number, "") : "",
    drawingName: markedAsDrawing ? safeText(source.drawingName || source.title || source.name, "") : "",
    discipline: markedAsDrawing ? safeText(source.discipline, "") : "",
    revision: markedAsDrawing ? normalizeDrawingRevisionLabel(source.revision || source.version || source.versionNo, "") : "",
    relatedDrawingNumber: markedAsDrawing ? relatedDrawingNumber : "",
    relatedDrawingId: markedAsDrawing ? relatedDrawingId : "",
  };
}

function normalizeDocumentSpecMetadata(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const markedAsSpec = Boolean(source.markedAsSpec || source.isSpec || source.enabled);
  const documentType = safeText(source.documentType || source.type, "Equipment Datasheet");
  return {
    markedAsSpec,
    documentType: markedAsSpec && supportedSpecDocumentTypes().includes(documentType) ? documentType : "",
    tagNumber: markedAsSpec ? safeText(source.tagNumber || source.tag_number, "") : "",
    equipmentType: markedAsSpec ? safeText(source.equipmentType || source.equipment_type, "") : "",
    discipline: markedAsSpec ? safeText(source.discipline, "") : "",
    revision: markedAsSpec ? normalizeDrawingRevisionLabel(source.revision || source.version || source.versionNo, "") : "",
    specEntryId: markedAsSpec ? safeText(source.specEntryId || source.spec_entry_id, "") : "",
    specVersionId: markedAsSpec ? safeText(source.specVersionId || source.spec_version_id, "") : "",
  };
}

function resolveDocumentDrawingMetadataRelations(metadata, projectId, currentDocumentId = "") {
  const normalized = normalizeDocumentDrawingMetadata(metadata);
  if (!normalized.markedAsDrawing) {
    return normalized;
  }
  const normalizedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  const targetId = safeText(normalized.relatedDrawingId, "");
  const targetNumber = safeText(normalized.relatedDrawingNumber, "");
  const related = documents.find((doc) => {
    if (safeText(doc.projectId, DEFAULT_PROJECT_ID) !== normalizedProjectId || doc.id === currentDocumentId) {
      return false;
    }
    const drawing = normalizeDocumentDrawingMetadata(doc.drawingMetadata);
    if (!drawing.markedAsDrawing) {
      return false;
    }
    return (targetId && doc.id === targetId) || (targetNumber && drawing.drawingNumber === targetNumber);
  });
  if (!related) {
    return normalized;
  }
  const relatedMetadata = normalizeDocumentDrawingMetadata(related.drawingMetadata);
  return {
    ...normalized,
    relatedDrawingId: related.id,
    relatedDrawingNumber: relatedMetadata.drawingNumber || normalized.relatedDrawingNumber,
  };
}

function normalizeDrawingRevisionLabel(value, fallback = "") {
  const revision = safeText(value, fallback);
  if (!revision) {
    return "";
  }
  const compact = revision.replace(/\s+/g, "").replace(/_/g, ".");
  const match = compact.match(/^rev\.?([A-Za-z0-9.-]+)$/i);
  if (!match) {
    return compact;
  }
  return `Rev.${match[1].replace(/^\./, "").toUpperCase()}`;
}

function assertDrawingMetadataReady(metadata) {
  if (!metadata?.markedAsDrawing) {
    return;
  }
  const missing = [];
  if (!metadata.drawingNumber) missing.push("图纸编号");
  if (!metadata.drawingName) missing.push("图纸名称");
  if (!metadata.discipline) missing.push("专业");
  if (!metadata.revision) missing.push("版本号");
  if (missing.length) {
    const error = new Error(`图纸属性声明缺少必填项：${missing.join("、")}`);
    error.statusCode = 400;
    throw error;
  }
}

