function normalizeUser(user) {
  const value = user && typeof user === "object" ? user : {};
  const normalizedId = safeText(value.id, crypto.randomUUID());
  let normalizedName = safeText(value.name, "未命名用户");
  let normalizedEmail = normalizeEmail(value.email);
  let normalizedPlatformRole = normalizePlatformRole(value.platformRole, "user");
  const missingCredentials = !safeText(value.passwordSalt, "") || !safeText(value.passwordHash, "");
  let credentials = missingCredentials
    ? issuePasswordCredentials(DEFAULT_BOOTSTRAP_PASSWORD, {
        mustChangePassword: Boolean(value.mustChangePassword),
        passwordUpdatedAt: value.passwordUpdatedAt || value.createdAt || new Date().toISOString(),
        lastLoginAt: value.lastLoginAt || "",
      })
    : {
        passwordSalt: safeText(value.passwordSalt, ""),
        passwordHash: safeText(value.passwordHash, ""),
        mustChangePassword: value.mustChangePassword !== undefined ? Boolean(value.mustChangePassword) : false,
        passwordUpdatedAt: safeText(value.passwordUpdatedAt, value.createdAt || new Date().toISOString()),
        lastLoginAt: safeText(value.lastLoginAt, ""),
      };
  let migratedSeedAdmin = false;
  if (normalizedId === DEFAULT_CURRENT_USER_ID) {
    if (!normalizedName || normalizedName === "翔宇 洪") {
      normalizedName = DEFAULT_ADMIN_DISPLAY_NAME;
      migratedSeedAdmin = true;
    }
    if (normalizedPlatformRole !== "super_admin") {
      normalizedPlatformRole = "super_admin";
      migratedSeedAdmin = true;
    }
    if (LEGACY_DEFAULT_ADMIN_EMAILS.has(normalizedEmail)) {
      normalizedEmail = DEFAULT_ADMIN_EMAIL;
      credentials = issuePasswordCredentials(DEFAULT_BOOTSTRAP_PASSWORD, {
        mustChangePassword: false,
        lastLoginAt: safeText(value.lastLoginAt, ""),
      });
      migratedSeedAdmin = true;
    }
  }
  if (
    missingCredentials ||
    migratedSeedAdmin ||
    value.mustChangePassword === undefined ||
    value.passwordUpdatedAt === undefined ||
    value.lastLoginAt === undefined
  ) {
    storeHydrationMutated = true;
  }
  return {
    id: normalizedId,
    name: normalizedName,
    email: normalizedEmail,
    avatarUrl: safeText(value.avatarUrl, ""),
    status: ["active", "inactive", "invited"].includes(String(value.status || "").trim()) ? String(value.status || "").trim() : "active",
    platformRole: normalizedPlatformRole,
    createdAt: value.createdAt || new Date().toISOString(),
    passwordSalt: credentials.passwordSalt,
    passwordHash: credentials.passwordHash,
    mustChangePassword: credentials.mustChangePassword,
    passwordUpdatedAt: credentials.passwordUpdatedAt,
    lastLoginAt: credentials.lastLoginAt,
    invitedAt: safeText(value.invitedAt, ""),
    larkOpenId: safeText(value.larkOpenId, ""),
    larkUnionId: safeText(value.larkUnionId, ""),
    larkUserId: safeText(value.larkUserId, ""),
    larkName: safeText(value.larkName, ""),
    larkEmail: normalizeEmail(value.larkEmail),
    larkAvatarUrl: safeText(value.larkAvatarUrl, ""),
    larkTenantKey: safeText(value.larkTenantKey, ""),
    larkBoundAt: safeText(value.larkBoundAt, ""),
  };
}

