function normalizeAuditLog(log) {
  const value = log && typeof log === "object" ? log : {};
  if (!safeText(value.action, "") || !safeText(value.resourceType, "")) {
    return null;
  }
  const entry = {
    id: safeText(value.id, crypto.randomUUID()),
    userId: safeText(value.userId, "system"),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    action: safeText(value.action, "unknown"),
    resourceType: safeText(value.resourceType, "system"),
    resourceId: safeText(value.resourceId, ""),
    detail: value.detail && typeof value.detail === "object" ? value.detail : {},
    ip: safeText(value.ip, ""),
    createdAt: value.createdAt || new Date().toISOString(),
    previousHash: safeText(value.previousHash, ""),
    hash: safeText(value.hash, ""),
  };
  if (!entry.hash) {
    entry.hash = auditLogHash(entry);
    storeHydrationMutated = true;
  }
  return entry;
}

function normalizeWorkflowStepMode(value, fallback = "single") {
  return ["single", "parallel_all", "parallel_any"].includes(String(value || "").trim())
    ? String(value || "").trim()
    : fallback;
}

function workflowTemplateUserLookupPool() {
  return Array.isArray(users) && users.length ? users : seedDefaultUsers();
}

function workflowTemplateRoleFromValue(value) {
  const raw = safeText(value, "");
  if (!raw) {
    return "";
  }
  if (PROJECT_ROLE_ORDER.includes(raw)) {
    return raw;
  }
  return (
    Object.entries({
      super_admin: "超级管理员",
      project_admin: "项目管理员",
      reviewer: "审阅者",
      editor: "编辑者",
      guest: "访客",
    }).find(([, label]) => label === raw)?.[0] || ""
  );
}

function normalizeWorkflowTemplateReviewerSelector(reviewer, index = 0) {
  const value = reviewer && typeof reviewer === "object" ? reviewer : {};
  const explicitType = safeText(value.type, "");
  const rawValue = typeof reviewer === "string" ? safeText(reviewer, "") : safeText(value.label || value.name || value.userId || value.role, "");
  const inferredRole = workflowTemplateRoleFromValue(value.role || rawValue);
  const type = explicitType === "role" || (!explicitType && inferredRole) ? "role" : "user";

  if (type === "role") {
    const role = workflowTemplateRoleFromValue(value.role || rawValue || "reviewer") || "reviewer";
    return {
      id: safeText(value.id, `workflow-template-reviewer-${index + 1}`),
      type: "role",
      userId: "",
      role,
      label: safeText(value.label, projectRoleLabel(role)),
    };
  }

  const lookupPool = workflowTemplateUserLookupPool();
  const explicitUserId = safeText(value.userId, "");
  const matchedUser =
    lookupPool.find((item) => item.id === explicitUserId) ||
    lookupPool.find((item) => normalizeEmail(item.email) === normalizeEmail(rawValue)) ||
    lookupPool.find((item) => safeText(item.name, "") === rawValue) ||
    null;

  return {
    id: safeText(value.id, `workflow-template-reviewer-${index + 1}`),
    type: "user",
    userId: matchedUser?.id || explicitUserId,
    role: "",
    label: matchedUser?.name || rawValue || "未指定成员",
  };
}

function workflowTemplateReviewerLabel(selector) {
  if (!selector || typeof selector !== "object") {
    return "";
  }
  if (selector.type === "role") {
    return projectRoleLabel(selector.role) || safeText(selector.label, "");
  }
  const lookupPool = workflowTemplateUserLookupPool();
  const matchedUser =
    lookupPool.find((item) => item.id === safeText(selector.userId, "")) ||
    lookupPool.find((item) => safeText(item.name, "") === safeText(selector.label, "")) ||
    lookupPool.find((item) => normalizeEmail(item.email) === normalizeEmail(selector.label));
  return matchedUser?.name || safeText(selector.label, "");
}

function normalizeWorkflowTemplateStep(step, index = 0) {
  const value = step && typeof step === "object" ? step : {};
  const reviewers = Array.isArray(value.reviewers)
    ? value.reviewers.map((item, reviewerIndex) => normalizeWorkflowTemplateReviewerSelector(item, reviewerIndex)).filter(Boolean)
    : [];
  return {
    id: safeText(value.id, `workflow-template-step-${index + 1}`),
    name: safeText(value.name, `Step ${index + 1}`),
    mode: normalizeWorkflowStepMode(value.mode, reviewers.length > 1 ? "parallel_all" : "single"),
    assigneeMode: safeText(value.assigneeMode, reviewers.some((item) => item.type === "role") ? "role" : "user") === "role" ? "role" : "user",
    reviewers,
    dueDays: Math.max(1, Number(value.dueDays || 1) || 1),
    description: safeText(value.description, ""),
  };
}

