    confidence: Math.max(0, Math.min(1, Number(value.confidence || 0) || 0)),
    versionLabel: safeText(value.versionLabel, ""),
    reviewerNames: Array.isArray(value.reviewerNames) ? value.reviewerNames.map((name) => safeText(name, "")).filter(Boolean) : [],
    sourceCount: Math.max(1, Number(value.sourceCount || 1) || 1),
