function desalinationProfessionalHealthTemplateDefinitions() {
  return [
    { discipline: "civil", config: desalinationCivilHealthTemplateDefinition() },
    { discipline: "process", config: desalinationProcessHealthTemplateDefinition() },
    { discipline: "electrical", config: desalinationElectricalHealthTemplateDefinition() },
    { discipline: "hvac", config: desalinationHvacHealthTemplateDefinition() },
  ];
}

function modelHealthGeometryLimitsFromChecks(checks = []) {
  const limits = {};
  checks.forEach((check) => {
    const rule = safeText(check?.rule, "");
    const params = check?.params || {};
    if (rule === "length_in_range") limits.Length = { min: params.min, max: params.max };
    if (rule === "height_in_range") limits.Height = { min: params.min, max: params.max };
    if (rule === "thickness_in_range") limits.Thickness = { min: params.min, max: params.max };
    if (rule === "area_in_range") limits.Area = { min: params.min, max: params.max };
    if (rule === "volume_gt_zero") limits.Volume = { min: 0.001 };
    if (rule === "area_gt_zero") limits.Area = { ...(limits.Area || {}), min: 0.001 };
    if (rule === "length_gt_zero") limits.Length = { ...(limits.Length || {}), min: 0.001 };
    if (rule === "height_gt_zero") limits.Height = { ...(limits.Height || {}), min: 0.001 };
  });
  return limits;
}

function modelHealthGeometryLimitMetaFromChecks(checks = []) {
  const meta = {};
  const setMeta = (field, check) => {
    meta[field] = {
      severity: safeText(check?.severity, "error"),
      note: safeText(check?.note, ""),
      rule: safeText(check?.rule, ""),
    };
  };
  checks.forEach((check) => {
    const rule = safeText(check?.rule, "");
    if (rule === "length_in_range" || rule === "length_gt_zero") setMeta("Length", check);
    if (rule === "height_in_range" || rule === "height_gt_zero") setMeta("Height", check);
    if (rule === "thickness_in_range") setMeta("Thickness", check);
    if (rule === "area_in_range" || rule === "area_gt_zero") setMeta("Area", check);
    if (rule === "volume_gt_zero") setMeta("Volume", check);
  });
  return meta;
}

function modelHealthTemplateDisciplines(templateConfig = {}) {
  if (Array.isArray(templateConfig.disciplines)) {
    return templateConfig.disciplines;
  }
  if (Array.isArray(templateConfig.element_types)) {
    return [{
      id: safeText(templateConfig.template?.id, "DISCIPLINE"),
      name: safeText(templateConfig.template?.discipline, templateConfig.template?.name || "Discipline"),
      software: safeText(templateConfig.template?.software, ""),
      element_types: templateConfig.element_types,
      layer_checks: templateConfig.layer_checks,
      workset_checks: templateConfig.workset_checks,
    }];
  }
  return [];
}

function modelHealthTemplateAiChecks(templateConfig = {}) {
  if (Array.isArray(templateConfig.ai_checks)) {
    return {
      enabled: templateConfig.template?.gate_config?.ai_check_enabled !== false,
      checks: templateConfig.ai_checks,
    };
  }
  if (templateConfig.ai_checks && typeof templateConfig.ai_checks === "object") {
    return templateConfig.ai_checks;
  }
  return { enabled: false, checks: [] };
}

function modelHealthTemplateExtras(templateConfig = {}) {
  return Object.fromEntries(Object.entries(templateConfig || {}).filter(([key]) => ![
    "template",
    "disciplines",
    "element_types",
    "layer_checks",
    "workset_checks",
    "cross_discipline_checks",
    "ai_checks",
    "naming_conventions",
    "severity_definitions",
    "score_calculation",
    "project_specific_notes",
  ].includes(key)));
}

function modelHealthRulesFromDesalinationTemplate(templateConfig = desalinationEpcHealthTemplateDefinition()) {
  const requiredFields = {};
  const requiredFieldMeta = {};
  const geometryLimits = {};
  const geometryLimitMeta = {};
  const allowedSystems = new Set();
  const allowedWorksets = new Set();
  const allowedFamilies = new Set();
  const allowedTypes = new Set();
  const uniqueFields = {};
  const outlierParameters = {};
  const disciplines = modelHealthTemplateDisciplines(templateConfig);
  const aiChecks = modelHealthTemplateAiChecks(templateConfig);

  disciplines.forEach((discipline) => {
    [...(discipline.layer_checks?.allowlist || []), ...(discipline.workset_checks?.allowlist || [])].forEach((item) => allowedWorksets.add(item));
    (discipline.element_types || []).forEach((element) => {
      const fields = (element.required_properties || []).map((property) => property.name).filter(Boolean);
      requiredFields[element.type] = fields;
      requiredFieldMeta[element.type] = Object.fromEntries((element.required_properties || []).map((property) => [property.name, {
        pattern: property.pattern,
        severity: property.severity || "error",
        note: property.note || "",
      }]));
      const limits = modelHealthGeometryLimitsFromChecks(element.geometry_checks || []);
      if (Object.keys(limits).length) geometryLimits[element.type] = limits;
      const limitMeta = modelHealthGeometryLimitMetaFromChecks(element.geometry_checks || []);
      if (Object.keys(limitMeta).length) geometryLimitMeta[element.type] = limitMeta;
      if (Array.isArray(element.uniqueness_checks) && element.uniqueness_checks.length) {
        uniqueFields[element.type] = element.uniqueness_checks;
      }
      (element.fluid_service_allowlist || []).forEach((item) => allowedSystems.add(item));
      (element.equipment_type_allowlist || []).forEach((item) => allowedTypes.add(item));
      (element.naming_checks || []).forEach((check) => {
        const field = safeText(check.field, "").toLowerCase();
        (check.allowlist || []).forEach((item) => {
          if (field.includes("family")) allowedFamilies.add(item);
          else allowedTypes.add(item);
        });
      });
    });
  });

  (aiChecks.checks || []).forEach((check) => {
    const type = safeText(check.element_type, "");
    if (!type) return;
    const fields = [...(check.grouping || []), ...(check.reference_fields || [])].filter(Boolean);
    if (fields.length) outlierParameters[type] = Array.from(new Set([...(outlierParameters[type] || []), ...fields]));
  });

  return {
    requiredFields,
    requiredFieldMeta,
    namingRules: {
      drawingNumber: templateConfig.naming_conventions?.drawing_number_format || "",
      revision: templateConfig.naming_conventions?.revision_format || "",
      tag: templateConfig.naming_conventions?.equipment_tag_pattern || "",
      lineNumber: templateConfig.naming_conventions?.line_number_pattern || "",
      instrumentTag: templateConfig.naming_conventions?.instrument_tag_pattern || "",
      roomNumber: templateConfig.naming_conventions?.room_number_pattern || "",
    },
    allowedSystems: Array.from(allowedSystems),
    allowedFamilies: Array.from(allowedFamilies),
    allowedTypes: Array.from(allowedTypes),
    allowedWorksets: Array.from(allowedWorksets),
    geometryLimits,
    geometryLimitMeta,
    uniqueFields,
    levels: [],
    outlierParameters,
    templateProfile: {
      id: templateConfig.template?.id,
      name: templateConfig.template?.name,
      projectType: templateConfig.template?.project_type,
      discipline: templateConfig.template?.discipline,
      software: templateConfig.template?.software,
      version: templateConfig.template?.version,
    },
    templateDisciplines: disciplines,
    crossDisciplineChecks: templateConfig.cross_discipline_checks || [],
    aiChecks,
    namingConventions: templateConfig.naming_conventions,
    severityDefinitions: templateConfig.severity_definitions,
    scoreCalculation: templateConfig.score_calculation,
    projectSpecificNotes: templateConfig.project_specific_notes || [],
    templateExtras: modelHealthTemplateExtras(templateConfig),
  };
}

function seedDefaultModelHealthRulesets(projectList = []) {
  const desalinationTemplate = desalinationEpcHealthTemplateDefinition();
  const desalinationRules = modelHealthRulesFromDesalinationTemplate(desalinationTemplate);
  const professionalTemplates = desalinationProfessionalHealthTemplateDefinitions().map((item) => ({
    discipline: item.discipline,
    name: item.config.template.name,
    description: `${item.config.template.discipline} discipline health template for seawater desalination EPC model approval gate checks.`,
    rules: modelHealthRulesFromDesalinationTemplate(item.config),
    gateConfig: {
      mode: "standard",
      errorThreshold: 0,
      requireWarningDisposition: false,
      requireAiDisposition: true,
      aiEnabled: item.config.template.gate_config.ai_check_enabled !== false,
      minScoreToSubmit: item.config.template.gate_config.min_score_to_submit,
    },
    version: item.config.template.version,
  }));
  const templates = [
    {
      discipline: "desalination",
      name: desalinationTemplate.template.name,
      description: "Seawater desalination EPC model health template covering civil, process, electrical, HVAC, cross-discipline consistency, AI anomaly checks, and approval gate rules.",
      rules: desalinationRules,
      gateConfig: {
        mode: "standard",
        errorThreshold: 0,
        requireWarningDisposition: false,
        requireAiDisposition: true,
        aiEnabled: true,
        minScoreToSubmit: desalinationTemplate.template.gate_config.min_score_to_submit,
      },
      version: desalinationTemplate.template.version,
    },
    ...professionalTemplates,
  ];
  return (Array.isArray(projectList) ? projectList : []).flatMap((project) =>
    templates.map((template) => buildDefaultModelHealthRuleset({
      id: `${safeText(project.id, DEFAULT_PROJECT_ID)}-health-${template.discipline}`,
      projectId: safeText(project.id, DEFAULT_PROJECT_ID),
      discipline: template.discipline,
      name: template.name,
      description: template.description,
      rules: template.rules,
      gateConfig: template.gateConfig || {
        mode: "standard",
        errorThreshold: 0,
        requireWarningDisposition: true,
        requireAiDisposition: true,
        aiEnabled: true,
      },
      version: template.version || "1.0.0",
      builtIn: true,
      createdAt: "2026-04-25T00:00:00.000Z",
      updatedAt: "2026-04-25T00:00:00.000Z",
    })),
  );
}

function normalizeQuantityTemplate(template) {
  const value = template && typeof template === "object" ? template : {};
  const createdAt = safeText(value.createdAt, new Date().toISOString());
  const isSeededDefault = safeText(value.id, "").endsWith("-qt-default") && safeText(value.name, "") === "默认工程量统计";
  const name = isSeededDefault ? "海水淡化工程量统计" : safeText(value.name, "工程量模板");
  const description = isSeededDefault
    ? "按对象类型、系统/区域、专业和材质/规格汇总数量、面积、长度、体积。"
    : safeText(value.description, "");
  const config = isSeededDefault
    ? {
	        ...(value.config && typeof value.config === "object" ? value.config : value),
	        name: "海水淡化工程量统计",
	        fields: ["Category", "Type Name", "Equipment Type", "Part Type", "System", "System Name", "Zone", "Plant Area", "Process Unit", "Discipline", "Material", "Specification", "Pipe Spec", "Size", "Diameter", "Area", "Length", "Line Length", "Volume", "Weight"],
	        fieldMappings: {
	          elementType: ["Equipment Type", "Part Type", "Line Class", "Category", "Type Name"],
	          floor: ["Process Unit", "System", "System Name", "Zone", "Plant Area"],
	          discipline: ["Discipline", "System Classification"],
	          material: ["Pipe Spec", "Specification", "Material", "Size"],
	          length: ["Line Length", "Length", "Curve Length"],
	          diameter: ["Nominal Diameter", "Diameter", "DN", "Size"],
	          weight: ["Weight", "Mass"],
	        },
	        groupBy: ["elementType", "floor", "discipline", "material"],
	        metrics: {
	          count: { label: "对象数量", kind: "count", unit: "件" },
	          area: { label: "面积", kind: "sum", source: "area", unit: "m²" },
	          length: { label: "长度", kind: "sum", source: "length", unit: "m" },
	          volume: { label: "体积", kind: "sum", source: "volume", unit: "m³" },
	          pipeLength: { label: "管线米数", kind: "sum", source: "length", unit: "m", appliesTo: { elementTypes: ["Pipe", "管线", "管道"] } },
	          valveCount: { label: "阀门台数", kind: "count", unit: "台", appliesTo: { elementTypes: ["Valve", "阀门"] } },
	          equipmentWeight: { label: "设备重量", kind: "sum", source: "weight", unit: "kg" },
	        },
	        filters: {},
	      }
    : (value.config && typeof value.config === "object" ? value.config : value);
  return {
    id: safeText(value.id, crypto.randomUUID()),
    projectId: safeText(value.projectId, DEFAULT_PROJECT_ID),
    name,
    description,
    config: normalizeTakeoffTemplate({
      ...config,
      id: safeText(value.id, ""),
      name: safeText(name, config?.name || "工程量模板"),
      description: safeText(description, config?.description || ""),
    }),
    createdBy: safeText(value.createdBy, "系统"),
    createdAt,
    updatedAt: safeText(value.updatedAt, createdAt),
  };
}

