function projectSummaryRecord(project, userContext = null) {
  const folderPolicy = projectFolderPolicyPreset(project.folderPolicyKey);
  const memberSource = projectById(project.memberSourceProjectId);
  const templateSource = projectById(project.templateSourceProjectId);
  const projectTemplateRecords = workflowTemplates.filter(
    (item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(project.id, DEFAULT_PROJECT_ID),
  );
  const activeMemberCount = activeProjectMembers(project.id).length;
  return {
    id: project.id,
    name: project.name,
    code: project.code,
    description: project.description || "",
    createdAt: project.createdAt,
    createdBy: safeText(project.createdBy, ""),
    createdByName:
      userById(project.createdBy)?.name ||
      (safeText(project.createdBy, "").toLowerCase() === "system" ? "系统" : safeText(project.createdBy, "系统")),
    folderPolicyKey: folderPolicy.key,
    folderPolicyLabel: folderPolicy.label,
    folderPolicyDescription: folderPolicy.description,
    memberInitMode: normalizeProjectMemberInitMode(project.memberInitMode, "creator_only"),
    memberInitLabel: projectMemberInitModeMeta(project.memberInitMode).label,
    memberSourceProjectId: project.memberSourceProjectId || "",
    memberSourceProjectName: memberSource?.name || "",
    templateInitMode: normalizeProjectTemplateInitMode(project.templateInitMode, "default_templates"),
    templateInitLabel: projectTemplateInitModeMeta(project.templateInitMode).label,
    templateSourceProjectId: project.templateSourceProjectId || "",
    templateSourceProjectName: templateSource?.name || "",
    folderCount: folders.filter((item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === project.id).length,
    memberCount: activeMemberCount,
    templateCount: projectTemplateRecords.length,
    templateAutoExportCount: projectTemplateRecords.filter((item) => Boolean(item.autoExport?.enabled)).length,
    templatePreviewNames: projectTemplateRecords.slice(0, 3).map((item) => safeText(item.name, "未命名模板")).filter(Boolean),
    documentCount: documents.filter((item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === project.id).length,
    workflowCount: workflows.filter((item) => safeText(item.projectId, DEFAULT_PROJECT_ID) === project.id).length,
    isCurrent: userContext ? project.id === safeText(userContext.projectId, DEFAULT_PROJECT_ID) : false,
  };
}

function defaultProjectTemplateBlueprints() {
  const previewProject = normalizeProject({
    id: "project-template-preview",
    name: "当前项目",
    code: "PROJECT",
    folderPolicyKey: "cde_standard",
    memberInitMode: "creator_only",
    templateInitMode: "default_templates",
    createdBy: "system",
    createdAt: "2026-04-24T00:00:00.000Z",
  });
  const previewFolders = createProjectFoldersFromPolicy(previewProject, previewProject.createdAt);
  return seedProjectWorkflowTemplates(previewProject, previewFolders).map((template) => ({
    name: template.name,
    description: template.description,
    stepCount: Array.isArray(template.steps) ? template.steps.length : 0,
    autoExportEnabled: Boolean(template.autoExport?.enabled),
  }));
}

function buildProjectManagementPayload(userContext) {
  const canManageProjects = Boolean(userContext?.isSuperAdmin);
  const visibleProjects = canManageProjects ? [...projects] : projectsForUser(userContext?.user);
  const projectRecords = visibleProjects
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
    .map((project) => projectSummaryRecord(project, userContext));

  return {
    canManageProjects,
    canCreateProjects: canManageProjects,
    currentProjectId: safeText(userContext?.projectId, ""),
    defaultValues: {
      memberInitMode: "creator_only",
      templateInitMode: "default_templates",
      folderPolicyKey: "cde_standard",
    },
    memberInitModes: PROJECT_MEMBER_INIT_MODE_ORDER.map((value) => ({
      value,
      ...projectMemberInitModeMeta(value),
    })),
    templateInitModes: PROJECT_TEMPLATE_INIT_MODE_ORDER.map((value) => ({
      value,
      ...projectTemplateInitModeMeta(value),
    })),
    folderPolicies: PROJECT_FOLDER_POLICY_ORDER.map((value) => {
      const preset = projectFolderPolicyPreset(value);
      return {
        value,
        label: preset.label,
        description: preset.description,
        nodes: preset.nodes.map((node) => ({
          key: node.key,
          name: node.name,
          parentKey: node.parentKey || "",
          accessLevel: node.accessLevel || "edit",
        })),
      };
    }),
    defaultTemplateBlueprints: defaultProjectTemplateBlueprints(),
    sourceProjects: projectRecords.map((item) => ({
      value: item.id,
      label: item.name,
      description: `${item.code} · ${item.memberCount} 成员 · ${item.templateCount} 模板`,
    })),
    projects: projectRecords,
  };
}

function sanitizeProjectCode(value, fallbackName = "") {
  const raw = safeText(value, fallbackName)
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
  return raw;
}

function slugifyProjectIdSeed(value) {
  const raw = safeText(value, "project")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 32);
  return raw || "project";
}

function normalizeCopiedProjectRole(role) {
  const normalized = normalizeProjectRole(role, "reviewer");
  return normalized === "super_admin" ? "project_admin" : normalized;
}

function projectRoleRank(role) {
  return PROJECT_ROLE_ORDER.indexOf(normalizeProjectRole(role, "guest"));
}

function mergeProjectRole(currentRole, nextRole) {
  return projectRoleRank(nextRole) > projectRoleRank(currentRole) ? normalizeProjectRole(nextRole, "guest") : normalizeProjectRole(currentRole, "guest");
}

function ensureLocalProjectMemberAssignment(list, projectId, userId, role, invitedBy, joinedAt) {
  const normalizedRole = normalizeCopiedProjectRole(role);
  const existing = list.find((item) => item.projectId === projectId && item.userId === userId);
  if (existing) {
    existing.role = mergeProjectRole(existing.role, normalizedRole);
    existing.removedAt = "";
    return existing;
  }
  const created = normalizeProjectMember({
    id: crypto.randomUUID(),
    projectId,
    userId,
    role: normalizedRole,
    invitedBy,
    joinedAt,
    removedAt: "",
  });
  list.push(created);
  return created;
}

function cloneProjectMembersToList(sourceProjectId, targetProjectId, createdMembers, userContext, joinedAt) {
  activeProjectMembers(sourceProjectId).forEach((member) => {
    ensureLocalProjectMemberAssignment(
      createdMembers,
      targetProjectId,
      member.userId,
      member.role,
      safeText(userContext.user?.id, "system"),
      joinedAt,
    );
  });
}

function collectTemplateReviewerUserIds(templateDefinitions = []) {
  return Array.from(
    new Set(
      templateDefinitions.flatMap((template) =>
        (template.steps || []).flatMap((step) =>
          (step.reviewers || [])
            .filter((reviewer) => reviewer.type === "user" && safeText(reviewer.userId, ""))
            .map((reviewer) => safeText(reviewer.userId, "")),
        ),
      ),
    ),
  );
}

function ensureTemplateReviewersPresent(targetProjectId, sourceProjectId, createdMembers, templateDefinitions, userContext, joinedAt) {
  collectTemplateReviewerUserIds(templateDefinitions).forEach((userId) => {
    const user = userById(userId);
    if (!user || user.status !== "active") {
      return;
    }
    const sourceMember = activeProjectMemberByUserId(userId, sourceProjectId);
    ensureLocalProjectMemberAssignment(
      createdMembers,
      targetProjectId,
      userId,
      sourceMember?.role || "reviewer",
      safeText(userContext.user?.id, "system"),
      joinedAt,
    );
  });
}

function resolveTargetFolderForTemplateAutoExport(sourceTemplate, targetProjectId, folderCollection = folders) {
  const sourceFolder = folderByIdOrNull(safeText(sourceTemplate?.autoExport?.targetFolderId, ""));
  if (sourceFolder?.policyKey) {
    const mappedFolder = projectFolderByPolicyKey(targetProjectId, sourceFolder.policyKey, folderCollection);
    if (mappedFolder) {
      return mappedFolder.id;
    }
  }
  if (sourceFolder) {
    const matchedByName = (Array.isArray(folderCollection) ? folderCollection : []).find(
      (item) =>
        safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(targetProjectId, DEFAULT_PROJECT_ID) &&
        safeText(item.name, "") === safeText(sourceFolder.name, ""),
    );
    if (matchedByName) {
      return matchedByName.id;
    }
  }
  const fallbackTargets = resolveProjectTemplateTargetFolders(targetProjectId, folderCollection);
  return fallbackTargets.generalFolderId || "";
}

function cloneWorkflowTemplatesForProject(sourceProjectId, targetProject, folderCollection, createdAt, createdBy) {
  return workflowTemplates
    .filter((template) => safeText(template.projectId, DEFAULT_PROJECT_ID) === safeText(sourceProjectId, DEFAULT_PROJECT_ID))
    .map((template) => {
      const targetFolderId = resolveTargetFolderForTemplateAutoExport(template, targetProject.id, folderCollection);
      const targetPath = targetFolderId
        ? projectFolderAbsolutePath(targetProject.id, targetFolderId, folderCollection, targetProject.name)
        : `/${targetProject.name}`;
      return normalizeWorkflowTemplate({
        ...template,
        id: crypto.randomUUID(),
        projectId: targetProject.id,
        projectName: targetProject.name,
        createdBy,
        createdAt,
        updatedAt: createdAt,
        autoExport: normalizeWorkflowAutoExport({
          ...(template.autoExport || {}),
          targetFolderId,
          targetPath,
        }),
        steps: (template.steps || []).map((step, index) => ({
          ...step,
          id: `${targetProject.id}-template-step-${index + 1}-${crypto.randomUUID().slice(0, 6)}`,
        })),
      });
    });
}

function createProjectDefinition(body, userContext) {
  ensureCanManageProjects(userContext);

  const name = safeText(body?.name, "").trim();
  const code = sanitizeProjectCode(body?.code, name);
  const description = safeText(body?.description, "").trim().slice(0, 200);
  const folderPolicyKey = normalizeProjectFolderPolicyKey(body?.folderPolicyKey, "cde_standard");
  const memberInitMode = normalizeProjectMemberInitMode(body?.memberInitMode, "creator_only");
  const templateInitMode = normalizeProjectTemplateInitMode(body?.templateInitMode, "default_templates");
  const memberSourceProjectId = memberInitMode === "copy_project" ? safeText(body?.memberSourceProjectId, "") : "";
  const templateSourceProjectId = templateInitMode === "copy_project" ? safeText(body?.templateSourceProjectId, "") : "";

  if (!name) {
    const error = new Error("项目名称不能为空。");
    error.statusCode = 400;
    throw error;
  }
  if (!code || code.length < 3) {
    const error = new Error("项目编码不能为空，且至少需要 3 位。");
    error.statusCode = 400;
    throw error;
  }
  if (projects.some((item) => safeText(item.name, "").toLowerCase() === name.toLowerCase())) {
    const error = new Error("已存在同名项目，请更换项目名称。");
    error.statusCode = 409;
    throw error;
  }
  if (projects.some((item) => safeText(item.code, "").toUpperCase() === code.toUpperCase())) {
    const error = new Error("已存在相同项目编码，请更换后再创建。");
    error.statusCode = 409;
    throw error;
  }
  if (memberInitMode === "copy_project" && !projectById(memberSourceProjectId)) {
    const error = new Error("请选择一个有效的成员复制来源项目。");
    error.statusCode = 400;
    throw error;
  }
  if (templateInitMode === "copy_project" && !projectById(templateSourceProjectId)) {
    const error = new Error("请选择一个有效的模板复制来源项目。");
    error.statusCode = 400;
    throw error;
  }

  const createdAt = new Date().toISOString();
  const projectId = `project-${slugifyProjectIdSeed(name)}-${crypto.randomUUID().slice(0, 8)}`;
  const createdBy = safeText(userContext.user?.id, "system");
  const project = normalizeProject({
    id: projectId,
    name,
    code,
    description,
    folderPolicyKey,
    memberInitMode,
    memberSourceProjectId,
    templateInitMode,
    templateSourceProjectId,
    createdBy,
    createdAt,
    guestPolicy: {
      canDownload: false,
      canAnnotate: true,
      canReply: true,
    },
  });

  const createdFolders = createProjectFoldersFromPolicy(project, createdAt);
  const folderCollection = [...folders, ...createdFolders];
  const createdMembers = [];
  ensureLocalProjectMemberAssignment(
    createdMembers,
    project.id,
    safeText(userContext.user?.id, ""),
    "project_admin",
    createdBy,
    createdAt,
  );

  if (memberInitMode === "copy_project") {
    cloneProjectMembersToList(memberSourceProjectId, project.id, createdMembers, userContext, createdAt);
  }

  let createdTemplates = [];
  if (templateInitMode === "default_templates") {
    createdTemplates = seedProjectWorkflowTemplates(project, folderCollection).map((template) =>
      normalizeWorkflowTemplate({
        ...template,
        id: crypto.randomUUID(),
        createdAt,
        updatedAt: createdAt,
        createdBy,
      }),
    );
    ensureTemplateReviewersPresent(project.id, DEFAULT_PROJECT_ID, createdMembers, createdTemplates, userContext, createdAt);
  } else if (templateInitMode === "copy_project") {
    createdTemplates = cloneWorkflowTemplatesForProject(templateSourceProjectId, project, folderCollection, createdAt, createdBy);
    ensureTemplateReviewersPresent(project.id, templateSourceProjectId, createdMembers, createdTemplates, userContext, createdAt);
  }

  projects.unshift(project);
  folders.push(...createdFolders);
  projectMembers.push(...createdMembers);
  workflowTemplates.unshift(...createdTemplates);
  upsertProjectEmailNotificationSetting({
    projectId: project.id,
    updatedBy: createdBy,
    updatedAt: createdAt,
  });
  persistStore();
  return project;
}

function replaceProjectNameInAbsolutePath(pathLabel, previousProjectName, nextProjectName) {
  const rawPath = safeText(pathLabel, "");
  if (!rawPath) {
    return "";
  }
  const segments = rawPath
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean);
  if (!segments.length) {
    return "";
  }
  if (segments[0] === safeText(previousProjectName, "")) {
    segments[0] = safeText(nextProjectName, segments[0]);
  }
  return `/${segments.join("/")}`;
}

function syncProjectLinkedDisplayFields(project, previousProjectName, updatedAt) {
  workflowTemplates.forEach((template) => {
    if (safeText(template.projectId, DEFAULT_PROJECT_ID) !== project.id) {
      return;
    }
    template.projectName = project.name;
    if (template.autoExport && typeof template.autoExport === "object") {
      template.autoExport.targetPath = safeText(template.autoExport.targetFolderId, "")
        ? workflowAutoExportTargetPath(template.autoExport.targetFolderId, template.autoExport.targetPath, project.id)
        : replaceProjectNameInAbsolutePath(template.autoExport.targetPath, previousProjectName, project.name);
    }
    template.updatedAt = updatedAt;
  });

  workflows.forEach((workflow) => {
    if (safeText(workflow.projectId, DEFAULT_PROJECT_ID) !== project.id) {
      return;
    }
    workflow.projectName = project.name;
    if (workflow.autoExport && typeof workflow.autoExport === "object") {
      workflow.autoExport.targetPath = safeText(workflow.autoExport.targetFolderId, "")
        ? workflowAutoExportTargetPath(workflow.autoExport.targetFolderId, workflow.autoExport.targetPath, project.id)
        : replaceProjectNameInAbsolutePath(workflow.autoExport.targetPath, previousProjectName, project.name);
    }
    workflow.updatedAt = updatedAt;
  });
}

function updateProjectDefinition(projectId, body, userContext) {
  ensureCanManageProjects(userContext);

  const project = projectById(projectId);
  if (!project) {
    const error = new Error("未找到要编辑的项目。");
    error.statusCode = 404;
    throw error;
  }

  const hasName = body && Object.prototype.hasOwnProperty.call(body, "name");
  const hasCode = body && Object.prototype.hasOwnProperty.call(body, "code");
  const hasDescription = body && Object.prototype.hasOwnProperty.call(body, "description");
  const name = String(hasName ? body?.name ?? "" : project.name || "").trim();
  const code = sanitizeProjectCode(hasCode ? body?.code ?? "" : project.code || "", "");
  const description = String(hasDescription ? body?.description ?? "" : project.description || "").trim().slice(0, 200);

  if (!name) {
    const error = new Error("项目名称不能为空。");
    error.statusCode = 400;
    throw error;
  }
  if (!code || code.length < 3) {
    const error = new Error("项目编码不能为空，且至少需要 3 位。");
    error.statusCode = 400;
    throw error;
  }
  if (
    projects.some(
      (item) =>
        item.id !== project.id &&
        safeText(item.name, "").toLowerCase() === name.toLowerCase(),
    )
  ) {
    const error = new Error("已存在同名项目，请更换项目名称。");
    error.statusCode = 409;
    throw error;
  }
  if (
    projects.some(
      (item) =>
        item.id !== project.id &&
        safeText(item.code, "").toUpperCase() === code.toUpperCase(),
    )
  ) {
    const error = new Error("已存在相同项目编码，请更换后再保存。");
    error.statusCode = 409;
    throw error;
  }

  const previous = {
    name: project.name,
    code: project.code,
    description: project.description || "",
  };
  const updatedAt = new Date().toISOString();

  project.name = name;
  project.code = code;
  project.description = description;

  syncProjectLinkedDisplayFields(project, previous.name, updatedAt);
  persistStore();
  return {
    project,
    previous,
  };
}

function upsertFolderPermission(folderId, body, userContext) {
  const project = userContext?.project || projectById(userContext?.projectId) || seedDefaultProject();
  if (!isProjectAdminRole(userContext.projectRole)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以设置文件夹级权限。");
  }

  const userId = safeText(body.userId, "");
  if (!userId || !userById(userId)) {
    const error = new Error("未找到要设置权限的成员。");
    error.statusCode = 400;
    throw error;
  }

  const requestedPermission = normalizeFolderPermissionLevel(body.permission, "viewer");
  const permission = clipFolderPermissionForUser(userId, requestedPermission, project.id);
  const existing = folderPermissions.find(
    (item) => item.projectId === project.id && item.folderId === folderId && item.userId === userId,
  );

  if (existing) {
    existing.permission = permission;
    existing.setBy = safeText(userContext.user?.id, "system");
    existing.updatedAt = new Date().toISOString();
    persistStore();
    return existing;
  }

  const created = normalizeFolderPermission({
    id: crypto.randomUUID(),
    projectId: project.id,
    folderId,
    userId,
    permission,
    setBy: safeText(userContext.user?.id, "system"),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
  folderPermissions.push(created);
  persistStore();
  return created;
}

function updateFolderPermissionRecord(record, body, userContext) {
  if (!isProjectAdminRole(userContext.projectRole)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以设置文件夹级权限。");
  }
  if (safeText(record.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    throw permissionDeniedError("不能修改当前项目之外的目录权限。");
  }
  record.permission = clipFolderPermissionForUser(
    record.userId,
    normalizeFolderPermissionLevel(body.permission, record.permission),
    record.projectId,
  );
  record.setBy = safeText(userContext.user?.id, "system");
  record.updatedAt = new Date().toISOString();
  persistStore();
  return record;
}

function deleteFolderPermissionRecord(record, userContext) {
  if (!isProjectAdminRole(userContext.projectRole)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以设置文件夹级权限。");
  }
  if (safeText(record.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    throw permissionDeniedError("不能删除当前项目之外的目录权限。");
  }
  folderPermissions = folderPermissions.filter((item) => item.id !== record.id);
  persistStore();
}

function ensureCanManageWorkflowTemplates(userContext) {
  if (!isProjectAdminRole(userContext.projectRole) && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("仅项目管理员和超级管理员可以配置流程模板。");
  }
}

function createWorkflowTemplate(body, userContext = SYSTEM_USER_CONTEXT) {
  const project = userContext?.project || projectById(userContext?.projectId) || seedDefaultProject();
  ensureCanManageWorkflowTemplates(userContext);
  const input = {
    ...body,
    id: crypto.randomUUID(),
    projectId: safeText(body.projectId, project.id),
    projectName: safeText(body.projectName, project.name),
    createdBy: safeText(userContext.user?.id, "system"),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  validateWorkflowTemplateRoleInputs(input);
  const template = validateWorkflowTemplateDefinition(normalizeWorkflowTemplate(input));
  workflowTemplates.unshift(template);
  persistStore();
  return template;
}

function updateWorkflowTemplate(templateId, body, userContext = SYSTEM_USER_CONTEXT) {
  ensureCanManageWorkflowTemplates(userContext);
  const existing = workflowTemplateById(templateId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  if (!existing) {
    const error = new Error("Workflow template not found");
    error.statusCode = 404;
    throw error;
  }
  const input = {
    ...existing,
    ...body,
    id: existing.id,
    createdAt: existing.createdAt,
    createdBy: existing.createdBy,
    updatedAt: new Date().toISOString(),
  };
  validateWorkflowTemplateRoleInputs(input);
  const updated = validateWorkflowTemplateDefinition(normalizeWorkflowTemplate(input));
  Object.assign(existing, updated);
  persistStore();
  return existing;
}

function deleteWorkflowTemplate(templateId, userContext = SYSTEM_USER_CONTEXT) {
  ensureCanManageWorkflowTemplates(userContext);
  const existing = workflowTemplateById(templateId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  if (!existing) {
    const error = new Error("Workflow template not found");
    error.statusCode = 404;
    throw error;
  }
  if (workflows.some((workflow) => workflow.templateId === templateId && workflow.status === "running")) {
    const error = new Error("当前还有运行中的流程实例正在使用该模板，暂时不能删除。");
    error.statusCode = 409;
    throw error;
  }
  workflowTemplates = workflowTemplates.filter((item) => item.id !== templateId);
  persistStore();
  return existing;
}

async function createWorkflowInstance(body, userContext = SYSTEM_USER_CONTEXT) {
  const project = userContext?.project || projectById(userContext?.projectId) || seedDefaultProject();
  const actorName = safeText(body.actor, actorDisplayName(userContext));
  const template = validateWorkflowTemplateDefinition(resolveWorkflowTemplateForLaunch(body, null, userContext));
  const role = safeText(userContext?.projectRole, "guest");
  const canLaunchTemplate =
    isProjectAdminRole(role) ||
    isSuperAdmin(userContext) ||
    (isWorkflowStarterRole(role) && (template.allowedRoles || []).includes(role));
  if (!canLaunchTemplate) {
    throw permissionDeniedError("当前角色不能使用该流程模板发起审批流。");
  }

  const requestedIds = Array.isArray(body.fileIds)
    ? body.fileIds
    : Array.isArray(body.documentIds)
      ? body.documentIds
      : [];
  const docIds = Array.from(new Set(requestedIds.map((item) => safeText(item, "")).filter(Boolean)));
  if (!docIds.length) {
    const error = new Error("请至少选择一个文件发起流程。");
    error.statusCode = 400;
    throw error;
  }

  const docs = docIds.map((id) => requireDocument(id, userContext));
  const healthGateOverrides = [];
  docs.forEach((doc) => {
    assertDocumentCapability(doc, "workflow.start", userContext, "所选文件中包含无权限发起流程的项。");
    assertDrawingPrecheckGateAllowsWorkflow(doc);
    const healthOverride = assertModelHealthGateAllowsWorkflow(doc, body, userContext);
    if (healthOverride) {
      healthGateOverrides.push(healthOverride);
    }
    if (safeText(doc.activeWorkflowId, "")) {
      const runningWorkflow = workflowById(doc.activeWorkflowId, project.id);
      if (runningWorkflow && runningWorkflow.status === "running") {
        const error = new Error(`文件 ${doc.name} 当前已有运行中的流程，需先撤回或完成后再发起新流程。`);
        error.statusCode = 409;
        throw error;
      }
    }
  });

  const createdAt = new Date().toISOString();
  const steps = (template.steps || []).map((step, index) =>
    normalizeWorkflowStepState({
      ...step,
      status: index === 0 ? "active" : "pending",
      startedAt: index === 0 ? createdAt : "",
      completedAt: "",
      reviewers: resolveWorkflowTemplateStepReviewers(step, project.id).map((reviewer) => {
        const reviewerUser = userById(reviewer.userId);
        return {
          userId: reviewerUser?.id || safeText(reviewer.userId, ""),
          name: reviewerUser?.name || reviewer.name,
          status: "pending",
          actedAt: "",
          comment: "",
        };
      }),
    }, index),
  );

  const workflow = normalizeWorkflowInstance({
    id: crypto.randomUUID(),
    workflowName: safeText(body.workflowName || body.name, template.name),
    templateId: safeText(template.id, ""),
    templateName: template.name,
    templateCategory: template.category,
    projectId: project.id,
    projectName: project.name,
    initiator: safeText(body.initiator, actorName),
    initiatorUserId: safeText(userContext?.user?.id, ""),
    description: safeText(String(body.description || body.versionDescription || "").slice(0, 200), ""),
    dueDate: safeText(body.dueDate, workflowDueDateFromTemplate(template)),
    status: "running",
    currentStepIndex: 0,
    steps,
    fileRefs: docs.map((doc) => workflowFileRefFromDocument(doc)),
    activity: [
      {
        actor: actorName,
        label: "发起流程",
        note: `流程 ${safeText(body.workflowName || body.name, template.name)} 已提交给 ${workflowStepPendingReviewerNames(steps[0]).join(" / ") || "审批人"}`,
        timestamp: createdAt,
      },
    ],
    autoExport: normalizeWorkflowAutoExport(template.autoExport),
    healthGateOverrides,
    createdAt,
    updatedAt: createdAt,
  });

  workflows.unshift(workflow);
  docs.forEach((doc) => {
    syncDocumentFromWorkflowInstance(doc, workflow);
    touchDocument(doc);
    addActivity(
      doc,
      actorName,
      "发起流程",
      `流程 ${workflow.workflowName} 已提交给 ${workflowStepPendingReviewerNames(workflow.steps[0]).join(" / ") || "审批人"}`,
    );
    const override = healthGateOverrides.find((item) => item.fileId === doc.id);
    if (override) {
      addActivity(doc, actorName, "健康度检查豁免", override.reason);
      appendAuditLog(userContext, "model_health.gate.override", "document", doc.id, {
        workflowId: workflow.id,
        taskId: override.taskId,
        reason: override.reason,
        exemptResultIds: override.exemptResultIds,
      });
    }
  });
  persistStore();
  return workflow;
}

async function updateWorkflowInstanceAction(workflow, body, userContext = SYSTEM_USER_CONTEXT) {
  const action = safeText(body.action, "");
  const actor = safeText(body.actor, actorDisplayName(userContext));
  const permissions = workflowPermissionsForInstance(workflow, userContext);
  const isAdmin = isProjectAdminRole(safeText(userContext?.projectRole, "guest")) || isSuperAdmin(userContext);
  const currentStep = workflowCurrentStep(workflow);
  const currentStepIndex = workflow.currentStepIndex;
  const currentDocs = (workflow.fileRefs || [])
    .map((fileRef) => documents.find((item) => item.id === fileRef.docId))
    .filter(Boolean);

  if (action === "withdrawFlow") {
    if (!permissions.withdraw) {
      throw permissionDeniedError("你没有撤回当前流程的权限。");
    }
    workflow.status = "withdrawn";
    workflow.updatedAt = new Date().toISOString();
    if (currentStep) {
      currentStep.status = "skipped";
      currentStep.completedAt = workflow.updatedAt;
    }
    workflow.activity.unshift(
      normalizeWorkflowActivityItem({
        actor,
        label: "撤回流程",
        note: "流程已撤回，文件恢复为待发起状态。",
        timestamp: workflow.updatedAt,
      }),
    );
    currentDocs.forEach((doc) => {
      syncDocumentFromWorkflowInstance(doc, workflow);
      touchDocument(doc);
      addActivity(doc, actor, "撤回流程", "流程已撤回，文件恢复为待发起状态");
    });
    persistStore();
    return workflow;
  }

  if (!permissions.run || !currentStep) {
    throw permissionDeniedError("你没有执行当前审批动作的权限。");
  }

  const reviewer =
    currentStep.reviewers.find(
      (item) => item.status === "pending" && (workflowReviewerMatches(item, userContext) || isAdmin),
    ) || null;
  if (!reviewer) {
    const error = new Error("当前节点没有可执行的审批人。");
    error.statusCode = 409;
    throw error;
  }

  const now = new Date().toISOString();
  const currentIsFinalStep = workflowIsFinalStep(workflow);

  if (["returnToInitiator", "rejectFlow"].includes(action)) {
    reviewer.status = "rejected";
    reviewer.actedAt = now;
    reviewer.comment = safeText(body.comment, "");
    currentStep.status = "rejected";
    currentStep.completedAt = now;
    workflow.status = "rejected";
    workflow.updatedAt = now;
    workflow.activity.unshift(
      normalizeWorkflowActivityItem({
        actor,
        label: currentIsFinalStep ? "驳回修改" : "退回发起者",
        note: currentIsFinalStep ? "终审未通过，流程退回发起者修改。" : "当前流程已退回发起者修改。",
        timestamp: now,
      }),
    );
    currentDocs.forEach((doc) => {
      syncDocumentFromWorkflowInstance(doc, workflow);
      touchDocument(doc);
      addActivity(
        doc,
        actor,
        currentIsFinalStep ? "驳回修改" : "退回发起者",
        currentIsFinalStep ? "终审未通过，文档退回发起者修改" : "请根据批注和备注修改后重新发起流程",
      );
    });
    persistStore();
    return workflow;
  }

  if (!["submitToApprover", "approveFlow"].includes(action)) {
    const error = new Error("Unsupported workflow action");
    error.statusCode = 400;
    throw error;
  }

  reviewer.status = "approved";
  reviewer.actedAt = now;
  reviewer.comment = safeText(body.comment, "");

  const pendingReviewers = currentStep.reviewers.filter((item) => item.status === "pending");
  if (currentStep.mode === "parallel_any") {
    pendingReviewers.forEach((item) => {
      item.status = "skipped";
      item.actedAt = now;
    });
  }

  const remainingPending = currentStep.reviewers.filter((item) => item.status === "pending");
  const currentStepApproved =
    currentStep.mode === "parallel_all"
      ? currentStep.reviewers.every((item) => item.status === "approved")
      : currentStep.mode === "parallel_any"
        ? currentStep.reviewers.some((item) => item.status === "approved")
        : reviewer.status === "approved";

  if (!currentStepApproved && remainingPending.length) {
    workflow.updatedAt = now;
    workflow.activity.unshift(
      normalizeWorkflowActivityItem({
        actor,
        label: "会签通过",
        note: `${reviewer.name} 已完成审批，等待 ${remainingPending.map((item) => item.name).join(" / ")} 继续处理。`,
        timestamp: now,
      }),
    );
    currentDocs.forEach((doc) => {
      syncDocumentFromWorkflowInstance(doc, workflow);
      touchDocument(doc);
      addActivity(doc, actor, "会签通过", `${reviewer.name} 已完成审批，等待其他并联节点继续处理`);
    });
    persistStore();
    return workflow;
  }

  currentStep.status = "approved";
  currentStep.completedAt = now;

  if (currentStepIndex < workflow.steps.length - 1) {
    const nextStep = workflow.steps[currentStepIndex + 1];
    workflow.currentStepIndex = currentStepIndex + 1;
    nextStep.status = "active";
    nextStep.startedAt = now;
    workflow.updatedAt = now;
    const nextOwners = workflowStepPendingReviewerNames(nextStep).join(" / ") || "下一节点";
    const label = workflow.currentStepIndex >= workflow.steps.length - 1 ? "提交终审" : "推进流程";
    const note =
      label === "提交终审"
        ? `已转交 ${nextOwners} 进行最终审阅。`
        : `已进入 ${nextStep.name}，当前责任人 ${nextOwners}。`;
    workflow.activity.unshift(
      normalizeWorkflowActivityItem({
        actor,
        label,
        note,
        timestamp: now,
      }),
    );
    currentDocs.forEach((doc) => {
      syncDocumentFromWorkflowInstance(doc, workflow);
      touchDocument(doc);
      addActivity(doc, actor, label, note);
    });
    persistStore();
    return workflow;
  }

  workflow.status = "approved";
  workflow.updatedAt = now;
  workflow.activity.unshift(
    normalizeWorkflowActivityItem({
      actor,
      label: "批准归档",
      note: "流程已全部通过，文件进入归档状态。",
      timestamp: now,
    }),
  );
  currentDocs.forEach((doc) => {
    syncDocumentFromWorkflowInstance(doc, workflow);
    touchDocument(doc);
    addActivity(doc, actor, "批准归档", "文档已完成审阅并进入归档状态");
  });
  await maybeRunWorkflowAutoExport(workflow);
  persistStore();
  return workflow;
}

function normalizeWorkflowCrsManualCheckItems(value) {
  if (Array.isArray(value)) {
    return value.map((item) => safeText(item, "")).filter(Boolean).slice(0, 50);
  }
  if (typeof value === "string") {
    return value
      .split(/\r?\n/)
      .map((item) => safeText(item, ""))
      .filter(Boolean)
      .slice(0, 50);
  }
  return [];
}

function normalizeWorkflowCrsDraftReportInput(report, fallback = {}) {
  const value = report && typeof report === "object" ? report : {};
  const fallbackValue = fallback && typeof fallback === "object" ? fallback : {};
  const items = Array.isArray(value.items) ? value.items : fallbackValue.items;
  return normalizeWorkflowCrsDraft({
    report: {
      fileName: safeText(value.fileName, safeText(fallbackValue.fileName, "")),
      versionLabel: safeText(value.versionLabel, safeText(fallbackValue.versionLabel, "")),
      approvalCycle: safeText(value.approvalCycle, safeText(fallbackValue.approvalCycle, "")),
      executiveSummary: safeText(String(value.executiveSummary || "").slice(0, 4000), safeText(fallbackValue.executiveSummary, "")),
      unresolvedSummary: safeText(String(value.unresolvedSummary || "").slice(0, 4000), safeText(fallbackValue.unresolvedSummary, "")),
      manualCheckItems: normalizeWorkflowCrsManualCheckItems(value.manualCheckItems),
      items: Array.isArray(items) ? items.map((item, index) => normalizeWorkflowCrsDraftItem(item, index)) : [],
    },
  }).report;
}

function updateWorkflowCrsDraft(workflow, body, userContext = SYSTEM_USER_CONTEXT) {
  const actor = actorDisplayName(userContext);
  const actorUserId = safeText(userContext?.user?.id, "");
  const current = normalizeWorkflowCrsDraft(workflow.crsDraft);
  const nextReport = normalizeWorkflowCrsDraftReportInput(body?.report, current.report);
  if (!nextReport.executiveSummary && !nextReport.items.length) {
    const error = new Error("CRS 草稿至少需要保留摘要或一条意见。");
    error.statusCode = 400;
    throw error;
  }

  const now = new Date().toISOString();
  const manualCheckCount =
    nextReport.manualCheckItems.length ||
    nextReport.items.filter((item) => item.needsHumanReview).length;
  const unresolvedCount = nextReport.items.filter((item) => item.status !== "closed").length;
  workflow.crsDraft = normalizeWorkflowCrsDraft({
    ...current,
    status: "succeeded",
    progress: 100,
    error: "",
    message: body?.confirm ? "CRS 草稿已确认并纳入报告。" : "CRS 草稿已保存。",
    updatedAt: now,
    confirmedAt: body?.confirm ? now : current.confirmedAt,
    confirmedBy: body?.confirm ? actor : current.confirmedBy,
    confirmedByUserId: body?.confirm ? actorUserId : current.confirmedByUserId,
    sourceStats: {
      ...(current.sourceStats || {}),
      itemCount: nextReport.items.length,
      unresolvedCount,
      manualCheckCount,
    },
    report: nextReport,
  });
  workflow.updatedAt = now;
  workflow.activity.unshift(
    normalizeWorkflowActivityItem({
      actor,
      label: body?.confirm ? "确认 CRS 草稿" : "更新 CRS 草稿",
      note: body?.confirm
        ? `已确认 ${nextReport.items.length} 条 CRS 草稿，并纳入当前流程报告。`
        : `已更新 CRS 草稿，当前共 ${nextReport.items.length} 条结构化意见。`,
      timestamp: now,
    }),
  );
  persistStore();
  return workflow;
}

async function appendDocumentVersion(doc, body, userContext = SYSTEM_USER_CONTEXT) {
  const actor = safeText(body.actor, "系统");
  const checkedOutBy = currentCheckedOutBy(doc);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.uploadVersion) {
    if (checkedOutBy && checkedOutBy !== actor) {
      const error = new Error(`当前文件已被 ${checkedOutBy} 占用，其他人只能只读下载，不能上传新版本覆盖`);
      error.statusCode = 409;
      throw error;
    }
    throw permissionDeniedError(
      permissions.approvalLocked
        ? "文件处于审批锁定状态，需先撤回或完成流程后才能上传新版本。"
        : "你没有上传新版本的权限。",
    );
  }

  if (checkedOutBy && checkedOutBy !== actor && !permissions.forceUnlock) {
    const error = new Error(`当前文件已被 ${checkedOutBy} 占用，其他人只能只读下载，不能上传新版本覆盖`);
    error.statusCode = 409;
    throw error;
  }

  const nextName = safeText(body.name, doc.name);
  const mimeType = inferDocumentMimeType(nextName, body.mimeType || doc.mimeType);
  const nextDrawingMetadata =
    body.drawingMetadata === undefined
      ? resolveDocumentDrawingMetadataRelations(normalizeDocumentDrawingMetadata(doc.drawingMetadata), doc.projectId, doc.id)
      : resolveDocumentDrawingMetadataRelations(normalizeDocumentDrawingMetadata(body.drawingMetadata), doc.projectId, doc.id);
  const nextSpecMetadata =
    body.specMetadata === undefined
      ? normalizeDocumentSpecMetadata(doc.specMetadata)
      : normalizeDocumentSpecMetadata(body.specMetadata);
  assertDrawingMetadataReady(nextDrawingMetadata);
  const uploadSource = documentUploadSourceFromBody(body);
  const storedFileName = `${crypto.randomUUID()}${storageExtensionForName(nextName, mimeType)}`;
  await uploadSource.writeTo(storedFileName, mimeType);

  const uploadedAt = new Date().toISOString();
  const actorId = safeText(userContext?.user?.id, "");
  const nextVersion = nextVersionLabel(doc.version, activeVersionEntries(doc).length || 1);
  const nextVersionId = crypto.randomUUID();
  const nextEntry = normalizeVersionEntry(
    {
      id: nextVersionId,
      version: nextVersion,
      versionNo: versionNumber(nextVersion),
      name: nextName,
      storedFileName,
      size: uploadSource.size,
      mimeType,
      uploadedAt,
      uploadedById: actorId,
      uploadedBy: actor,
      note: safeText(body.note, "—"),
      parseStatus: "processing",
      isCurrent: true,
      share: normalizeShare({ enabled: false }),
    },
    currentVersionSnapshot({
      ...doc,
      currentVersionId: nextVersionId,
      name: nextName,
      version: nextVersion,
      storedFileName,
      size: uploadSource.size,
      mimeType,
      updatedAt: uploadedAt,
      uploaderId: actorId,
      uploader: actor,
      parseStatus: "processing",
    }),
  );
  scheduleVersionParsing(nextEntry);

  doc.name = nextName;
  doc.storedFileName = storedFileName;
  doc.size = uploadSource.size;
  doc.version = nextVersion;
  doc.currentVersionId = nextVersionId;
  doc.updatedAt = uploadedAt;
  doc.uploaderId = actorId;
  doc.uploader = actor;
  doc.mimeType = mimeType;
  doc.isPdf = mimeType === "application/pdf";
  doc.drawingMetadata = nextDrawingMetadata;
  doc.specMetadata = nextSpecMetadata;
  doc.parseStatus = "processing";
  doc.parseReadyAt = safeText(nextEntry.parseReadyAt, "");
  doc.lastExportFileName = "";
  doc.status = "uploaded";
  doc.versionHistory = Array.isArray(doc.versionHistory) ? doc.versionHistory : [];
  markCurrentVersion(doc, nextVersionId);
  doc.versionHistory.push(nextEntry);

  touchFolder(doc.parentId);
  addActivity(doc, actor, "上传新版本", `${nextName} 已更新为 ${nextVersion}${body.note ? ` · ${body.note}` : ""}`);
  addActivity(doc, "系统", "版本通知", "已通知分享接收者、流程参与人和项目管理员关注新版本变更");
  persistStore();
  await bestEffortProjectEmailNotification("versionUploaded", {
    document: doc,
    versionEntry: nextEntry,
    userContext,
    occurredAt: uploadedAt,
    note: safeText(body.note, ""),
  });
  queueApsTranslationForDocument(doc, actor, {
    reason: `模型文件已更新为 ${nextVersion}`,
  });
  const ocrResult = enqueueDrawingOcrTask(doc, nextEntry, userContext, {
    reason: "version_upload",
  });
  if (ocrResult.job) {
    scheduleAsyncJob(ocrResult.job);
  }
  return doc;
}

async function restoreDocumentVersion(doc, versionId, actor, userContext = SYSTEM_USER_CONTEXT) {
  const entry = requireVersionEntry(doc, versionId);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.uploadVersion) {
    throw permissionDeniedError(
      permissions.approvalLocked
        ? "文件处于审批锁定状态，需先撤回或完成流程后才能还原历史版本。"
        : "你没有还原历史版本的权限。",
    );
  }

  const checkedOutBy = currentCheckedOutBy(doc);
  if (checkedOutBy && checkedOutBy !== actor && !permissions.forceUnlock) {
    const error = new Error(`当前文件已被 ${checkedOutBy} 占用，其他人只能只读下载，不能上传新版本覆盖`);
    error.statusCode = 409;
    throw error;
  }

  if (!safeText(entry.storedFileName, "") || !(await storageService.uploads.exists(entry.storedFileName))) {
    const error = new Error("Source version file not found");
    error.statusCode = 404;
    throw error;
  }

  const mimeType = inferDocumentMimeType(doc.name, entry.mimeType || doc.mimeType);
  const storedFileName = `${crypto.randomUUID()}${storageExtensionForName(entry.name || doc.name, mimeType)}`;
  await storageService.uploads.copyObject(entry.storedFileName, storedFileName);

  const uploadedAt = new Date().toISOString();
  const actorId = safeText(userContext?.user?.id, "");
  const nextVersion = nextVersionLabel(doc.version, activeVersionEntries(doc).length || 1);
  const nextVersionId = crypto.randomUUID();
  const restoredEntry = normalizeVersionEntry(
    {
      id: nextVersionId,
      version: nextVersion,
      versionNo: versionNumber(nextVersion),
      name: doc.name,
      storedFileName,
      size: Number(entry.size || doc.size || 0),
      mimeType,
      uploadedAt,
      uploadedById: actorId,
      uploadedBy: actor,
      note: `还原自 ${safeText(entry.version, "历史版本")}`,
      parseStatus: "done",
      isCurrent: true,
      share: normalizeShare({ enabled: false }),
    },
    currentVersionSnapshot({
      ...doc,
      currentVersionId: nextVersionId,
      storedFileName,
      size: Number(entry.size || doc.size || 0),
      mimeType,
      updatedAt: uploadedAt,
      uploaderId: actorId,
      uploader: actor,
      version: nextVersion,
      parseStatus: "done",
    }),
  );
  doc.storedFileName = storedFileName;
  doc.size = Number(entry.size || doc.size || 0);
  doc.version = nextVersion;
  doc.currentVersionId = nextVersionId;
  doc.updatedAt = uploadedAt;
  doc.uploaderId = actorId;
  doc.uploader = actor;
  doc.mimeType = mimeType;
  doc.isPdf = mimeType === "application/pdf";
  doc.parseStatus = "done";
  doc.parseReadyAt = "";
  doc.lastExportFileName = "";
  doc.status = "uploaded";
  doc.versionHistory = Array.isArray(doc.versionHistory) ? doc.versionHistory : [];
  markCurrentVersion(doc, nextVersionId);
  doc.versionHistory.push(restoredEntry);

  touchFolder(doc.parentId);
  addActivity(doc, actor, "还原历史版本", `${doc.name} 已从 ${safeText(entry.version, "历史版本")} 还原并生成 ${nextVersion}`);
  persistStore();
  await bestEffortProjectEmailNotification("versionUploaded", {
    document: doc,
    versionEntry: restoredEntry,
    userContext,
    occurredAt: uploadedAt,
    note: `还原自 ${safeText(entry.version, "历史版本")}`,
  });
  queueApsTranslationForDocument(doc, actor, {
    reason: `模型文件已从 ${safeText(entry.version, "历史版本")} 还原`,
  });
  return doc;
}

function setCurrentDocumentVersion(doc, versionId, actor, userContext = SYSTEM_USER_CONTEXT) {
  const entry = requireVersionEntry(doc, versionId);
  if (entry.id === doc.currentVersionId || entry.isCurrent) {
    return doc;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.uploadVersion) {
    throw permissionDeniedError(
      permissions.approvalLocked
        ? "文件处于审批锁定状态，需先撤回或完成流程后才能切换当前版本。"
        : "你没有切换当前版本的权限。",
    );
  }

  const checkedOutBy = currentCheckedOutBy(doc);
  if (checkedOutBy && checkedOutBy !== actor && !permissions.forceUnlock) {
    const error = new Error(`当前文件已被 ${checkedOutBy} 占用，其他人只能只读下载，不能切换当前版本`);
    error.statusCode = 409;
    throw error;
  }

  markCurrentVersion(doc, entry.id);
  syncCurrentVersionFromEntry(doc, entry);
  doc.status = "uploaded";
  doc.lastExportFileName = "";
  touchDocument(doc);
  addActivity(doc, actor, "设为当前版本", `${doc.name} 已切换为 ${entry.version} 作为当前生效版本`);
  persistStore();
  queueApsTranslationForDocument(doc, actor, {
    reason: `当前模型版本切换为 ${entry.version}`,
  });
  return doc;
}

function updateDocumentVersion(doc, versionId, body, actor, userContext = SYSTEM_USER_CONTEXT) {
  const entry = requireVersionEntry(doc, versionId);
  const changes = [];
  const permissions = documentPermissionsForUser(doc, userContext);

  if (body.note !== undefined) {
    if (!permissions.uploadVersion) {
      throw permissionDeniedError("你没有修改版本说明的权限。");
    }
    const nextNote = safeText(String(body.note || "").slice(0, 200), "—");
    if (entry.note !== nextNote) {
      entry.note = nextNote;
      changes.push(`更新 ${entry.version} 的版本说明`);
    }
  }

  if (body.share !== undefined) {
    if (!permissions.share) {
      throw permissionDeniedError("你没有生成或修改版本分享链接的权限。");
    }
    const nextShare = normalizeShare({
      ...(entry.share || {}),
      ...(body.share || {}),
    });

    if (
      entry.share?.enabled !== nextShare.enabled ||
      entry.share?.permission !== nextShare.permission ||
      entry.share?.expiresAt !== nextShare.expiresAt ||
      entry.share?.token !== nextShare.token
    ) {
      entry.share = nextShare;
      changes.push(
        nextShare.enabled
          ? `${entry.version} 的锁定分享已更新（${sharePermissionLabel(nextShare.permission)}，截止 ${nextShare.expiresAt}）`
          : `关闭 ${entry.version} 的锁定分享`,
      );
    }
  }

  if (!changes.length) {
    syncApsStateToVersionEntry(doc, nextAps);
    persistStore();
    return doc;
  }

  touchDocument(doc);
  addActivity(doc, actor, "更新版本配置", changes.join("；"));
  persistStore();
  return doc;
}

function deleteDocumentVersion(doc, versionId, actor, userContext = SYSTEM_USER_CONTEXT) {
  const entry = requireVersionEntry(doc, versionId);
  if (entry.isCurrent || entry.id === doc.currentVersionId) {
    const error = new Error("当前版本不可删除，请先切换其他版本为当前。");
    error.statusCode = 409;
    throw error;
  }
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.delete) {
    throw permissionDeniedError("你没有删除历史版本的权限。");
  }

  entry.deletedAt = new Date().toISOString();
  entry.deletedBy = actor;
  touchDocument(doc);
  addActivity(doc, actor, "删除历史版本", `${entry.version} 已删除，原始文件进入 30 天缓冲清理队列`);
  persistStore();
  return doc;
}

function updateDocument(doc, body, userContext = SYSTEM_USER_CONTEXT) {
  const actor = safeText(body.actor, "系统");
  const changes = [];
  const targetParentId =
    body.parentId !== undefined
      ? resolveFolderParentId(body.parentId, userContext, safeText(doc.projectId, DEFAULT_PROJECT_ID))
      : doc.parentId;
  const nextName = body.name !== undefined ? safeText(body.name, doc.name) : doc.name;
  const permissions = documentPermissionsForUser(doc, userContext);

  ensureUniqueDocumentName(nextName, targetParentId, doc.id, safeText(doc.projectId, DEFAULT_PROJECT_ID));

  if (doc.name !== nextName) {
    if (!permissions.rename) {
      throw permissionDeniedError("你没有重命名文件的权限。");
    }
    doc.name = nextName;
    if (Array.isArray(doc.versionHistory)) {
      doc.versionHistory.forEach((entry) => {
        entry.name = nextName;
      });
    }
    changes.push(`重命名为 ${nextName}`);
  }

  if (doc.parentId !== targetParentId) {
    if (!permissions.move) {
      throw permissionDeniedError("你没有移动文件的权限。");
    }
    assertFolderCapability(targetParentId, "upload", userContext, "目标目录不允许写入文件。");
    const previousParentId = doc.parentId;
    doc.parentId = targetParentId;
    touchFolder(previousParentId);
    touchFolder(targetParentId);
    changes.push(`移动到 ${folderName(targetParentId)}`);
  }

  if (body.accessLevel !== undefined) {
    if (!permissions.rename) {
      throw permissionDeniedError("你没有修改文件属性的权限。");
    }
    const nextAccessLevel = normalizeAccessLevel(body.accessLevel, doc.accessLevel);
    if (doc.accessLevel !== nextAccessLevel) {
      doc.accessLevel = nextAccessLevel;
      changes.push(`权限改为 ${accessLevelLabel(nextAccessLevel)}`);
    }
  }

  if (body.downloadScope !== undefined) {
    if (!permissions.rename) {
      throw permissionDeniedError("你没有修改下载策略的权限。");
    }
    const nextDownloadScope = normalizeDownloadScope(body.downloadScope, doc.downloadScope);
    if (doc.downloadScope !== nextDownloadScope) {
      doc.downloadScope = nextDownloadScope;
      changes.push(`下载范围改为 ${downloadScopeLabel(nextDownloadScope)}`);
    }
  }

  if (body.watermarkEnabled !== undefined) {
    if (!permissions.rename) {
      throw permissionDeniedError("你没有修改文件属性的权限。");
    }
    const nextWatermarkEnabled = Boolean(body.watermarkEnabled);
    if (doc.watermarkEnabled !== nextWatermarkEnabled) {
      doc.watermarkEnabled = nextWatermarkEnabled;
      changes.push(nextWatermarkEnabled ? "启用预览水印" : "关闭预览水印");
    }
  }

  if (body.drawingMetadata !== undefined) {
    if (!permissions.rename) {
      throw permissionDeniedError("你没有修改图纸属性的权限。");
    }
    const nextDrawingMetadata = resolveDocumentDrawingMetadataRelations(
      normalizeDocumentDrawingMetadata(body.drawingMetadata),
      safeText(doc.projectId, DEFAULT_PROJECT_ID),
      doc.id,
    );
    assertDrawingMetadataReady(nextDrawingMetadata);
    const currentDrawingMetadata = normalizeDocumentDrawingMetadata(doc.drawingMetadata || {});
    if (JSON.stringify(currentDrawingMetadata) !== JSON.stringify(nextDrawingMetadata)) {
      doc.drawingMetadata = nextDrawingMetadata;
      changes.push(
        nextDrawingMetadata.markedAsDrawing
          ? `图纸属性更新为 ${nextDrawingMetadata.drawingNumber} ${nextDrawingMetadata.revision}`
          : "清除图纸属性",
      );
    }
  }

  const requestedCheckedOut =
    body.checkedOut !== undefined ? Boolean(body.checkedOut) : body.locked !== undefined ? Boolean(body.locked) : undefined;
  if (requestedCheckedOut !== undefined) {
    if (!permissions.checkout && !(permissions.forceUnlock && requestedCheckedOut === false)) {
      throw permissionDeniedError("你没有签出 / 签入该文件的权限。");
    }
    const currentHolder = currentCheckedOutBy(doc);
    if (requestedCheckedOut) {
      if (currentHolder && currentHolder !== actor) {
        const error = new Error(`当前文件已被 ${currentHolder} 占用，其他人只能只读下载，不能上传新版本覆盖`);
        error.statusCode = 409;
        throw error;
      }
      if (!currentHolder) {
        doc.checkedOutBy = actor;
        doc.checkedOutAt = new Date().toISOString();
        doc.checkedOut = true;
        doc.locked = true;
        changes.push(`签出文件，占用人 ${actor}`);
      }
    } else if (currentHolder) {
      if (currentHolder !== actor && !permissions.forceUnlock) {
        const error = new Error(`当前文件由 ${currentHolder} 占用，仅占用人可释放`);
        error.statusCode = 409;
        throw error;
      }
      doc.checkedOutBy = "";
      doc.checkedOutAt = "";
      doc.checkedOut = false;
      doc.locked = false;
      changes.push(`释放文件占用（原占用人 ${currentHolder}）`);
    }
  }

  if (body.share !== undefined) {
    if (!permissions.share) {
      throw permissionDeniedError("你没有生成或修改分享链接的权限。");
    }
    const nextShare = normalizeShare({
      ...(doc.share || {}),
      ...(body.share || {}),
    });

    if (
      doc.share?.enabled !== nextShare.enabled ||
      doc.share?.permission !== nextShare.permission ||
      doc.share?.expiresAt !== nextShare.expiresAt ||
      doc.share?.token !== nextShare.token
    ) {
      doc.share = nextShare;
      changes.push(
        nextShare.enabled
          ? `分享链接已更新（${sharePermissionLabel(nextShare.permission)}，截止 ${nextShare.expiresAt}）`
          : "关闭临时分享",
      );
    }
  }

  if (!changes.length) {
    return doc;
  }

  touchDocument(doc);
  addActivity(doc, actor, "更新文档配置", changes.join("；"));
  persistStore();
  return doc;
}

function updateDocumentAps(doc, body, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.rename) {
    throw permissionDeniedError("你没有修改模型配置的权限。");
  }
  const actor = safeText(body.actor, "系统");
  const rawApsBody = (body && typeof body === "object" ? body.aps : null) || body || {};
  const nextAps = normalizeApsConfig({
    ...(doc.aps || {}),
    ...rawApsBody,
  });
  if (Object.prototype.hasOwnProperty.call(rawApsBody, "urn") && !safeText(rawApsBody.urn, "")) {
    nextAps.pendingUrn = "";
  }
  if (nextAps.urn && !nextAps.pendingUrn) {
    nextAps.pendingUrn = nextAps.urn;
  }
  if (nextAps.urn && !isApsTranslationActive(nextAps.translationStatus)) {
    clearApsTranslationTimer(doc.id);
    nextAps.translationRequestId = "";
    nextAps.translationStatus = "success";
    nextAps.translationMessage = safeText(nextAps.translationMessage, "已手动填写 APS URN");
    nextAps.translationError = "";
  }
  if (!nextAps.urn && !nextAps.pendingUrn && !isApsTranslationActive(nextAps.translationStatus)) {
    nextAps.translationStatus = "idle";
    nextAps.translationMessage = "";
    nextAps.translationError = "";
  }
  const changes = [];

  if ((doc.aps?.urn || "") !== nextAps.urn) {
    changes.push(nextAps.urn ? "更新 APS URN" : "清空 APS URN");
  }

  if ((doc.aps?.defaultView || "auto") !== nextAps.defaultView) {
    changes.push(`默认模型视图改为 ${nextAps.defaultView.toUpperCase()}`);
  }

  if ((doc.aps?.layoutMode || "linked") !== nextAps.layoutMode) {
    changes.push(`Viewer 布局切换为 ${nextAps.layoutMode.toUpperCase()}`);
  }

  if ((doc.aps?.viewable2dGuid || "") !== nextAps.viewable2dGuid) {
    changes.push(nextAps.viewable2dGuid ? "更新 2D 视图 GUID" : "清空 2D 视图 GUID");
  }

  if ((doc.aps?.viewable3dGuid || "") !== nextAps.viewable3dGuid) {
    changes.push(nextAps.viewable3dGuid ? "更新 3D 视图 GUID" : "清空 3D 视图 GUID");
  }

  if ((doc.aps?.markupsSvg || "") !== nextAps.markupsSvg) {
    changes.push(nextAps.markupsSvg ? "更新模型标注" : "清空模型标注");
  }

  if (JSON.stringify(doc.aps?.savedViews || []) !== JSON.stringify(nextAps.savedViews)) {
    changes.push(`更新 ${nextAps.savedViews.length} 个模型视点`);
  }

  if (JSON.stringify(doc.aps?.lastViewState || null) !== JSON.stringify(nextAps.lastViewState || null)) {
    changes.push("更新模型主视图状态");
  }

  if (JSON.stringify(doc.aps?.linkedViewState || null) !== JSON.stringify(nextAps.linkedViewState || null)) {
    changes.push("更新模型联动视图状态");
  }

  if (JSON.stringify(doc.aps?.isolatedDbIds || []) !== JSON.stringify(nextAps.isolatedDbIds || [])) {
    changes.push("更新模型隔离状态");
  }

  if (JSON.stringify(doc.aps?.themingColors || []) !== JSON.stringify(nextAps.themingColors || [])) {
    changes.push("更新模型着色状态");
  }

  if (JSON.stringify(doc.aps?.elementIndex || []) !== JSON.stringify(nextAps.elementIndex || [])) {
    changes.push("更新构件稳定标识索引");
  }

  if ((doc.aps?.discipline || "") !== nextAps.discipline) {
    changes.push(nextAps.discipline ? `模型专业改为 ${nextAps.discipline}` : "清空模型专业");
  }

  if ((doc.aps?.coordinateSystem || "") !== nextAps.coordinateSystem) {
    changes.push(nextAps.coordinateSystem ? `坐标系改为 ${nextAps.coordinateSystem}` : "清空坐标系");
  }

  if (JSON.stringify(doc.aps?.transform || {}) !== JSON.stringify(nextAps.transform || {})) {
    changes.push("更新模型坐标变换");
  }

  if (JSON.stringify(doc.aps?.geometryIndex || []) !== JSON.stringify(nextAps.geometryIndex || [])) {
    changes.push(`更新 ${nextAps.geometryIndex.length} 个构件几何索引`);
  }

  if (!changes.length) {
    return doc;
  }

  doc.aps = nextAps;
  syncApsStateToVersionEntry(doc, doc.aps);
  touchDocument(doc);
  addActivity(doc, actor, "更新 APS 配置", changes.join("；"));
  persistStore();
  return doc;
}

function migrateOpenIssueBindingsForApsDocument(doc, options = {}) {
  const elementIndex = normalizeElementIndex(options.elementIndex || doc.aps?.elementIndex || []);
  const summary = migrateIssueBindings(doc.annotations, {
    elementIndex,
    modelUrn: options.modelUrn || doc.aps?.urn || "",
    boundModelVersion: options.boundModelVersion || doc.version || "",
    versionId: options.versionId || doc.currentVersionId || "",
  });
  if (summary.synced || summary.deleted || summary.pending) {
    addActivity(
      doc,
      options.actor || "系统",
      "迁移模型 Issue",
      `同步 ${summary.synced} 项，删除 ${summary.deleted} 项，待确认 ${summary.pending} 项`,
    );
  }
  return summary;
}

function inferModelDisciplineFromDocument(doc) {
  const textValue = `${safeText(doc?.name, "")} ${safeText(doc?.parentId ? folderPathLabel(doc.parentId) : "", "")}`.toLowerCase();
  if (/struct|结构|土建|civil/.test(textValue)) {
    return "structure";
  }
  if (/pipe|piping|mep|机电|管线|管道|暖通|给排水|电气|plant/.test(textValue)) {
    return "mep";
  }
  if (/arch|建筑/.test(textValue)) {
    return "architecture";
  }
  return "general";
}

function modelClashGeometryForDocument(doc) {
  const aps = normalizeApsConfig(doc.aps);
  return {
    documentId: doc.id,
    urn: aps.urn,
    name: doc.name,
    discipline: aps.discipline || inferModelDisciplineFromDocument(doc),
    transform: aps.transform,
    elements: aps.geometryIndex,
  };
}

function modelGeometryFixturePayloadAllowed() {
  return String(process.env.CDE_ALLOW_MODEL_GEOMETRY_FIXTURE_PAYLOAD || "").trim() === "1";
}

function assertModelGeometryPayloadBoundary(propertiesPayload) {
  if (!propertiesPayload) {
    return;
  }
  if (modelGeometryFixturePayloadAllowed()) {
    return;
  }
  const error = new Error("测试几何载荷仅允许在 CDE_ALLOW_MODEL_GEOMETRY_FIXTURE_PAYLOAD=1 的测试环境使用。");
  error.statusCode = 400;
  throw error;
}

function objectIdsFromDerivativeProperties(payload) {
  return Array.from(new Set(collectionFromDerivativePayload(payload)
    .map((item) => Number(item?.objectid ?? item?.objectId ?? item?.dbId ?? item?.dbid))
    .filter((item) => Number.isInteger(item) && item >= 0)));
}

function simpleDerivativePropertyValue(item, aliases = []) {
  const normalizedAliases = new Set(aliases.map((alias) => safeText(alias, "").toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "")));
  const candidates = [];
  if (Array.isArray(item?.properties)) {
    item.properties.forEach((property) => {
      candidates.push({
        key: safeText(property?.displayName || property?.name || property?.attributeName, ""),
        value: property?.displayValue ?? property?.display_value ?? property?.value,
      });
    });
  } else if (item?.properties && typeof item.properties === "object") {
    Object.entries(item.properties).forEach(([key, value]) => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        candidates.push({
          key: safeText(value.displayName || value.name || key, key),
          value: value.displayValue ?? value.display_value ?? value.value,
        });
      } else {
        candidates.push({ key, value });
      }
    });
  }
  ["name", "category", "discipline", "externalId", "guid", "uniqueId"].forEach((key) => {
    if (item?.[key] !== undefined) {
      candidates.push({ key, value: item[key] });
    }
  });
  for (const candidate of candidates) {
    const normalizedKey = safeText(candidate.key, "").toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "");
    if (normalizedAliases.has(normalizedKey) && safeText(candidate.value, "")) {
      return candidate.value;
    }
  }
  return "";
}

function metadataByDbIdFromDerivativeProperties(payload, defaultDiscipline = "general") {
  const metadata = new Map();
  collectionFromDerivativePayload(payload).forEach((item) => {
    const dbId = Number(item?.objectid ?? item?.objectId ?? item?.dbId ?? item?.dbid);
    if (!Number.isInteger(dbId) || dbId < 0) {
      return;
    }
    metadata.set(dbId, {
      name: safeText(item?.name || simpleDerivativePropertyValue(item, ["Name", "名称"]), `dbId ${dbId}`),
      discipline: normalizeModelDiscipline(
        simpleDerivativePropertyValue(item, ["Discipline", "System Classification", "System Type", "Category", "类别", "专业"]) ||
          item?.discipline ||
          item?.category,
        defaultDiscipline,
      ),
    });
  });
  return metadata;
}

function createModelGeometryExtractionTask(doc, source, actor = "系统") {
  const aps = normalizeApsConfig(doc.aps);
  const now = new Date().toISOString();
  const task = normalizeModelGeometryExtractionTask({
    id: crypto.randomUUID(),
    documentId: doc.id,
    projectId: safeText(doc.projectId, DEFAULT_PROJECT_ID),
    versionId: safeText(doc.currentVersionId, ""),
    modelUrn: aps.urn,
    source,
    status: "running",
    parserVersion: MODEL_GEOMETRY_PARSER_VERSION,
    createdBy: actor,
    createdAt: now,
    updatedAt: now,
  });
  modelGeometryExtractionTasks.unshift(task);
  return task;
}

function completeModelGeometryExtractionTask(task, patch = {}) {
  const now = new Date().toISOString();
  Object.assign(task, normalizeModelGeometryExtractionTask({
    ...task,
    ...patch,
    status: patch.status || "succeeded",
    updatedAt: now,
    completedAt: patch.completedAt || now,
  }));
  return task;
}

function shouldAttemptObjGeometryFallback(primaryExtraction, options = {}) {
  if (Array.isArray(options.objPayloads) && options.objPayloads.length) {
    return true;
  }
  if (options.propertiesPayload) {
    return false;
  }
  const summary = primaryExtraction?.summary || {};
  const indexedElements = Number(summary.indexedElements || 0);
  return indexedElements === 0 ||
    Number(summary.skippedElements || 0) > 0 ||
    Number(summary.meshElementCount || 0) < indexedElements;
}

function mergeObjExtractionResults(results) {
  return (Array.isArray(results) ? results : []).reduce(
    (merged, result) => mergeGeometryExtractionSources({ primary: merged, fallback: result }),
    { geometryIndex: [], elementIndex: [], warnings: [], summary: { totalObjects: 0, indexedElements: 0, skippedElements: 0, elementIndexCount: 0, meshElementCount: 0 } },
  );
}

function extractGeometryFromFixtureObjPayloads(objPayloads, options = {}) {
  const metadataByDbId = options.metadataByDbId || new Map();
  const parsed = (Array.isArray(objPayloads) ? objPayloads : []).map((payload) => buildGeometryIndexFromObjDerivative(
    payload?.objText || payload?.text || payload?.content || "",
    {
      objectIds: Array.isArray(payload?.objectIds) ? payload.objectIds : [],
      metadataByDbId,
      defaultDiscipline: options.defaultDiscipline,
    },
  ));
  const extraction = mergeObjExtractionResults(parsed);
  return {
    ...extraction,
    derivativeUrns: (Array.isArray(objPayloads) ? objPayloads : []).map((payload) => safeText(payload?.derivativeUrn, "")).filter(Boolean),
  };
}

async function fetchApsMetadataItems(accessToken, urn) {
  const encodedUrn = encodeURIComponent(urn);
  const metadataPayload = await fetchApsModelDerivativeJson(
    accessToken,
    `https://developer.api.autodesk.com/modelderivative/v2/designdata/${encodedUrn}/metadata`,
    "APS metadata",
  );
  return Array.isArray(metadataPayload?.data?.metadata) ? metadataPayload.data.metadata : [];
}

function selectAps3dMetadataItem(metadataItems, preferredGuid = "") {
  return (Array.isArray(metadataItems) ? metadataItems : []).find((item) => safeText(item.guid, "") === preferredGuid) ||
    (Array.isArray(metadataItems) ? metadataItems : []).find((item) => safeText(item.role, "").toLowerCase() === "3d") ||
    (Array.isArray(metadataItems) ? metadataItems : [])[0] ||
    null;
}

async function startApsObjGeometryExtractionJob(accessToken, urn, modelGuid, objectIds) {
  const normalizedObjectIds = objectIdsFromDerivativeProperties({ data: objectIds.map((objectid) => ({ objectid })) });
  const response = await fetch("https://developer.api.autodesk.com/modelderivative/v2/designdata/job", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      "x-ads-force": "true",
    },
    body: JSON.stringify({
      input: { urn },
      output: {
        formats: [
          {
            type: "obj",
            advanced: {
              modelGuid,
              objectIds: normalizedObjectIds,
            },
          },
        ],
      },
    }),
  });

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS OBJ geometry extraction job failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }
  return response.json();
}

async function waitForApsObjDerivativeResource(accessToken, urn, options = {}) {
  for (let attempt = 0; attempt < 18; attempt += 1) {
    const manifest = await fetchApsManifest(accessToken, urn);
    const [resource] = findObjDerivativeResources(manifest, options);
    if (resource) {
      return resource;
    }
    await waitMs(Math.min(5000, 500 + attempt * 350));
  }
  const error = new Error("APS OBJ derivative 未在超时时间内生成。");
  error.statusCode = 504;
  throw error;
}

function cookieHeaderFromSignedCookieResponse(headers) {
  const getSetCookie = typeof headers?.getSetCookie === "function" ? headers.getSetCookie() : [];
  const rawCookies = getSetCookie.length ? getSetCookie : [headers?.get?.("set-cookie")].filter(Boolean);
  return rawCookies
    .flatMap((value) => String(value || "").split(/,(?=[^;,]+=)/))
    .map((value) => value.split(";")[0].trim())
    .filter(Boolean)
    .join("; ");
}

async function downloadApsDerivativeText(accessToken, urn, derivativeUrn) {
  const response = await fetch(
    `https://developer.api.autodesk.com/modelderivative/v2/designdata/${encodeURIComponent(urn)}/manifest/${encodeURIComponent(derivativeUrn)}/signedcookies`,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    },
  );

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS derivative signedcookies request failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }
  const cookieHeader = cookieHeaderFromSignedCookieResponse(response.headers);
  const payload = await response.json().catch(() => ({}));
  const downloadUrl = safeText(payload.url || payload.data?.url || payload.href || payload.location || response.headers.get("location"), "");
  if (!downloadUrl) {
    const error = new Error("APS derivative signedcookies response did not include a download URL.");
    error.statusCode = 502;
    throw error;
  }
  const downloadResponse = await fetch(downloadUrl, {
    headers: cookieHeader ? { Cookie: cookieHeader } : {},
  });
  if (!downloadResponse.ok) {
    const detail = await downloadResponse.text().catch(() => "");
    const error = new Error(detail || `APS derivative download failed (${downloadResponse.status})`);
    error.statusCode = 502;
    throw error;
  }
  return downloadResponse.text();
}

async function extractGeometryFromApsObjDerivatives(doc, propertiesPayload, primaryExtraction) {
  const aps = normalizeApsConfig(doc.aps);
  const token = await getApsAccessToken(["data:read", "viewables:read"]);
  const metadataItems = await fetchApsMetadataItems(token.access_token, aps.urn);
  const metadataItem = selectAps3dMetadataItem(metadataItems, aps.viewable3dGuid);
  const modelGuid = safeText(metadataItem?.guid, aps.viewable3dGuid);
  if (!modelGuid) {
    const error = new Error("APS 未返回可用于 OBJ 几何提取的 3D modelGuid。");
    error.statusCode = 502;
    throw error;
  }

  const metadataByDbId = metadataByDbIdFromDerivativeProperties(propertiesPayload, aps.discipline || inferModelDisciplineFromDocument(doc));
  const allObjectIds = objectIdsFromDerivativeProperties(propertiesPayload);
  const indexedWithoutMesh = (Array.isArray(primaryExtraction?.geometryIndex) ? primaryExtraction.geometryIndex : [])
    .filter((item) => !item.mesh)
    .map((item) => Number(item.dbId))
    .filter((item) => Number.isInteger(item) && item >= 0);
  const candidateObjectIds = allObjectIds.length ? allObjectIds : indexedWithoutMesh;
  const objectIds = candidateObjectIds.slice(0, CDE_MODEL_GEOMETRY_MAX_OBJ_OBJECTS);
  if (!objectIds.length) {
    return { geometryIndex: [], elementIndex: [], warnings: [{ code: "no_obj_object_ids" }], summary: { totalObjects: 0, indexedElements: 0, skippedElements: 0, elementIndexCount: 0, meshElementCount: 0 }, derivativeUrns: [] };
  }

  const results = [];
  const derivativeUrns = [];
  for (let offset = 0; offset < objectIds.length; offset += CDE_MODEL_GEOMETRY_OBJ_BATCH_SIZE) {
    const batch = objectIds.slice(offset, offset + CDE_MODEL_GEOMETRY_OBJ_BATCH_SIZE);
    await startApsObjGeometryExtractionJob(token.access_token, aps.urn, modelGuid, batch);
    const resource = await waitForApsObjDerivativeResource(token.access_token, aps.urn, { modelGuid, objectIds: batch });
    const objText = await downloadApsDerivativeText(token.access_token, aps.urn, resource.urn);
    derivativeUrns.push(resource.urn);
    results.push(buildGeometryIndexFromObjDerivative(objText, {
      objectIds: batch,
      metadataByDbId,
      defaultDiscipline: aps.discipline || inferModelDisciplineFromDocument(doc),
    }));
  }
  const extraction = mergeObjExtractionResults(results);
  if (candidateObjectIds.length > objectIds.length) {
    extraction.warnings.push({
      code: "obj_object_limit_reached",
      requested: candidateObjectIds.length,
      processed: objectIds.length,
      limit: CDE_MODEL_GEOMETRY_MAX_OBJ_OBJECTS,
    });
  }
  extraction.derivativeUrns = derivativeUrns;
  return extraction;
}

async function extractModelGeometryForDocument(doc, options = {}) {
  const permissions = options.userContext ? documentPermissionsForUser(doc, options.userContext) : { rename: true, annotations: { create: true } };
  if (!permissions.rename && !permissions.annotations?.create) {
    throw permissionDeniedError("你没有提取该模型几何索引的权限。");
  }
  const aps = normalizeApsConfig(doc.aps);
  if (!safeText(aps.urn, "")) {
    const error = new Error(`模型 ${doc.name} 还没有 APS URN。`);
    error.statusCode = 400;
    throw error;
  }
  assertModelGeometryPayloadBoundary(options.propertiesPayload);
  if (Array.isArray(options.objPayloads) && options.objPayloads.length) {
    assertModelGeometryPayloadBoundary(options.objPayloads);
  }
  const actor = safeText(options.actor, "系统");
  const task = createModelGeometryExtractionTask(doc, options.propertiesPayload ? "fixture-properties" : "aps-properties", actor);
  try {
    const propertiesPayload = options.propertiesPayload || await fetchApsModelPropertiesForDocument(doc, aps.urn);
    let extraction = buildGeometryIndexFromDerivativeProperties(propertiesPayload, {
      defaultDiscipline: aps.discipline || inferModelDisciplineFromDocument(doc),
      includeMesh: true,
    });
    let source = options.propertiesPayload ? "fixture-properties" : "aps-properties";
    let derivativeUrns = [];
    if (shouldAttemptObjGeometryFallback(extraction, options)) {
      try {
        const metadataByDbId = metadataByDbIdFromDerivativeProperties(propertiesPayload, aps.discipline || inferModelDisciplineFromDocument(doc));
        const objExtraction = Array.isArray(options.objPayloads) && options.objPayloads.length
          ? extractGeometryFromFixtureObjPayloads(options.objPayloads, {
              metadataByDbId,
              defaultDiscipline: aps.discipline || inferModelDisciplineFromDocument(doc),
            })
          : await extractGeometryFromApsObjDerivatives(doc, propertiesPayload, extraction);
        derivativeUrns = objExtraction.derivativeUrns || [];
        if (objExtraction.geometryIndex.length) {
          extraction = mergeGeometryExtractionSources({ primary: extraction, fallback: objExtraction });
          source = `${source}+obj`;
        }
      } catch (error) {
        extraction.warnings = [
          ...(Array.isArray(extraction.warnings) ? extraction.warnings : []),
          { code: "obj_fallback_failed", message: formatApsTranslationFailure(error) },
        ];
        if (!extraction.geometryIndex.length) {
          throw error;
        }
      }
    }

    if (!extraction.geometryIndex.length) {
      const error = new Error(`模型 ${doc.name} 未能从 APS 属性或 OBJ derivative 中提取有效几何边界。`);
      error.statusCode = 422;
      error.details = extraction.summary;
      throw error;
    }

    const now = new Date().toISOString();
    const nextElementIndex = extraction.elementIndex.length ? extraction.elementIndex : aps.elementIndex;
    doc.aps = normalizeApsConfig({
      ...(doc.aps || {}),
      geometryIndex: extraction.geometryIndex,
      elementIndex: nextElementIndex,
      discipline: aps.discipline || inferModelDisciplineFromDocument(doc),
      translationMessage: `${safeText(aps.translationMessage, "APS 模型已就绪")}；几何索引 ${extraction.geometryIndex.length} 个构件（mesh ${extraction.summary.meshElementCount || 0}）`,
      translationError: "",
      translationUpdatedAt: now,
    });
    completeModelGeometryExtractionTask(task, {
      source,
      derivativeUrn: derivativeUrns.join(","),
      indexedCount: extraction.geometryIndex.length,
      meshCount: Number(extraction.summary.meshElementCount || 0),
      warnings: extraction.warnings,
      summary: extraction.summary,
    });
    touchDocument(doc);
    addActivity(
      doc,
      actor,
      "提取模型几何索引",
      `生成 ${extraction.geometryIndex.length} 个构件边界，mesh ${extraction.summary.meshElementCount || 0} 个，稳定标识 ${nextElementIndex.length} 个`,
    );
    persistStore();
    return {
      documentId: doc.id,
      task: toPublicModelGeometryExtractionTask(task),
      summary: extraction.summary,
      warnings: extraction.warnings,
    };
  } catch (error) {
    completeModelGeometryExtractionTask(task, {
      status: "failed",
      error: formatApsTranslationFailure(error),
    });
    persistStore();
    throw error;
  }
}

function modelClashRecordSignature(record) {
  const normalized = normalizeClashRecord(record);
  return [
    `${normalized.modelUrnA}:${normalized.dbIdA}`,
    `${normalized.modelUrnB}:${normalized.dbIdB}`,
  ].sort().join("|");
}

function closeStaleModelClashes(documentIds, activeSignatures, actor = "系统") {
  const documentIdSet = new Set(documentIds);
  const closedRecords = [];
  modelClashRecords.forEach((record) => {
    if (record.status !== "open") {
      return;
    }
    if (!documentIdSet.has(record.documentIdA) && !documentIdSet.has(record.documentIdB)) {
      return;
    }
    if (activeSignatures.has(modelClashRecordSignature(record))) {
      return;
    }
    record.status = "resolved";
    record.updatedAt = new Date().toISOString();
    const doc =
      documents.find((item) => item.id === record.documentIdA) ||
      documents.find((item) => item.id === record.documentIdB);
    const annotation = doc?.annotations?.find((item) => item.id === record.issueId);
    if (annotation && annotation.status !== "resolved") {
      annotation.status = "resolved";
      annotation.resolved = true;
      annotation.resolvedAt = record.updatedAt;
      addActivity(doc, actor, "自动复验碰撞", `${annotation.title} · 已自动关闭`);
      touchDocument(doc);
    }
    closedRecords.push(record);
  });
  return closedRecords;
}

function modelClashRunById(runId, projectId = DEFAULT_PROJECT_ID) {
  const id = safeText(runId, "");
  const resolvedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  return modelClashRuns.find((run) => run.id === id && safeText(run.projectId, DEFAULT_PROJECT_ID) === resolvedProjectId) || null;
}

function modelClashHeatmapById(heatmapId, projectId = DEFAULT_PROJECT_ID) {
  const id = safeText(heatmapId, "");
  const resolvedProjectId = safeText(projectId, DEFAULT_PROJECT_ID);
  return modelClashHeatmaps.find((task) => task.id === id && safeText(task.projectId, DEFAULT_PROJECT_ID) === resolvedProjectId) || null;
}

function modelClashHeatmapDetails(task, options = {}) {
  const normalizedTask = normalizeHeatmapTask(task);
  const heatmap = buildClashHeatmap(modelClashRecords, {
    id: normalizedTask.id,
    runId: normalizedTask.clashTaskId,
    projectId: normalizedTask.projectId,
    gridSize: options.gridSize ?? normalizedTask.gridSize,
    topN: options.topN || 5,
    disciplinePair: safeText(options.disciplinePair, "all"),
    status: safeText(options.status, "all"),
    minClashVolume: Math.max(0, Number(options.minClashVolume || 0) || 0),
    createdAt: normalizedTask.createdAt,
  });
  return {
    task: toPublicModelClashHeatmap({ ...normalizedTask, summary: heatmap.summary, gridSize: heatmap.task.gridSize }),
    cells: heatmap.cells.map(toPublicModelClashHeatmapCell),
    hotspots: heatmap.hotspots.map(toPublicModelClashHotspot),
    matrix: heatmap.matrix,
    summary: heatmap.summary,
  };
}

function createModelClashHeatmapForRun(run, records, options = {}) {
  const existingIds = new Set(
    modelClashHeatmaps
      .filter((task) => task.clashTaskId === run.id && task.gridSize === (options.gridSize || 1))
      .map((task) => task.id),
  );
  const heatmap = buildClashHeatmap(records, {
    id: crypto.randomUUID(),
    runId: run.id,
    projectId: run.projectId,
    gridSize: options.gridSize,
    topN: options.topN || 5,
    createdAt: run.createdAt,
  });
  modelClashHeatmaps = modelClashHeatmaps.filter((task) => task.clashTaskId !== run.id || task.gridSize !== heatmap.task.gridSize);
  modelClashHeatmapCells = modelClashHeatmapCells.filter((cell) => !existingIds.has(cell.heatmapId));
  modelClashHotspots = modelClashHotspots.filter((hotspot) => !existingIds.has(hotspot.heatmapId));
  modelClashHeatmaps.unshift(heatmap.task);
  modelClashHeatmapCells.unshift(...heatmap.cells);
  modelClashHotspots.unshift(...heatmap.hotspots);
  return heatmap;
}

function assertModelClashHeatmapExportAccess(heatmap, userContext) {
  const run = modelClashRunById(heatmap.clashTaskId, userContext.projectId);
  const docIds = Array.isArray(run?.documentIds) ? run.documentIds : [];
  docIds.forEach((docId) => {
    const doc = requireDocument(docId, userContext);
    const permissions = documentPermissionsForUser(doc, userContext);
    if (!permissions.preview) {
      throw permissionDeniedError("你没有导出该碰撞热力图的权限。");
    }
  });
}

function normalizeHeatmapExportKind(value) {
  const kind = safeText(value, "package").toLowerCase();
  return ["snapshot", "matrix", "hotspots", "package"].includes(kind) ? kind : "package";
}

function heatmapExportFileName(heatmap, kind) {
  const suffix = crypto.randomUUID().slice(0, 8);
  const timestamp = Date.now();
  if (kind === "snapshot") {
    return `${heatmap.id}-heatmap-${timestamp}-${suffix}.svg`;
  }
  if (kind === "matrix") {
    return `${heatmap.id}-clash-matrix-${timestamp}-${suffix}.xlsx`;
  }
  if (kind === "hotspots") {
    return `${heatmap.id}-hotspots-${timestamp}-${suffix}.pdf`;
  }
  return `${heatmap.id}-heatmap-package-${timestamp}-${suffix}.zip`;
}

async function runModelClashHeatmapExportScript(heatmap, kind, outputPath, options = {}) {
  persistStore();
  return new Promise((resolve, reject) => {
    const child = spawn(PYTHON_BIN, [
      MODEL_CLASH_HEATMAP_EXPORT_SCRIPT,
      STORE_PATH,
      safeText(heatmap?.id, ""),
      kind,
      outputPath,
    ], exportSpawnOptions(options.language));

    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
    });

    child.on("close", (code) => {
      if (code === 0) {
        resolve();
        return;
      }
      const error = new Error(stderr.trim() || "Failed to export model clash heatmap");
      error.statusCode = 500;
      reject(error);
    });

    child.on("error", reject);
  });
}

async function exportModelClashHeatmap(heatmap, body, userContext) {
  const normalized = normalizeHeatmapTask(heatmap);
  assertModelClashHeatmapExportAccess(normalized, userContext);
  const kind = normalizeHeatmapExportKind(body?.kind);
  const language = normalizeUiLanguage(body?.language);

  if (kind === "package") {
    const exportFileName = heatmapExportFileName(normalized, "package");
    const archivePath = path.join(EXPORTS_DIR, exportFileName);
    const stagingDir = fs.mkdtempSync(path.join(EXPORTS_DIR, `heatmap-${normalized.id}-`));
    try {
      await runModelClashHeatmapExportScript(normalized, "snapshot", path.join(stagingDir, "heatmap-snapshot.svg"), { language });
      await runModelClashHeatmapExportScript(normalized, "matrix", path.join(stagingDir, "discipline-matrix.xlsx"), { language });
      await runModelClashHeatmapExportScript(normalized, "hotspots", path.join(stagingDir, "hotspot-report.pdf"), { language });
      await zipDirectory(stagingDir, archivePath);
    } finally {
      fs.rmSync(stagingDir, { recursive: true, force: true });
    }
    registerProtectedExportFile(exportFileName, {
      kind: "model_clash_heatmap_package",
      heatmapId: normalized.id,
      createdBy: safeText(userContext?.user?.id, ""),
      createdAt: new Date().toISOString(),
    });
    return { kind, fileName: exportFileName, downloadUrl: signedExportUrl(exportFileName), heatmap: toPublicModelClashHeatmap(normalized) };
  }

  const exportFileName = heatmapExportFileName(normalized, kind);
  await runModelClashHeatmapExportScript(normalized, kind, path.join(EXPORTS_DIR, exportFileName), { language });
  registerProtectedExportFile(exportFileName, {
    kind: `model_clash_heatmap_${kind}`,
    heatmapId: normalized.id,
    createdBy: safeText(userContext?.user?.id, ""),
    createdAt: new Date().toISOString(),
  });
  return { kind, fileName: exportFileName, downloadUrl: signedExportUrl(exportFileName), heatmap: toPublicModelClashHeatmap(normalized) };
}

async function runModelClashDetection(body, userContext, req = null) {
  const actor = actorDisplayName(userContext);
  const requestedIds = Array.isArray(body?.documentIds) ? body.documentIds : [];
  const documentIds = Array.from(new Set(requestedIds.map((item) => safeText(item, "")).filter(Boolean)));
  if (!documentIds.length) {
    const error = new Error("请至少选择一个模型文件进行碰撞检测。");
    error.statusCode = 400;
    throw error;
  }

  const docs = documentIds.map((id) => requireDocument(id, userContext));
  const geometryPayloads = body?.geometryPayloads && typeof body.geometryPayloads === "object" ? body.geometryPayloads : {};
  const geometryObjPayloads = body?.geometryObjPayloads && typeof body.geometryObjPayloads === "object" ? body.geometryObjPayloads : {};
  const geometryExtractions = [];

  for (const doc of docs) {
    const permissions = documentPermissionsForUser(doc, userContext);
    if (!permissions.preview || !permissions.annotations.create) {
      throw permissionDeniedError("所选模型中包含无权查看或创建 Issue 的文件。");
    }
    if (!isApsModelDocument(doc.name) || apsDocumentWorkspaceKind(doc.name) !== "model") {
      const error = new Error(`文件 ${doc.name} 不是可检测的三维模型。`);
      error.statusCode = 400;
      throw error;
    }
    if (!safeText(doc.aps?.urn, "")) {
      const error = new Error(`模型 ${doc.name} 还没有 APS URN。`);
      error.statusCode = 400;
      throw error;
    }
    if (!Array.isArray(doc.aps?.geometryIndex) || !doc.aps.geometryIndex.length) {
      const extraction = await extractModelGeometryForDocument(doc, {
        actor,
        userContext,
        propertiesPayload: geometryPayloads[doc.id] || null,
        objPayloads: Array.isArray(geometryObjPayloads[doc.id]) ? geometryObjPayloads[doc.id] : [],
      });
      geometryExtractions.push(extraction);
    }
  }

  const projectId = safeText(userContext?.projectId, DEFAULT_PROJECT_ID);
  const rule = normalizeClashRule(body?.rule);
  const detection = detectClashes({
    rule,
    models: docs.map(modelClashGeometryForDocument),
  });
  const now = new Date().toISOString();
  const runId = crypto.randomUUID();
  const records = createClashRecords(detection.clashes, {
    runId,
    projectId,
    createdAt: now,
  });

  const activeSignatures = new Set(records.map(modelClashRecordSignature));
  const closedRecords = closeStaleModelClashes(documentIds, activeSignatures, actor);
  const issueIds = [];

  for (const record of records) {
    const issueDoc = documents.find((item) => item.id === record.documentIdA) || docs[0];
    const issuePayload = buildClashIssuePayload(record, {
      actor,
      boundModelVersion: issueDoc.version,
    });
    const annotation = await createAnnotation(issuePayload, issueDoc.currentVersionId, {
      modelUrn: issueDoc.aps?.urn,
      boundModelVersion: issueDoc.version,
    });
    issueDoc.annotations.push(annotation);
    record.issueId = annotation.id;
    record.updatedAt = now;
    issueIds.push(annotation.id);
    touchDocument(issueDoc);
    addActivity(issueDoc, actor, "自动碰撞检测", `${annotation.title} · ${annotation.note}`);
    await bestEffortProjectEmailNotification("annotationCreated", {
      document: issueDoc,
      annotation,
      userContext,
      req,
      occurredAt: annotation.createdAt,
    });
  }

  modelClashRecords.unshift(...records);
  const run = normalizeModelClashRun({
    id: runId,
    projectId,
    documentIds,
    status: "succeeded",
    rule,
    summary: {
      ...detection.summary,
      clashCount: records.length,
      closedCount: closedRecords.length,
    },
    recordIds: records.map((record) => record.id),
    issueIds,
    actor,
    createdAt: now,
    updatedAt: now,
  });
  modelClashRuns.unshift(run);
  const heatmap = createModelClashHeatmapForRun(run, records, {
    gridSize: body?.heatmap?.gridSize ?? body?.heatmapGridSize,
    topN: body?.heatmap?.topN || 5,
  });
  persistStore();

  return {
    run: toPublicModelClashRun(run),
    records: records.map(toPublicModelClashRecord),
    geometryExtractions,
    closedRecords: closedRecords.map(toPublicModelClashRecord),
    heatmap: {
      task: toPublicModelClashHeatmap(heatmap.task),
      cells: heatmap.cells.map(toPublicModelClashHeatmapCell),
      hotspots: heatmap.hotspots.map(toPublicModelClashHotspot),
      matrix: heatmap.matrix,
      summary: heatmap.summary,
    },
  };
}

function updateModelClashRecord(recordId, body, userContext) {
  const record = modelClashRecords.find((item) => item.id === recordId);
  if (!record || safeText(record.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    const error = new Error("Clash record not found");
    error.statusCode = 404;
    throw error;
  }
  const nextStatus = normalizeClashRecord({ ...record, status: body?.status }).status;
  const issueDoc =
    documents.find((item) => item.id === record.documentIdA) ||
    documents.find((item) => item.id === record.documentIdB);
  if (issueDoc) {
    assertDocumentCapability(issueDoc, "annotations.changeStatus", userContext, "你没有更新该碰撞 Issue 状态的权限。");
  }
  record.status = nextStatus;
  record.updatedAt = new Date().toISOString();

  const annotation = issueDoc?.annotations?.find((item) => item.id === record.issueId);
  if (annotation) {
    annotation.status = nextStatus === "open" ? "open" : "resolved";
    annotation.resolved = annotation.status === "resolved";
    annotation.resolvedAt = annotation.resolved ? record.updatedAt : null;
    touchDocument(issueDoc);
    addActivity(
      issueDoc,
      actorDisplayName(userContext),
      annotation.resolved ? "处理批注" : "更新批注",
      `${annotation.title} · ${annotationStatusLabel(annotation.status)}`,
    );
  }

  persistStore();
  return record;
}

function updateFolder(folder, body, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = folderPermissionsForUser(folder, userContext);
  const projectId = safeText(folder.projectId, DEFAULT_PROJECT_ID);
  const targetParentId =
    body.parentId !== undefined ? resolveFolderParentId(body.parentId, userContext, projectId) : folder.parentId;
  const nextName = body.name !== undefined ? safeText(body.name, folder.name) : folder.name;
  if ((folder.name !== nextName || folder.parentId !== targetParentId || body.accessLevel !== undefined) && !permissions.rename) {
    throw permissionDeniedError("你没有修改该文件夹的权限。");
  }

  if (targetParentId === folder.id || isDescendantFolder(targetParentId, folder.id, projectId)) {
    const error = new Error("文件夹不能移动到自己或下级目录中");
    error.statusCode = 409;
    throw error;
  }

  ensureUniqueFolderName(nextName, targetParentId, folder.id, projectId);
  if (folder.parentId !== targetParentId) {
    assertFolderCapability(targetParentId, "createFolder", userContext, "目标目录不允许移动文件夹到这里。");
  }

  const previousParentId = folder.parentId;
  folder.name = nextName;
  folder.parentId = targetParentId;

  if (body.accessLevel !== undefined) {
    folder.accessLevel = normalizeAccessLevel(body.accessLevel, folder.accessLevel);
  }

  folder.updatedAt = new Date().toISOString();
  touchFolder(previousParentId);
  touchFolder(targetParentId);
  persistStore();
  return folder;
}

async function deleteDocument(doc, actor, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.delete) {
    throw permissionDeniedError("你没有删除该文件的权限。");
  }
  clearApsTranslationTimer(doc.id);
  const fileNames = new Set([doc.storedFileName]);
  const attachmentStorageNames = documentAttachmentStorageNames(doc);
  (doc.versionHistory || []).forEach((entry) => {
    if (entry.storedFileName) {
      fileNames.add(entry.storedFileName);
    }
  });

  for (const fileName of fileNames) {
    if (fileName) {
      await storageService.uploads.delete(fileName);
    }
  }

  if (doc.lastExportFileName) {
    await storageService.exports.delete(doc.lastExportFileName);
  }

  documents = documents.filter((item) => item.id !== doc.id);
  touchFolder(doc.parentId);
  persistStore();
  await cleanupUnusedStoredAttachments(attachmentStorageNames);
}

function deleteFolder(folder, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = folderPermissionsForUser(folder, userContext);
  if (!permissions.delete) {
    throw permissionDeniedError("你没有删除该文件夹的权限。");
  }
  const hasChildFolder = folders.some((item) => item.parentId === folder.id);
  const hasDocuments = documents.some((item) => item.parentId === folder.id);
  if (hasChildFolder || hasDocuments) {
    const error = new Error("请先清空文件夹中的子目录和文件");
    error.statusCode = 409;
    throw error;
  }

  folders = folders.filter((item) => item.id !== folder.id);
  touchFolder(folder.parentId);
  persistStore();
}

async function createAnnotation(body, versionId = "", defaults = {}) {
  const type = body.type;
  if (!["circle", "mark", "note", "line", "pen"].includes(type)) {
    const error = new Error("Unsupported annotation type");
    error.statusCode = 400;
    throw error;
  }

  const status = normalizeAnnotationStatus(body.status, "open");
  const page = Number(body.page || 1);
  const x = clampNumber(body.x);
  const y = clampNumber(body.y);
  const width = clampNumber(body.width || 0.12);
  const height = clampNumber(body.height || 0.08);
  const locationDefaults = hasIssueLocation(body)
    ? {
        modelUrn: defaults.modelUrn,
        boundModelVersion: defaults.boundModelVersion,
      }
    : {};
  const issueLocation = normalizeIssueLocationFields(body, locationDefaults);

  return {
    id: crypto.randomUUID(),
    versionId: safeText(versionId, ""),
    type,
    variant: normalizeAnnotationVariant(body.variant, type, ""),
    page,
    x,
    y,
    width,
    height,
    points: normalizeAnnotationPoints(body.points, fallbackPointsForAnnotation(type, x, y, width, height)),
    strokes: normalizeAnnotationStrokes(body.strokes, type === "pen" ? [normalizeAnnotationPoints(body.points, fallbackPointsForAnnotation(type, x, y, width, height))] : []),
    nativeAnnotationId: safeText(body.nativeAnnotationId || body.nativeAnnotation?.id, ""),
    nativeAnnotation: sanitizeNativeAnnotation(body.nativeAnnotation),
    pageAnchored: Boolean(body.pageAnchored || body.page_anchored),
    title: safeText(body.title, defaultAnnotationTitle(type, page, body.variant)),
    note: String(body.note ?? "").trim(),
    actor: safeText(body.actor, "系统"),
    color: normalizeColor(body.color, defaultColor(type)),
    status,
    createdAt: new Date().toISOString(),
    resolved: status === "resolved",
    resolvedAt: status === "resolved" ? new Date().toISOString() : null,
    replies: [],
    attachments: await materializeAttachments(body.attachments),
    source: safeText(body.source, ""),
    ...issueLocation,
  };
}

async function createReply(body) {
  const content = typeof body.content === "string" ? body.content.trim() : "";
  const attachments = await materializeAttachments(body.attachments);
  if (!content && !attachments.length) {
    const error = new Error("Reply content or attachments are required");
    error.statusCode = 400;
    throw error;
  }

  return {
    id: crypto.randomUUID(),
    actor: safeText(body.actor, "系统"),
    content,
    createdAt: new Date().toISOString(),
    attachments,
  };
}

function runWorkflowAction(doc, action, actor) {
  if (action === "withdrawFlow") {
    doc.activeWorkflowId = "";
    doc.status = "uploaded";
    touchDocument(doc);
    addActivity(doc, actor, "撤回流程", "流程已撤回，文件恢复为待发起状态");
    return;
  }

  if (action === "returnToInitiator") {
    doc.activeWorkflowId = "";
    doc.status = "rejected";
    touchDocument(doc);
    addActivity(doc, actor, "退回发起者", "请根据批注和备注修改后重新发起流程");
    return;
  }

  if (action === "submitToApprover") {
    doc.status = "final_review";
    touchDocument(doc);
    addActivity(doc, actor, "提交终审", `已转交 ${doc.approver} 进行最终审阅`);
    return;
  }

  if (action === "approveFlow") {
    doc.activeWorkflowId = "";
    doc.status = "approved";
    touchDocument(doc);
    addActivity(doc, actor, "批准归档", "文档已完成审阅并进入归档状态");
    return;
  }

  if (action === "rejectFlow") {
    doc.activeWorkflowId = "";
    doc.status = "rejected";
    touchDocument(doc);
    addActivity(doc, actor, "驳回修改", "终审未通过，文档退回发起者修改");
    return;
  }

  const error = new Error("Unsupported workflow action");
  error.statusCode = 400;
  throw error;
}

function addActivity(doc, actor, label, note) {
  doc.activity.push({
    id: crypto.randomUUID(),
    actor,
    label,
    note,
    timestamp: new Date().toISOString(),
  });
}

function touchDocument(doc) {
  doc.updatedAt = new Date().toISOString();
  touchFolder(doc.parentId);
}

function requireDocument(id, userContext = null) {
  const doc = documents.find((item) => item.id === id);
  if (!doc) {
    const error = new Error("Document not found");
    error.statusCode = 404;
    throw error;
  }
  if (userContext && safeText(doc.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    const error = new Error("Document not found");
    error.statusCode = 404;
    throw error;
  }
  return doc;
}

function requireWorkflow(id, userContext = null) {
  const workflow = workflowById(id, safeText(userContext?.projectId, ""));
  if (!workflow) {
    const error = new Error("Workflow not found");
    error.statusCode = 404;
    throw error;
  }
  return workflow;
}

function touchFolder(id) {
  if (!id) {
    return;
  }

  const folder = folders.find((item) => item.id === id);
  if (folder) {
    folder.updatedAt = new Date().toISOString();
  }
}

function resolveFolderParentId(value, userContext = null, projectId = "") {
  const parentId = normalizeFolderId(value);
  if (!parentId) {
    return null;
  }

  const normalizedProjectId = safeText(projectId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  const folder = folders.find(
    (item) =>
      item.id === parentId &&
      safeText(item.projectId, DEFAULT_PROJECT_ID) === normalizedProjectId,
  );
  if (folder) {
    return parentId;
  }

  const equivalentFolder = equivalentProjectFolderForStaleId(parentId, normalizedProjectId);
  if (!equivalentFolder) {
    const error = new Error("Folder not found");
    error.statusCode = 404;
    throw error;
  }

  return equivalentFolder.id;
}

function normalizeFolderId(value) {
  const text = String(value || "").trim();
  return text || null;
}

function requireFolder(id, userContext = null) {
  const folder = folders.find((item) => item.id === id);
  if (!folder) {
    const error = new Error("Folder not found");
    error.statusCode = 404;
    throw error;
  }
  if (userContext && safeText(folder.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    const error = new Error("Folder not found");
    error.statusCode = 404;
    throw error;
  }
  return folder;
}

function inferUploadActor(doc) {
  const uploadActivity = Array.isArray(doc.activity)
    ? doc.activity.find((item) => item.label === "上传文件" || item.label === "上传 PDF")
    : null;
  return safeText(uploadActivity?.actor, "系统");
}

function normalizeCheckedOutBy(doc) {
  const explicitHolder = safeText(doc.checkedOutBy || doc.occupiedBy || doc.lockedBy, "");
  if (explicitHolder) {
    return explicitHolder;
  }
  if (doc.checkedOut || doc.locked) {
    return safeText(doc.owner, safeText(doc.uploader, inferUploadActor(doc)));
  }
  return "";
}

function currentCheckedOutBy(doc) {
  return safeText(doc?.checkedOutBy, "");
}

function normalizeConflictMode(value) {
  return ["replace", "rename", "skip", "replace_new"].includes(value) ? value : "replace";
}

function normalizeAccessLevel(value, fallback) {
  return ["edit", "view", "restricted"].includes(value) ? value : fallback;
}

function normalizeDownloadScope(value, fallback) {
  return ["team", "admins", "restricted"].includes(value) ? value : fallback;
}

function normalizeSharePermission(value, fallback) {
  return ["view", "download"].includes(value) ? value : fallback;
}

function normalizeShare(share) {
  const nextShare = share && typeof share === "object" ? share : {};
  const enabled = Boolean(nextShare.enabled);
  return {
    enabled,
    token: enabled ? safeText(nextShare.token, crypto.randomUUID()) : safeText(nextShare.token, ""),
    permission: normalizeSharePermission(nextShare.permission, "view"),
    expiresAt: safeText(nextShare.expiresAt, defaultShareExpiryDate()),
  };
}

function defaultShareExpiryDate() {
  const days = Math.max(1, Math.floor(positiveEnvNumber("CDE_SHARE_DEFAULT_EXPIRY_DAYS", 30)));
  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}

function inferDocumentMimeType(name, mimeType = "") {
  const explicit = safeText(mimeType, "").toLowerCase();
  if (explicit) {
    return explicit;
  }

  const ext = path.extname(String(name || "")).toLowerCase();
  return {
    ".pdf": "application/pdf",
    ".doc": "application/msword",
    ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ".xls": "application/vnd.ms-excel",
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    ".csv": "text/csv; charset=utf-8",
    ".ppt": "application/vnd.ms-powerpoint",
    ".pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    ".txt": "text/plain; charset=utf-8",
    ".zip": "application/zip",
    ".wasm": "application/wasm",
    ".dwg": "application/acad",
    ".dxf": "application/octet-stream",
    ".dgn": "application/octet-stream",
    ".idw": "application/octet-stream",
    ".nwd": "application/octet-stream",
    ".nwc": "application/octet-stream",
    ".rvt": "application/octet-stream",
    ".ifc": "application/octet-stream",
  }[ext] || "application/octet-stream";
}

function storageExtensionForName(name, mimeType = "") {
  const directExt = path.extname(String(name || "")).toLowerCase();
  if (directExt) {
    return directExt;
  }

  const inferredMimeType = inferDocumentMimeType(name, mimeType);
  return {
    "application/pdf": ".pdf",
    "application/msword": ".doc",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": ".docx",
    "application/vnd.ms-excel": ".xls",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": ".xlsx",
    "text/csv; charset=utf-8": ".csv",
    "application/vnd.ms-powerpoint": ".ppt",
    "application/vnd.openxmlformats-officedocument.presentationml.presentation": ".pptx",
    "text/plain; charset=utf-8": ".txt",
    "application/zip": ".zip",
    "application/acad": ".dwg",
  }[inferredMimeType] || "";
}

function normalizeExternalUrl(value) {
  return String(value || "").trim().replace(/\/+$/, "");
}

function requestOrigin(req) {
  const forwardedProto = safeText(req.headers["x-forwarded-proto"], "");
  const forwardedHost = safeText(req.headers["x-forwarded-host"], "");
  const protocol = forwardedProto || "http";
  const host = forwardedHost || safeText(req.headers.host, "127.0.0.1:8080");
  return `${protocol}://${host}`;
}

function onlyOfficeDocumentType(name) {
  const ext = path.extname(String(name || "")).toLowerCase();
  if ([".doc", ".docx", ".txt", ".rtf", ".odt", ".md"].includes(ext)) {
    return "word";
  }
  if ([".xls", ".xlsx", ".csv", ".ods"].includes(ext)) {
    return "cell";
  }
  if ([".ppt", ".pptx", ".odp"].includes(ext)) {
    return "slide";
  }
  return "";
}

function isOnlyOfficeSupportedDocument(name) {
  return Boolean(onlyOfficeDocumentType(name));
}

function onlyOfficePublicOrigin(req) {
  return ONLYOFFICE_PUBLIC_BASE_URL || requestOrigin(req);
}

function onlyOfficeCallbackGrantSecret() {
  return ONLYOFFICE_JWT_SECRET || storageSigningSecret();
}

function signOnlyOfficeCallbackGrantPayload(payload) {
  const body = base64UrlEncode(JSON.stringify(payload));
  const signature = base64UrlEncode(
    crypto.createHmac("sha256", onlyOfficeCallbackGrantSecret()).update(body).digest(),
  );
  return `${body}.${signature}`;
}

function createOnlyOfficeCallbackGrant(doc, versionEntry, userContext, requestedMode = "edit") {
  const expiresAt = Date.now() + Math.max(1000, Number(ONLYOFFICE_DOCUMENT_URL_TTL_MS || 0) || 0);
  return signOnlyOfficeCallbackGrantPayload({
    purpose: "onlyoffice-callback",
    docId: safeText(doc?.id, ""),
    versionId: safeText(versionEntry?.id, ""),
    projectId: safeText(doc?.projectId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID)),
    userId: safeText(userContext?.user?.id, ""),
    mode: safeText(requestedMode, "edit"),
    issuedAt: Date.now(),
    expiresAt,
  });
}

function parseBase64UrlJson(value) {
  try {
    const normalized = String(value || "").replaceAll("-", "+").replaceAll("_", "/");
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
  } catch {
    return null;
  }
}

function verifyOnlyOfficeCallbackGrant(token, doc, sourceVersionId) {
  const text = safeText(token, "");
  const [body, signature] = text.split(".");
  if (!body || !signature || text.split(".").length !== 2) {
    const error = new Error("OnlyOffice 回调授权缺失或格式无效。");
    error.statusCode = 403;
    throw error;
  }

  const expectedSignature = base64UrlEncode(
    crypto.createHmac("sha256", onlyOfficeCallbackGrantSecret()).update(body).digest(),
  );
  const left = Buffer.from(signature);
  const right = Buffer.from(expectedSignature);
  if (!left.length || left.length !== right.length || !crypto.timingSafeEqual(left, right)) {
    const error = new Error("OnlyOffice 回调授权签名校验失败。");
    error.statusCode = 403;
    throw error;
  }

  const payload = parseBase64UrlJson(body);
  const projectId = safeText(payload?.projectId, "");
  const userId = safeText(payload?.userId, "");
  if (
    !payload ||
    safeText(payload.purpose, "") !== "onlyoffice-callback" ||
    safeText(payload.docId, "") !== safeText(doc?.id, "") ||
    safeText(payload.versionId, "") !== safeText(sourceVersionId, "") ||
    projectId !== safeText(doc?.projectId, DEFAULT_PROJECT_ID) ||
    safeText(payload.mode, "") === "view" ||
    !userId ||
    Number(payload.expiresAt || 0) < Date.now()
  ) {
    const error = new Error("OnlyOffice 回调授权已失效或与当前文档不匹配。");
    error.statusCode = 403;
    throw error;
  }

  const user = userById(userId);
  if (!user || safeText(user.status, "") !== "active") {
    const error = new Error("OnlyOffice 回调授权对应用户不可用。");
    error.statusCode = 403;
    throw error;
  }

  const userContext = buildUserContext(user, projectId);
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.onlyOfficeEdit || !permissions.uploadVersion) {
    throw permissionDeniedError(
      permissions.approvalLocked
        ? "文件处于审批锁定状态，审批期间不能保存 OnlyOffice 编辑内容。"
        : "OnlyOffice 回调授权用户没有上传新版本的权限。",
    );
  }

  return userContext;
}

function buildOnlyOfficePayload(req, doc, versionEntry, requestedMode = "edit", actor = "系统", userContext = SYSTEM_USER_CONTEXT) {
  const documentType = onlyOfficeDocumentType(versionEntry.name || doc.name);
  if (!ONLYOFFICE_SERVER_URL) {
    return {
      enabled: false,
      reason: "missing_server_url",
      message: "尚未配置 OnlyOffice 文档服务地址。",
      setup: {
        serverUrlEnv: "ONLYOFFICE_SERVER_URL",
        publicBaseUrlEnv: "ONLYOFFICE_PUBLIC_BASE_URL",
        jwtSecretEnv: "ONLYOFFICE_JWT_SECRET",
      },
    };
  }

  if (!documentType) {
    return {
      enabled: false,
      reason: "unsupported_type",
      message: "当前文件类型不在 OnlyOffice 在线编辑范围内。",
    };
  }

  const actorLabel = safeText(actor, "系统");
  const editable =
    requestedMode !== "view" &&
    versionEntry.id === doc.currentVersionId &&
    canEditOnlyOfficeDocument(doc, actorLabel, userContext);
  const ext = path.extname(String(versionEntry.name || doc.name || "")).toLowerCase().replace(/^\./, "") || "docx";
  const publicOrigin = onlyOfficePublicOrigin(req);
  const homeUrl = new URL("/", `${publicOrigin}/`).toString();
  const fileUrl = new URL(signedOnlyOfficeUploadUrl(versionEntry.storedFileName), `${publicOrigin}/`).toString();
  const callbackGrant = editable ? createOnlyOfficeCallbackGrant(doc, versionEntry, userContext, requestedMode) : "";
  const callbackUrl = new URL(
    `/api/onlyoffice/documents/${doc.id}/callback?versionId=${encodeURIComponent(versionEntry.id)}&actor=${encodeURIComponent(actorLabel)}&grant=${encodeURIComponent(callbackGrant)}`,
    `${publicOrigin}/`,
  ).toString();
  const config = {
    documentType,
    type: "desktop",
    width: "100%",
    height: "100%",
    document: {
      title: versionEntry.name || doc.name,
      url: fileUrl,
      fileType: ext,
      info: {
        owner: safeText(doc.owner, safeText(doc.uploader, actorLabel)),
        uploaded: formatOnlyOfficeInfoDate(versionEntry.uploadedAt || doc.updatedAt || doc.uploadedAt),
        folder: folderName(doc.parentId),
      },
      key: crypto
        .createHash("sha1")
        .update([ONLYOFFICE_DOCUMENT_KEY_NAMESPACE, doc.id, versionEntry.id, versionEntry.uploadedAt, versionEntry.size, requestedMode].join(":"))
        .digest("hex"),
      permissions: {
        edit: editable,
        download: true,
        print: true,
        comment: editable,
        review: editable,
      },
    },
    editorConfig: {
      lang: "zh-CN",
      mode: editable ? "edit" : "view",
      user: {
        id: actorLabel,
        name: actorLabel,
      },
      customization: {
        autosave: true,
        forcesave: true,
        compactToolbar: false,
        compactHeader: false,
        close: {
          visible: true,
          text: "关闭文档",
        },
        goback: {
          url: homeUrl,
          text: "返回 CDE 文件管理系统",
          blank: false,
        },
      },
    },
  };

  if (editable) {
    config.editorConfig.callbackUrl = callbackUrl;
  }

  if (ONLYOFFICE_JWT_SECRET) {
    config.token = signOnlyOfficeToken(config);
  }

  return {
    enabled: true,
    serverUrl: ONLYOFFICE_SERVER_URL,
    docsApiUrl: `${ONLYOFFICE_SERVER_URL}/web-apps/apps/api/documents/api.js`,
    mode: config.editorConfig.mode,
    actor: actorLabel,
    publicOrigin,
    config,
  };
}

function modelDiffViewerUrnForVersion(doc, versionEntry, taskId = "") {
  const task = taskId ? modelDiffTaskById(taskId) : null;
  if (!doc || !versionEntry || !task || task.documentId !== doc.id) {
    return "";
  }
  const versionId = safeText(versionEntry.id, "");
  if (versionId === task.versionAId) {
    return safeText(task.modelUrnA || modelDiffSnapshotById(task.snapshotAId)?.modelUrn, "");
  }
  if (versionId === task.versionBId) {
    return safeText(task.modelUrnB || modelDiffSnapshotById(task.snapshotBId)?.modelUrn, "");
  }
  return "";
}

function apsConfigForViewerVersion(doc, versionEntry, options = {}) {
  const selectedVersion = versionEntry || resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId) || currentVersionSnapshot(doc);
  const versionId = safeText(selectedVersion?.id, safeText(doc?.currentVersionId, ""));
  const docAps = normalizeApsConfig(doc?.aps || {});
  const versionAps = normalizeApsConfig(selectedVersion?.aps || {});
  const docApsBelongsToVersion = Boolean(
    versionId &&
    [safeText(docAps.sourceVersionId, ""), safeText(doc?.currentVersionId, "")].includes(versionId),
  );
  const diffTaskUrn = modelDiffViewerUrnForVersion(doc, selectedVersion, safeText(options.modelDiffTaskId, ""));
  let resolved = normalizeApsConfig({
    ...(docApsBelongsToVersion ? versionAps : {}),
    ...(docApsBelongsToVersion ? docAps : versionAps),
    sourceVersionId: versionId,
  });
  if (diffTaskUrn) {
    resolved = normalizeApsConfig({
      ...resolved,
      urn: diffTaskUrn,
      translationStatus: "success",
      translationMessage: resolved.translationMessage || "来自模型差异对比任务的版本 URN",
      sourceVersionId: versionId,
    });
  }
  return resolved;
}

function buildApsViewerPayload(req, doc, actor = "系统", options = {}) {
  const apsSettings = effectiveApsSettings();
  const assetLabel = apsDocumentAssetLabel(doc.name);
  const versionEntry = options.versionEntry || resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId) || currentVersionSnapshot(doc);
  const apsConfig = apsConfigForViewerVersion(doc, versionEntry, {
    modelDiffTaskId: options.modelDiffTaskId,
  });
  const scheduleId = safeText(options.scheduleId, "");
  const schedule = scheduleId ? constructionScheduleById(scheduleId) : null;
  const schedulePayload = schedule && schedule.documentId === doc.id
    ? {
        scheduleId: schedule.id,
        name: schedule.name,
        date: normalizeScheduleDate(options.scheduleDate) || schedule.dataDate || new Date().toISOString().slice(0, 10),
        timeline: buildConstructionTimelinePayload(schedule.id, normalizeScheduleDate(options.scheduleDate) || schedule.dataDate || new Date().toISOString().slice(0, 10)).timeline,
        completeness: buildConstructionMappingCompleteness(schedule.id),
        activities: constructionActivitiesForSchedule(schedule.id).map((activity) => ({
          id: activity.id,
          activityId: activity.activityId,
          name: activity.name,
          wbsId: activity.wbsId,
          plannedStart: activity.plannedStart,
          plannedFinish: activity.plannedFinish,
          percentComplete: activity.percentComplete,
          status: activity.status,
        })),
      }
    : null;
  if (!isApsModelDocument(doc.name)) {
    return {
      enabled: false,
      reason: "unsupported_type",
      message: `当前文件类型未配置为 APS ${assetLabel}工作台。`,
    };
  }

  if (!apsSettingsReady(apsSettings)) {
    return {
      enabled: false,
      reason: "missing_credentials",
      message: "尚未配置 APS Viewer 所需的客户端凭证，请在系统设置 / APS 配置中补齐。",
      setup: {
        settingsMenu: "access/aps_configuration",
      },
    };
  }

  const translationStatus = normalizeApsTranslationStatus(apsConfig.translationStatus, apsConfig.urn ? "success" : "idle");
  if (!apsConfig.urn) {
    if (isApsTranslationActive(translationStatus)) {
      return {
        enabled: false,
        reason: "translation_pending",
        message: apsConfig.translationProgress
          ? `当前${assetLabel}正在 APS 自动转换中（${apsConfig.translationProgress}），完成后会自动回填 URN。`
          : `当前${assetLabel}正在 APS 自动转换中，完成后会自动回填 URN。`,
        aps: apsConfig,
      };
    }

    if (translationStatus === "failed") {
      return {
        enabled: false,
        reason: "translation_failed",
        message: apsConfig.translationError
          ? `APS 自动转换失败：${apsConfig.translationError}`
          : `APS 自动转换失败，请检查${assetLabel}文件和凭证配置后重试。`,
        aps: apsConfig,
      };
    }

    return {
      enabled: false,
      reason: "missing_urn",
      message: `当前${assetLabel}版本 ${versionEntry.version || ""} 还没有配置 APS URN，请先完成该版本转换或生成属性快照。`,
      aps: apsConfig,
    };
  }

  return {
    enabled: true,
    actor: safeText(actor, "系统"),
    viewerVersion: apsSettings.viewerVersion,
    viewerEnv: apsSettings.viewerEnv,
    viewerApi: apsSettings.viewerApi,
    viewerJsUrl: `https://developer.api.autodesk.com/modelderivative/v2/viewers/${apsSettings.viewerVersion}/viewer3D.min.js`,
    viewerCssUrl: `https://developer.api.autodesk.com/modelderivative/v2/viewers/${apsSettings.viewerVersion}/style.min.css`,
    tokenUrl: "/api/aps/auth/token",
    reviewApiUrl: `/api/documents/${doc.id}/aps`,
    file: {
      id: doc.id,
      name: doc.name,
      version: versionEntry.version || doc.version,
      versionId: versionEntry.id || doc.currentVersionId,
      folder: folderName(doc.parentId),
      updatedAt: versionEntry.uploadedAt || doc.updatedAt,
      owner: doc.owner,
    },
    workspaceKind: apsDocumentWorkspaceKind(doc.name),
    versionLocked: Boolean(versionEntry.id && versionEntry.id !== doc.currentVersionId),
    aps: apsConfig,
    issues: (doc.annotations || [])
      .filter((annotation) => hasIssueLocation(annotation))
      .map((annotation) => ({ ...annotation })),
    schedule: schedulePayload,
  };
}

function isApsModelDocument(name) {
  const ext = path.extname(String(name || "")).toLowerCase();
  return APS_VIEWER_DOCUMENT_EXTENSIONS.has(ext);
}

function apsDocumentWorkspaceKind(name) {
  const ext = path.extname(String(name || "")).toLowerCase();
  return APS_DRAWING_DOCUMENT_EXTENSIONS.has(ext) ? "drawing" : "model";
}

function apsDocumentAssetLabel(name) {
  return apsDocumentWorkspaceKind(name) === "drawing" ? "图纸" : "模型";
}

async function getApsViewerToken() {
  return getApsAccessToken(["data:read", "viewables:read"]);
}

async function getApsAccessToken(scopes = []) {
  const apsSettings = effectiveApsSettings();
  if (!apsSettingsReady(apsSettings)) {
    const error = new Error("Missing APS credentials");
    error.statusCode = 503;
    throw error;
  }

  const normalizedScopes = [...new Set((Array.isArray(scopes) ? scopes : [scopes]).map((item) => safeText(item, "")).filter(Boolean))].sort();
  const scopeKey = normalizedScopes.join(" ");
  const cacheKey = `${sha1Hash(apsSettings.clientId)}:${scopeKey}`;
  const now = Date.now();
  const cached = apsTokenCaches.get(cacheKey);
  if (cached && cached.expiresAt > now + 60 * 1000) {
    return {
      access_token: cached.accessToken,
      expires_in: Math.max(60, Math.floor((cached.expiresAt - now) / 1000)),
      token_type: cached.tokenType,
    };
  }

  const response = await fetch("https://developer.api.autodesk.com/authentication/v2/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams({
      client_id: apsSettings.clientId,
      client_secret: apsSettings.clientSecret,
      grant_type: "client_credentials",
      scope: scopeKey,
    }).toString(),
  });

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS token request failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  const payload = await response.json();
  const expiresIn = Math.max(300, Number(payload.expires_in || 3599));
  apsTokenCaches.set(cacheKey, {
    accessToken: safeText(payload.access_token, ""),
    tokenType: safeText(payload.token_type, "Bearer"),
    expiresAt: now + expiresIn * 1000,
  });

  return {
    access_token: safeText(payload.access_token, ""),
    expires_in: expiresIn,
    token_type: safeText(payload.token_type, "Bearer"),
  };
}

function isApsTranslationActive(status) {
  return ["queued", "uploading", "uploaded", "translating"].includes(normalizeApsTranslationStatus(status, "idle"));
}

function resolvedApsBucketKey() {
  const apsSettings = effectiveApsSettings();
  return normalizeApsBucketKey(apsSettings.bucketKey || `cde-docs-${sha1Hash(apsSettings.clientId || "local").slice(0, 18)}`);
}

function normalizeApsBucketKey(value) {
  const normalized = String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 128)
    .replace(/-+$/g, "");
  if (normalized.length >= 3) {
    return normalized;
  }
  return `cde-docs-${sha1Hash(normalized || "fallback").slice(0, 10)}`;
}

function sanitizeApsObjectSegment(value, fallback = "model") {
  const original = String(value || "").trim();
  const extension = path.extname(original).toLowerCase();
  const baseName = path.basename(original || fallback, extension)
    .replace(/[^a-zA-Z0-9._-]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return `${baseName || fallback}${extension}`;
}

function buildApsObjectKey(doc, versionEntry) {
  const sourceVersionId = safeText(versionEntry?.id, safeText(doc?.currentVersionId, crypto.randomUUID()));
  const safeName = sanitizeApsObjectSegment(versionEntry?.name || doc?.name || "model");
  return `documents/${safeText(doc?.id, "unknown")}/${sourceVersionId}-${safeName}`;
}

function apsObjectIdToUrn(objectId) {
  return Buffer.from(String(objectId || ""), "utf8")
    .toString("base64")
    .replace(/=+$/g, "");
}

function clearApsTranslationTimer(docId) {
  const timer = apsTranslationTimers.get(docId);
  if (timer) {
    clearTimeout(timer);
  }
  apsTranslationTimers.delete(docId);
}

function currentApsTranslationDocument(docId, requestId = "", sourceVersionId = "") {
  const doc = documents.find((item) => item.id === docId);
  if (!doc || !isApsModelDocument(doc.name)) {
    return null;
  }

  if (requestId && safeText(doc.aps?.translationRequestId, "") !== requestId) {
    return null;
  }

  if (sourceVersionId && safeText(doc.aps?.sourceVersionId, "") !== sourceVersionId) {
    return null;
  }

  return doc;
}

function syncApsStateToVersionEntry(doc, apsState = {}) {
  const versionId = safeText(apsState.sourceVersionId, safeText(doc?.currentVersionId, ""));
  if (!doc || !versionId || !Array.isArray(doc.versionHistory)) {
    return;
  }
  const entry = doc.versionHistory.find((item) => item.id === versionId);
  if (!entry) {
    return;
  }
  entry.aps = normalizeApsConfig({
    ...(entry.aps || {}),
    ...apsState,
    sourceVersionId: versionId,
  });
}

function patchApsTranslationState(docId, requestId, patch, { touch = false, persist = true } = {}) {
  const doc = currentApsTranslationDocument(docId, requestId, safeText(patch?.sourceVersionId, ""));
  if (!doc) {
    return null;
  }

  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    ...(patch || {}),
    translationUpdatedAt: new Date().toISOString(),
  });
  syncApsStateToVersionEntry(doc, doc.aps);

  if (touch) {
    touchDocument(doc);
  }

  if (persist) {
    persistStore();
  }

  return doc;
}

function queueApsTranslationForDocument(doc, actor, options = {}) {
  if (!doc || !isApsModelDocument(doc.name)) {
    return doc;
  }

  const currentAps = normalizeApsConfig(doc.aps);
  const versionEntry = resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId) || currentVersionSnapshot(doc);
  const sourceVersionId = safeText(versionEntry.id, safeText(doc.currentVersionId, ""));
  if (!sourceVersionId) {
    return doc;
  }

  if (!options.force && currentAps.sourceVersionId === sourceVersionId) {
    if ((currentAps.urn && currentAps.translationStatus === "success") || isApsTranslationActive(currentAps.translationStatus)) {
      return doc;
    }
  }

  const requestId = crypto.randomUUID();
  doc.aps = normalizeApsConfig({
    ...(doc.aps || {}),
    urn: "",
    pendingUrn: "",
    bucketKey: resolvedApsBucketKey(),
    objectKey: buildApsObjectKey(doc, versionEntry),
    objectId: "",
    sourceVersionId,
    translationRequestId: requestId,
    translationStatus: "queued",
    translationProgress: "0%",
    translationMessage: apsSettingsReady() ? "等待上传到 APS OSS" : "APS 凭证未配置，请到系统设置 / APS 配置补齐后重试",
    translationError: "",
    translationUpdatedAt: new Date().toISOString(),
    viewable2dGuid: "",
    viewable3dGuid: "",
  });
  syncApsStateToVersionEntry(doc, doc.aps);
  setVersionParseStatus(doc, versionEntry, "processing");

  touchDocument(doc);
  addActivity(doc, actor, "提交 APS 转换", safeText(options.reason, `${doc.name} ${doc.version} 已提交 APS 自动转换`));
  persistStore();
  scheduleApsTranslationRun(doc.id, requestId, actor, 50);
  return doc;
}

function scheduleApsTranslationRun(docId, requestId, actor, delayMs = 0) {
  clearApsTranslationTimer(docId);
  const timer = setTimeout(() => {
    apsTranslationTimers.delete(docId);
    void runApsTranslationJob(docId, requestId, actor).catch((error) => {
      markApsTranslationFailed(docId, requestId, actor, error);
    });
  }, delayMs);
  apsTranslationTimers.set(docId, timer);
}

function scheduleApsManifestPoll(docId, requestId, urn, actor, delayMs = 4000) {
  clearApsTranslationTimer(docId);
  const timer = setTimeout(() => {
    apsTranslationTimers.delete(docId);
    void pollApsTranslationManifest(docId, requestId, urn, actor).catch((error) => {
      markApsTranslationFailed(docId, requestId, actor, error);
    });
  }, delayMs);
  apsTranslationTimers.set(docId, timer);
}

async function runApsTranslationJob(docId, requestId, actor) {
  const doc = currentApsTranslationDocument(docId, requestId);
  if (!doc) {
    return;
  }

  const sourceVersionId = safeText(doc.aps?.sourceVersionId, doc.currentVersionId);
  const versionEntry = requireVersionEntry(doc, sourceVersionId);
  if (!safeText(versionEntry.storedFileName, "") || !(await storageService.uploads.exists(versionEntry.storedFileName))) {
    const error = new Error("找不到待转换的本地模型文件。");
    error.statusCode = 404;
    throw error;
  }

  patchApsTranslationState(docId, requestId, {
    sourceVersionId,
    translationStatus: "uploading",
    translationProgress: "5%",
    translationMessage: "正在获取 APS 上传地址",
    translationError: "",
  });

  const token = await getApsAccessToken([
    "bucket:create",
    "bucket:read",
    "data:create",
    "data:read",
    "data:write",
    "viewables:read",
  ]);
  const bucketKey = safeText(doc.aps?.bucketKey, resolvedApsBucketKey());
  const objectKey = safeText(doc.aps?.objectKey, buildApsObjectKey(doc, versionEntry));
  await ensureApsBucket(token.access_token, bucketKey);

  patchApsTranslationState(docId, requestId, {
    sourceVersionId,
    bucketKey,
    objectKey,
    translationStatus: "uploading",
    translationProgress: "15%",
    translationMessage: "正在上传模型到 APS OSS",
  });

  const buffer = await storageService.uploads.readBuffer(versionEntry.storedFileName);
  const signedUpload = await requestApsSignedUpload(token.access_token, bucketKey, objectKey);
  const etag = await uploadBufferToApsSignedUrl(signedUpload.urls[0], buffer);
  const completedUpload = await completeApsSignedUpload(
    token.access_token,
    bucketKey,
    objectKey,
    signedUpload.uploadKey,
    buffer.length,
    [etag],
    versionEntry.mimeType || doc.mimeType,
  );

  const objectId = safeText(completedUpload.objectId, `urn:adsk.objects:os.object:${bucketKey}/${objectKey}`);
  const pendingUrn = apsObjectIdToUrn(objectId);
  patchApsTranslationState(docId, requestId, {
    sourceVersionId,
    bucketKey,
    objectKey,
    objectId,
    pendingUrn,
    translationStatus: "uploaded",
    translationProgress: "30%",
    translationMessage: "OSS 上传完成，正在提交 Model Derivative 任务",
  });

  await startApsModelDerivativeJob(token.access_token, pendingUrn);
  patchApsTranslationState(docId, requestId, {
    sourceVersionId,
    pendingUrn,
    translationStatus: "translating",
    translationProgress: "40%",
    translationMessage: "APS 正在转换模型，请稍候",
  });
  scheduleApsManifestPoll(docId, requestId, pendingUrn, actor, 4000);
}

async function pollApsTranslationManifest(docId, requestId, urn, actor) {
  const doc = currentApsTranslationDocument(docId, requestId);
  if (!doc) {
    return;
  }

  const token = await getApsAccessToken(["data:read", "viewables:read"]);
  const manifest = await fetchApsManifest(token.access_token, urn);
  if (!manifest) {
    patchApsTranslationState(docId, requestId, {
      translationStatus: "translating",
      translationProgress: "",
      translationMessage: "APS 已接收任务，正在排队转换",
    });
    scheduleApsManifestPoll(docId, requestId, urn, actor, 4000);
    return;
  }

  const status = String(manifest.status || "").toLowerCase();
  const progress = safeText(manifest.progress, status === "success" ? "complete" : "");

  if (status === "success") {
    const viewableGuids = extractApsViewableGuids(manifest);
    const updated = patchApsTranslationState(
      docId,
      requestId,
      {
        urn,
        pendingUrn: urn,
        viewable2dGuid: viewableGuids.viewable2dGuid,
        viewable3dGuid: viewableGuids.viewable3dGuid,
        translationStatus: "success",
        translationProgress: progress || "complete",
        translationMessage: "APS 转换完成，已自动回填 URN",
        translationError: "",
      },
      { touch: true, persist: false },
    );
    if (updated) {
      const parsedEntry = requireVersionEntry(updated, safeText(updated.aps?.sourceVersionId, updated.currentVersionId));
      setVersionParseStatus(updated, parsedEntry, "done");
      addActivity(updated, actor, "APS 转换完成", `${updated.name} ${updated.version} 已完成模型转换并自动回填 URN`);
      try {
        await extractModelGeometryForDocument(updated, {
          actor: "系统",
          userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, updated.projectId),
        });
      } catch (error) {
        updated.aps = normalizeApsConfig({
          ...(updated.aps || {}),
          translationMessage: `APS 转换完成，几何索引提取失败：${formatApsTranslationFailure(error)}`,
          translationError: formatApsTranslationFailure(error),
          translationUpdatedAt: new Date().toISOString(),
        });
        addActivity(updated, "系统", "模型几何索引提取失败", formatApsTranslationFailure(error));
        touchDocument(updated);
      }
      migrateOpenIssueBindingsForApsDocument(updated, {
        actor: "系统",
        elementIndex: updated.aps?.elementIndex || [],
        modelUrn: urn,
        boundModelVersion: updated.version,
        versionId: updated.currentVersionId,
      });
      persistStore();
      await bestEffortProjectEmailNotification("parseCompleted", {
        document: updated,
        versionEntry: parsedEntry,
        userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, updated.projectId),
        occurredAt: safeText(updated.aps?.translationUpdatedAt, new Date().toISOString()),
        note: "APS 模型转换完成，URN 已自动回填",
      });
    }
    clearApsTranslationTimer(docId);
    return;
  }

  if (status === "failed" || status === "timeout") {
    throw new Error(formatApsManifestFailure(manifest));
  }

  patchApsTranslationState(docId, requestId, {
    translationStatus: "translating",
    translationProgress: progress,
    translationMessage: progress ? `APS 正在转换模型（${progress}）` : "APS 正在转换模型，请稍候",
  });
  scheduleApsManifestPoll(docId, requestId, urn, actor, 4500);
}

function markApsTranslationFailed(docId, requestId, actor, error) {
  clearApsTranslationTimer(docId);
  const updated = patchApsTranslationState(
    docId,
    requestId,
    {
      urn: "",
      translationStatus: "failed",
      translationMessage: "APS 自动转换失败",
      translationError: formatApsTranslationFailure(error),
    },
    { touch: true, persist: false },
  );

  if (updated) {
    const failedEntry = resolveCurrentVersionEntry(updated.versionHistory, safeText(updated.aps?.sourceVersionId, updated.currentVersionId));
    setVersionParseStatus(updated, failedEntry, "failed", {
      errorMessage: safeText(updated.aps?.translationError, "APS 自动转换失败"),
    });
    addActivity(updated, actor, "APS 转换失败", updated.aps.translationError || "未知错误");
    persistStore();
    void bestEffortProjectEmailNotification("parseFailed", {
      document: updated,
      versionEntry: failedEntry,
      userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, updated.projectId),
      occurredAt: safeText(updated.aps?.translationUpdatedAt, new Date().toISOString()),
      errorMessage: safeText(updated.aps?.translationError, "APS 自动转换失败"),
    });
  }
}

async function ensureApsBucket(accessToken, bucketKey) {
  if (apsEnsuredBucketKey === bucketKey) {
    return;
  }

  const apsSettings = effectiveApsSettings();
  const response = await fetch("https://developer.api.autodesk.com/oss/v2/buckets", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      "x-ads-region": apsSettings.bucketRegion,
    },
    body: JSON.stringify({
      bucketKey,
      policyKey: apsSettings.bucketPolicy,
    }),
  });

  if (!response.ok && response.status !== 409) {
    const detail = await response.text();
    const error = new Error(detail || `APS bucket create failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  apsEnsuredBucketKey = bucketKey;
}

async function requestApsSignedUpload(accessToken, bucketKey, objectKey) {
  const encodedObjectKey = encodeURIComponent(objectKey);
  const response = await fetch(
    `https://developer.api.autodesk.com/oss/v2/buckets/${encodeURIComponent(bucketKey)}/objects/${encodedObjectKey}/signeds3upload`,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    },
  );

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS signed upload request failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  const payload = await response.json();
  if (!Array.isArray(payload.urls) || !payload.urls.length || !safeText(payload.uploadKey, "")) {
    const error = new Error("APS signed upload response is incomplete");
    error.statusCode = 502;
    throw error;
  }

  return payload;
}

async function uploadBufferToApsSignedUrl(url, buffer) {
  const response = await fetch(String(url || ""), {
    method: "PUT",
    body: buffer,
  });

  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    const error = new Error(detail || `APS signed upload PUT failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  const etag = String(response.headers.get("etag") || "")
    .replace(/^"+|"+$/g, "")
    .trim();
  if (!etag) {
    const error = new Error("APS signed upload did not return ETag");
    error.statusCode = 502;
    throw error;
  }

  return etag;
}

async function completeApsSignedUpload(accessToken, bucketKey, objectKey, uploadKey, size, eTags, mimeType = "") {
  const encodedObjectKey = encodeURIComponent(objectKey);
  const response = await fetch(
    `https://developer.api.autodesk.com/oss/v2/buckets/${encodeURIComponent(bucketKey)}/objects/${encodedObjectKey}/signeds3upload`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
        ...(safeText(mimeType, "") ? { "x-ads-meta-Content-Type": mimeType } : {}),
      },
      body: JSON.stringify({
        uploadKey,
        size,
        eTags,
      }),
    },
  );

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS signed upload completion failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  return response.json();
}

async function startApsModelDerivativeJob(accessToken, urn) {
  const response = await fetch("https://developer.api.autodesk.com/modelderivative/v2/designdata/job", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      "x-ads-force": "true",
    },
    body: JSON.stringify({
      input: {
        urn,
      },
      output: {
        formats: [
          {
            type: "svf2",
            views: ["2d", "3d"],
          },
        ],
      },
    }),
  });

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS translation job request failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  return response.json();
}

async function fetchApsManifest(accessToken, urn) {
  const response = await fetch(
    `https://developer.api.autodesk.com/modelderivative/v2/designdata/${encodeURIComponent(urn)}/manifest`,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    },
  );

  if (response.status === 404) {
    return null;
  }

  if (!response.ok) {
    const detail = await response.text();
    const error = new Error(detail || `APS manifest request failed (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  return response.json();
}

function retryAfterHeaderMs(value) {
  const text = safeText(value, "");
  if (!text) {
    return 0;
  }
  const seconds = Number(text);
  if (Number.isFinite(seconds)) {
    return Math.max(0, seconds * 1000);
  }
  const timestamp = Date.parse(text);
  return Number.isFinite(timestamp) ? Math.max(0, timestamp - Date.now()) : 0;
}

async function fetchApsModelDerivativeJson(accessToken, url, label) {
  let lastError = null;
  for (let attempt = 1; attempt <= CDE_APS_HTTP_MAX_RETRIES; attempt += 1) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), CDE_APS_HTTP_TIMEOUT_MS);
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      });
      const requestId = safeText(
        response.headers.get("x-ads-troubleshooting-id") ||
        response.headers.get("x-request-id") ||
        response.headers.get("x-ads-request-id"),
        "",
      );

      if (!response.ok) {
        const detail = await response.text().catch(() => "");
        const statusCode = [429, 500, 502, 503, 504].includes(response.status) ? response.status : 502;
        const error = new Error(detail || `${label} request failed (${response.status}${requestId ? `, request ${requestId}` : ""})`);
        error.statusCode = statusCode;
        error.retryAfterMs = retryAfterHeaderMs(response.headers.get("retry-after"));
        error.requestId = requestId;
        throw error;
      }

      return response.json();
    } catch (error) {
      lastError = error;
      const statusCode = Number(error?.statusCode || 0);
      const retryable = error?.name === "AbortError" || !statusCode || [408, 429, 500, 502, 503, 504].includes(statusCode);
      if (attempt >= CDE_APS_HTTP_MAX_RETRIES || !retryable) {
        if (error?.name === "AbortError") {
          const timeoutError = new Error(`${label} request timed out after ${CDE_APS_HTTP_TIMEOUT_MS}ms`);
          timeoutError.statusCode = 504;
          throw timeoutError;
        }
        throw error;
      }
      await waitMs(Math.min(error.retryAfterMs || CDE_BACKGROUND_JOB_RETRY_BASE_MS * attempt, 10000));
    } finally {
      clearTimeout(timeout);
    }
  }
  throw lastError || new Error(`${label} request failed`);
}

function apsNextPageUrl(payload) {
  return safeText(
    payload?.pagination?.next ||
    payload?.links?.next?.href ||
    payload?.data?.next ||
    payload?.next,
    "",
  );
}

async function fetchApsModelDerivativePropertyCollection(accessToken, firstUrl) {
  const firstPayload = await fetchApsModelDerivativeJson(accessToken, firstUrl, "APS properties");
  const firstCollection = Array.isArray(firstPayload?.data?.collection) ? firstPayload.data.collection : null;
  let nextUrl = apsNextPageUrl(firstPayload);
  if (!firstCollection || !nextUrl) {
    return firstPayload;
  }
  const merged = [...firstCollection];
  const seenUrls = new Set([firstUrl]);
  for (let page = 0; nextUrl && page < 100; page += 1) {
    const absoluteUrl = new URL(nextUrl, firstUrl).toString();
    if (seenUrls.has(absoluteUrl)) {
      break;
    }
    seenUrls.add(absoluteUrl);
    const payload = await fetchApsModelDerivativeJson(accessToken, absoluteUrl, "APS properties");
    if (Array.isArray(payload?.data?.collection)) {
      merged.push(...payload.data.collection);
    }
    nextUrl = apsNextPageUrl(payload);
  }
  return {
    ...firstPayload,
    data: {
      ...(firstPayload.data || {}),
      collection: merged,
      pagination: {
        ...(firstPayload.data?.pagination || {}),
        fetchedPages: seenUrls.size,
      },
    },
  };
}

async function fetchApsModelPropertiesForDocument(doc, modelUrn = "") {
  const urn = safeText(modelUrn, doc?.aps?.urn || "");
  if (!urn) {
    const error = new Error("APS 属性提取缺少模型 URN。");
    error.statusCode = 400;
    throw error;
  }

  const token = await getApsAccessToken(["data:read", "viewables:read"]);
  const encodedUrn = encodeURIComponent(urn);
  const metadataPayload = await fetchApsModelDerivativeJson(
    token.access_token,
    `https://developer.api.autodesk.com/modelderivative/v2/designdata/${encodedUrn}/metadata`,
    "APS metadata",
  );
  const metadataItems = Array.isArray(metadataPayload?.data?.metadata)
    ? metadataPayload.data.metadata
    : [];
  const preferredGuid = safeText(doc?.aps?.viewable3dGuid, "");
  const selectedMetadata =
    metadataItems.find((item) => safeText(item.guid, "") === preferredGuid) ||
    metadataItems.find((item) => safeText(item.role, "").toLowerCase() === "3d") ||
    metadataItems[0];

  if (!safeText(selectedMetadata?.guid, "")) {
    const error = new Error("APS 未返回可用于属性提取的 metadata guid。");
    error.statusCode = 502;
    throw error;
  }

  return fetchApsModelDerivativePropertyCollection(
    token.access_token,
    `https://developer.api.autodesk.com/modelderivative/v2/designdata/${encodedUrn}/metadata/${encodeURIComponent(selectedMetadata.guid)}/properties?forceget=true`,
  );
}

async function fetchApsModelPropertiesForQuantityTask(task) {
  const doc = documents.find((item) => item.id === task?.documentId) || null;
  return fetchApsModelPropertiesForDocument(doc, safeText(task?.modelUrn, doc?.aps?.urn || ""));
}

function formatApsManifestFailure(manifest) {
  const messages = collectApsManifestMessages(manifest);
  if (messages.length) {
    return messages.join("；");
  }
  if (safeText(manifest?.status, "")) {
    return `Model Derivative 返回状态 ${manifest.status}`;
  }
  return "Model Derivative 未返回可用的错误信息";
}

function collectApsManifestMessages(manifest) {
  const messages = [];
  const queue = [manifest];
  while (queue.length) {
    const current = queue.shift();
    if (!current || typeof current !== "object") {
      continue;
    }

    const currentType = safeText(current.type, "");
    const currentMessage = safeText(current.message || current.error || current.reason, "");
    if (currentMessage) {
      messages.push(currentType ? `${currentType}: ${currentMessage}` : currentMessage);
    }

    const errors = Array.isArray(current.errors) ? current.errors : [];
    errors.forEach((item) => {
      const message = safeText(item?.message || item?.error, "");
      if (message) {
        messages.push(message);
      }
    });

    const children = Array.isArray(current.children) ? current.children : [];
    const derivatives = Array.isArray(current.derivatives) ? current.derivatives : [];
    queue.push(...children, ...derivatives);
  }
  return [...new Set(messages.filter(Boolean))];
}

function extractApsViewableGuids(manifest) {
  const queue = [manifest];
  let viewable2dGuid = "";
  let viewable3dGuid = "";

  while (queue.length && (!viewable2dGuid || !viewable3dGuid)) {
    const current = queue.shift();
    if (!current || typeof current !== "object") {
      continue;
    }

    if (!viewable2dGuid && current.type === "geometry" && current.role === "2d" && safeText(current.guid, "")) {
      viewable2dGuid = safeText(current.guid, "");
    }

    if (!viewable3dGuid && current.type === "geometry" && current.role === "3d" && safeText(current.guid, "")) {
      viewable3dGuid = safeText(current.guid, "");
    }

    const children = Array.isArray(current.children) ? current.children : [];
    const derivatives = Array.isArray(current.derivatives) ? current.derivatives : [];
    queue.push(...children, ...derivatives);
  }

  return {
    viewable2dGuid,
    viewable3dGuid,
  };
}

function formatApsTranslationFailure(error) {
  return safeText(error?.message, "未知错误");
}

function resumePendingApsTranslations() {
  documents.forEach((doc) => {
    if (!isApsModelDocument(doc.name)) {
      return;
    }

    const aps = normalizeApsConfig(doc.aps);
    const requestId = safeText(aps.translationRequestId, "");
    if (!requestId) {
      return;
    }

    if (["queued", "uploading", "uploaded"].includes(aps.translationStatus)) {
      scheduleApsTranslationRun(doc.id, requestId, safeText(doc.uploader, "系统"), 1000);
      return;
    }

    if (aps.translationStatus === "translating") {
      if (aps.pendingUrn) {
        scheduleApsManifestPoll(doc.id, requestId, aps.pendingUrn, safeText(doc.uploader, "系统"), 1000);
        return;
      }
      scheduleApsTranslationRun(doc.id, requestId, safeText(doc.uploader, "系统"), 1000);
    }
  });
}

function canEditOnlyOfficeDocument(doc, actor, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.onlyOfficeEdit) {
    return false;
  }
  const checkedOutBy = currentCheckedOutBy(doc);
  return !checkedOutBy || checkedOutBy === actor;
}

function signOnlyOfficeToken(payload) {
  const header = base64UrlEncode(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const body = base64UrlEncode(JSON.stringify(payload));
  const signature = base64UrlEncode(
    crypto.createHmac("sha256", ONLYOFFICE_JWT_SECRET).update(`${header}.${body}`).digest(),
  );
  return `${header}.${body}.${signature}`;
}

function base64UrlEncode(value) {
  return Buffer.from(value)
    .toString("base64")
    .replaceAll("+", "-")
    .replaceAll("/", "_")
    .replace(/=+$/g, "");
}

function sha1Hash(value) {
  return crypto.createHash("sha1").update(value).digest("hex");
}

function sha256Hash(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function canonicalizeJson(value) {
  if (Array.isArray(value)) {
    return value.map(canonicalizeJson);
  }
  if (value && typeof value === "object") {
    return Object.keys(value).sort().reduce((next, key) => {
      next[key] = canonicalizeJson(value[key]);
      return next;
    }, {});
  }
  return value;
}

function storageSigningSecret() {
  return process.env.CDE_STORAGE_SIGNING_SECRET || DEFAULT_BOOTSTRAP_PASSWORD || "cde-storage-signing";
}

function storageSignature(bucket, fileName, expiresAt) {
  return crypto
    .createHmac("sha256", storageSigningSecret())
    .update(`${bucket}:${path.basename(String(fileName || ""))}:${Number(expiresAt || 0)}`)
    .digest("hex");
}

function signedStorageUrl(bucket, fileName, ttlMs = STORAGE_SIGNED_URL_TTL_MS) {
  const safeName = path.basename(String(fileName || ""));
  const expiresAt = Date.now() + Math.max(1000, Number(ttlMs || STORAGE_SIGNED_URL_TTL_MS));
  const signature = storageSignature(bucket, safeName, expiresAt);
  return `/${bucket}/${encodeURIComponent(safeName)}?expires=${encodeURIComponent(String(expiresAt))}&signature=${encodeURIComponent(signature)}`;
}

function signedExportUrl(fileName, ttlMs) {
  return signedStorageUrl("exports", fileName, ttlMs);
}

function signedUploadUrl(fileName, ttlMs) {
  return signedStorageUrl("uploads", fileName, ttlMs);
}

function signedOnlyOfficeUploadUrl(fileName, ttlMs = ONLYOFFICE_DOCUMENT_URL_TTL_MS) {
  const safeName = path.basename(String(fileName || ""));
  const expiresAt = Date.now() + Math.max(1000, Number(ttlMs || ONLYOFFICE_DOCUMENT_URL_TTL_MS));
  const signature = storageSignature("onlyoffice-uploads", safeName, expiresAt);
  return `/uploads/${encodeURIComponent(safeName)}?expires=${encodeURIComponent(String(expiresAt))}&signature=${encodeURIComponent(signature)}&onlyoffice=1`;
}

function signedAttachmentUrl(fileName, ttlMs) {
  return signedStorageUrl("attachments", fileName, ttlMs);
}

function hasValidOnlyOfficeUploadSignature(fileName, requestUrl) {
  if (safeText(requestUrl?.searchParams?.get("onlyoffice"), "") !== "1") {
    return false;
  }
  const expiresAt = Number(requestUrl?.searchParams?.get("expires") || 0);
  const signature = safeText(requestUrl?.searchParams?.get("signature"), "");
  if (!expiresAt || expiresAt < Date.now() || !/^[a-f0-9]{64}$/i.test(signature)) {
    return false;
  }
  const expected = storageSignature("onlyoffice-uploads", fileName, expiresAt);
  const left = Buffer.from(signature, "hex");
  const right = Buffer.from(expected, "hex");
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

function hasValidStorageSignature(bucket, fileName, requestUrl) {
  const expiresAt = Number(requestUrl?.searchParams?.get("expires") || 0);
  const signature = safeText(requestUrl?.searchParams?.get("signature"), "");
  if (!expiresAt || !signature || expiresAt < Date.now()) {
    return false;
  }
  const expected = storageSignature(bucket, fileName, expiresAt);
  const left = Buffer.from(signature, "hex");
  const right = Buffer.from(expected, "hex");
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

async function hashStoredUpload(storedFileName) {
  const normalizedName = safeText(storedFileName, "");
  if (!normalizedName) {
    return "";
  }

  if (!(await storageService.uploads.exists(normalizedName))) {
    return "";
  }

  return sha1Hash(await storageService.uploads.readBuffer(normalizedName));
}

function pruneOnlyOfficeCallbackCache() {
  const cutoff = Date.now() - ONLYOFFICE_CALLBACK_CACHE_TTL_MS;
  for (const [key, timestamp] of onlyOfficeCallbackCache.entries()) {
    if (Number(timestamp) < cutoff) {
      onlyOfficeCallbackCache.delete(key);
    }
  }
}

function nextAvailableDocumentName(name, parentId, projectId = DEFAULT_PROJECT_ID) {
  const ext = path.extname(name);
  const stem = ext ? name.slice(0, -ext.length) : name;
  let index = 1;
  let candidate = name;

  while (
    documents.some(
      (item) =>
        safeText(item.projectId, DEFAULT_PROJECT_ID) === projectId &&
        item.parentId === parentId &&
        item.name.toLowerCase() === candidate.toLowerCase(),
    )
  ) {
    candidate = `${stem} (${index})${ext}`;
    index += 1;
  }

  return candidate;
}

function currentVersionSnapshot(doc) {
  const mimeType = inferDocumentMimeType(doc.name, doc.mimeType);
  const version = safeText(doc.version, "V1");
  return {
    id: doc.currentVersionId || crypto.randomUUID(),
    version,
    versionNo: versionNumber(version),
    name: safeText(doc.name, "未命名文件"),
    storedFileName: safeText(doc.storedFileName, ""),
    size: Number(doc.size || 0),
    mimeType,
    uploadedAt: doc.updatedAt || doc.uploadedAt || new Date().toISOString(),
    uploadedById: safeText(doc.uploaderId, ""),
    uploadedBy: safeText(doc.uploader, inferUploadActor(doc)),
    note: "当前版本",
    parseStatus: normalizeParseStatus(doc.parseStatus, "done"),
    parseReadyAt: safeText(doc.parseReadyAt, ""),
    parseError: safeText(doc.parseError, ""),
    isCurrent: true,
    share: normalizeShare(doc.share),
    aps: normalizeApsConfig(doc.aps || {}),
  };
}

function normalizeVersionHistory(history, currentSnapshot, preferredCurrentVersionId = "") {
  const baseHistory = Array.isArray(history) && history.length ? history : [currentSnapshot];
  const nextHistory = baseHistory.map((entry) => normalizeVersionEntry(entry, currentSnapshot));
  const latestEntry = nextHistory[nextHistory.length - 1];

  if (
    !latestEntry ||
    latestEntry.storedFileName !== currentSnapshot.storedFileName ||
    latestEntry.version !== currentSnapshot.version
  ) {
    nextHistory.push(normalizeVersionEntry(currentSnapshot, currentSnapshot));
  }

  const currentEntry =
    resolveCurrentVersionEntry(nextHistory, preferredCurrentVersionId) ||
    nextHistory.find((entry) => entry.storedFileName === currentSnapshot.storedFileName && entry.version === currentSnapshot.version) ||
    nextHistory[nextHistory.length - 1];

  return nextHistory.map((entry) => ({
    ...entry,
    isCurrent: Boolean(currentEntry) && entry.id === currentEntry.id,
  }));
}

function normalizeVersionEntry(entry, fallback) {
  const version = safeText(entry.version, safeText(fallback.version, "V1"));
  return {
    id: entry.id || crypto.randomUUID(),
    version,
    versionNo: Number(entry.versionNo || versionNumber(version)),
    name: safeText(entry.name, safeText(fallback.name, "未命名文件")),
    storedFileName: safeText(entry.storedFileName, safeText(fallback.storedFileName, "")),
    size: Number(entry.size || fallback.size || 0),
    mimeType: inferDocumentMimeType(entry.name || fallback.name, entry.mimeType || fallback.mimeType),
    uploadedAt: entry.uploadedAt || fallback.uploadedAt || new Date().toISOString(),
    uploadedById: safeText(entry.uploadedById, safeText(fallback.uploadedById, "")),
    uploadedBy: safeText(entry.uploadedBy, safeText(fallback.uploadedBy, "系统")),
    note: safeText(entry.note, "—"),
    parseStatus: normalizeParseStatus(entry.parseStatus, "done"),
    parseReadyAt: safeText(entry.parseReadyAt, ""),
    parseError: safeText(entry.parseError, ""),
    isCurrent: Boolean(entry.isCurrent),
    share: normalizeShare(entry.share),
    aps: normalizeApsConfig(entry.aps || {}),
    deletedAt: safeText(entry.deletedAt, ""),
    deletedBy: safeText(entry.deletedBy, ""),
  };
}

function nextVersionLabel(currentVersion, fallbackIndex) {
  const match = /^V(\d+)$/i.exec(String(currentVersion || ""));
  if (match) {
    return `V${Number(match[1]) + 1}`;
  }
  return `V${Math.max(2, Number(fallbackIndex) + 1 || 2)}`;
}

function versionNumber(version) {
  const match = /^V(\d+)$/i.exec(String(version || ""));
  return match ? Number(match[1]) : 1;
}

function normalizeParseStatus(value, fallback = "done") {
  return ["pending", "processing", "done", "failed"].includes(value) ? value : fallback;
}

function resolveCurrentVersionEntry(history, preferredCurrentVersionId = "") {
  const visibleHistory = Array.isArray(history) ? history.filter((entry) => !entry.deletedAt) : [];
  if (!visibleHistory.length) {
    return null;
  }
  if (preferredCurrentVersionId) {
    const preferred = visibleHistory.find((entry) => entry.id === preferredCurrentVersionId);
    if (preferred) {
      return preferred;
    }
  }
  return visibleHistory.find((entry) => entry.isCurrent) || visibleHistory[visibleHistory.length - 1];
}

function activeVersionEntries(doc) {
  return Array.isArray(doc.versionHistory) ? doc.versionHistory.filter((entry) => !entry.deletedAt) : [];
}

function requireVersionEntry(doc, versionId, { includeDeleted = false } = {}) {
  const entries = includeDeleted ? doc.versionHistory || [] : activeVersionEntries(doc);
  const entry = entries.find((item) => item.id === versionId);
  if (!entry) {
    const error = new Error("Version not found");
    error.statusCode = 404;
    throw error;
  }
  return entry;
}

function syncCurrentVersionFromEntry(doc, entry) {
  if (!entry) {
    return;
  }
  doc.currentVersionId = entry.id;
  doc.version = entry.version;
  doc.storedFileName = entry.storedFileName;
  doc.size = Number(entry.size || 0);
  doc.mimeType = inferDocumentMimeType(entry.name || doc.name, entry.mimeType || doc.mimeType);
  doc.isPdf = doc.mimeType === "application/pdf";
  doc.uploaderId = safeText(entry.uploadedById, doc.uploaderId || "");
  doc.uploader = safeText(entry.uploadedBy, doc.uploader || "系统");
  doc.parseStatus = normalizeParseStatus(entry.parseStatus, "done");
  doc.parseReadyAt = safeText(entry.parseReadyAt, "");
  doc.parseError = safeText(entry.parseError, "");
}

function setVersionParseStatus(doc, entry, status, options = {}) {
  if (!doc || !entry) {
    return;
  }
  const normalizedStatus = normalizeParseStatus(status, "processing");
  entry.parseStatus = normalizedStatus;
  entry.parseReadyAt = normalizedStatus === "processing" ? safeText(options.parseReadyAt, "") : "";
  entry.parseError = normalizedStatus === "failed" ? safeText(options.errorMessage, "解析失败") : "";
  if (entry.id === doc.currentVersionId || entry.isCurrent) {
    doc.parseStatus = normalizedStatus;
    doc.parseReadyAt = safeText(entry.parseReadyAt, "");
    doc.parseError = safeText(entry.parseError, "");
  }
}

function markCurrentVersion(doc, versionId) {
  doc.versionHistory = Array.isArray(doc.versionHistory) ? doc.versionHistory : [];
  doc.versionHistory.forEach((entry) => {
    entry.isCurrent = entry.id === versionId;
  });
  doc.currentVersionId = versionId;
}

function scheduleVersionParsing(entry, delayMs = 2600) {
  entry.parseStatus = "processing";
  entry.parseReadyAt = new Date(Date.now() + delayMs).toISOString();
  entry.parseError = "";
}

async function settleDocumentParsingStates() {
  let changed = false;
  const now = Date.now();
  const notifications = [];

  documents.forEach((doc) => {
    const entries = Array.isArray(doc.versionHistory) ? doc.versionHistory : [];
    entries.forEach((entry) => {
      if (entry.deletedAt) {
        return;
      }
      if (isApsModelDocument(doc.name)) {
        const entryAps = normalizeApsConfig(entry.aps || {});
        const documentAps = normalizeApsConfig(doc.aps || {});
        const apsState = safeText(documentAps.sourceVersionId, "") === safeText(entry.id, "") ? documentAps : entryAps;
        const apsStatus = normalizeApsTranslationStatus(apsState.translationStatus, "idle");
        if (apsStatus === "success" && entry.parseStatus !== "done") {
          setVersionParseStatus(doc, entry, "done");
          changed = true;
        } else if (apsStatus === "failed" && entry.parseStatus !== "failed") {
          setVersionParseStatus(doc, entry, "failed", {
            errorMessage: apsState.translationError || apsState.translationMessage || "APS 自动转换失败",
          });
          changed = true;
        }
        return;
      }
      if (entry.parseStatus === "processing" && entry.parseReadyAt) {
        const readyAt = new Date(entry.parseReadyAt).getTime();
        if (!Number.isNaN(readyAt) && readyAt <= now) {
          setVersionParseStatus(doc, entry, "done");
          changed = true;
          notifications.push({
            eventKey: "parseCompleted",
            context: {
              document: doc,
              versionEntry: entry,
              userContext: buildUserContext(SYSTEM_USER_CONTEXT.user, doc.projectId),
              occurredAt: new Date().toISOString(),
              note: `版本 ${safeText(entry.version, doc.version)} 的预览解析已完成`,
            },
          });
        }
      }
    });

    const currentEntry = resolveCurrentVersionEntry(entries, doc.currentVersionId);
    if (currentEntry) {
      if (doc.currentVersionId !== currentEntry.id) {
        doc.currentVersionId = currentEntry.id;
        changed = true;
      }
      if (
        doc.storedFileName !== currentEntry.storedFileName ||
        doc.version !== currentEntry.version ||
        Number(doc.size || 0) !== Number(currentEntry.size || 0) ||
        normalizeParseStatus(doc.parseStatus, "done") !== normalizeParseStatus(currentEntry.parseStatus, "done") ||
        safeText(doc.parseReadyAt, "") !== safeText(currentEntry.parseReadyAt, "")
      ) {
        syncCurrentVersionFromEntry(doc, currentEntry);
        changed = true;
      }
    }
  });

  if (changed) {
    persistStore();
  }
  for (const item of notifications) {
    await bestEffortProjectEmailNotification(item.eventKey, item.context);
  }
}

async function retryDocumentParsing(doc, actor, userContext = SYSTEM_USER_CONTEXT) {
  const permissions = documentPermissionsForUser(doc, userContext);
  if (!permissions.preview && !permissions.uploadVersion && !permissions.rename) {
    throw permissionDeniedError("你没有重新解析该文件的权限。");
  }
  const entry = resolveCurrentVersionEntry(doc.versionHistory, doc.currentVersionId);
  if (!entry) {
    const error = new Error("Current version not found");
    error.statusCode = 404;
    throw error;
  }
  if (!safeText(entry.storedFileName, "") || !(await storageService.uploads.exists(entry.storedFileName))) {
    setVersionParseStatus(doc, entry, "failed", { errorMessage: "源文件不存在，无法重新解析。" });
    persistStore();
    const error = new Error("Source file not found");
    error.statusCode = 404;
    throw error;
  }

  if (isApsModelDocument(doc.name)) {
    setVersionParseStatus(doc, entry, "processing");
    queueApsTranslationForDocument(doc, actor, {
      force: true,
      reason: "用户手动重新解析",
    });
  } else {
    scheduleVersionParsing(entry);
    syncCurrentVersionFromEntry(doc, entry);
    touchDocument(doc);
    addActivity(doc, actor, "重新解析", `${doc.name} ${safeText(entry.version, doc.version)} 已重新进入解析队列`);
    persistStore();
  }
  return doc;
}

function ensureUniqueDocumentName(name, parentId, excludeId = null, projectId = DEFAULT_PROJECT_ID) {
  const duplicate = documents.find(
    (item) =>
      item.id !== excludeId &&
      safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID) &&
      item.parentId === parentId &&
      item.name.toLowerCase() === name.toLowerCase(),
  );
  if (duplicate) {
    const error = new Error("目标目录下已存在同名文件");
    error.statusCode = 409;
    throw error;
  }
}

function ensureUniqueFolderName(name, parentId, excludeId = null, projectId = DEFAULT_PROJECT_ID) {
  const duplicate = folders.find(
    (item) =>
      item.id !== excludeId &&
      safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID) &&
      item.parentId === parentId &&
      item.name.toLowerCase() === name.toLowerCase(),
  );
  if (duplicate) {
    const error = new Error("目标目录下已存在同名文件夹");
    error.statusCode = 409;
    throw error;
  }
}

function isDescendantFolder(candidateParentId, folderId, projectId = DEFAULT_PROJECT_ID) {
  let cursor = normalizeFolderId(candidateParentId);
  while (cursor) {
    if (cursor === folderId) {
      return true;
    }
    cursor =
      folders.find(
        (item) =>
          item.id === cursor &&
          safeText(item.projectId, DEFAULT_PROJECT_ID) === safeText(projectId, DEFAULT_PROJECT_ID),
      )?.parentId || null;
  }
  return false;
}

function folderName(folderId) {
  if (!folderId) {
    return "根目录";
  }
  return folders.find((item) => item.id === folderId)?.name || "未知目录";
}

function folderPathLabel(folderId) {
  if (!folderId) {
    return "根目录";
  }
  const parts = [];
  let cursor = folderByIdOrNull(folderId);
  while (cursor) {
    parts.unshift(safeText(cursor.name, ""));
    cursor = folderByIdOrNull(cursor.parentId);
  }
  return parts.filter(Boolean).join(" / ") || "根目录";
}

function formatOnlyOfficeInfoDate(value) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleString("zh-CN", {
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function accessLevelLabel(value) {
  const labels = {
    edit: "项目可编辑",
    view: "只读查看",
    restricted: "外委受限",
  };
  return labels[value] || "项目可编辑";
}

function downloadScopeLabel(value) {
  const labels = {
    team: "项目成员可下载",
    admins: "仅管理员可下载",
    restricted: "外委仅预览",
  };
  return labels[value] || "项目成员可下载";
}

function sharePermissionLabel(value) {
  const labels = {
    view: "仅预览",
    download: "可下载",
  };
  return labels[value] || "仅预览";
}

function defaultDueDate() {
  const date = new Date();
  date.setDate(date.getDate() + 3);
  return date.toISOString().slice(0, 10);
}

function defaultAnnotationTitle(type, page, variant = "") {
  const map = {
    circle: "定点批注",
    mark: "矩形批注",
    note: "文本批注",
    line: normalizeAnnotationVariant(variant, "line", "") === "leader" ? "引线批注" : "箭头批注",
    pen: "手绘批注",
  };
  return `${map[type] || "批注"} · 第 ${Number(page || 1)} 页`;
}

function defaultColor(type) {
  if (type === "mark") return "blue";
  if (type === "note") return "amber";
  if (type === "pen") return "blue";
  if (type === "line") return "red";
  return "red";
}

function normalizeAnnotationPoints(points, fallback = []) {
  if (!Array.isArray(points) || !points.length) {
    return fallback.slice(0, 240).map((point) => ({
      x: clampNumber(point?.x),
      y: clampNumber(point?.y),
    }));
  }

  return points
    .map((point) => ({
      x: clampNumber(point?.x),
      y: clampNumber(point?.y),
    }))
    .slice(0, 240);
}

function normalizeAnnotationStrokes(strokes, fallback = []) {
  const source = Array.isArray(strokes) && strokes.length ? strokes : fallback;
  if (!Array.isArray(source) || !source.length) {
    return [];
  }

  return source
    .map((stroke) => normalizeAnnotationPoints(stroke, []))
    .filter((stroke) => stroke.length)
    .slice(0, 32);
}

function fallbackPointsForAnnotation(type, x, y, width, height) {
  if (type === "line") {
    return [
      { x, y },
      { x: clampNumber(x + width), y: clampNumber(y + height) },
    ];
  }

  if (type === "pen") {
    return [
      { x, y: clampNumber(y + height * 0.15) },
      { x: clampNumber(x + width * 0.38), y: clampNumber(y + height * 0.72) },
      { x: clampNumber(x + width * 0.68), y: clampNumber(y + height * 0.42) },
      { x: clampNumber(x + width), y: clampNumber(y + height * 0.78) },
    ];
  }

  return [];
}

function attachmentStorageNames(attachments = []) {
  return new Set(
    attachments
      .map((attachment) => safeText(attachment?.storageName || path.basename(String(attachment?.url || "")), ""))
      .filter(Boolean),
  );
}

function annotationAttachmentStorageNames(annotation) {
  const storageNames = attachmentStorageNames(annotation?.attachments || []);
  (annotation?.replies || []).forEach((reply) => {
    attachmentStorageNames(reply.attachments || []).forEach((storageName) => {
      storageNames.add(storageName);
    });
  });
  return storageNames;
}

function documentAttachmentStorageNames(doc) {
  const storageNames = new Set();
  (doc?.annotations || []).forEach((annotation) => {
    annotationAttachmentStorageNames(annotation).forEach((storageName) => {
      storageNames.add(storageName);
    });
  });
  return storageNames;
}

function allReferencedAttachmentStorageNames() {
  const storageNames = new Set();
  documents.forEach((doc) => {
    documentAttachmentStorageNames(doc).forEach((storageName) => {
      storageNames.add(storageName);
    });
  });
  return storageNames;
}

function diffStorageNames(previousStorageNames, nextStorageNames) {
  const diff = new Set();
  previousStorageNames.forEach((storageName) => {
    if (!nextStorageNames.has(storageName)) {
      diff.add(storageName);
    }
  });
  return diff;
}

async function cleanupUnusedStoredAttachments(storageNames) {
  if (!storageNames || !storageNames.size) {
    return;
  }

  const referencedStorageNames = allReferencedAttachmentStorageNames();
  for (const storageName of storageNames) {
    if (!storageName || referencedStorageNames.has(storageName)) {
      continue;
    }
    await storageService.attachments.delete(storageName);
  }
}

function normalizeColor(value, fallback) {
  return ["red", "amber", "blue"].includes(value) ? value : fallback;
}

function normalizeAttachmentKind(value, fallback) {
  return ["image", "document", "link"].includes(value) ? value : fallback;
}

function normalizeAnnotationStatus(value, fallback) {
  return ["open", "in_progress", "resolved"].includes(value) ? value : fallback;
}

function normalizeAnnotationVariant(value, type, fallback = "") {
  if (type !== "line") {
    return "";
  }
  return ["arrow", "leader"].includes(value) ? value : fallback || "arrow";
}

function annotationStatusLabel(status) {
  const labels = {
    open: "未解决",
    in_progress: "进行中",
    resolved: "已解决",
  };
  return labels[status] || "未解决";
}

function formatDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return safeText(value, "—").slice(0, 10) || "—";
  }
  return date.toISOString().slice(0, 10);
}

function safeText(value, fallback) {
  const text = String(value || "").trim();
  return text || fallback;
}

function safeUrl(value, fallback) {
  const text = String(value || "").trim();
  if (!text) {
    return fallback;
  }

  try {
    const url = new URL(text);
    if (!["http:", "https:"].includes(url.protocol)) {
      return fallback;
    }
    return url.toString();
  } catch {
    return fallback;
  }
}

function clampNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return 0;
  }
  return Math.max(0, Math.min(1, number));
}

async function materializeAttachments(attachments) {
  if (!Array.isArray(attachments) || !attachments.length) {
    return [];
  }

  const materialized = [];
  for (const attachment of attachments) {
    const nextAttachment = await materializeAttachment(attachment);
    if (nextAttachment) {
      materialized.push(nextAttachment);
    }
  }
  return materialized;
}

async function materializeAttachment(attachment) {
  const kind = normalizeAttachmentKind(
    attachment.kind,
    inferAttachmentKind(attachment.mimeType, attachment.name),
  );
  const createdAt = attachment.createdAt || new Date().toISOString();

  if (kind === "link") {
    const url = safeUrl(attachment.url, "");
    if (!url) {
      const error = new Error("Invalid attachment link");
      error.statusCode = 400;
      throw error;
    }

    return {
      id: attachment.id || crypto.randomUUID(),
      kind,
      name: safeText(attachment.name, url),
      mimeType: "text/uri-list",
      size: 0,
      url,
      createdAt,
    };
  }

  assertAttachmentAllowed(attachment);

  const dataBase64 = String(attachment.dataBase64 || "");
  let storageName = safeText(
    attachment.storageName || path.basename(String(attachment.url || "")),
    "",
  );

  let attachmentBuffer = null;
  if (dataBase64) {
    attachmentBuffer = decodeLimitedBase64Payload(dataBase64, {
      declaredSize: attachment.size,
      maxBytes: MAX_ATTACHMENT_BYTES,
      label: "Attachment upload",
    });
    const extension = attachmentExtension(attachment.name, attachment.mimeType, kind);
    storageName = `${crypto.randomUUID()}${extension}`;
    await storageService.attachments.writeBuffer(storageName, attachmentBuffer);
  }

  if (!storageName) {
    const error = new Error("Missing attachment file");
    error.statusCode = 400;
    throw error;
  }

  const size =
    attachmentBuffer?.length ||
    Number(attachment.size || 0) ||
    (storageName && await storageService.attachments.exists(storageName) ? await storageService.attachments.size(storageName) : 0);

  return {
    id: attachment.id || crypto.randomUUID(),
    kind,
    name: safeText(attachment.name, "未命名附件"),
    mimeType: safeText(attachment.mimeType, fallbackMimeType(kind, attachment.name)),
    size,
    storageName,
    url: signedAttachmentUrl(storageName),
    createdAt,
  };
}

function assertAttachmentAllowed(attachment) {
  const extension = path.extname(String(attachment?.name || "")).toLowerCase();
  if (!extension) {
    return;
  }
  if (ATTACHMENT_BLOCKED_EXTENSIONS.has(extension) || (ATTACHMENT_ALLOWED_EXTENSIONS.size && !ATTACHMENT_ALLOWED_EXTENSIONS.has(extension))) {
    const error = new Error(`Attachment type ${extension} is not allowed`);
    error.statusCode = 415;
    throw error;
  }
}

function inferAttachmentKind(mimeType, name) {
  const mime = String(mimeType || "").toLowerCase();
  const lowerName = String(name || "").toLowerCase();
  if (mime.startsWith("image/") || /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(lowerName)) {
    return "image";
  }
  if (mime === "text/uri-list") {
    return "link";
  }
  return "document";
}

function fallbackMimeType(kind, name) {
  if (kind === "link") return "text/uri-list";
  if (kind === "image") return "image/*";

  const lowerName = String(name || "").toLowerCase();
  if (lowerName.endsWith(".pdf")) return "application/pdf";
  if (lowerName.endsWith(".doc")) return "application/msword";
  if (lowerName.endsWith(".docx")) return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  if (lowerName.endsWith(".xls")) return "application/vnd.ms-excel";
  if (lowerName.endsWith(".xlsx")) return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  if (lowerName.endsWith(".csv")) return "text/csv; charset=utf-8";
  if (lowerName.endsWith(".ppt")) return "application/vnd.ms-powerpoint";
  if (lowerName.endsWith(".pptx")) return "application/vnd.openxmlformats-officedocument.presentationml.presentation";
  if (lowerName.endsWith(".dwg")) return "application/acad";
  if (lowerName.endsWith(".dxf")) return "application/octet-stream";
  if (lowerName.endsWith(".dgn")) return "application/octet-stream";
  if (lowerName.endsWith(".idw")) return "application/octet-stream";
  if (lowerName.endsWith(".zip")) return "application/zip";
  return "application/octet-stream";
}

function attachmentExtension(name, mimeType, kind) {
  const ext = path.extname(String(name || "")).toLowerCase();
  if (ext) {
    return ext;
  }

  const mime = String(mimeType || "").toLowerCase();
  if (mime === "application/pdf") return ".pdf";
  if (mime === "application/msword") return ".doc";
  if (mime === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") return ".docx";
  if (mime === "application/vnd.ms-excel") return ".xls";
  if (mime === "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet") return ".xlsx";
  if (mime === "text/csv; charset=utf-8") return ".csv";
  if (mime === "application/vnd.ms-powerpoint") return ".ppt";
  if (mime === "application/vnd.openxmlformats-officedocument.presentationml.presentation") return ".pptx";
  if (mime === "application/zip") return ".zip";
  if (mime.startsWith("image/")) {
    return `.${mime.split("/")[1] || "png"}`;
  }
  if (kind === "image") return ".png";
  return ".bin";
}

function pathHealthStatus(dirPath, { writable = false } = {}) {
  const result = {
    configured: Boolean(dirPath),
    exists: false,
    writable: writable ? false : undefined,
  };
  if (!dirPath) {
    return result;
  }

  try {
    const stat = fs.statSync(dirPath);
    result.exists = stat.isDirectory() || stat.isFile();
    if (writable) {
      fs.accessSync(dirPath, fs.constants.W_OK);
      result.writable = true;
    }
  } catch {
    result.exists = false;
    if (writable) {
      result.writable = false;
    }
  }
  return result;
}

function fileHealthStatus(filePath) {
  const result = {
    configured: Boolean(filePath),
    exists: false,
  };
  if (!filePath) {
    return result;
  }

  try {
    result.exists = fs.statSync(filePath).isFile();
  } catch {
    result.exists = false;
  }
  return result;
}

function storageBucketHealthOk(bucketHealth) {
  return Boolean(
    bucketHealth &&
      bucketHealth.configured !== false &&
      bucketHealth.writable &&
      bucketHealth.exists !== false,
  );
}

async function buildHealthPayload() {
  const audit = verifyAuditLogChain();
  const data = {
    store: {
      adapter: STORE_ADAPTER,
      jsonPath: STORE_PATH,
      sqlitePath: SQLITE_STORE_PATH,
      ...storeRepository.health(),
    },
    dataDir: pathHealthStatus(DATA_DIR, { writable: true }),
    storage: await storageService.health(),
    uploadsDir: await storageService.uploads.health(),
    exportsDir: await storageService.exports.health(),
    attachmentsDir: await storageService.attachments.health(),
    audit,
    exportScript: fileHealthStatus(EXPORT_SCRIPT),
    commentReportExportScript: fileHealthStatus(COMMENT_REPORT_EXPORT_SCRIPT),
    workflowCommentReportExportScript: fileHealthStatus(WORKFLOW_COMMENT_REPORT_EXPORT_SCRIPT),
    workflowReportExportScript: fileHealthStatus(WORKFLOW_REPORT_EXPORT_SCRIPT),
    constructionScheduleExportScript: fileHealthStatus(CONSTRUCTION_SCHEDULE_EXPORT_SCRIPT),
    drawingRedlineDetectScript: fileHealthStatus(DRAWING_REDLINE_DETECT_SCRIPT),
    drawingOcrExtractScript: fileHealthStatus(DRAWING_OCR_EXTRACT_SCRIPT),
    pdfjsDir: pathHealthStatus(PDFJS_DIR),
  };

  const onlyOffice = {
    configured: Boolean(ONLYOFFICE_SERVER_URL && ONLYOFFICE_PUBLIC_BASE_URL),
    serverUrlConfigured: Boolean(ONLYOFFICE_SERVER_URL),
    publicBaseUrlConfigured: Boolean(ONLYOFFICE_PUBLIC_BASE_URL),
    jwtConfigured: Boolean(ONLYOFFICE_JWT_SECRET),
  };

  const apsSettings = effectiveApsSettings();
  const aps = {
    configured: apsSettingsReady(apsSettings),
    enabled: Boolean(apsSettings.enabled),
    status: apsSettingsStatus(apsSettings),
    clientIdConfigured: Boolean(apsSettings.clientId),
    clientSecretConfigured: Boolean(apsSettings.clientSecret),
    bucketKeyConfigured: Boolean(apsSettings.bucketKey),
    bucketPolicy: apsSettings.bucketPolicy,
    bucketRegion: apsSettings.bucketRegion,
    viewerVersion: apsSettings.viewerVersion,
    viewerEnv: apsSettings.viewerEnv,
    viewerApi: apsSettings.viewerApi,
  };

  const lark = {
    configured: isLarkLoginConfigured(),
    appIdConfigured: Boolean(LARK_APP_ID),
    appSecretConfigured: Boolean(LARK_APP_SECRET),
    redirectUriConfigured: Boolean(LARK_REDIRECT_URI),
    openBaseUrl: LARK_OPEN_BASE_URL,
  };

  const requiredDataOk = [
    data.store.exists,
    data.dataDir.exists && data.dataDir.writable,
    storageBucketHealthOk(data.uploadsDir),
    storageBucketHealthOk(data.exportsDir),
    storageBucketHealthOk(data.attachmentsDir),
    data.exportScript.exists,
    data.commentReportExportScript.exists,
    data.workflowCommentReportExportScript.exists,
    data.workflowReportExportScript.exists,
    data.audit.ok,
  ].every(Boolean);

  return {
    status: requiredDataOk ? "ok" : "degraded",
    service: "cde-doc-workflow",
    timestamp: new Date().toISOString(),
    uptimeSeconds: Math.round(process.uptime()),
    version: "0.1.0",
    checks: {
      data,
      onlyOffice,
      aps,
      lark,
    },
  };
}

function sendJson(res, statusCode, payload, extraHeaders = {}) {
  const json = JSON.stringify(payload);
  res.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
    ...extraHeaders,
  });
  res.end(json);
}

function contentTypeForFileName(fileName) {
  const ext = path.extname(fileName).toLowerCase();
  return {
    ".html": "text/html; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".mjs": "text/javascript; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".svg": "image/svg+xml",
    ".doc": "application/msword",
    ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ".xls": "application/vnd.ms-excel",
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    ".csv": "text/csv; charset=utf-8",
    ".ppt": "application/vnd.ms-powerpoint",
    ".pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    ".txt": "text/plain; charset=utf-8",
    ".zip": "application/zip",
    ".dwg": "application/acad",
    ".dxf": "application/octet-stream",
    ".dgn": "application/octet-stream",
    ".idw": "application/octet-stream",
    ".nwd": "application/octet-stream",
    ".rvt": "application/octet-stream",
    ".map": "application/json; charset=utf-8",
  }[ext] || "application/octet-stream";
}

function cacheControlForFileName(fileName) {
  const ext = path.extname(fileName).toLowerCase();
  // Revalidate text assets via ETag/Last-Modified (304) instead of re-downloading the body
  // on every load, while still picking up edits immediately. PDFs stay uncached.
  return [".html", ".css", ".js", ".mjs", ".map"].includes(ext)
    ? "no-cache"
    : ext === ".pdf"
      ? "no-store"
      : "public, max-age=0";
}

function cacheControlForFileRequest(fileName, req) {
  const ext = path.extname(fileName).toLowerCase();
  if ([".css", ".js", ".mjs", ".map", ".wasm"].includes(ext)) {
    try {
      const url = new URL(req?.url || "", "http://127.0.0.1");
      if (url.searchParams.has("v")) {
        return "public, max-age=31536000, immutable";
      }
    } catch {
      // Fall back to the filename-based policy below.
    }
  }
  return cacheControlForFileName(fileName);
}

async function serveStorageObject(res, bucket, fileName) {
  if (!(await bucket.exists(fileName))) {
    sendJson(res, 404, { error: "File not found" });
    return;
  }

  res.writeHead(200, {
    "Content-Type": contentTypeForFileName(fileName),
    "Cache-Control": cacheControlForFileName(fileName),
  });

  (await bucket.createReadStream(fileName)).pipe(res);
}

const COMPRESSIBLE_EXTENSIONS = new Set([".html", ".css", ".js", ".mjs", ".json", ".svg", ".csv", ".txt", ".map"]);
const compressedFileCache = new Map();

function compressedFileCacheKey(filePath, stat, encoding) {
  return `${encoding}:${filePath}:${stat.size}:${Math.round(stat.mtimeMs)}`;
}

function servePublicAssetRequest(pathname, req, res) {
  if (!["GET", "HEAD"].includes(String(req.method || "").toUpperCase())) {
    return false;
  }
  if (pathname === "/favicon.ico") {
    res.writeHead(204);
    res.end();
    return true;
  }
  if (pathname.startsWith("/vendor/pdfjs/")) {
    serveFile(res, path.join(PDFJS_DIR, path.basename(pathname)), req);
    return true;
  }
  if (pathname.startsWith("/vendor/embedpdf/")) {
    serveFile(res, path.join(EMBEDPDF_DIST_DIR, path.basename(pathname)), req);
    return true;
  }

  const publicFiles = new Map([
    ["/", "index.html"],
    ["/index.html", "index.html"],
    ["/invite.html", "invite.html"],
    ["/onlyoffice.html", "onlyoffice.html"],
    ["/apsviewer.html", "apsviewer.html"],
    ["/drawingviewer.html", "drawingviewer.html"],
    ["/pdf.html", "pdf.html"],
    ["/app.js", "app.js"],
    ["/auth-bootstrap.js", "auth-bootstrap.js"],
    ["/apsviewer.js", "apsviewer.js"],
    ["/pdf-runtime.js", "pdf-runtime.js"],
    ["/styles.css", "styles.css"],
    ["/styles-critical.css", "styles-critical.css"],
  ]);
  const fileName = publicFiles.get(pathname);
  if (!fileName) {
    return false;
  }
  serveFile(res, path.join(ROOT, fileName), req);
  return true;
}

function negotiateEncoding(req, ext, size) {
  if (!req || size < 1024 || !COMPRESSIBLE_EXTENSIONS.has(ext)) {
    return "";
  }
  const accept = String(req.headers["accept-encoding"] || "");
  if (/\bbr\b/.test(accept)) {
    return "br";
  }
  if (/\bgzip\b/.test(accept)) {
    return "gzip";
  }
  return "";
}

function serveFile(res, filePath, req) {
  let stat;
  try {
    stat = fs.statSync(filePath);
  } catch {
    sendJson(res, 404, { error: "File not found" });
    return;
  }
  if (!stat.isFile()) {
    sendJson(res, 404, { error: "File not found" });
    return;
  }

  const etag = `W/"${stat.size.toString(16)}-${Math.round(stat.mtimeMs).toString(16)}"`;
  const headers = {
    "Content-Type": contentTypeForFileName(filePath),
    "Cache-Control": cacheControlForFileRequest(filePath, req),
    "Last-Modified": stat.mtime.toUTCString(),
    ETag: etag,
  };

  const ifNoneMatch = req?.headers["if-none-match"];
  const ifModifiedSince = req?.headers["if-modified-since"];
  const notModified = ifNoneMatch
    ? ifNoneMatch === etag
    : Boolean(ifModifiedSince) && Date.parse(ifModifiedSince) >= Math.floor(stat.mtimeMs / 1000) * 1000;
  if (notModified) {
    res.writeHead(304, headers);
    res.end();
    return;
  }

  const encoding = negotiateEncoding(req, path.extname(filePath).toLowerCase(), stat.size);
  if (encoding) {
    const cacheKey = compressedFileCacheKey(filePath, stat, encoding);
    let compressed = compressedFileCache.get(cacheKey);
    if (!compressed) {
      const raw = fs.readFileSync(filePath);
      compressed = encoding === "br"
        ? zlib.brotliCompressSync(raw, { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 6 } })
        : zlib.gzipSync(raw);
      compressedFileCache.set(cacheKey, compressed);
    }
    headers["Content-Encoding"] = encoding;
    headers.Vary = "Accept-Encoding";
    headers["Content-Length"] = compressed.length;
    res.writeHead(200, headers);
    res.end(compressed);
    return;
  }

  headers["Content-Length"] = stat.size;
  res.writeHead(200, headers);
  fs.createReadStream(filePath).pipe(res);
}

function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];

    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        const error = new Error("Request body too large");
        error.statusCode = 413;
        reject(error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on("end", () => {
      try {
        if (!chunks.length) {
          resolve({});
          return;
        }
        resolve(JSON.parse(Buffer.concat(chunks).toString("utf8")));
      } catch {
        const error = new Error("Invalid JSON payload");
        error.statusCode = 400;
        reject(error);
      }
    });

    req.on("error", reject);
  });
}

function readRawBody(req, { maxBytes = MAX_UPLOAD_BYTES, label = "Request body" } = {}) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];

    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > maxBytes) {
        const error = payloadTooLargeError(label, maxBytes);
        reject(error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on("end", () => {
      resolve(Buffer.concat(chunks));
    });

    req.on("error", reject);
  });
}

function safeResumableUploadId(id) {
  const value = safeText(id, "");
  if (!/^[a-f0-9-]{36}$/i.test(value)) {
    const error = new Error("Upload session not found");
    error.statusCode = 404;
    throw error;
  }
  return value;
}

function resumableUploadDir(id) {
  return path.join(RESUMABLE_UPLOADS_DIR, safeResumableUploadId(id));
}

function resumableUploadManifestPath(id) {
  return path.join(resumableUploadDir(id), "manifest.json");
}

function resumableUploadChunkPath(id, index) {
  return path.join(resumableUploadDir(id), `${Number(index)}.part`);
}

function readResumableUploadManifest(id) {
  const manifestPath = resumableUploadManifestPath(id);
  if (!fs.existsSync(manifestPath)) {
    const error = new Error("Upload session not found");
    error.statusCode = 404;
    throw error;
  }
  return JSON.parse(fs.readFileSync(manifestPath, "utf8"));
}

function writeResumableUploadManifest(session) {
  const dir = resumableUploadDir(session.id);
  ensureDir(dir);
  fs.writeFileSync(resumableUploadManifestPath(session.id), JSON.stringify(session, null, 2));
}

function readAllResumableUploadSessions() {
  if (!fs.existsSync(RESUMABLE_UPLOADS_DIR)) {
    return [];
  }
  return fs.readdirSync(RESUMABLE_UPLOADS_DIR, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => {
      try {
        return readResumableUploadManifest(entry.name);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}

function resumableReceivedChunks(session) {
  const dir = resumableUploadDir(session.id);
  const chunkCount = Number(session.chunkCount || 0);
  const receivedChunks = [];
  let receivedBytes = 0;
  for (let index = 0; index < chunkCount; index += 1) {
    const chunkPath = path.join(dir, `${index}.part`);
    if (fs.existsSync(chunkPath)) {
      const size = fs.statSync(chunkPath).size;
      receivedChunks.push(index);
      receivedBytes += size;
    }
  }
  return { receivedChunks, receivedBytes };
}

function toPublicResumableUploadSession(session) {
  const chunkCount = Number(session.chunkCount || 0);
  const completed = session.status === "completed";
  const received = completed
    ? {
        receivedChunks: Array.from({ length: chunkCount }, (_, index) => index),
        receivedBytes: Number(session.size || 0),
      }
    : resumableReceivedChunks(session);
  const { receivedChunks, receivedBytes } = received;
  return {
    id: session.id,
    fingerprint: safeText(session.fingerprint, ""),
    name: session.name,
    size: Number(session.size || 0),
    mimeType: session.mimeType,
    parentId: session.parentId || null,
    projectId: session.projectId,
    chunkSize: Number(session.chunkSize || RESUMABLE_UPLOAD_CHUNK_BYTES),
    chunkCount,
    receivedChunks,
    receivedBytes,
    status: session.status || "created",
    documentId: safeText(session.documentId, ""),
    createdAt: session.createdAt,
    updatedAt: session.updatedAt,
    completedAt: safeText(session.completedAt, ""),
  };
}

function assertResumableUploadSessionAccess(session, userContext) {
  if (safeText(session.projectId, DEFAULT_PROJECT_ID) !== safeText(userContext?.projectId, DEFAULT_PROJECT_ID)) {
    const error = new Error("Upload session not found");
    error.statusCode = 404;
    throw error;
  }
  const ownerUserId = safeText(session.createdByUserId, "");
  const currentUserId = safeText(userContext?.user?.id, "");
  if (ownerUserId && currentUserId && ownerUserId !== currentUserId && !isSuperAdmin(userContext)) {
    throw permissionDeniedError("你不能操作其他用户的上传任务。");
  }
}

function normalizeResumableUploadChunkSize(value) {
  const requested = Number(value || RESUMABLE_UPLOAD_CHUNK_BYTES);
  const fallback = Math.max(1, RESUMABLE_UPLOAD_CHUNK_BYTES);
  if (!Number.isFinite(requested) || requested <= 0) {
    return fallback;
  }
  return Math.max(1, Math.min(Math.floor(requested), fallback));
}

function normalizeResumableUploadFingerprint(value, fallbackParts = []) {
  const provided = safeText(value, "");
  const raw = provided || fallbackParts.map((part) => safeText(part, "-")).join("|");
  return raw.slice(0, 512);
}

function isActiveResumableUploadSession(session) {
  return !["completed", "canceled"].includes(session?.status);
}

function isReusableResumableUploadSession(session, draft, userContext) {
  if (!session || !isActiveResumableUploadSession(session)) {
    return false;
  }
  if (safeText(session.projectId, DEFAULT_PROJECT_ID) !== safeText(draft.projectId, DEFAULT_PROJECT_ID)) {
    return false;
  }
  if (safeText(session.createdByUserId, "") !== safeText(userContext?.user?.id, "")) {
    return false;
  }
  if (safeText(session.fingerprint, "") !== safeText(draft.fingerprint, "")) {
    return false;
  }
  return (
    safeText(session.name, "") === safeText(draft.name, "") &&
    Number(session.size || 0) === Number(draft.size || 0) &&
    safeText(session.parentId, "") === safeText(draft.parentId, "")
  );
}

function listResumableUploadSessions(searchParams, userContext) {
  const status = safeText(searchParams?.get("status"), "all");
  return readAllResumableUploadSessions()
    .filter((session) => {
      try {
        assertResumableUploadSessionAccess(session, userContext);
        return true;
      } catch {
        return false;
      }
    })
    .filter((session) => {
      if (status === "active") {
        return isActiveResumableUploadSession(session);
      }
      if (status === "completed") {
        return session.status === "completed";
      }
      return true;
    })
    .sort((left, right) => String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || "")));
}

function createOrReuseResumableUploadSession(body, userContext) {
  const projectId = safeText(body.projectId, safeText(userContext?.projectId, DEFAULT_PROJECT_ID));
  const name = safeText(body.name, "未命名文件");
  const size = Number(body.size || 0);
  if (!Number.isFinite(size) || size < 0) {
    const error = new Error("Invalid upload size");
    error.statusCode = 400;
    throw error;
  }
  if (size > MAX_UPLOAD_BYTES) {
    throw payloadTooLargeError("Document upload", MAX_UPLOAD_BYTES);
  }
  const parentId = resolveFolderParentId(body.parentId, userContext, projectId);
  assertFolderCapability(parentId, "upload", userContext, "当前目录不允许上传文件。");
  const chunkSize = normalizeResumableUploadChunkSize(body.chunkSize);
  const mimeType = inferDocumentMimeType(name, body.mimeType);
  const fingerprint = normalizeResumableUploadFingerprint(body.fingerprint, [
    "cde-upload-v1",
    projectId,
    safeText(userContext?.user?.id, ""),
    parentId || "root",
    name,
    size,
    mimeType,
  ]);
  const draft = { projectId, parentId, name, size, fingerprint };
  const reusable = readAllResumableUploadSessions().find((session) => isReusableResumableUploadSession(session, draft, userContext));
  if (reusable) {
    reusable.updatedAt = new Date().toISOString();
    writeResumableUploadManifest(reusable);
    return { session: reusable, reused: true };
  }
  const now = new Date().toISOString();
  const session = {
    id: crypto.randomUUID(),
    projectId,
    fingerprint,
    name,
    size,
    mimeType,
    parentId,
    conflictMode: normalizeConflictMode(body.conflictMode),
    actor: safeText(body.actor, actorDisplayName(userContext)),
    owner: safeText(body.owner, ""),
    note: safeText(body.note, ""),
    accessLevel: normalizeAccessLevel(body.accessLevel, "edit"),
    downloadScope: normalizeDownloadScope(body.downloadScope, "team"),
    watermarkEnabled: body.watermarkEnabled !== undefined ? Boolean(body.watermarkEnabled) : undefined,
    share: normalizeShare(body.share),
    drawingMetadata: normalizeDocumentDrawingMetadata(body.drawingMetadata),
    specMetadata: normalizeDocumentSpecMetadata(body.specMetadata),
    chunkSize,
    chunkCount: Math.ceil(size / chunkSize),
    status: "created",
    createdByUserId: safeText(userContext?.user?.id, ""),
    createdBy: actorDisplayName(userContext),
    createdAt: now,
    updatedAt: now,
  };
  writeResumableUploadManifest(session);
  return { session, reused: false };
}

function requireResumableUploadSession(id, userContext) {
  const session = readResumableUploadManifest(id);
  assertResumableUploadSessionAccess(session, userContext);
  return session;
}

function expectedResumableChunkSize(session, index) {
  const chunkCount = Number(session.chunkCount || 0);
  const chunkSize = Number(session.chunkSize || RESUMABLE_UPLOAD_CHUNK_BYTES);
  const totalSize = Number(session.size || 0);
  if (chunkCount === 0) {
    return 0;
  }
  if (index === chunkCount - 1) {
    return Math.max(0, totalSize - chunkSize * index);
  }
  return chunkSize;
}

async function writeResumableUploadChunk(id, indexValue, req, userContext) {
  const session = requireResumableUploadSession(id, userContext);
  const index = Number(indexValue);
  if (!Number.isInteger(index) || index < 0 || index >= Number(session.chunkCount || 0)) {
    const error = new Error("Invalid upload chunk index");
    error.statusCode = 400;
    throw error;
  }
  if (["completed", "canceled"].includes(session.status)) {
    const error = new Error("Upload session is already closed");
    error.statusCode = 409;
    throw error;
  }

  const expectedSize = expectedResumableChunkSize(session, index);
  const buffer = await readRawBody(req, {
    maxBytes: Math.max(expectedSize, 1),
    label: "Upload chunk",
  });
  if (buffer.length !== expectedSize) {
    const error = new Error(`Upload chunk size mismatch for chunk ${index}`);
    error.statusCode = 400;
    throw error;
  }
  fs.writeFileSync(resumableUploadChunkPath(session.id, index), buffer);
  session.status = "uploading";
  session.updatedAt = new Date().toISOString();
  writeResumableUploadManifest(session);
  return session;
}

async function assembleResumableUpload(session) {
  const dir = resumableUploadDir(session.id);
  const outputPath = path.join(dir, "assembled.upload");
  const writer = fs.createWriteStream(outputPath);
  try {
    for (let index = 0; index < Number(session.chunkCount || 0); index += 1) {
      const chunkPath = resumableUploadChunkPath(session.id, index);
      if (!fs.existsSync(chunkPath)) {
        const error = new Error(`Upload session is missing chunk ${index}`);
        error.statusCode = 409;
        throw error;
      }
      const expectedSize = expectedResumableChunkSize(session, index);
      if (fs.statSync(chunkPath).size !== expectedSize) {
        const error = new Error(`Upload chunk ${index} is incomplete`);
        error.statusCode = 409;
        throw error;
      }
      await new Promise((resolve, reject) => {
        const reader = fs.createReadStream(chunkPath);
        reader.on("error", reject);
        writer.on("error", reject);
        reader.on("end", resolve);
        reader.pipe(writer, { end: false });
      });
    }
  } catch (error) {
    writer.destroy();
    throw error;
  }
  await new Promise((resolve, reject) => {
    writer.on("error", reject);
    writer.end(resolve);
  });
  assertDeclaredUploadSize(fs.statSync(outputPath).size, session.size, "Document upload");
  return outputPath;
}

async function completeResumableUploadSession(id, userContext) {
  const session = requireResumableUploadSession(id, userContext);
  if (session.status === "completed") {
    const document = documents.find((item) => item.id === session.documentId);
    if (!document) {
      const error = new Error("Completed upload document not found");
      error.statusCode = 404;
      throw error;
    }
    return { document, session, reused: true };
  }
  const received = resumableReceivedChunks(session);
  if (received.receivedChunks.length !== Number(session.chunkCount || 0) || received.receivedBytes !== Number(session.size || 0)) {
    const error = new Error("Upload session is incomplete");
    error.statusCode = 409;
    throw error;
  }
  assertFolderCapability(session.parentId || null, "upload", userContext, "当前目录不允许上传文件。");
  session.status = "assembling";
  session.updatedAt = new Date().toISOString();
  writeResumableUploadManifest(session);
  const assembledPath = await assembleResumableUpload(session);
  const document = await createDocument({
    name: session.name,
    size: session.size,
    parentId: session.parentId || null,
    actor: safeText(session.actor, actorDisplayName(userContext)),
    mimeType: session.mimeType,
    conflictMode: session.conflictMode,
    owner: session.owner,
    note: session.note,
    accessLevel: session.accessLevel,
    downloadScope: session.downloadScope,
    watermarkEnabled: session.watermarkEnabled,
    share: session.share,
    drawingMetadata: session.drawingMetadata,
    specMetadata: session.specMetadata,
    _sourcePath: assembledPath,
  }, userContext);
  session.status = "completed";
  session.documentId = document.id;
  session.completedAt = new Date().toISOString();
  session.updatedAt = new Date().toISOString();
  writeResumableUploadManifest(session);
  cleanupResumableUploadPayloadFiles(session);
  return { document, session, reused: false };
}

function cleanupResumableUploadPayloadFiles(session) {
  const dir = resumableUploadDir(session.id);
  for (let index = 0; index < Number(session.chunkCount || 0); index += 1) {
    fs.rmSync(resumableUploadChunkPath(session.id, index), { force: true });
  }
  fs.rmSync(path.join(dir, "assembled.upload"), { force: true });
}

function cancelResumableUploadSession(id, userContext) {
  const session = requireResumableUploadSession(id, userContext);
  fs.rmSync(resumableUploadDir(session.id), { recursive: true, force: true });
  return session;
}

async function runExportScript(doc, outputPath, options = {}) {
  persistStore();
  const sourcePath = await storageService.uploads.materializeToTempPath(doc.storedFileName);

  return new Promise((resolve, reject) => {
    const child = spawn(PYTHON_BIN, [
      EXPORT_SCRIPT,
      STORE_PATH,
      doc.id,
      sourcePath,
      outputPath,
    ], exportSpawnOptions(options.language));

    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
    });

    child.on("close", (code) => {
      storageService.uploads.cleanupTempPath?.(sourcePath);
      if (code === 0) {
        resolve();
        return;
      }
      const error = new Error(stderr.trim() || "Failed to export reviewed PDF");
      error.statusCode = 500;
      reject(error);
    });

    child.on("error", (error) => {
      storageService.uploads.cleanupTempPath?.(sourcePath);
      reject(error);
    });
  });
}

