function runDrawingOcrExtraction({ sourcePath, options = {} }) {
  return new Promise((resolve, reject) => {
    const child = spawn(PYTHON_BIN, [DRAWING_OCR_EXTRACT_SCRIPT], {
      stdio: ["pipe", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
      stdout += chunk.toString("utf8");
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
    });
    child.on("close", (code) => {
      if (code !== 0) {
        const error = new Error(stderr.trim() || stdout.trim() || "Failed to extract drawing OCR text");
        error.statusCode = 500;
        reject(error);
        return;
      }
      try {
        resolve(JSON.parse(stdout || "{}"));
      } catch (error) {
        const parseError = new Error(`Failed to parse drawing OCR extraction output: ${error.message}`);
        parseError.statusCode = 500;
        reject(parseError);
      }
    });
    child.on("error", reject);
    child.stdin.end(JSON.stringify({ sourcePath, options }));
  });
}

function runDrawingRegisterExportScript(registerPayload, outputPath, options = {}) {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "cde-drawing-register-"));
  const manifestPath = path.join(tempDir, "register.json");
  fs.writeFileSync(manifestPath, JSON.stringify({
    register: registerPayload,
    options,
  }, null, 2));

  return new Promise((resolve, reject) => {
    const cleanup = () => {
      try {
        fs.rmSync(tempDir, { recursive: true, force: true });
      } catch {
        // Best-effort cleanup only; export result is already determined.
      }
    };
    const child = spawn(PYTHON_BIN, [
      DRAWING_REGISTER_EXPORT_SCRIPT,
      manifestPath,
      outputPath,
    ], exportSpawnOptions(options.language));

    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
    });

    child.on("close", (code) => {
      cleanup();
      if (code === 0) {
        resolve();
        return;
      }
      const error = new Error(stderr.trim() || "Failed to export drawing register workbook");
      error.statusCode = 500;
      reject(error);
    });

    child.on("error", (error) => {
      cleanup();
      reject(error);
    });
  });
}

async function runWorkflowCommentReportExportScript(workflow, docs, outputPath, options = {}) {
  persistStore();
  const stagingDir = fs.mkdtempSync(path.join(EXPORTS_DIR, "workflow-comment-report-"));
  const manifestPath = path.join(stagingDir, "manifest.json");
  const manifest = {
    workflowId: safeText(workflow?.id, ""),
    documents: [],
  };

  try {
    for (const doc of docs || []) {
      const sourcePath = await storageService.uploads.materializeToTempPath(doc.storedFileName);
      manifest.documents.push({
        docId: doc.id,
        inputFile: sourcePath,
      });
    }
    fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), "utf8");

    return await new Promise((resolve, reject) => {
      const child = spawn(PYTHON_BIN, [
        WORKFLOW_COMMENT_REPORT_EXPORT_SCRIPT,
        STORE_PATH,
        safeText(workflow?.id, ""),
        manifestPath,
        outputPath,
      ], exportSpawnOptions(options.language));

      let stderr = "";
      child.stderr.on("data", (chunk) => {
        stderr += chunk.toString("utf8");
      });

      child.on("close", (code) => {
        if (code === 0) {
          resolve();
          return;
        }
        const error = new Error(stderr.trim() || "Failed to export workflow comment report");
        error.statusCode = 500;
        reject(error);
      });

      child.on("error", reject);
    });
  } finally {
    manifest.documents.forEach((item) => {
      storageService.uploads.cleanupTempPath?.(item.inputFile);
    });
    fs.rmSync(stagingDir, { recursive: true, force: true });
  }
}

