async function handleOnlyOfficeCallback(req, doc, body, requestUrl) {
  const status = Number(body?.status || 0);
  const actor = safeText(requestUrl.searchParams.get("actor"), "OnlyOffice");
  const sourceVersionId = safeText(requestUrl.searchParams.get("versionId"), doc.currentVersionId);

  if (![2, 6].includes(status) || !safeText(body?.url, "")) {
    return { error: 0 };
  }

  const callbackUserContext = verifyOnlyOfficeCallbackGrant(requestUrl.searchParams.get("grant"), doc, sourceVersionId);
  const callbackActor = actorDisplayName(callbackUserContext);
  const buffer = await downloadRemoteBinary(body.url);
  const bufferHash = sha1Hash(buffer);
  const callbackKey = [doc.id, sourceVersionId, bufferHash].join(":");

  pruneOnlyOfficeCallbackCache();
  if (onlyOfficeCallbackCache.has(callbackKey)) {
    return { error: 0, skipped: true };
  }

  if ((await hashStoredUpload(doc.storedFileName)) === bufferHash) {
    onlyOfficeCallbackCache.set(callbackKey, Date.now());
    return { error: 0, skipped: true };
  }

  onlyOfficeCallbackCache.set(callbackKey, Date.now());

  try {
    const updated = await appendDocumentVersion(doc, {
      name: doc.name,
      size: buffer.length,
      note: status === 6 ? "OnlyOffice 强制保存" : "OnlyOffice 在线编辑保存",
      dataBase64: buffer.toString("base64"),
      actor: callbackActor,
      mimeType: doc.mimeType,
    }, callbackUserContext);
    addActivity(updated, callbackActor, "OnlyOffice 保存", `${updated.name} 已通过 OnlyOffice 保存为 ${updated.version}`);
    persistStore();
    return { error: 0 };
  } catch (error) {
    onlyOfficeCallbackCache.delete(callbackKey);
    throw error;
  }
}

async function downloadRemoteBinary(url) {
  const response = await fetch(String(url || ""));
  if (!response.ok) {
    const error = new Error(`Failed to download OnlyOffice callback file (${response.status})`);
    error.statusCode = 502;
    throw error;
  }

  const arrayBuffer = await response.arrayBuffer();
  return Buffer.from(arrayBuffer);
}

async function createBatchDownloadArchive(ids, userContext = SYSTEM_USER_CONTEXT) {
  const docIds = Array.isArray(ids) ? ids.map((item) => String(item || "").trim()).filter(Boolean) : [];
  const selectedDocs = docIds
    .map((id) => requireDocument(id, userContext))
    .filter(Boolean);

  if (!selectedDocs.length) {
    const error = new Error("请选择至少一个文件后再批量下载。");
    error.statusCode = 400;
    throw error;
  }

  const stagingDir = fs.mkdtempSync(path.join(EXPORTS_DIR, "batch-download-"));
  const usedNames = new Map();

  try {
    selectedDocs.forEach((doc) => {
      const sourcePath = path.join(UPLOADS_DIR, doc.storedFileName);
      if (!fs.existsSync(sourcePath)) {
        return;
      }

      const ext = path.extname(doc.name || ".pdf");
      const baseName = path.basename(doc.name || `${doc.id}${ext}`, ext) || doc.id;
      const currentCount = usedNames.get(baseName) || 0;
      usedNames.set(baseName, currentCount + 1);
      const exportName = currentCount ? `${baseName}-${currentCount + 1}${ext}` : `${baseName}${ext}`;
      fs.copyFileSync(sourcePath, path.join(stagingDir, exportName));
    });

    const archiveName = `workflow-batch-${Date.now()}.zip`;
    const archivePath = path.join(EXPORTS_DIR, archiveName);
    await zipDirectory(stagingDir, archivePath);
    registerProtectedExportFile(archiveName, {
      kind: "batch_download",
      docIds: selectedDocs.map((doc) => doc.id),
      createdBy: safeText(userContext?.user?.id, ""),
      createdAt: new Date().toISOString(),
    });
    return `/exports/${archiveName}`;
  } finally {
    fs.rmSync(stagingDir, { recursive: true, force: true });
  }
}

const ZIP_CRC32_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let i = 0; i < table.length; i++) {
    let value = i;
    for (let bit = 0; bit < 8; bit++) {
      value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    }
    table[i] = value >>> 0;
  }
  return table;
})();

function zipCrc32(buffer) {
  let next = 0xffffffff;
  for (const byte of buffer) {
    next = ZIP_CRC32_TABLE[(next ^ byte) & 0xff] ^ (next >>> 8);
  }
  return (next ^ 0xffffffff) >>> 0;
}

function zipDosDateTime(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  const dosTime = (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2);
  const dosDate = ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { dosDate, dosTime };
}

function writeUInt16LE(value) {
  const buffer = Buffer.alloc(2);
  buffer.writeUInt16LE(value & 0xffff, 0);
  return buffer;
}

function writeUInt32LE(value) {
  const buffer = Buffer.alloc(4);
  buffer.writeUInt32LE(value >>> 0, 0);
  return buffer;
}

async function collectZipEntries(sourceDir, baseDir = sourceDir) {
  const dirents = await fs.promises.readdir(sourceDir, { withFileTypes: true });
  const entries = [];
  for (const dirent of dirents.sort((left, right) => left.name.localeCompare(right.name, "zh-CN"))) {
    const absolutePath = path.join(sourceDir, dirent.name);
    const relativePath = path.relative(baseDir, absolutePath).split(path.sep).join("/");
    if (dirent.isDirectory()) {
      entries.push(...await collectZipEntries(absolutePath, baseDir));
    } else if (dirent.isFile()) {
      entries.push({ absolutePath, relativePath });
    }
  }
  return entries;
}

function deflateRawBuffer(buffer) {
  return new Promise((resolve, reject) => {
    zlib.deflateRaw(buffer, { level: 6 }, (error, result) => {
      if (error) reject(error);
      else resolve(result);
    });
  });
}

async function zipDirectory(sourceDir, archivePath) {
  const entries = await collectZipEntries(sourceDir);
  const output = await fs.promises.open(archivePath, "w");
  const centralDirectory = [];
  let offset = 0;
  try {
    for (const entry of entries) {
      const content = await fs.promises.readFile(entry.absolutePath);
      const compressed = await deflateRawBuffer(content);
      const stat = await fs.promises.stat(entry.absolutePath);
      const { dosDate, dosTime } = zipDosDateTime(stat.mtime);
      const nameBuffer = Buffer.from(entry.relativePath, "utf8");
      const crc = zipCrc32(content);
      const localHeader = Buffer.concat([
        writeUInt32LE(0x04034b50), writeUInt16LE(20), writeUInt16LE(0x0800), writeUInt16LE(8),
        writeUInt16LE(dosTime), writeUInt16LE(dosDate), writeUInt32LE(crc),
        writeUInt32LE(compressed.length), writeUInt32LE(content.length), writeUInt16LE(nameBuffer.length),
        writeUInt16LE(0), nameBuffer
      ]);
      await output.write(localHeader);
      await output.write(compressed);
      centralDirectory.push({ nameBuffer, crc, compressedSize: compressed.length, size: content.length, dosDate, dosTime, offset });
      offset += localHeader.length + compressed.length;
    }
    const centralStart = offset;
    for (const entry of centralDirectory) {
      const header = Buffer.concat([
        writeUInt32LE(0x02014b50), writeUInt16LE(20), writeUInt16LE(20), writeUInt16LE(0x0800),
        writeUInt16LE(8), writeUInt16LE(entry.dosTime), writeUInt16LE(entry.dosDate), writeUInt32LE(entry.crc),
        writeUInt32LE(entry.compressedSize), writeUInt32LE(entry.size), writeUInt16LE(entry.nameBuffer.length),
        writeUInt16LE(0), writeUInt16LE(0), writeUInt16LE(0), writeUInt16LE(0),
        writeUInt32LE(0), writeUInt32LE(entry.offset), entry.nameBuffer
      ]);
      await output.write(header);
      offset += header.length;
    }
    const centralSize = offset - centralStart;
    await output.write(Buffer.concat([
      writeUInt32LE(0x06054b50), writeUInt16LE(0), writeUInt16LE(0),
      writeUInt16LE(centralDirectory.length), writeUInt16LE(centralDirectory.length),
      writeUInt32LE(centralSize), writeUInt32LE(centralStart), writeUInt16LE(0)
    ]));
  } finally {
    await output.close();
  }
}
